            <li>Как и благодаря чему [кто-либо] становится</li>
            <li>владыкой богатств, о Подобный пространству?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>43. Как и почему возник род Шакья и [род] Икшваку?</li>
            <li>Откуда пришёл риши Диргхатапас<a href="#citation-162" id="ref-162" class="citation-mark"><sup>162</sup></a></li>
            <li>и как им было явлено учение?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>44. Почему именно Ты один являешься повсюду</li>
            <li>во всех мирах, под разными именами и в разных обликах,</li>
            <li>окружённый сыновьями Победителей?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>45. Почему мясо недопустимо [для еды]</li>
            <li>и почему оно запрещено?</li>
            <li>Почему рождённые в роду пожирателей плоти</li>
            <li>всё же едят мясо?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>46. Как [миры] подобны луне и солнцу,</li>
            <li>или напоминают [гору] Меру и лотос?</li>
            <li>Поведай мне: почему миры принимают форму льва</li>
            <li>или [знака] Шриватса?<a href="#citation-163" id="ref-163" class="citation-mark"><sup>163</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>47. Как [миры] бывают перевёрнуты вверх дном</li>
            <li>или подобны сети Индры?</li>
            <li>Как и почему [возникают] миры,</li>
            <li>состоящие сплошь из драгоценностей?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>48. Как [миры] принимают форму вины или барабана,</li>
            <li>или подобны разным цветам и плодам?</li>
            <li>Как они [сияют] чистотой солнца и луны? Поведай мне!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>49. Кто такие Будды воплощения (<em>nirmāṇika</em>),</li>
            <li>кто — Будды созревания [заслуг] (<em>vipākaja</em>)?</li>
            <li>Кто такие Будды Мудрости Таковости (<em>tathatā-jñāna-buddha</em>) —</li>
            <li>и благодаря чему Они [таковы]? Поведай мне!<a href="#citation-164" id="ref-164" class="citation-mark"><sup>164</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>50. Поведай мне: почему Ты не пробуждаешься</li>
            <li>в мире желаний (<em>kāma-dhātu</em>)?</li>
            <li>Почему Ты пробуждаешься лишь в [мире] <em>Акаништха</em>,</li>
            <li>среди свободных от страстей?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>51. Кто будет поддерживать Учение,</li>
            <li>когда Сугата уйдёт в [окончательное] угасание?</li>
            <li>Как долго будет пребывать Учитель</li>
            <li>и как долго сохранится Его путь?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>52. Сколько существует видов учения (<em>siddhānta</em>)</li>
            <li>в Твоей традиции и каковы воззрения?<a href="#citation-165" id="ref-165" class="citation-mark"><sup>165</sup></a></li>
            <li>Какова дисциплина (<em>vinaya</em>)</li>
            <li>и как [обретается] состояние монаха? Поведай мне об этом!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>53. Как происходит поворот основы [у бодхисаттв] (<em>parāvṛtti</em>) и</li>
            <li>как [достигается] состояние вне ментальных образов?</li>
            <li>[В чём различие] между пратьекабуддами,</li>
            <li>сыновьями Победителей и шраваками? Поведай мне!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>54. Как возникают мирские сверхзнания (<em>abhijñā</em>)</li>
            <li>и как обретаются сверхзнания запредельные? </li>
            <li>Поведай мне, как и благодаря чему</li>
            <li>семь ступеней (<em>bhūmayaḥ sapta</em>) [проходит] ум (<em>cittaṃ</em>)!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>55. Сколько видов Сангхи существует</li>
            <li>и как происходит её раскол?</li>
            <li>Как и почему возникла врачебная наука</li>
            <li>для [исцеления] существ?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>56. Почему Ты говоришь сыновьям Победителей:</li>
            <li>«Я был Кашьяпой, Кракуччхандой и Канакамуни»?</li>
            <li>Поведай об этом, о Великий Мудрец!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>57. Почему [существуют] учения о ложном Я</li>
            <li>и почему — о вечности и уничтожении?</li>
            <li>Почему Ты не провозглашаешь повсюду истину о том,</li>
            <li>что всё есть лишь ум?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>58. Откуда берётся лес мужчин и женщин?<a href="#citation-166" id="ref-166" class="citation-mark"><sup>166</sup></a></li>
            <li>Откуда — леса миробаланов и амлы?</li>
            <li>Как [возникли] гора Кайласа, </li>
            <li>кольцо гор Чакравала и Алмазная твердыня?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>59. Кто те непоколебимые существа,</li>
            <li>что пребывают в этих [горах],</li>
            <li>украшенных множеством драгоценностей</li>
            <li>и наполненных риши и гандхарвами?</li>
            <li>Поведай мне, как и почему это так!</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2. (Будда уточняет вопросы Махамати)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>60. Выслушав это, Великий Герой — Будда,</li>
            <li>лучший из знатоков мира, —</li>
            <li>явил ум Махаяны, сердце и силу Будд.</li>
        </ul>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>61. Прекрасно, прекрасно, о великомудрый Махамати!</li>
            <li>Внимай же! Я изложу по порядку всё, о чём ты вопрошал.<a href="#citation-167" id="ref-167" class="citation-mark"><sup>167</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>62. Изложу возникновение и не-возникновение,</li>
            <li>Нирвану и <em>шуньяту</em> признаков,</li>
            <li>переход из существования в существование,</li>
            <li>отсутствие собственной природы (<em>asvabhāvatva</em>),</li>
            <li>природу Будд, Парамиты и сыновей, [взращённых] Парамитами.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>63. Расскажу о шраваках, сынах Победителей и тиртхиках,</li>
            <li>а также о тех, кто пребывает в бесформенных мирах;</li>
            <li>о горе Меру, океанах, горных твердынях (<em>acalā</em>),</li>
            <li>островах, мирах и земле.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>64. О созвездиях, солнце и луне,</li>
            <li>о тиртхиках, богах и асурах;</li>
            <li>об освобождениях (<em>vimokṣa</em>), владычествах (<em>vaśitā</em>),</li>
            <li>сверхзнаниях (<em>abhijñā</em>), могуществах (<em>bala</em>),</li>
            <li><em>дхьянах</em> и <em>самадхи</em>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>65. О прекращении (<em>nirodha</em>), основах чудесных сил (<em>ṛddhipāda</em>),</li>
            <li>факторах Пробуждения (<em>bodhyaṅga</em>) и самом Пути (<em>mārga</em>);</li>
            <li>о <em>дхьянах</em>, безмерных состояниях (<em>apramāṇa</em>),</li>
            <li><em>скандхах</em> и приходах и уходах (блужданиях) (<em>gatyāgatāni</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>66. О достижениях сосредоточения (<em>samāpatti</em>),</li>
            <li>о прекращении и выходе из него (<em>vyutthāna</em>),</li>
            <li>об учении об уме (<em>citta-deśanā</em>);</li>
            <li>об умe (<em>citta</em>), <em>манасе</em> (<em>manas</em>) и различающем сознании (<em>vijñāna</em>);</li>
            <li>об отсутствии «я» (<em>nairātmya</em>) и пяти дхармах.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>67. О собственной природе (<em>svabhāva</em>),</li>
            <li>воображении (<em>kalpanā</em>) и воображаемом (<em>kalpya</em>);</li>
            <li>о видимом (<em>dṛśya</em>) и</li>
            <li>как возникают две крайности во взглядах (<em>dṛṣṭi-dvaya</em>);</li>
            <li>о видах Колесниц, родах (<em>gotrāṇi</em>)</li>
            <li>и происхождении золота, драгоценностей и жемчуга.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>68. Об <em>иччхантиках</em>, великих первоэлементах (<em>mahābhūtā</em>),</li>
            <li>блужданиях (<em>bhramarā</em>)<a href="#citation-168" id="ref-168" class="citation-mark"><sup>168</sup></a></li>
            <li>и о природе единого Будды (<em>ekabuddhatā</em>);</li>
            <li>о знании (<em>jñāna</em>), познаваемом (<em>jñeya</em>),</li>
            <li>ходе практики (<em>gama</em>), достижении (<em>prāpti</em>),</li>
            <li>а также о бытии и небытии существ (<em>bhavābhava</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>69. Почему и как кони, слоны и олени</li>
            <li>попадают в ловушки — изложу об этом;</li>
            <li>высшую истину (<em>siddhānta</em>),</li>
            <li>подтверждённую примерами и доводами (<em>dṛṣṭānta-hetubhiḥ</em>),</li>
            <li>и саму природу изложения Учения (<em>deśanā</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>70. Что есть следствие и причина;</li>
            <li>в чём суть разнообразных заблуждений (<em>nānābhrānti</em>)</li>
            <li>и верные способы аргументации (<em>nayam</em>);</li>
            <li>почему всё есть только ум и нет воспринимаемого;</li>
            <li>и почему на самом деле нет последовательности ступеней.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>71. Ты спрашиваешь Меня о сотне способов поворота</li>
            <li>к состоянию без ментальных образов(<em>nirābhāsa-parāvṛtti)?</em></li>
            <li>Спроси же тогда и о медицине,</li>
            <li>ремёслах, искусствах и преданиях!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>72. Вопрошай же о размерах гор Ачала и Меру,</li>
            <li>о мерах самой земли!</li>
            <li>Поведай Мне, как ученик:</li>
            <li>каковы меры океанов, луны и солнца?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>73. Сосчитай: сколько пылинок (<em>rajas</em>) в телах существ —</li>
            <li>высших, средних и низших?</li>
            <li>Сколько пылинок в каждом мире (<em>kṣetra</em>)?</li>
            <li>Сколько их в каждой мере длины (<em>dhanu</em>)?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>74. Сколько их в локте, в шаге, в кроше,</li>
            <li>в йоджане и в половине йоджаны?</li>
            <li>Сколько частиц уместится на волоске зайца, в игольном ушке,</li>
            <li>на гниде, на овечьей шерсти, в зерне ячменя?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>75. Сколько ячменных зёрен в мере <em>прастха</em> </li>
            <li>и сколько в половине <em>прастхи</em>?</li>
            <li>Сколько их в мерах <em>дрона</em> и <em>кхари</em>?</li>
            <li>Сколько там <em>лакх</em>, <em>крор</em> и <em>бимбар</em>?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>76. Сколько атомов (<em>aṇu</em>) в горчичном зерне?</li>
            <li>Сколько горчичных зёрен в бобе <em>маша</em>?</li>
            <li>И сколько таких бобов — в весе <em>дхарана</em>?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>77. Сколько <em>дхаран</em> в весе <em>карша</em>, </li>
            <li>и сколько <em>карш</em> — в тяжёлом <em>пала</em>?</li>
            <li>Исходя из этих мер веса, сколько <em>пал</em> весит гора Меру?</li>
            <li>Именно об этом спрашивай Меня, сын Мой!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>78. Зачем тебе вопрошать об ином?</li>
            <li>Из скольких атомов состоит тело пратьекабудд,</li>
            <li>шраваков, Будд и сыновей Победителей?</li>
            <li>Почему бы тебе не спросить об этом?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>79. Сколько атомов в языке пламени?</li>
            <li>Сколько их в порыве ветра?</li>
            <li>Сколько их в каждом отдельном органе чувств,</li>
            <li>в порах кожи и в бровях?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>80. Как люди становятся владыками богатств,</li>
            <li>царями и миродержцами?</li>
            <li>Как они стерегут свои царства?</li>
            <li>И как им достичь освобождения?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>81. Почему ты вопрошаешь о прозе и поэзии,</li>
            <li>о половом соединении, известном миру,</li>
            <li>о разнообразии пищи и питья</li>
            <li>и о лесах мужчин и женщин?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>82. Благодаря чему [они] обладают </li>
            <li>несокрушимостью ваджры (<em>vajrasaṃhananāḥ</em>)?</li>
            <li>Поведай мне, как [становятся они] непоколебимыми (<em>acalāḥ</em>)?</li>
            <li>Благодаря чему [явления] подобны магии и сну (<em>māyāsvapnanibhāḥ</em>)?</li>
            <li>И как [уподобляются они] миражу (<em>mṛgatṛṣṇopamāḥ</em>)?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>83. Где собираются облака и откуда приходят времена года?</li>
            <li>Откуда у вкусов их вкус?</li>
            <li>И отчего существа делятся на мужчин, женщин и гермафродитов?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>84. О великолепии и сынах Победителей —</li>
            <li>спрашивай Меня, о сын!</li>
            <li>Как возникают божественные горы,</li>
            <li>украшенные риши и гандхарвами?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>85. Куда уходит освобождённый?</li>
            <li>Кто здесь связан и кем освобождается?</li>
            <li>Какова сфера пребывания тех, кто погружён в <em>дхьяну</em>?</li>
            <li>Что за искусные проявления и учения тиртхиков?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>86. Как возникают существование (<em>sat</em>), несуществование (<em>asat</em>) </li>
            <li>и не-деяние (<em>akriyā</em>)?</li>
            <li>Как прекращается видимое?</li>
            <li>Как очищается рассудочное мышление</li>
            <li>и откуда оно вообще возникает?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>87. Что приводит в действие деяние?</li>
            <li>Как совершается движение?</li>
            <li>Как прекращается распознавание (<em>saṃjñā</em>)</li>
            <li>и что именно называют «самадхи»?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>88. Кто тот, кто разрушает тройственное бытие (<em>tribhava</em>)?</li>
            <li>Каково его тело и где он пребывает?</li>
            <li>Почему Я учу об отсутствии «я»,</li>
            <li>если при этом говорю об условном [выражении истины] (<em>saṃvṛti</em>)?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>89. О каких таких «признаках» ты Меня вопрошаешь?</li>
            <li>Что ты ищешь в «отсутствии "я"»?</li>
            <li>И почему ты спрашиваешь Меня</li>
            <li>о гарбхах (<em>garbha</em>) и ньяиках?</li>
            <li>Спрашивай об этом, сын Победителей!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>90. Откуда взялись воззрения о вечности и уничтожении?</li>
            <li>Чем ум связывается [или: омрачается]?</li>
            <li>Что такое речь, знание, нравственность и род (<em>gotra</em>)?</li>
            <li>О сын Победителей! Спрашивай же!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>91. Ты спрашивал Меня о логике и толковании,</li>
            <li>об учителе и ученике,</li>
            <li>о причинах разнообразия существ;</li>
            <li>о пище и питье, небе и облаках, Марах</li>
            <li>и о том, что всё это — лишь условные обозначения (<em>prajñaptimātra</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>92. Ты спрашивал, сын Победителя,</li>
            <li>как и почему растут деревья и лианы;</li>
            <li>благодаря чему разнообразны земли Будд (<em>kṣetrāṇi</em>),</li>
            <li>и [кто таков] риши Диргхатапас.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>93. Ты спрашивал, сын Победителя,</li>
            <li>о Моём роде (<em>vaṃśa</em>) и Моём учителе (<em>guru</em>);</li>
            <li>о том, почему люди впадают в рабство/зависимость (<em>uhoḍimā</em>),</li>
            <li>и почему Пробуждение не происходит в мире желаний.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>94. Ты спрашивал, почему высшая истина (<em>siddhānta</em>)</li>
            <li> обретается в мирах Акаништха; о логике (<em>yukti</em>);</li>
            <li>благодаря чему возникают мирские сверхзнания (<em>laukikābhijñā</em>),</li>
            <li>и о том, как обретается состояние монаха.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>95. Ты спрашивал о Буддах воплощения (<em>nairmāṇika</em>)</li>
            <li>и Буддах созревания плода (<em>vipāka-sthāna</em>);</li>
            <li>о Буддах Таковости и Знания (<em>tathatā-jñāna-buddha</em>),</li>
            <li>и о том, какова Сангха.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>96. Ты спрашивал о мирах, подобных вине, барабанам и цветам,</li>
            <li>свободных от обычного мира (<em>lokavivarjitāḥ</em>);</li>
            <li>о том, почему ум проходит через семь ступеней, сын Победителя.</li>
            <li>Обо всём этом и многих других вопросах ты вопрошал Меня, сын Мой!</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>97. Я разъясню по порядку — внемли же Мне! —</li>
            <li>каждое [положение], наделённое верными признаками,</li>
            <li>и свободное от изъянов ложных воззрений (<em>dṛṣṭi-doṣa-varjita</em>);</li>
            <li>изложу высшую истину (<em>siddhānta</em>) и само Учение (<em>deśanā</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 3. (108 пар противоположностей)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>98. Изложу Я [объяснение] этих положений —</li>
            <li>внемли Мне, сын!</li>
