        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Вот те сто восемь положений, Махамати, что были провозглашены Буддами прошлого».<a href="#citation-170" id="ref-170" class="citation-mark"><sup>170</sup></a></li>
