    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 4. (О возникновении, пребывании и прекращении сознаний)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
        <li>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</li>
        <li>— Сколько существует видов возникновения, пребывания и прекращения сознаний?</li>
        <li>Благословенный ответил:</li>
    </ul>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>— Махамати, рассудочные логики (<em>tārkika</em>) не понимают, что у сознаний есть два вида возникновения, пребывания и прекращения.</li>

            <li>Прекращение бывает двух видов: прекращается либо сам <strong>поток</strong><a href="#citation-171" id="ref-171" class="citation-mark"><sup>171</sup></a> сознания, либо его <strong>признаки</strong><a href="#citation-172" id="ref-172" class="citation-mark"><sup>172</sup></a> (характеристики проявления).</li>

            <li>Возникновение тоже двух видов: возникает либо <strong>поток</strong><a href="#citation-173" id="ref-173" class="citation-mark"><sup>173</sup></a> сознания, либо его <strong>признаки</strong><a href="#citation-174" id="ref-174" class="citation-mark"><sup>174</sup></a>.</li>

            <li>Пребывание также двух видов: пребывает либо <strong>поток</strong><a href="#citation-175" id="ref-175" class="citation-mark"><sup>175</sup></a>, либо <strong>признаки</strong><a href="#citation-176" id="ref-176" class="citation-mark"><sup>176</sup></a>.</li>

            <li>Махамати, у каждого сознания три признака: признак <strong>деятельности</strong>,<a href="#citation-177" id="ref-177" class="citation-mark"><sup>177</sup></a> признак <strong>действия</strong><a href="#citation-178" id="ref-178" class="citation-mark"><sup>178</sup></a> и признак <strong>рождения</strong>.<a href="#citation-179" id="ref-179" class="citation-mark"><sup>179</sup></a></li>

            <li>Если говорить кратко, Махамати, всё сознание, обладающее восемью признаками, сводится к двум видам:</li>

            <li>— <strong>сознанию проявления</strong>,<a href="#citation-180" id="ref-180" class="citation-mark"><sup>180</sup></a> которое просто отражает, как зеркало отражает формы и</li>
            <li>— <strong>сознанию различения объектов.</strong><a href="#citation-181" id="ref-181" class="citation-mark"><sup>181</sup></a></li>

            <li>Эти два вида нераздельны и порождают друг друга. Что их порождает? </li>

            <li>Причина <strong>сознания проявления</strong> — это <strong>непостижимое преобразование отпечатков</strong><a href="#citation-182" id="ref-182" class="citation-mark"><sup>182</sup></a> (прошлого опыта).</li>

            <li>Причина же <strong>сознания различения объектов</strong> — это само <strong>различение объектов</strong><a href="#citation-183" id="ref-183" class="citation-mark"><sup>183</sup></a> и <strong>отпечатки безначального размножествления понятий</strong><a href="#citation-184" id="ref-184" class="citation-mark"><sup>184</sup></a>.</li>

            <li>Теперь о прекращении. Когда прекращаются все чувственные сознания (зрение, слух и т.д.), это означает, что в <em>Алайя-виджняне</em> прекращается многообразное действие отпечатков (<em>vāsanā</em>) ложного умопостроения<a href="#citation-185" id="ref-185" class="citation-mark"><sup>185</sup></a>.</li>
            <li>Это и называется <strong>прекращением признака</strong><a href="#citation-186" id="ref-186" class="citation-mark"><sup>186</sup></a> — перестают проявляться характеристики сознания.</li>

            <li><strong>Прекращение потока</strong><a href="#citation-187" id="ref-187" class="citation-mark"><sup>187</sup></a> — это когда исчезает сама основа, из которой возникает сознание.</li>
            <li>Эта основа двойная: <strong>опора</strong> (<em>āśraya</em>) — накопленные отпечатки пагубной косности безначального размножествления понятий<a href="#citation-188" id="ref-188" class="citation-mark"><sup>188</sup></a>, и <strong>объект опоры</strong> (<em>ālambana</em>) — различения в сфере воспринимаемого собственным умом (<em>svacitta-dṛśya</em>)<a href="#citation-189" id="ref-189" class="citation-mark"><sup>189</sup></a>.</li>

            <li>Рассмотрим, для примера, ком глины и мельчайшие частицы глины. Ком — это не совершенно иное, чем частицы глины, но и не абсолютно то же самое. Аналогично золото и украшение из золота. Если бы ком был полностью отличен от частиц, он не мог бы состоять из них. Но поскольку он из них состоит, он не может быть совершенно отличен от них. Если бы он был полностью идентичен частицам, не было бы разницы между комом и отдельной частицей.</li>

            <li>То же самое с сознаниями. Активные сознания<a href="#citation-190" id="ref-190" class="citation-mark"><sup>190</sup></a> (зрение, слух и т.д.) соотносятся с признаком рождения<a href="#citation-191" id="ref-191" class="citation-mark"><sup>191</sup></a> <em>Алайя-виджняны</em> так же, как ком с частицами. Если бы они были полностью отличны от Алайи, она не была бы их причиной. Если бы они были тождественны ей, то с прекращением активных сознаний прекращалась бы и сама <em>Алайя-виджняна</em>. Но этого не происходит — её признак рождения<a href="#citation-192" id="ref-192" class="citation-mark"><sup>192</sup></a> не прекращается.</li>

            <li>Поэтому, Махамати, когда сознания прекращаются, прекращается их признак действия,<a href="#citation-193" id="ref-193" class="citation-mark"><sup>193</sup></a> но не признак рождения. Если бы прекращался признак рождения, исчезла бы сама <em>Алайя-виджняна</em>. А если бы прекратилась Алайя-виджняна, это учение ничем не отличалось бы от нигилизма (<em>ucchedavāda</em>) тиртхиков, которые утверждают полное уничтожение.</li>

            <li>Учение тиртхиков, Махамати, гласит: «С прекращением схватывания объектов прекращается и поток сознания. А с прекращением потока сознания обрывается безначальная преемственность». Тиртхики, Махамати, объясняют движение потока через причинность. Они не объясняют, что зрительное сознание возникает просто от встречи формы и света. Они ищут метафизическую Первопричину: Первоматерию (<em>pradhāna</em>), Дух (<em>puruṣa</em>), бога Ишвару, Время или Атомы.<a href="#citation-194" id="ref-194" class="citation-mark"><sup>194</sup></a></li>
        </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 5. (Семь природ и семь сфер высшей истины)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует семь видов природ (<em>svabhāva</em>):<a href="#citation-195" id="ref-195" class="citation-mark"><sup>195</sup></a></li>
            <li>Природа возникновения;<a href="#citation-196" id="ref-196" class="citation-mark"><sup>196</sup></a></li>
            <li>Природа явления;<a href="#citation-197" id="ref-197" class="citation-mark"><sup>197</sup></a></li>
            <li>Природа признака;<a href="#citation-198" id="ref-198" class="citation-mark"><sup>198</sup></a></li>
            <li>Природа великих первоэлементов;<a href="#citation-199" id="ref-199" class="citation-mark"><sup>199</sup></a></li>
            <li>Природа причины;</li>
            <li>Природа условий;<a href="#citation-200" id="ref-200" class="citation-mark"><sup>200</sup></a></li>
            <li>Природа завершённости<a href="#citation-201" id="ref-201" class="citation-mark"><sup>201</sup></a> — седьмая.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует семь видов<a href="#citation-202" id="ref-202" class="citation-mark"><sup>202</sup></a> высшей истины (<em>paramārtha</em>):</li>
            <li>1. Сфера ума;<a href="#citation-203" id="ref-203" class="citation-mark"><sup>203</sup></a></li>
            <li>2. Сфера знания;<a href="#citation-204" id="ref-204" class="citation-mark"><sup>204</sup></a></li>
            <li>3. Сфера мудрости;<a href="#citation-205" id="ref-205" class="citation-mark"><sup>205</sup></a></li>
            <li>4. Сфера двух воззрений;<a href="#citation-206" id="ref-206" class="citation-mark"><sup>206</sup></a></li>
            <li>5. Сфера, превосходящая два воззрения;<a href="#citation-207" id="ref-207" class="citation-mark"><sup>207</sup></a></li>
            <li>6. Сфера последовательного прохождения ступеней Сынов Победителя;<a href="#citation-208" id="ref-208" class="citation-mark"><sup>208</sup></a></li>
            <li>7. Сфера личного постижения Татхагаты.<a href="#citation-209" id="ref-209" class="citation-mark"><sup>209</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Это, Махамати, и есть сердцевина учения о высшей истине собственной природы явлений, принадлежащая Татхагатам, Архатам и Совершенно Пробуждённым прошлого, будущего и настоящего. Обладая ею, Татхагаты посредством благородного ока мудрости (<em>āryeṇa prajñācakṣuṣā</em>) устанавливают наивысшие мирские и запредельные дхармы в их единичных и общих признаках. И устанавливают они их так, чтобы эти установления не совпадали с ложными воззрениями и утверждениями тиртхиков.</li>

            <li>Как же, Махамати, возникает это совпадение с ложными воззрениями тиртхиков? Оно возникает из-за неспособности сознаний постичь, что объекты собственного ума суть умопостроения (<em>vikalpa</em>). Махамати, из-за неспособности войти в постижение того, что всё есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>), невежественные обыватели становятся приверженцами двух воззрений  о высшей истине (<em>paramārtha</em>), как собственной природе (<em>svabhāva</em>) существования и несуществования.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.6 (О преодолении учения об уничтожении и утверждении пути только-ума)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
                <li>Кроме того, Махамати, Я разъясню: [путь] прекращения страданий трёх миров, порождённых различениями; прекращение неведения, жажды и кармических условий; а также созерцание объектов как майи — как лишь воспринимаемого собственным умом (<em>svacitta-dṛśya</em>).</li>

                <li>Махамати, те шраманы или брахманы, которые полагают, что [явления] возникают, не существуя прежде, и проявляются через причины, плоды, самостоятельные сущности (<em>dravya</em>), время и условия, и которые желают видеть возникновение и пребывание <em>скандх</em>, <em>дхату</em> и <em>аятан</em>, а затем — их исчезновение, такие люди, Махамати, становятся приверженцами учения об уничтожении (<em>ucchedavāda</em>).<a href="#citation-210" id="ref-210" class="citation-mark"><sup>210</sup></a></li>

                <li>Они разрушают [учение о] преемственности (<em>saṃtati</em>), действии, возникновении и распаде, бытии, Нирване, Пути, карме, плоде и истине. Почему это так? Потому что они лишены прямого восприятия (<em>pratyakṣa</em>) и не видят изначальной основы.<a href="#citation-211" id="ref-211" class="citation-mark"><sup>211</sup></a></li>

                <li>Подобно тому, Махамати, как черепки разбитого кувшина не могут исполнять назначение кувшина, и как сожжённое семя не может дать ростка, так же и <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em>, которые прекратились, прекращаются или прекратятся, не обладают непрерывным развёртыванием (<em>nairantarya-pravṛtti</em>),<a href="#citation-212" id="ref-212" class="citation-mark"><sup>212</sup></a> поскольку их причиной является лишь различающее видение воспринимаемого собственным умом.</li>

                <li>Если бы, Махамати, согласно убеждению [тиртхиков], основанных [лишь] на вере, возникновение сознаний из небытия (<em>abhūtvā</em>) через действие условия тройного сочетания (<em>trisaṃgati</em>),<a href="#citation-213" id="ref-213" class="citation-mark"><sup>213</sup></a> было бы возможным, тогда, Махамати, могли бы возникать и черепашьи волосы, а масло — извлекаться из песка. В таком случае, Махамати, рушились бы их собственные тезисы и нарушался бы установленный порядок; учения тех, кто утверждает бытие и небытие действия, кармы и деятеля, становились бы бессмысленными. И всё же, Махамати, у них имеется собственное наставление о действии условия тройного сочетания. Пребывая на уровне рассудочного мышления (<em>tarka-bhūmi</em>), движимые отпечатками пороков собственных воззрений, они — посредством рассуждения (<em>yukti</em>), предания (<em>āgama</em>) и собственных признаков причины и плода — утверждают существование признаков прошлого, будущего, настоящего, существующего и несуществующего. Так, Махамати, невежды, укушенные ложными воззрениями и обладающие извращённым умом, называют «высшим учением» то, что создано такими же невеждами.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Те же шраманы и брахманы, Махамати, кто видят [этот кажущийся плотным (<em>ghana</em>)] мир как лишённый собственной природы (<em>niḥsvabhāva</em>), нерождённый (<em>anutpāda</em>), подобный огненному колесу, городу гандхарвов, <em>майе</em>, мареву, отражению луны в воде и сновидению; кто осознают, что внешнее воспринимаемое — лишь различения собственного ума, обусловленные безначальным понятийным разрастанием; кто свободны от воображаемых имён (<em>abhidhāna</em>), признаков, обозначаемого и обозначающего (<em>lakṣya-lakṣaṇa</em>) и обозначаемых объектов (<em>abhidheya</em>); кто созерцают сферу без ментальных образов (<em>nirābhāsa-gocara</em>), свободную от двойственности схватываемого и схватывающего, вне возникновения, пребывания и распада — ту сферу, что есть лишь проявление собственного ума, — такие бодхисаттвы-махасаттвы, Махамати, в скором времени достигнут равенства сансары и нирваны.</li>

                <li>Обладая великим состраданием и искусными средствами, действуя без усилий (<em>anābhoga</em>), они видят всех существ как магические отражения. Свободные от условий, порождающих представление о внешнем, они понимают: вне ума ничего не существует. Следуя беззнаковому благословению (<em>animitta-adhiṣṭhāna</em>) и постепенно проходя ступени и сферы <em>самадхи</em>, они осознают три мира как собственный ум и обретают <em>самадхи, подобное майе</em> (<em>māyopama-samādhi</em>).</li>

                <li>Проникнув в сферу без ментальных образов, которая есть лишь их собственный ум, они достигают пребывания в Совершенной Мудрости (<em>prajñāpāramitā-vihāra</em>).<a href="#citation-214" id="ref-214" class="citation-mark"><sup>214</sup></a> Свободные от йоги возникновения и деяния (<em>utpādakriyāyogavirahita</em>), они обретают Тело Татхагаты — подобное ваджрному отражению <em>самадхи</em> (<em>samādhi-vajra-bimba</em>), сопровождаемое проявлениями таковости (<em>tathatā-nirmāṇa</em>), украшенное <em>силами</em>, <em>сверхзнаниями</em>, <em>владычеством</em> и состраданием, достигающее всех земель Будд и обителей тиртхиков (<em>tīrthyāyatana</em>), свободное от ума (<em>citta</em>), <em>манаса</em> (<em>manas</em>) и различающего сознания (<em>vijñāna</em>) — через поворот основы (<em>parāvṛtti</em>).</li>

                <li>Посему, Махамати, бодхисаттвы-махасаттвы, стремящиеся к обретению Тела Татхагаты, должны пребывать свободными от <em>скандх</em>, <em>дхату</em>, <em>аятан</em>, ума (<em>citta</em>), причин, условий, йоги деяния (<em>kriyāyoga</em>), возникновения, пребывания и распада, различения (<em>vikalpa</em>) и понятийного разрастания (<em>prapañca</em>), следуя лишь пути только-ума (<em>cittamātra</em>).</li>

                <li>Тот, кто видит тройственное бытие как порождение отпечатков (<em>vāsanā</em>) различений пагубной косности (<em>dauṣṭhulya</em>) безначального понятийного разрастания — тот, благодаря памятованию о не-возникновении и о ступенях Будд, свободных от ментальных образов, вступает в сферу личного благородного постижения Дхармы. Такой [бодхисаттва] обретает власть над собственным умом и входит на путь действия без усилий.<a href="#citation-215" id="ref-215" class="citation-mark"><sup>215</sup></a></li>

                <li>Подобно драгоценному камню, принимающему все цвета (<em>viśvarūpa-maṇi</em>), он проникает в движения умов живых существ с помощью своих тончайших тел-проявлений (<em>sūkṣma-nirmāṇa-vigraha</em>). Утвердившись в понимании того, что всё есть только-ум (<em>cittamātra</em>), он ведет [других] по ступеням и путям [<em>самадхи</em>]. Посему, Махамати, бодхисаттве-махасаттве следует быть искусным в собственном высшем учении.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.7 (О признаках ума, манаса и виджнян)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>И вновь Махамати обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-3 ml-2">
                <li>Пусть Благословенный изложит мне драгоценный цветок учения Дхармы (<em>dharmaparyāya</em>) — учение о признаках ума (<em>citta</em>), <em>манаса</em> (<em>manas</em>) и различающего сознания (<em>vijñāna</em>), о пяти <em>дхармах</em> и трёх <em>свабхавах!</em></li>

                <li>Это — путь, по которому следуют Будды и бодхисаттвы; это — средство освобождения от уз, привязывающих к сфере видимого, что есть лишь проявление собственного ума.<a href="#citation-216" id="ref-216" class="citation-mark"><sup>216</sup></a></li>

                <li>Провозгласи же <strong><em>Сердце всех наставлений Будды</em></strong>, разрывающее все словесные и логические определения истины!</li>

                <li>Поведай о волнах [активных сознаний], возникающих в океане <em>Алайи</em><a href="#citation-217" id="ref-217" class="citation-mark"><sup>217</sup></a> и о Теле Дхармы Татхагаты — ради бодхисаттв, пребывающих здесь, на горе Малая в граде Ланка!</li>
            </ul>
        </blockquote>
        <p>Благословенный так ответил бодхисаттве-махасаттве Махамати:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
                <li>Махамати, зрительное сознание приходит в движение по четырём причинам. Каковы эти четыре? А именно:</li>
                <li>- неведение того, что схватываемое есть лишь проявление собственного ума;<a href="#citation-218" id="ref-218" class="citation-mark"><sup>218</sup></a></li>
                <li>- привязанность к отпечаткам (<em>vāsanā</em>) форм, порождённым пагубным безначальным понятийным разрастанием (<em>prapañca</em>);<a href="#citation-219" id="ref-219" class="citation-mark"><sup>219</sup></a></li>
                <li>- собственная природа сознания как таковая;<a href="#citation-220" id="ref-220" class="citation-mark"><sup>220</sup></a></li>
                <li>- стремление к восприятию разнообразных форм и признаков.<a href="#citation-221" id="ref-221" class="citation-mark"><sup>221</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
                <li>В силу этих четырёх причин, Махамати, из <em>Алайя-виджняны</em> — подобной внутреннему потоку — возникают волны активных сознаний.<a href="#citation-222" id="ref-222" class="citation-mark"><sup>222</sup></a> Подобно тому, Махамати, как возникает зрительное сознание, так же во всех органах чувств, в атомах и порах кожи одновременно или последовательно разворачиваются объекты — подобно отражениям в зеркале или волнам в океане, когда его возмущает ветер. Махамати, волны океана ума вздымаются ветром объектов. Эти пять групп чувственных сознаний непрерывны в своих причинах, действиях и признаках, каждое действует в собственной области, прочно спаяны в своих характеристиках кармы и рождения и не распознают собственной природы.</li>

                <li>Вместе с этими пятью группами сознаний развёртывается <em>мановиджняна</em>, которая определяет признаки объектов и причин. Её тело рождено теми же причинами. И ни у пяти сознаний, ни у <em>мановиджняны</em> не возникает мысли: «Мы являемся причинами друг друга; мы движимы привязанностью к различениям того, что есть лишь проявление собственного ума». При этом [сознания] приходят в движение, нераздельные в своих признаках, когда вовлечены в определение объектов познания.</li>

                <li>Их движение таково, что даже у йогина, вошедшего в <em>самадхи</em>, тончайшее течение отпечатков (<em>vāsanā</em>) остаётся непознанным. Йогины думают: «Мы войдём в <em>самадхи</em>, прекратив деятельность сознаний». Однако они входят в <em>самадхи</em>, не прекратив деятельность сознаний, ибо семена-отпечатки (<em>vāsanā-bīja</em>) не уничтожены. Сознания кажутся им прекращёнными лишь потому, что отсутствует восприятие развёртывающихся объектов.</li>

                <li>Настолько тонок, Махамати, ход и движение <em>Алайя-виджняны</em>, что его нелегко постичь кому-либо, кроме Татхагат и бодхисаттв, утверждённых на ступенях.</li>

                <li>Прочим же — шравакам, пратьекабуддам и йогинам-тиртхикам — не под силу постичь его, даже обладая силой сосредоточения и мудрости.</li>

                <li>Лишь те йогины — высшие, средние или низшие — что пребывают в лесных чащах и пещерах, свободные от многообразия понятий и различений того, что есть лишь проявление собственного ума, способны постичь признаки ступеней, мастерство в мудрости и знании, накопить бесконечные корни благого, и обрести <em>посвящение</em>, <em>власти</em>, <em>силы</em> и <em>самадхи</em> в бесконечных мирах Победителей.</li>

                <li>Только в сопровождении добрых друзей (<em>kalyāṇa-mitra</em>) и Победителей, Махамати, возможно пересечь океан бытия — этот круговорот различений ума (<em>citta</em>), <em>манаса</em> (<em>manas</em>) и сознания (<em>vijñāna</em>), порождённый кармой, жаждой и неведением. Посему, Махамати, йогин должен усердствовать в йоге под руководством добрых друзей и Победителей.</li>
            </ul>
        </blockquote>
            <p>Затем Благословенный провозгласил такие стихи:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>99. Подобно тому как волны океана, гонимые ветром,</li>
                <li>вздымаются в танце, и нет им прекращения, —</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>100. Так и поток <em>Алайи</em>,</li>
                <li>вечно движимый ветрами объектов (<em>viṣaya</em>),</li>
                <li>разворачивается в танце многообразных</li>
                <li>«волн-сознаний» (<em>taraṃga-vijñāna</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>101. Подобно тому как синева, краснота, солёность,</li>
                <li>белизна раковины, белизна молока, сладость сахара,</li>
                <li>ароматы плодов и цветов, лучи солнца —</li>
                <li>неотделимы от своей основы,</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>102. и как волны океана не считаются</li>
                <li>ни отличными от него, ни тождественными ему,</li>
                <li>так и семь сознаний соединены с Умом.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>103. Изменчивость (<em>pariṇāma</em>) океана</li>
                <li>есть многообразие волн;</li>
                <li>точно так же и <em>Алайя</em></li>
                <li>разворачивается в многообразии того,</li>
                <li>что зовётся «сознаниями» (<em>vijñānākhya</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>104. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и сознание (<em>vijñāna</em>)</li>
                <li>различаются лишь ради указания признаков.</li>
                <li>Все восемь [сознаний] неразличимы по своим признакам:</li>
                <li>нет ни определяемого (<em>lakṣya</em>), ни признака (<em>lakṣaṇa</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>105. Как между океаном и волнами</li>
                <li>нет обосабливающего их отличия,</li>
                <li>точно так же между различающими сознаниями</li>
                <li>и умом (<em>vijñānānāṃ tathā cittaiḥ</em>)</li>
                <li>не обнаруживается никакого</li>
                <li>видоизменения (<em>pariṇāma</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>106. Умом (<em>citta</em>) накапливается карма,</li>
                <li><em>манасом</em> — различается,</li>
                <li>[умственной] виджняной познаётся [объект],</li>
                <li>а пятью [чувственными сознаниями]</li>
                <li>выстраивается воспринимаемое.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>107. Сознание представляется людям</li>
                <li>как синее и красное;</li>
                <li>скажи, Махамати, почему [тогда] говорится</li>
                <li>о сходстве волн и ума?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>108. Воистину, в самих волнах</li>
                <li>нет синевы или красноты!</li>
                <li>Ум описывается как развёртывание (<em>vṛtti</em>)</li>
                <li>лишь ради [пояснения] признаков для незрелых.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>109. Сам же ум (<em>svacitta</em>) — без развёртывания (<em>vṛtti</em>),</li>
                <li>ибо он свободнен от схватываемого (<em>grāhya</em>).</li>
                <li>Если бы было схватываемое,</li>
                <li>тогда возникло бы и схватывающее (<em>grāha</em>) —</li>
                <li>подобно волнам [и океану].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>110. <em>Виджняна</em> проявляется людям</li>
                <li>как «тело», «объекты восприятия» и «мир-вместилище».<a href="#citation-223" id="ref-223" class="citation-mark"><sup>223</sup></a></li>
                <li>Поэтому его развёртывание видится</li>
                <li>подобной волнам [океана].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>111. Океан видится танцующим в облике волн.</li>
                <li>Почему же развёртывание (<em>vṛtti</em>) <em>Алайи</em></li>
                <li>не постигается рассудком  (<em>buddhi</em>)?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>112. Из-за слабости рассудка у незрелых (<em>bāla</em>)</li>
                <li>сходство <em>Алайи</em> с океаном</li>
                <li>и его развёртывания с волнами</li>
                <li>разъясняется через это сравнение.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Махамати спросил:]</li>
                <li>113. — Подобно тому как солнце восходит над миром,</li>
                <li>освещая низкое, среднее и высокое,</li>
                <li>так и Ты, Светоч Мира,</li>
                <li>излагаешь истинную природу (<em>tattva</em>) незрелым.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>114. Но утвердив [учеников] в дхармах,</li>
                <li>почему не излагаешь её прямо?</li>
                <li>Если же Ты изрекаешь её словами,</li>
                <li>то в самом Уме Истины не обнаруживается.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>[Благословенный ответил:]</li>
                <li>115. — Как волны в океане, отражения в зеркале</li>
                <li>образы во сне видятся одновременно (<em>yugapad</em>),</li>
                <li>так и ум в своей собственной сфере (<em>svagocara</em>)</li>
                <li>[проявляется сразу].</li>
               </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>116. Но из-за неполноты (<em>vaikalyāt</em>) условий</li>
                <li>[восприятие] разворачивается</li>
                <li>последовательно (<em>kramavṛttyā pravartate</em>):</li>
                <li>сознанием (<em>vijñāna</em>) распознают,</li>
                <li><em>манас</em> — мнит и оценивает (<em>manasā manyate punaḥ</em>).</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>117. Пяти чувственным сознаниям видимое</li>
                <li>является [как бы] одновременно,</li>
                <li>но в созерцательном сосредоточении (<em>samāhita</em>)</li>
                <li>последовательности нет.</li>
                <li>Как опытный живописец или его ученик</li>
                <li>подбирает те или иные краски ради создания картины,</li>
                <li>так и Я излагаю наставление.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>118. Сама картина не обнаруживается</li>
                <li>ни в красках, ни в холсте, ни в сосуде [с красками];</li>
                <li>но ради привлечения существ</li>
                <li>картина создаётся при помощи красок.</li>
            </ul>

            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>119. Хотя наставление изменчиво (<em>vyabhicāra</em>),</li>
                <li>истина (<em>tattva</em>) свободна от букв (<em>akṣara</em>).</li>
                <li>Утвердив [учеников] в дхармах,</li>
                <li>Я указываю йогинам истину (<em>tattva</em>).</li>
                <li>Истина постигается</li>
                <li>лишь внутренним опытом (<em>pratyātmagatikam</em>),</li>
                <li>свободна от измышляемого (<em>kalpya</em>)</li>
                <li>и измышления (<em>kalpana</em>).</li>
                <li>Я излагаю это сыновьям Победителя;</li>
                <li>это наставление не для незрелых.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>120. Подобно тому как многообразная иллюзия (<em>māyā</em>)</li>
                <li>видима, но не обнаруживается,</li>
                <li>так и наставление предстаёт многообразным,</li>
                <li>хотя излагается безошибочно (<em>avyabhicāriṇī</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>121. Ведь то, что является наставлением для одного,</li>
                <li>не является наставлением для другого.</li>
                <li>Как врач назначает лекарство</li>
                <li>каждому больному сообразно его недугу, так и Будды</li>
                <li>провозглашают существам о «только-уме» (<em>cittamātra</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>122. Это не сфера рассудочных логиков (<em>tārkika</em>)</li>
                <li>и не сфера шраваков.</li>
                <li>То, что излагают Владыки, —</li>
                <li>есть сфера постигаемого</li>
                <li>лишь внутренним опытом (<em>pratyātmagatigocara</em>).</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.8 (О трёх признаках благородного знания)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
                <li>И ещё, Махамати, бодхисаттве, желающему полностью постичь область, где выстраиваются понятия «схватываемое» и «схватывающий», которые являются лишь проявлением собственного ума, следует избегать сборищ (<em>saṃgaṇikā</em>), быть свободным от помехи сонливости и лени (<em>middha-nivaraṇa</em>), неустанно пребывать в йоге бодрствования в первую, среднюю и последнюю стражу ночи, быть свободным от признаков доктрин тиртхиков (<em>kutīrthya</em>) и их повествований (<em>ākhyāyikā</em>), а также колесниц шраваков и пратьекабудд. Бодхисаттве-махасаттве следует вступить на путь [постижения] различений и признаков воспринимаемого собственным умом.</li>

                <li>И ещё, Махамати, бодхисаттве-махасаттве, утвердившись в понимании признаков ума, сознания и мудрости (<em>prajñā</em>), следует практиковать йогу трёх признаков высшего благородного знания (<em>āryajñāna</em>). Каковы же эти три признака высшего благородного знания, Махамати? Это:</li>
                <li>— признак отсутствия образов (<em>nirābhāsa</em>),<a href="#citation-224" id="ref-224" class="citation-mark"><sup>224</sup></a></li>
                <li>— признак опоры на силу благого воздействия (<em>adhiṣṭhāna</em>) собственных обетов (<em>svapraṇidhāna</em>) всех прежних Будд;<a href="#citation-225" id="ref-225" class="citation-mark"><sup>225</sup></a></li>
                <li>— признак стези благородного знания, постигаемого лишь внутренним опытом (<em>pratyātmārya-jñāna-gati</em>).<a href="#citation-226" id="ref-226" class="citation-mark"><sup>226</sup></a></li>

                <li>Обретя их, йогин оставляет признаки ума, мудрости и знания (<em>citta, prajñā, jñāna</em>), подобно тому, как отбрасывают хромого осла (<em>khañja-gardabha</em>).<a href="#citation-227" id="ref-227" class="citation-mark"><sup>227</sup></a> Достигнув восьмой ступени сынов Победителя, он всецело входит в йогу этих трёх высших признаков.</li>

                <li>В отношении этого, Махамати, признак отсутствия образов развёртывается благодаря распознаванию признаков всех шраваков, пратьекабудд и тиртхиков.</li>

                <li>Признак благословения развёртывается благодаря благому воздействию собственных обетов прежних Будд.</li>
                <li>Признак личного благородного постижения развёртывается благодаря:</li>
                <li>- отсутствию привязанности к признакам всех дхарм,</li>
                <li>- обретению тела в <em>самадхи, подобном майе</em>,<a href="#citation-228" id="ref-228" class="citation-mark"><sup>228</sup></a></li>
                <li>- и вхождению в сферу деятельности ступеней Будды.</li>

                <li>Это, Махамати, — три признака Благородных. Обладая этими тремя признаками, Благородные достигают сферы личного благородного постижения. Посему, Махамати, следует практиковать йогу трёх признаков благородного знания.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">
        Подглава 2.9 (Исследование основы благородного знания)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
                <li>И тогда бодхисаттва-махасаттва Махамати, вновь постигнув ход мыслей и устремлений собрания бодхисаттв и поддерживаемый благим воздействием (<em>adhiṣṭhāna</em>) всех Будд, обратился к Благословенному с вопросом о наставлении в Дхарме, именуемом «Исследование основы благородного знания»:<a href="#citation-229" id="ref-229" class="citation-mark"><sup>229</sup></a></li>
            </ul>
            <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
                <li>Пусть Благословенный изложит мне наставление «Исследование основы благородного знания», раскрывающее различия ста восьми положений. Опираясь на него, Татхагаты, Архаты, Совершенно Пробуждённые разъясняют различия путей воображаемой природы (<em>parikalpita-svabhāva</em>) бодхисаттвам-махасаттвам, чьи умы всё ещё пребывают в собственных и общих признаках (<em>lakṣaṇa</em>).<a href="#citation-230" id="ref-230" class="citation-mark"><sup>230</sup></a> Благодаря ясному распознаванию этих путей воображаемой природы, бодхисаттвы</li>
                <li>• полностью очистят своё понимание отсутствия «я» в личности и в дхармах;<a href="#citation-231" id="ref-231" class="citation-mark"><sup>231</sup></a></li>
                <li>• станут искусными в прохождении ступеней;</li>
                <li>• превзойдут блаженство <em>дхьян</em>, <em>самадхи</em> и <em>самапатти</em> всех шраваков, пратьекабудд и тиртхиков;</li>
                <li>• вступят в развёртывание стези непостижимой сферы Татхагат, свободной от привязанности к пяти <em>дхармам</em> и трём <em>природам</em>.</li>
                <li>Так они обретут  Тело Дхармы Татхагаты — Дхармакаю, чья природа прочно связана с мудростью и знанием, свободное от привязанности к иллюзорной сфере объектов и способное проникать во все поля Будд, обитель Тушита и высший мир Акаништха.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.10 (О бытии и небытии)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Здесь, Махамати, некоторые тиртхики и нетиртхики, упорно придерживающиеся воззрения небытия (<em>nāstitva</em>),<a href="#citation-232" id="ref-232" class="citation-mark"><sup>232</sup></a> вследствие истощения причины различающего рассудка<a href="#citation-233" id="ref-233" class="citation-mark"><sup>233</sup></a> и из-за отсутствия независимой природы, умозрительно полагают: «Рогов у зайца нет» и [заключают]: «Подобно тому, как нет рогов у зайца, так и все явления (<em>bhāva</em>) лишены основы».<a href="#citation-234" id="ref-234" class="citation-mark"><sup>234</sup></a></li>

            <li>Другие же, Махамати, видя особенности первоэлементов, качеств, атомов, вещества, формы и взаиморасположения, и будучи привязанными к утверждению, что «рогов у зайца нет», умозрительно утверждают: «Но рога у коровы-то есть!»<a href="#citation-235" id="ref-235" class="citation-mark"><sup>235</sup></a></li>

            <li>Они, Махамати, впали в воззрения двух крайностей, поскольку их умы не утвердились в понимании только-ума (<em>cittamātra</em>). Поддерживая построение понятий (<em>vikalpa</em>) в сфере собственного ума, они лишь укрепляют эти крайности.</li>

            <li>Махамати, в одном лишь построении понятий (<em>vikalpa</em>) о «теле», «объектах наслаждения» и «мире-вместилища», не следует умозрительно наделять рога зайца признаками ни «существующего», ни  «несуществующего». Точно так же, Махамати, не следует наделять все явления (<em>bhāva</em>) признаками «существующего» или «несуществующего».</li>

            <li>Те же, Махамати, кто свободен от [двойственности] бытия и небытия, не выстраивают [понятие]: «Рогов у зайца нет». Им не следует измышлять отсутствие рогов у зайца, поскольку [идея] небытия имеет своей причиной опору на [идею] бытия.<a href="#citation-236" id="ref-236" class="citation-mark"><sup>236</sup></a></li>

            <li>Более того, Махамати, поскольку при тщательном исследовании вплоть до мельчайших частиц<a href="#citation-237" id="ref-237" class="citation-mark"><sup>237</sup></a> никакая реальная основа (<em>vastu</em>) не обнаруживается, не следует измышлять: «Рога у коровы есть», ибо это исключено из сферы благородного знания (<em>āryajñāna-gocara</em>).</li>
        </ul>
        </blockquote>

        <p>Тогда бодхисаттва-махасаттва Махамати сказал Благословенному:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Не так ли, Благословенный: видя признак не-развёртывания (<em>apravṛtti-lakṣaṇa</em>) различения, мы заключаем, что его небытие (<em>nāstitva</em>) обусловлено [соотнесением с] этим самым отсутствием развёртывания?<a href="#citation-238" id="ref-238" class="citation-mark"><sup>238</sup></a></li>
        </ul>
        </blockquote>

        <p>Благословенный ответил:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Нет, Махамати, его небытие не обусловлено отсутствием развёртывания различения. Почему? Потому что само различение является причиной своего развёртывания. Ведь различение, Махамати, развёртывается, опираясь на [образ] рогов. Поскольку оно разворачивается, опираясь на [эту] основу, то из-за наличия этой причинной опоры и в силу того, что оно не является ни отличным от неё, ни не-отличным, небытие рогов зайца не может быть установлено через соотнесение [с чем-либо].</li>

            <li>Если же оно было бы не-отличным от них, то из-за необнаружимости при разложении вплоть до частиц различение, будучи неотличным, также отсутствовало бы.</li>

            <li>Поскольку же оба этих случая (бытие и небытие) невозможны, то через соотнесение с чем и для кого возникает «небытие»?</li>

            <li>Посему, Махамати, не следует воображать небытие рогов зайца через соотнесение с их бытием. Из-за порочности самой причины (<em>viṣama-hetu</em>)<a href="#citation-239" id="ref-239" class="citation-mark"><sup>239</sup></a> утверждение о бытии и небытии не находит подтверждения у сторонников этих воззрений.</li>

            <li>Другие же тиртхики, Махамати, привязанные к формам, причинам и очертаниям и не искусные в различении природы пространства (<em>ākāśa</em>), измышляют, будто форма отделена от пространства. Но само пространство, Махамати, и есть форма. Вследствие  взаимопроникновения формы и первоэлементов, сама форма и есть пространство. Различие между формой и пространством следует понимать лишь как условное разделение на «поддерживаемое» (<em>ādheya</em>) и «поддерживающее» (<em>ādhāra</em>), «распадающееся» (<em>vyaya</em>) и «пребывающее» (<em>sthāna</em>).</li>

            <li>Первоэлементы, Махамати, проявляясь, различаются собственными признаками и кажутся не имеющими опоры в пространстве, но в них нет того, что не было бы пространством.</li>

            <li>Точно так же, Махамати, рога зайца [кажутся] существующими лишь в соотнесении с рогами коровы. Но если рога коровы разобрать на частицы, а те — на ещё более мелкие частицы, то они не сохранят признак «частицы». С чем же тогда соотносить «небытие»? Если же [соотносить] с иной основой (<em>vastu</em>), то и она [при анализе] окажется такой же.<a href="#citation-240" id="ref-240" class="citation-mark"><sup>240</sup></a></li>
        </ul>
        </blockquote>

        <p>Затем Благословенный вновь обратился к бодхисаттве-махасаттве Махамати:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Тебе, Махамати, а также и другим бодхисаттвам следует быть свободными от построения понятий, основанных на [ложных] воззрениях относительно рогов зайца и коровы, пространства, формы и прочего. Вам следует направлять ум вслед за пониманием воспринимаемого собственным умом.<a href="#citation-241" id="ref-241" class="citation-mark"><sup>241</sup></a></li>

            <li>Во всех землях Будд, где собираются Сыны Победителя, тебе надлежит давать наставления по этой йоге воспринимаемого собственным умом.<a href="#citation-242" id="ref-242" class="citation-mark"><sup>242</sup></a></li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>123. Воспринимаемого не обнаруживается;</li>
                <li>ум же развёртывается </li>
                <li>из воспринимаемого (<em>cittaṃ dṛśyātpravartate</em>).</li>
                <li>То, что представляется существам</li>
                <li>как тело, [объекты] наслаждения и обитель,</li>
                <li>именуется <em>Алайей</em>.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>124. Ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и различающее сознание (<em>vijñāna</em>),</li>
                <li><em>три природы</em>, <em>пять дхарм</em> и двойное отсутствие «я» —</li>
                <li>вот что провозглашают Владыки как чистое [учение].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>125. Подобно [понятиям] «длинное» и «короткое»,</li>
                <li>всё возникает лишь в соотношении.</li>
                <li>Нет самостоятельного доказательства существования;</li>
                <li>бытие устанавливается </li>
                <li>лишь в противоположности небытия [и наоборот].</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>126. Если разлагать форму до мельчайших частиц,</li>
                <li>то в конце концов нельзя будет вообразить никакую форму.</li>
                <li>Учение о «только-уме» (<em>cittamātra</em>) не постигается теми,</li>
                <li>кто придерживается ложных воззрений.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>127. То, что Владыки излагают как область</li>
                <li>личного постижения (<em>pratyātmagati-gocara</em>),</li>
                <li>непостижимо для умозрительных логиков (<em>tārkika</em>)</li>
                <li>и недоступно постижению шраваков.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.11 (Постепенное и мгновенное очищение)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <ul class="list-none mb-8 pl-2 space-y-1 ml-8">
            <li>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному, стремясь к очищению потока воспринимаемого собственным умом (<em>svacitta-dṛśya-dhārā</em>):</li>
        </ul>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>Как, Благословенный, очищается поток воспринимаемого собственным умом: мгновенно или постепенно?</li>
            </ul>
        </blockquote>

        <p>Благословенный ответил:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Постепенно, Махамати, очищается поток воспринимаемого собственным умом, а не мгновенно. Подобно тому как плоды манго созревают постепенно, а не мгновенно, так и поток воспринимаемого собственным умом у существ очищается постепенно. Подобно тому как гончар изготавливает сосуды постепенно, а не мгновенно, так и Татхагата очищает этот поток у существ постепенно. Подобно тому как травы, кустарники, целебные растения и деревья вырастают из земли постепенно, а не мгновенно, так и Татхагата очищает этот поток у существ постепенно. Подобно тому как искусство смеха, танца, пения, игры на струнных инструментах, письма и рисования обретается постепенно, а не мгновенно, так и Татхагата очищает поток воспринимаемого собственным умом у всех существ постепенно.</li>

            <li>Но также, Махамати, Татхагата одновременно очищает поток воспринимаемого собственным умом у всех существ, [делая его] свободным от различений (<em>nirvikalpa</em>) и выводящим за пределы сферы образов-знаков (<em>nirābhāsa-gocara</em>). Подобно тому как в зеркале одновременно и без различений проявляются все отражения форм, так и Татхагата одновременно очищает поток [восприятия] у существ. Подобно тому как диски луны и солнца одновременно освещают лучами все образы форм, так и Татхагата одновременно открывает сферу непостижимого знания Победителей тем существам, что очищены от грубых привычных следов. Подобно тому как сознание-хранилище (<em>ālaya-vijñāna</em>) одновременно проявляет тело, опору-вместилище и объекты пользования как воспринимаемое собственным умом, так и Будда-излияние (<em>niṣyanda-buddha</em>) <a href="#citation-243" id="ref-243" class="citation-mark"><sup>243</sup></a> мгновенно приводит существ к зрелости и дарует йогинам йогическое сосредоточение на пребывании во дворце-обители Акаништхи.  Подобно тому как Будда Таковости (<em>dharmatā-buddha</em>) одновременно сияет лучами [тел] излияния и воплощения, так и признак Дхармы личного благородного постижения одновременно сияет через преодоление ложных воззрений о бытии и небытии.</li>
        </ul>
            </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.12 (О трёх Буддах и их учении)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, Будда излияния дхармовости (<em>dharmatāniṣyandabuddha</em>) излагает [учение] о том, что все дхармы — в их собственных и общих признаках — связаны с причинами и признаками отпечатков (<em>vāsanā</em>) того, что воспринимается собственным умом (<em>svacitta-dṛśya</em>). Он учит о необнаружении реальной основы (<em>anupalabdhi</em>) у привязанности к воображаемой природе (<em>parikalpita-svabhāva</em>), не имеющей собственной сущности, подобно множеству иллюзорных фигур на сцене магического представления.</li>

            <li>Далее, Махамати, проявление воображаемой природы возникает из привязанности к зависимой природе (<em>paratantra-svabhāva</em>). Это подобно тому, как магическая фигура, созданная из травы, дерева, кустарника и лиан благодаря действию человека, владеющего искусством иллюзии, принимает облик любого существа; хотя она кажется телом живого существа, она не является им [по сути].</li>

            <li>Так же, Махамати, на основе зависимой природы (взаимообусловленных процессов) воображаемая природа являет разнообразие признаков ума, порождённого различениями. Разворачивая различения из отпечатков привязанности к признакам умозрительных объектов (<em>vastu-parikalpa</em>) ум сам принимает облик признаков воображаемой природы. Это, Махамати, — поучение Будды излияния.</li>

            <li>Будда Таковости (<em>dharmatābuddha</em>), напротив, утверждает состояние личного благородного постижения (<em>pratyātmāryagati</em>), свободное от любых признаков собственной природы ума (<em>citta-svabhāva</em>).</li>

            <li>Будда воплощения (<em>nirmāṇabuddha</em>), Махамати, разъясняет тонкости практики: даяние (<em>dāna</em>), нравственность (<em>śīla</em>), <em>дхьяны</em>, [методы] сосредоточения (<em>samādhi</em>) и разнообразные мудрости и знания (<em>prajñā-jñāna</em>), <em>скандхи</em>, <em>дхату</em>, <em>аятаны</em>, пути освобождения (<em>vimokṣa</em>) и признаки путей развёртывания сознаний (<em>vijñāna-gati-lakṣaṇa</em>). Он также разъясняет тиртхикам признаки выхода за пределы мира форм.</li>

            <li>Будда Таковости, Махамати, — безопорный (<em>nirālamba</em>). Он свободен от всех опор, действий, органов чувств, способов познания и признаков. Он недоступен для тех, кто захвачен признаками «я», как это бывает у невежд, шраваков и тиртхиков.</li>

            <li>Посему, Махамати, следует усердствовать в йоге личного благородного постижения и пребывать в видении, направленном на прекращение [удержания] признаков воспринимаемого собственным умом.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.13 (Особенности колесницы шраваков)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, существуют два вида признаков пути шраваков: признаки личного благородного постижения (<em>pratyātmāryādhigama-lakṣaṇa</em>), и признаки упорной привязанности к различению (<em>vikalpa</em>) собственной природы явлений.<a href="#citation-244" id="ref-244" class="citation-mark"><sup>244</sup></a></li>

            <li>Каковы, Махамати, признаки личного благородного постижения у шраваков? Благодаря полному знанию истинного положения дел (<em>yathābhūtaparijñānāt</em>), при котором затихает активность ума через успокоение, возникающее из бесстрастия к истинам, чьей сферой являются пустота, отсутствие «я» (<em>anātma</em>), страдание и непостоянство, а также через постижение признака исчезновения внешних объектов, равно как собственных и общих признаков <em>скандх</em>, <em>дхату</em> и <em>аятан</em>, — ум приходит в созерцательное сосредоточение (<em>cittaṃ samādhīyate</em>).</li>

            <li>Сосредоточив собственный ум и [пройдя через] <em>дхьяны</em>, освобождения (<em>vimokṣa</em>), <em>самадхи</em>, пути, плоды и достижения, шраваки, Махамати, обретают блаженное пребывание личного благородного постижения (<em>pratyātmāryagatilakṣaṇasukhavihāram</em>), свободное от падения и непостижимых преобразований, обусловленных отпечатками.</li>

            <li>Однако, Махамати, бодхисаттва-махасаттва, даже постигнув это блаженное пребывание шраваков — блаженство прекращения (<em>nirodha-sukha</em>) и блаженство достижения (<em>samāpatti-sukha</em>) — не должен осуществлять его непосредственно как собственное окончательное состояние. Ради деятельности на благо существ и в силу прежних обетов он не должен входить в это пребывание. Именно в этом, Махамати, бодхисаттве не следует упражняться.</li>

            <li>Каков же, Махамати, второй признак — упорная привязанность шраваков к различению собственной природы явлений? Увидев, что великие элементы, воспринимаемые как синее, жёлтое, тёплое, текучее, подвижное, твёрдое,<a href="#citation-245" id="ref-245" class="citation-mark"><sup>245</sup></a> не обладают самостоятельным развёртыванием (<em>akriyāpravṛtta</em>), но прочно установлены на основе собственных и общих признаков, рассуждения (<em>yukti</em>), писаний (<em>āgama</em>) и способов познания (<em>pramāṇa</em>), шраваки выстраивают привязанность к их собственной природе.</li>

            <li>Бодхисаттва, постигнув это, должен отвратиться от такого пути. Через вхождение в [постижение] отсутствие «я» в дхармах (<em>dharma-nairātmya</em>) он должен устранить воззрение, ограниченное лишь отсутствием «я» в «личности» (<em>pudgala-nairātmya</em>), и утвердиться на последовательности ступеней. Таков был изложен признак привязанности шраваков, и таково его разъяснение</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.14 (Вечное и Непостижимое)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Благословенный, Ты провозглашаешь <strong>Вечное и Непостижимое</strong> как сферу личного благородного постижения (<em>pratyātmāryagati-gocara</em>) и как сферу высшей истины (<em>paramārtha-gocara</em>). Но разве, Благословенный, тиртхики также не утверждают, что их Первопричина (<em>kāraṇa</em>) — Вечна и Непостижима?</li>
        </ul>
        </blockquote>

        <p>Благословенный ответил:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Нет, Махамати, у тиртхиков их <strong>первопричина</strong> не достигает подлинной <strong>Вечности и Непостижимости</strong>. И вот почему: у тиртхиков, Махамати, <strong>Вечное и Непостижимое</strong> не обладает собственным признаком причинности (<em>hetu-svalakṣaṇa-yukta</em>). Если же нечто не обладает собственным признаком причинности, то как и чем может быть обнаружено это <strong>«Вечное и Непостижимое»</strong>?</li>

            <li>Более того, Махамати, если бы их учение о <strong>Вечном и Непостижимом </strong>обладало собственным признаком причинности, то, будучи зависимым от обусловливающих факторов (<em>kāraṇādhīna</em>) в силу природы причинных признаков, оно как раз <strong>не было бы ни вечным, ни непостижимым</strong>.</li>

            <li>Моё же, Махамати, <strong>Высшее Вечное и Непостижимое</strong> связано с основанием, которым является признак высшей истины (<em>paramārtha-lakṣaṇa-hetu-yukta</em>). Оно <strong>свободно от бытия и небытия</strong>, поскольку является <strong>признаком личного благородного постижения</strong> и <strong>основанием познания высшей истины</strong>. И оно <strong>вечно</strong>, ибо свободно от причинно-обусловленных бытия и небытия и подобно несотворённым (<em>akṛtaka</em>) пространству, нирване и прекращению (<em>nirodha</em>). Посему, Махамати, это не тождественно учению тиртхиков.</li>

           <li>Эта <strong>Вечность и Непостижимость Татхагат</strong> — не что иное, как <strong>Таковость</strong> (<em>tathatā</em>), реализуемая через <strong>личное благородное постижение изначальной мудрости</strong>.</li>

            <li>Посему, Махамати, бодхисаттве-махасаттве следует усердствовать в йоге ради обретения этого <strong>Вечного и Непостижимого</strong> <strong>личного благородного постижения</strong>.</li>

            <li>Кроме того, Махамати, <strong>Вечность и Непостижимость</strong> тиртхиков обосновывается ими как иное по отношению к непостоянному.<a href="#citation-246" id="ref-246" class="citation-mark"><sup>246</sup></a> Она не является вечной, поскольку проявляется лишь через признаки причин, придуманные ими самими.<a href="#citation-247" id="ref-247" class="citation-mark"><sup>247</sup></a></li>

            <li>Если же, Махамати, <strong>Вечность и Непостижимость</strong> тиртхиков устанавливается их рассудочным умом (<em>anumāna-buddhi</em>) на основе умозаключения, когда они видят непостоянство и исчезновение сотворённых явлений и умозаключают о вечном, то по этой самой причине и Моё учение могло бы показаться таким же — ведь Я также указываю на вечное, исходя из видения непостоянства и исчезновения сотворённых явлений, но без опоры на [абстрактные] причинные утверждения.</li>

            <li>Если же, Махамати, их вечность и непостижимость связаны с признаками причины (<em>hetu-lakṣaṇa</em>), то из-за отсутствия у тиртхиков действительного бытия причины (<em>hetu-bhāva</em>) и собственных признаков (<em>sva-lakṣaṇa</em>) их <strong>Вечность и Непостижимость</strong>, Махамати, подобна рогам зайца.</li>

            <li>Их учение, Махамати, сводится лишь к словесному различению (<em>vāg-vikalpa</em>).<a href="#citation-248" id="ref-248" class="citation-mark"><sup>248</sup></a> Почему это так? Потому что рога зайца — это лишь словесное различение, поскольку у них полностью отсутствуют собственные причины и признаки (<em>sva-hetu-lakṣaṇa</em>).</li>

            <li>Моё же, Махамати, <strong>Вечное и Непостижимое</strong> является вечным, поскольку выступает признаком личного благородного постижения,<a href="#citation-249" id="ref-249" class="citation-mark"><sup>249</sup></a> ибо оно свободно от сотворённых бытия и небытия (<em>kṛtaka-bhāva-abhāva-varjitatvāt</em>),<a href="#citation-250" id="ref-250" class="citation-mark"><sup>250</sup></a> а не потому, что оно выводится на основе умозаключения из внешнего наличия бытия или небытия, вечного или невечного.<a href="#citation-251" id="ref-251" class="citation-mark"><sup>251</sup></a></li>

            <li>Тот же, Махамати, кто утверждает вечность лишь на основе логического вывода об отсутствии [непостоянного] вовне, тот не знает признака собственной причины этой вечности.</li>

            <li>Поскольку признаки сферы личного благородного постижения лежат полностью вне их поверхностных внешних рассуждений, с ними, Махамати, нечего и обсуждать.</li>

        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.15 (Сансара и Нирвана)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
                <li>Кроме того, Махамати, есть те, кто, страшась страданий, порождённых различениями в сансаре, ищут нирвану. Не зная отсутствия различия между сансарой и нирваной, они выстраивают понятие нирваны как отсутствие построений понятий относительно всех явлений (<em>bhāva</em>) и как прекращение активности органов чувств в отношении еще не возникших объектов, а не как поворот основы (<em>parāvṛtti</em>) в <em>Алайя-виджняне</em>, достигаемый через личное благородное постижение (<em>pratyātmagati</em>). Посему, Махамати, эти заблуждающиеся люди становятся приверженцами учения о Трёх Колесницах, а не учения «только-ума» (<em>cittamātra</em>), свободного от ментальных образов (<em>nirābhāsa</em>).</li>

                <li>Махамати, они не постигают сферу опыта Татхагат прошлого, будущего и настоящего, которая есть лишь воспринимаемое собственным умом;<a href="#citation-252" id="ref-252" class="citation-mark"><sup>252</sup></a> они привязаны к сфере объектов, кажущихся существующими вне ума.<a href="#citation-253" id="ref-253" class="citation-mark"><sup>253</sup></a> Так они, Махамати, продолжают вращаться в колесе сансары.</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.16 (Не-возникновение всех дхарм)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, Татхагаты прошлого, будущего и настоящего говорят о не-возникновении всех дхарм. Почему это так? Потому что, Махамати, в силу того, что бытие и небытие [явлений] есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-bhāva-abhāvāt</em>), и в силу свободы от возникновения существующего и несуществующего, все явления, Махамати, не имеют возникновения.</li>

            <li>Махамати, все дхармы подобны рогам зайца, лошади, осла или верблюда. Все явления, Махамати, являются невозникшими, ибо их собственная природа (<em>svabhāva</em>) лишь ложно воображена (<em>abhūta-parikalpita</em>) невеждами и обычными людьми.</li>

            <li>Ибо то, что кажется возникновением признаков собственной природы явлений, Махамати, есть [лишь] сфера личного благородного постижения изначальной мудрости (<em>pratyātmāryajñānagatigocara</em>); это не собственная природа двойственной сферы, воображаемой невеждами.</li>

            <li>Махамати, <em>Алайя-виджняна</em>, обладающая признаками природы движения тела, объектов наслаждения и обители (<em>deha-bhoga-pratiṣṭhā-gati-svabhāva-lakṣaṇa</em>), разворачивается через признаки схватываемого и схватывающего (<em>grāhya-grāhaka</em>), [тогда как] невежды, чьи умы захвачены двумя воззрениями — о возникновении, пребывании и распаде, — воображают возникновение всех явлений как «существующих» или «несуществующих».</li>
            <li>Посему, Махамати, тебе следует усердствовать в йоге.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.17 (Пять родов постижения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, существует пять родов предрасположенности к постижению (<em>pañcābhisamaya-gotrāṇi</em>).<a href="#citation-254" id="ref-254" class="citation-mark"><sup>254</sup></a> Каковы эти пять?</li>
            <li>Это род постижения колесницы шраваков;<a href="#citation-255" id="ref-255" class="citation-mark"><sup>255</sup></a> род постижения колесницы пратьекабудд;<a href="#citation-256" id="ref-256" class="citation-mark"><sup>256</sup></a> род постижения колесницы Татхагат;<a href="#citation-257" id="ref-257" class="citation-mark"><sup>257</sup></a> неопределённый род,<a href="#citation-258" id="ref-258" class="citation-mark"><sup>258</sup></a> склоняющийся к одной из трёх колесниц, и лишённый рода<a href="#citation-259" id="ref-259" class="citation-mark"><sup>259</sup></a> — пятый.</li>

            <li>Как же, Махамати, распознать род постижения колесницы шраваков? Тот, у кого при изложении учения о постижении собственных и общих признаков <em>скандх</em>, <em>дхату</em> и <em>аятан</em> волосы встают дыбом от благоговения, и чей ум устремляется к познанию этих признаков, но не к постижению признака нераздельности (<em>avinirbhāga-lakṣaṇa</em>) зависимого возникновения, — таков, Махамати, род постижения колесницы шраваков.</li>

            <li>Узрев этот путь постижения, такой человек на рубеже пятой и шестой ступени<a href="#citation-260" id="ref-260" class="citation-mark"><sup>260</sup></a> избавляется от явных клеш, но не от клеш-отпечатков (<em>vāsanā-kleśa</em>). Не избавившись от клеш-отпечатков, он пребывает в состоянии непостижимого перехода (<em>acintya-cyuti</em>) и испускает истинный львиный рык: «Рождение моё исчерпано, святая жизнь прожита!» Провозгласив это и подобное, он, в силу усвоения отсутствия «я» личности, полагает, что достиг нирваны.</li>

            <li>Иные же, Махамати, ищут нирвану на основе [своего] понимания «я» (<em>ātman</em>), «существа» (<em>sattva</em>), «жизненной силы» (<em>jīva</em>), «взращивающего» (<em>poṣa</em>), «человека» (<em>puruṣa</em>) и «личности» (<em>pudgala</em>).<a href="#citation-261" id="ref-261" class="citation-mark"><sup>261</sup></a></li>

            <li>Иные же, Махамати, увидев, что все дхармы зависят от причин, полагают, будто это и есть путь к нирване. Однако, Махамати, без видения отсутствия «я» в дхармах нет освобождения.</li>

            <li>Таково, Махамати, убеждение в [наличии] освобождения там, где освобождения нет (<em>aniryāṇa-niryāṇa-buddhi</em>), у тех, кто принадлежит к роду постижения колесницы шраваков.<a href="#citation-262" id="ref-262" class="citation-mark"><sup>262</sup></a></li>

            <li>Посему, Махамати, тебе следует усердствовать в йоге, чтобы отвратиться от этих ложных воззрений.</li>

            <li>Что касается, Махамати, рода постижения колесницы пратьекабудд, то это тот, у кого при изложении учения о личном осуществлении (<em>pratyekābhisamaya</em>) наворачиваются слёзы и волосы встают дыбом от благоговения. Его увлекает осознание разъединенности (<em>asaṃsarga-pratyaya</em>), а также проявление разнообразных сверхспособностей — преобразования собственного тела и парных чудес (<em>yamaka-prātihārya</em>), поскольку он сохраняет убежденность в бытии явлений (<em>bhāvābhiniveśa</em>).</li>

            <li>Зная, что это человек рода постижения колесницы пратьекабудд, следует вести с ним беседу, соответствующую его пути. Таков, Махамати, признак рода постижения колесницы пратьекабудд.</li>

            <li>Что касается, Махамати, рода постижения колесницы Татхагат, он трояк:</li>
            <li>Это род постижения собственной природы и отсутствия собственной природы явлений;<a href="#citation-263" id="ref-263" class="citation-mark"><sup>263</sup></a> род постижения личного благородного достижения;<a href="#citation-264" id="ref-264" class="citation-mark"><sup>264</sup></a> и род постижения внешних земель Будд и их величия.<a href="#citation-265" id="ref-265" class="citation-mark"><sup>265</sup></a></li>

            <li>Когда же, Махамати, при изложении любого из этих трёх [учений], — [а именно] при изложении непостижимой сферы тела, объектов наслаждения и обители, которые суть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya</em>), — [человек] не страшится, не трепещет и не впадает в ужас, следует знать: это — человек рода постижения колесницы Татхагат. Таков, Махамати, признак рода постижения колесницы Татхагат.</li>

            <li>Неопределённый же род, Махамати, — это те, кто, когда излагают любую из этих трёх колесниц, склоняются к той, к которой их влечёт. Их следует направлять именно в ту колесницу.</li>

            <li>Махамати, эта классификация родов — лишь подготовительная ступень (<em>parikarma-bhūmi</em>). Она устанавливается ради вхождения в ступени без ментальных образов (<em>nirābhāsa-bhūmi</em>).</li>

            <li>Но во внутреннем основании собственного опыта (<em>pratyātmālaya</em>), когда оно очищено от отпечатков собственных омрачений (<em>svakleśavāsanā-śuddha</em>), через видение отсутствия «я» в дхармах и обретение блаженного пребывания в <em>самадхи</em>, даже шравака обретает Тело Победителя (<em>jinakāyatā</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>128. Плод «вступившего в поток»,</li>
            <li>плод «однажды возвращающегося»,</li>
            <li>плод «невозвращающегося»</li>
            <li>и само состояние архата —</li>
            <li>всё это лишь заблуждение ума (<em>citta-vibhrama</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>129. О трёх колесницах, о единой колеснице</li>
            <li>и об отсутствии колесницы (<em>ayāna</em>)</li>
            <li>Я проповедую ради невежд и слабоумных,</li>
            <li>и ради уединённости (<em>viviktatā</em>) Благородных.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>130. Врата высшей истины (<em>paramārtha</em>) — осознавание,</li>
            <li>свободное от двойственности (<em>vijñapti-dvaya-varjitā</em>).</li>
            <li>Если [йогин] утвердился в сфере</li>
            <li>без ментальных образов (<em>nirābhāsa</em>),</li>
            <li>откуда взяться делению на три колесницы?</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>131. <em>Дхьяны</em>, безмерные состояния, бесформенные <em>самадхи</em></li>
            <li>и полное прекращение восприятия — ничто из этого</li>
            <li>не обнаруживается в сфере «только-ума» (<em>cittamātra</em>).</li>
        </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.18 (Иччхантики)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Что касается иччхантик, Махамати, то почему их освобождение считается невозможным? Это происходит по двум причинам: из-за отсечения всех корней благого (<em>sarva-kuśala-mūla-utsarga</em>) и из-за обетов в отношении существ, принятых в безначальные времена.</li>

            <li>Что есть отсечение всех корней благого? Это — отвержение собраний наставлений бодхисаттв (<em>bodhisattva-piṭaka-nikṣepa</em>) и клеветническое утверждение, будто эти сутры не согласуются с дисциплиной (<em>vinaya</em>) и освобождением (<em>mokṣa</em>). Из-за такого отсечения всех корней благого [существо] не достигает нирваны (<em>na nirvāyate</em>).</li>

            <li>Вторые же, Махамати, — это бодхисаттва-махасаттва, который, руководствуясь искусными средствами, дал обет: «Пока все существа не уйдут в паринирвану, Я Сам не уйду в паринирвану». По этой причине он не уходит в паринирвану (<em>na parinirvāti</em>).</li>

            <li>Таков, Махамати, признак тех, кто не уходит в окончательное угасание, и именно из-за этого они обретают участь иччхантик (<em>icchantika-gati</em>).</li>
        </ul>
        </blockquote>

        <p>Вновь Махамати спросил:</p>

        <p>— Кто же из них, Благословенный, никогда не уходит в окончательное угасание?</p>

        <p>Благословенный ответил:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, именно бодхисаттва-иччхантика, познав, что все явления изначально пребывают в паринирване (<em>ādi-parinirvṛta</em>), никогда не уходит в паринирвану. Но не тот иччхантика, что отсёк все корни благого.</li>
            <li>Ибо даже иччхантика, отсекший все корни благого, Махамати, может вновь пробудить их благодаря благословенной силе Татхагат (<em>tathāgatādhiṣṭhāna</em>).<a href="#citation-266" id="ref-266" class="citation-mark"><sup>266</sup></a> Почему это так? Потому что, Махамати, Татхагаты никогда не оставляют ни одного существа. По этой причине, Махамати, только бодхисаттва-иччхантика никогда не уходит в паринирвану.<a href="#citation-267" id="ref-267" class="citation-mark"><sup>267</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.19 (Три природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, бодхисаттве-махасаттве следует быть искусным в познании трёх признаков природ.<a href="#citation-268" id="ref-268" class="citation-mark"><sup>268</sup></a></li>

            <li>Махамати, воображаемая природа (<em>parikalpita-svabhāva</em>) разворачивается из образа-знака (<em>nimitta</em>).<a href="#citation-269" id="ref-269" class="citation-mark"><sup>269</sup></a> Как же, Махамати, воображаемая природа разворачивается из образа-знака? Махамати, зависимая природа (<em>paratantra-svabhāva</em>) предстаёт как основа, образ-знак, признак и внешняя форма.<a href="#citation-270" id="ref-270" class="citation-mark"><sup>270</sup></a></li>

            <li>Привязанность к этим формам и образам-знакам — двояка. Татхагаты, Архаты, Совершенно Пробуждённые устанавливают воображаемую природу через признак привязанности к именам<a href="#citation-271" id="ref-271" class="citation-mark"><sup>271</sup></a> и через признак привязанности к имени, основе и образу-знаку.<a href="#citation-272" id="ref-272" class="citation-mark"><sup>272</sup></a></li>

            <li>Здесь, Махамати, привязанность к признакам основы и образа-знака есть цепляние за внешние и внутренние дхармы.<a href="#citation-273" id="ref-273" class="citation-mark"><sup>273</sup></a> Привязанность к признакам образа-знака есть распознавание собственных и общих признаков именно в этих внешних и внутренних дхармах.<a href="#citation-274" id="ref-274" class="citation-mark"><sup>274</sup></a> Таковы, Махамати, два вида признака воображаемой природы.</li>
            <li>То, что разворачивается на основе опоры и объекта, — это зависимая [природа] (<em>paratantra</em>).</li>
            <li>Что же, Махамати, есть совершённая природа (<em>pariniṣpanna-svabhāva</em>)? Это свобода от различения образа-знака, имени, основы и признаков; это таковость, путь благородного знания и сфера, постижимая внутренним опытом благородного знания (<em>pratyātmāryajñānagatigocara</em>). Это, Махамати, и есть совершённая природа — Сердцевина Татхагатагарбхи (<em>tathāgatagarbha-hṛdayam</em>).</li>
        </ul>
    </blockquote>

    <p class="pl-2">Затем Благословенный произнёс гатху:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>132. Образ-знак (<em>nimitta</em>), имя (<em>nāma</em>) </li>
        <li>и умопостроение (<em>saṃkalpa</em>) —</li>
        <li>таковы признаки двух [первых] природ.</li>
        <li>Подлинное знание (<em>samyag-jñāna</em>)</li>
        <li>и Таковость (<em>tathatā</em>) —</li>
        <li>таковы признаки <em>Совершённой природы</em>.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Это, Махамати, есть наставление в Дхарме, именуемое «Исследованием признаков пяти дхарм и [трёх] природ» — сфера личного благородного постижения, в которой тебе и другим бодхисаттвам следует упражняться.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold my-6">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.20 (Два вида отсутствия «я»)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, бодхисаттве-махасаттве следует быть искусным в исследовании двух видов отсутствия «я» (<em>nairātmya-dvaya</em>).</li>

            <li>Что есть знание об отсутствии «я» в личности (<em>pudgala-nairātmya-jñāna</em>)? Это — понимание того, что совокупность <em>скандх</em>, <em>дхату</em> и <em>аятан</em>, порождённая неведением, кармой и жаждой, лишена «я» и «моего» (<em>ātma-ātmīya-rahita</em>). Сознание (<em>vijñāna</em>), приходя в движение из-за привязанности к восприятию форм глазом и другими органами чувств, являет [нам] обитель, тело и вместилище (<em>bhājanadehālaya</em>) — всё то, что воображено различениями собственного ума (<em>svacitta-vikalpa-vikalpitam</em>).<a href="#citation-275" id="ref-275" class="citation-mark"><sup>275</sup></a></li>

            <li>Подобно реке, ростку, светильнику, ветру или облаку, [эта совокупность] распадается в каждое мгновение непрерывной череды; она непостоянна, словно обезьяна, нечиста и ищет нечистое, подобно мухе; она ненасытна, словно огонь; подобно колодезному колесу (<em>araghaṭṭa</em>), она вращается в колесе существования сансары, несущем отпечатки безначального многообразия различений (<em>anādi-prapañca-viṣaya-vāsanā</em>); она движется, принимая разнообразные телесные формы, подобно механической кукле (<em>yantra</em>) или иллюзии (<em>māyā</em>). Махамати, знание, прозревающее эти признаки, именуется знанием об отсутствии «я» в личности (<em>pudgala-nairātmya-jñāna</em>).<a href="#citation-276" id="ref-276" class="citation-mark"><sup>276</sup></a></li>

            <li>Что же, Махамати, есть знание об отсутствии «я» в дхармах (<em>dharmanairātmyajñāna</em>)? Это — постижение того, что <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em> лишены воображаемой собственной природы (<em>parikalpita-lakṣaṇa-svabhāva</em>). Подобно тому, Махамати, как <em>скандхи</em> лишены «я» и являются лишь совокупностью элементов, связанных нитями причины, кармы и жажды, и движутся взаимной обусловленностью, без самостоятельной активности, — так же и сами <em>скандхи</em>, Махамати, лишены собственных и общих признаков (<em>sva-sāmānya-lakṣaṇa</em>), и являются лишь разнообразным проявлением ложного воображения (<em>abhūta-parikalpa</em>), которое измышляют невежды, но не Благородные.<a href="#citation-277" id="ref-277" class="citation-mark"><sup>277</sup></a></li>

            <li>Махамати, бодхисаттва-махасаттва становится искусным в отсутствии «я» в дхармах, когда созерцает все явления как свободные от ума (<em>citta</em>), <em>манаса</em> (<em>manas</em>), различающего сознания (<em>vijñāna</em>), а также от пяти дхарм и трех собственных природ (<em>svabhāva</em>).</li>

            <li>Обретя это мастерство, Махамати, бодхисаттва вскоре достигает первой ступени бодхисаттв — «Радостной» (<em>pramuditā</em>), где начинается исследование сферы, свободной от ментальных образов (<em>nirābhāsa-pravicaya</em>). Последовательно пройдя ступени, на десятой [ступени] он обретает великое «Облако Дхармы» (<em>mahā-dharma-megha</em>). Утвердившись на ней, он восседает в великом драгоценном чертоге (<em>mahā-ratna-vimāna</em>), подобном царю лотосов (<em>mahā-padma-rāja</em>), украшенном бесчисленными драгоценностями и жемчугом. Он окружён сыновьями Победителя (<em>jina-putra</em>) и, подобно сыну царя-чакравартина, получает посвящение (<em>abhiṣeka</em>) от рук всех Будд, пришедших из всех земель Будд.</li>

            <li>Превзойдя ступень «сыновей Будды», благодаря личному постижению благородной Дхармы (<em>pratyātmārya-dharma-gati</em>), он становится Татхагатой, безраздельно владеющим Телом Дхармы (<em>dharmakāya-vaśavartin</em>), ибо узрел отсутствие «я» в дхармах. Таков, Махамати, признак отсутствия «я» во всех дхармах. В этом тебе и другим бодхисаттве-махасаттве следует усердствовать.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.21 (Наложение и отрицание)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Пусть Благословенный разъяснит мне признаки наложения (<em>samāropa</em>) и отрицания (<em>apavāda</em>), дабы я и другие бодхисаттвы, освободив ум от ложных воззрений, связанных с наложением и отрицанием, быстро достигли непревзойдённого совершенного пробуждения. Достигнув же пробуждения и оставив воззрения на вечность, наложение, отрицание и уничтожение, мы не станем более порицать Твоё Око Будды.</li>
    </ul>
    </blockquote>

    <p>Затем Благословенный, восприняв просьбу бодхисаттвы-махасаттвы Махамати, произнёс этот стих:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>133. В реальности «только-ума» (<em>cittamātra</em>)</li>
            <li>нет ни наложения, ни отрицания.</li>
            <li>Те же неразумные, что не знают,</li>
            <li>что [весь мир] — лишь воспринимаемое собственным умом,</li>
            <li>являющееся как тело, объекты наслаждения и обитель,</li>
            <li>— те блуждают в наложении и отрицании.</li>
        </ul>
    </blockquote>

    <p>И далее Благословенный, разъясняя смысл этого стиха, вновь сказал:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Существует, Махамати, четыре вида наложения несуществующего (<em>asat-samāropa</em>). Каковы эти четыре?</li>
        <li>— Наложение несуществующих признаков (<em>asal-lakṣaṇa-samāropa</em>);</li>
        <li>— Наложение несуществующих воззрений (<em>asat-dṛṣṭi-samāropa</em>);</li>
        <li>— Наложение несоответствующих причин (<em>atad-dhetu-samāropa</em>);</li>
        <li>— Наложение несуществующего бытия (<em>asat-bhāva-samāropa</em>).</li>
        <li>Таковы, Махамати, четыре вида наложения.</li>
    </ul>

    <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
        <li>Что же касается отрицания (<em>apavāda</em>), Махамати, — что оно собой представляет? Это — отрицание, возникающее из-за отсутствия распознавания необнаружимости (<em>anupalabdhi-pravicaya-abhāva</em>) именно этого ложного воззрения-наложения (<em>kudṛṣṭi-samāropa</em>). Таков, Махамати, признак наложения и отрицания.</li>

        <li>Кроме того, Махамати, каков признак наложения несуществующих признаков? Это — привязанность к несуществующим собственным и общим признакам <em>скандх</em>, <em>дхату</em> и <em>аятан</em> в форме утверждения: «Это именно так и не иначе!» Таков, Махамати, признак наложения несуществующих признаков.</li>

        <li>Поистине, Махамати, это различение (<em>vikalpa</em>) — наложение несуществующих признаков — разворачивается из-за привязанности к разнообразным отпечаткам (<em>vāsanā</em>), порождённым грубостью безначального расширяющегося построения понятий (<em>anādi-prapañca-dauṣṭhulya</em>). Таков, Махамати, признак наложения несуществующих признаков.</li>

        <li>Что же есть, Махамати, наложение несуществующих воззрений? Это — приписывание тем же <em>скандхам</em>, <em>дхату</em> и <em>аятанам</em> воззрений на: «я» (<em>ātman</em>), «существо» (<em>sattva</em>), «живое существо» (<em>jīva</em>), «рождённое» (<em>jantu</em>), «индивидуум» (<em>puruṣa</em>), «личность» (<em>pudgala</em>), «питающее» (<em>poṣa</em>). Именно это, Махамати, именуется наложением несуществующих воззрений.</li>

        <li>Что же, Махамати, есть наложение несоответствующих причин (<em>atad-dhetu-samāropa</em>)? Это — воззрение, будто [прежнее] сознание, не существовавшее прежде, возникает без причины (<em>ahetu</em>) — не возникнув по-настоящему, подобно иллюзии (<em>māyāvad-anutpanna</em>), — [тем не менее] приходит в движение, предваряемое глазом, формой, светом и памятью, а возникнув и просуществовав, вновь исчезает. Таков, Махамати, признак наложения несоответствующих причин.</li>

        <li>Что же есть, Махамати, наложение несуществующего бытия? Это — привязанность к бытию пространства (<em>ākāśa</em>), прекращения (<em>nirodha</em>), нирваны (<em>nirvāṇa</em>) и несотворённого (<em>akṛtaka</em>). Поистине, Махамати, эти явления свободны от бытия и небытия.</li>

        <li>Все они, Махамати, подобны рогам зайца, лошади, осла или верблюда, либо видению плавающих перед глазами волос и пушинок (<em>keśoṇḍuka</em>). Они свободны от крайностей существования и несуществования, и от наложения и отрицания. Лишь невежды, чьи умы не постигли, что всё — лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>), выстраивают такие различения. Но не Благородные.</li>

        <li>Таков, Махамати, признак наложения и отрицания в отношении ложного выстраивания бытия. Посему, Махамати, тебе следует пребывать свободным от воззрений наложения и отрицания.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.22 (Тело Воплощения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, бодхисаттвы, вступив в сферу постижения ума (<em>citta</em>), <em>манаса</em> (<em>manas</em>), различающего сознания (<em>manovijñāna</em>), пяти дхарм, трёх природ и двух признаков отсутствия «я» (<em>nairātmya-lakṣaṇa-dvaya</em>), ради блага других принимают разнообразные облики.</li>

            <li>Подобно тому как воображаемая природа возникает на опоре зависимой, так и они, имея опорой зависимую природу, схожи с драгоценным камнем чинтамани, принимающим любые формы.</li>

            <li>Пребывая в собраниях всех земель Будд, они слушают из уст всех Татхагат наставления в Дхарме, выходящие за пределы колесниц шраваков и пратьекабудд, где все дхармы описываются как подобные иллюзии (<em>māyā</em>), сну, миражу, отражению и луне в воде, а также свободные от возникновения, разрушения, вечности и прерывания.</li>

            <li>Они обретают сотни тысяч врат сосредоточения (<em>samādhi-mukha</em>), а также мириады десятков миллионов и сотен тысяч таких сосредоточений; посредством этих сосредоточений они переходят из [одной] земли [Будды] в [иную] землю.</li>

            <li>Посвящая себя почитанию Будд и наставляя в Трёх Драгоценностях во всех обителях богов и мирах становления, они принимают облик Будды и, окружённые собраниями шраваков и бодхисаттв, вводят существ в понимание того, что всё есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>), и разъясняют отсутствие внешнего бытия и небытия, дабы отвратить их от сторон существования и несуществования.</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс этот стих:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>134. Когда сыновья Победителя</li>
            <li>созерцают мир как «только-ум» (<em>cittamātra</em>),</li>
            <li>они обретают Тело Воплощения (<em>nairmāṇikaṃ kāyaṃ</em>),</li>
            <li>свободное от действий и</li>
            <li>формирующих факторов (<em>kriyā-saṃskāra</em>),</li>
            <li>неразрывно связанное с <em>силами</em> (<em>bala</em>), </li>
            <li><em>сверхзнаниями</em> (<em>ābhijña</em>) и <em>владычествами</em> (<em>vaśita</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.23 (Семь видов шуньяты)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Пусть Благословенный разъяснит признаки <em>шуньяты</em>, не-возникновения, недвойственности и отсутствия собственной природы всех дхарм, дабы, благодаря постижению этих признаков, я и другие бодхисаттвы-махасаттвы, освободившись от выстраивания понятий о «есть» и «нет», быстро достигли непревзойдённого совершенного пробуждения.</li>
        </ul>
        </blockquote>
        <p>Тогда Благословенный сказал бодхисаттве-махасаттве Махамати:</p>
        <p>— Слушай же внимательно, Махамати, и хорошо удержи это в уме! Я разъясню тебе это.</p>
        <p>— Да, Благословенный! — ответил бодхисаттва-махасаттва Махамати.</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li><em>«Шуньята</em>, <em>шуньята»</em>, Махамати, — это лишь слово, принадлежащее воображаемой природе (<em>parikalpita-svabhāva-pada</em>). Из-за привязанности к воображаемой природе люди утверждают существование <em>шуньяты</em>, не-возникновения,</li>
            <li>недвойственности и отсутствия собственной природы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Если говорить кратко, Махамати, существует семь видов <em>шуньяты</em>:</li>
            <li><em>Шуньята признака</em> (<em>lakṣaṇa-śūnyatā</em>);</li>
            <li><em>Шуньята собственной природы явлений</em> (<em>bhāva-svabhāva-śūnyatā</em>);</li>
            <li><em>Шуньята непроявленного</em> (<em>apracarita-śūnyatā</em>);</li>
            <li><em>Шуньята проявленного</em> (<em>pracarita-śūnyatā</em>);</li>
            <li><em>Шуньята необозначимости всех дхарм</em> (<em>sarvadharma-nirabhilāpya-śūnyatā</em>);</li>
            <li><em>Великая шуньята высшей истины и благородного знания</em> (<em>paramārthāryajñāna-mahāśūnyatā</em>);</li>
            <li><em>Шуньята взаимного отсутствия</em> (<em>itaretara-śūnyatā</em>) — седьмая.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Что же, Махамати, есть <em>шуньята признака</em> (<em>lakṣaṇa-śūnyatā</em>)? Это — то, что все явления лишены собственных и общих признаков (<em>sva-sāmānya-lakṣaṇa-śūnyāḥ</em>). Махамати, собственные и общие признаки не устанавливаются, поскольку [явления] существуют лишь во взаимозависимых сочетаниях и не допускают аналитического разделения (<em>pravicaya-vibhāga-abhāvāt</em>). И поскольку отсутствуют [основания для различения] себя, другого и обоих (<em>svaparobhayābhāvāt</em>), признаки не утверждаются (<em>na avatiṣṭhate</em>). Потому говорится: «Все явления лишены собственных признаков (<em>svalakṣaṇa-śūnyāḥ</em>)».</li>

            <li>Что же, Махамати, есть <em>шуньята собственной природы явлений</em> (<em>bhāva-svabhāva-śūnyatā</em>)? Махамати, все дхармы лишены собственной природы. Поэтому и говорится: «шуньята собственной природы явлений».</li>

            <li>Что же, Махамати, есть <em>шуньята непроявленного</em> (<em>apracarita-śūnyatā</em>)? Махамати, нирвана не была ранее проявлена в <em>скандхах</em>. Потому и говорится: «шуньята непроявленного».</li>

            <li>Что же, Махамати, есть <em>шуньята проявленного</em> (<em>pracarita-śūnyatā</em>)? Махамати, <em>скандхи</em>, лишённые «я» и «моего» (<em>ātmātmīya-rahitāḥ</em>), продолжают своё развёртывание лишь через соединение причин, рассуждений, действий и кармы (<em>hetu-yukti-kriyā-karma-yoga</em>). Потому и говорится: «шуньята проявленного».</li>

            <li>Что же, Махамати, есть <em>шуньята необозначимости всех дхарм</em> (<em>sarvadharma-nirabhilāpya-śūnyatā</em>)? Махамати, все дхармы пусты от обозначаемости, поскольку воображаемая природа (<em>parikalpita-svabhāva</em>) не поддаётся установлению в словах. Потому и говорится: «шуньята необозначимости».</li>

            <li>Что же, Махамати, есть великая <em>шуньята высшей истины и благородного знания</em> (<em>paramārthāryajñāna-mahāśūnyatā</em>)? Махамати, это — внутреннее благородное постижение (<em>svapratyātmāryajñānādhigamaḥ</em>), пустое от отпечатков, оставляемых изъянами всех воззрений. Потому и говорится: «великая шуньята высшей истины и благородного знания».</li>

            <li>Что же, Махамати, есть <em>шуньята взаимного отсутствия</em> (<em>itaretara-śūnyatā</em>)? Махамати, это когда говорят: «Поскольку того здесь нет, это пусто от него». Подобно тому, Махамати, как во дворце Матери Шригалы нет слонов, коров, овец и прочего. Потому я и сказал: «Он не пуст, ибо в нём находятся бхикшу». Говорится лишь, что он пуст от тех [животных]. Но это не означает, Махамати, что дворец отсутствует как явление дворца, или что бхикшу отсутствуют как явление бхикшу. И это не означает, что те слоны, коровы и прочие явления (<em>bhāvāḥ</em>) не существуют где-то в другом месте. Таковы собственные и общие признаки (<em>svasāmānyalakṣaṇa</em>) всех дхарм: одно не обнаруживается в другом. Это именуется «шуньята взаимного отсутствия».</li>

            <li>Таковы, Махамати, семь видов <em>шуньяты</em>. Но эта <em>шуньята взаимного отсутствия</em> — самая низшая (<em>sarvajaghanyā</em>), и тебе следует её избегать.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.24 (Признаки не-возникновения, недвойственности и отсутствия собственной природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>[Явления] не возникают сами по себе; и всё же, Махамати, они обнаруживаются лишь в состоянии сочетания условий (<em>samādhyavasthā</em>). Поэтому они именуются «невозникшими и лишёнными собственной природы». Махамати, именно ввиду невозникновения все явления лишены собственной природы. Также, Махамати, все явления лишены собственной природы из-за отсутствия непрерывности в потоке мгновений (<em>kṣaṇa-saṃtati-prabandha-abhāva</em>) и в силу видения изменчивости (<em>anyathā-bhāva-darśana</em>). Потому и говорится: «все явления лишены собственной природы».<a href="#citation-278" id="ref-278" class="citation-mark"><sup>278</sup></a></li>

            <li>Что же, Махамати, есть <em>признак недвойственности</em> (<em>advaya-lakṣaṇa</em>)? Махамати, подобно тому как тень и свет, длинное и короткое, чёрное и белое не обнаруживаются по отдельности друг от друга, так же все дхармы недвойственны, подобно сансаре и нирване. Где присутствует нирвана — там нет сансары, а где сансара — там нет нирваны, поскольку имеются причины их различия (<em>vilakṣaṇa-hetu-sadbhāva</em>). Потому и говорится: «<strong>Все дхармы недвойственны, подобно сансаре и нирване</strong>». Потому, Махамати, тебе следует практиковать йогу в отношении признаков <strong><em>шуньяты</em></strong>, <strong>невозникновения</strong>, <strong>недвойственности</strong> и <strong>отсутствия собственной природы</strong>.<a href="#citation-279" id="ref-279" class="citation-mark"><sup>279</sup></a></li>
        </ul>
       </blockquote>

        <p>Затем Благословенный произнёс эти гатхи:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>135. Я всегда проповедую <em>шуньяту</em>,</li>
            <li>свободную от [крайностей] вечности и уничтожения;</li>
            <li>[я проповедую] сансару, именуемую сном и иллюзией,</li>
            <li>однако карма не исчезает.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
             <li>136. Пространство (<em>ākāśa</em>), а также</li>
             <li>нирвану и прекращение (<em>nirodha</em>) —</li>
            <li>эту пару — невежды воображают непроизведёнными.</li>
            <li>Благородные же [видят их]</li>
            <li>свободными от «есть» и «нет».<a href="#citation-280" id="ref-280" class="citation-mark"><sup>280</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.25 (Суть и буква Учения)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем Благословенный вновь обратился к бодхисаттве-махасаттве Махамати:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Поистине, Махамати, эта четверица — <em>шуньята</em>, невозникновение, недвойственность и отсутствие собственной природы — пронизывает все сутры всех Будд. В какой бы сутре [эта четверица ни излагалась], следует усматривать именно этот смысл.</li>

            <li>Ибо, Махамати, поучения в сутрах различаются в соответствии со склонностями всех существ, но они не являются речью, утверждающей саму таковость (<em>tattva</em>).</li>

            <li>Подобно тому, Махамати, как мираж в пустыне влечёт оленей, заставляя их ухватиться за убеждение о существовании воды, хотя воды там нет, — так и поучения во всех сутрах служат удовлетворению собственного различения невежд, но не являются речью, устанавливающей благородное знание таковости (<em>tattva-āryajñāna-vyavasthāna</em>).</li>

            <li>Посему, Махамати, надлежит следовать исключительно за смыслом (<em>artha</em>), оставив цепляние <strong>за</strong> словесную форму изложения (<em>deśanā-abhilāpa</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.26 (Татхагатагарбха и Атман)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати обратился к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Благословенный, в Твоих поучениях в сутрах Ты описываешь Зародыш Татхагаты (<em>tathāgatagarbha</em>). Ты говоришь, что он чист в силу изначальной светоносности своей природы (<em>prakṛti-prabhāsvara-viśuddhi</em>), наделён тридцатью двумя признаками и пребывает в телах всех живых существ (<em>sarvasattvadehāntargataḥ</em>). Ты сравниваешь его с бесценным сокровищем, завёрнутым в грязную ткань, и описываешь его как окутанный <em>скандхами</em>, <em>дхату</em> и <em>аятанами</em>, запятнанный грязью страсти, гнева, заблуждения и ложных воображений (<em>abhūta-parikalpa</em>). Ты называешь его вечным (<em>nitya</em>), неизменным (<em>dhruva</em>), благим (<em>śiva</em>) и постоянным (<em>śāśvata</em>). Как же, Благословенный, Твоё учение о Зародыше Татхагаты не совпадает с учением тиртхиков о «я» (<em>ātma-vāda</em>)? Ведь и тиртхики, Благословенный, учат о «я» как о вечном, «деятеле» (<em>kartā</em>), лишённом качеств, всепроникающем и неразрушимом.</li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, Моё учение о Зародыше Татхагаты (<em>tathāgatagarbha</em>) не совпадает с учением тиртхиков о «я» (<em>ātma-vāda</em>). Напротив, Махамати, Татхагаты, Архаты, Совершенно Пробуждённые, проповедуя посредством учения о Зародыше Татхагаты, раскрывают сферу, лишённую различений и проявлений, — а именно <strong><em>шуньяту</em></strong>, <strong>предел истинности</strong> (<em>bhūtakoṭi</em>), <strong>нирвану</strong>, <strong>не-возникновение</strong>, <strong>без-образность-без-признаковость</strong> (<em>ānimitta</em>) и <strong>безустремлённость</strong> (<em>apraṇihita</em>). Делают они это ради того, чтобы неискушённые не впадали в страх перед учением об отсутствии «я» (<em>nairātmya</em>). И не следует бодхисаттвам настоящего и будущего допускать здесь привязанность к «я».</li>

            <li>Подобно тому, Махамати, как гончар из одной и той же кучи глины изготавливает разные сосуды с помощью рук, умения, палки, воды и нити — так и Татхагаты излагают то же самое отсутствие «я» в дхармах, свободное от всех признаков (<em>lakṣaṇa</em>), порождаемых различением. Они делают это через разнообразные искусные средства (<em>upāya-kauśalya</em>): то через учение о Зародыше, то через учение об отсутствии «я», используя, подобно гончару, разные сочетания слов и оборотов.</li>

            <li>Поэтому, Махамати, учение о Зародыше Татхагаты не совпадает с учением тиртхиков о «я». Татхагаты учат о Зародыше лишь для того, чтобы привлечь тиртхиков, укоренённых в учении о «я». [Они проповедуют так, думая]: «Как бы эти люди, чьи помыслы пали в плен воззрений о небывалом "я", смогли через врата трёх освобождений быстро полностью пробудиться к непревзойдённому совершенному пробуждению?» Вот ради чего, Махамати, Татхагаты, Архаты, Совершенно Пробуждённые проповедуют учение о Зародыше Татхагаты. </li>

            <li>Посему, Махамати, дабы отвратиться от воззрений тиртхиков, тебе следует следовать за Зародышем Татхагаты, чьё существо — отсутствие «я» (<em>nairātmyagarbha</em>).</li>
        </ul>
        </blockquote>
        <p>Затем Благословенный произнёс этот стих:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>137. Личность (<em>pudgala</em>), поток (<em>saṃtati</em>), <em>скандхи</em>,</li>
            <li>условия (<em>pratyaya</em>), атомы (<em>aṇu</em>), первоматерия (<em>pradhāna</em>),</li>
            <li>Владыка (<em>īśvara</em>) и деятель (<em>kartā</em>) —</li>
            <li>всё это лишь различения (<em>vikalpa</em>) «только-ума» (<em>cittamātra</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.27 (27. Четыре совершенных качества йогина)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати, взирая на грядущие поколения, вновь обратился к Благословенному:</p>
        <p>— Пусть Благословенный разъяснит прямое йогическое постижение (<em>yogābhisamaya</em>), дабы бодхисаттвы-махасаттвы стали великими практиками йоги (<em>mahāyoga-yogin</em>)</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, бодхисаттвы-махасаттвы становятся великими практиками йоги, будучи наделены четырьмя качествами. Каковы эти четыре? А именно:</li>
            <li>• постижением того, что всё воспринимаемое — лишь видимое собственного ума (<em>svacittadṛśya</em>);</li>
            <li>• отбрасыванием воззрений о возникновении, пребывании и распаде;</li>
            <li>• распознаванием того, что явления (<em>bhāva</em>) лишены и бытия, и небытия;</li>
            <li>• устремлённостью к личному благородному постижению (<em>svapratyātmāryajñānādhigama</em>).</li>
            <li>Обладая этими четырьмя качествами, Махамати, бодхисаттвы-махасаттвы становятся великими практиками йоги.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Как же, Махамати, бодхисаттвы-махасаттвы становятся искусными в постижении того, что всё воспринимаемое — лишь видимое собственного ума (<em>svacittadṛśyavibhāvanā</em>)? Они созерцают это так:</li>
            <li>«Этот тройственный мир (<em>traidhātuka</em>) — лишь собственный ум; он лишён "я" и "моего". Он лишён устремлённости (<em>nirīha</em>) и свободен от собирания и нагромождения (<em>āyūha-niyūha</em>). Он пропитан отпечатками привязанности к пагубному понятийному разрастанию (<em>prapañca</em>), длящемуся с безначальных времён. Он обусловлен условным проявлением разнообразных форм тройственного мира; он различается (<em>vikalpyate</em>) и является (<em>khyāyate</em>) как поток представлений о теле, объектах восприятия, мире-обители (<em>deha-bhoga-pratiṣṭhā</em>) и различных формах существования».</li>
            <li>Поистине, Махамати, именно так бодхисаттвы-махасаттвы становятся искусными в постижении того, что всё воспринимаемое — лишь видимое собственного ума.</li>
            <li>Как же, Махамати, бодхисаттвы-махасаттвы становятся свободными от воззрений о возникновении, пребывании и распаде? Так:</li>
            <li>Они видят, что все явления (<em>bhāva</em>) подобны призрачным образам во сне или иллюзии и не возникают, поскольку невозможны ни из себя, ни из другого, ни из обоих [вместе]. Следуя [пониманию], что всё есть лишь собственный ум, и созерцая неразворачивание сознаний (<em>vijñāna</em>) благодаря видению отсутствия внешних явлений, они постигают, что условия (<em>pratyaya</em>) — это лишь нагромождение, лишённое прочной основы (<em>akūṭarāśitva</em>), и видят тройственный мир как порождение различения (<em>vikalpa</em>) и условий.</li>
            <li>Не обнаруживая дхарм ни внутри, ни вовне, и видя отсутствие у них собственной природы (<em>niḥsvabhāva</em>), они отвращаются от воззрений о возникновении. Проникая в природу дхарм как подобную иллюзии, они обретают убеждённость в невозникновении дхарм (<em>anutpattika-dharma-kṣānti</em>).</li>
            <li>Утвердившись на восьмой ступени [бодхисаттвы] и достигнув поворота основы (<em>parāvṛtti</em>) ума, <em>манаса</em>, различающего сознания (<em>citta-manas-manovijñāna</em>), пяти дхарм, [трёх] видов собственной природы и двоякого отсутствия «я», они обретают <em>тело, созданное умом</em> (<em>manomayakāya</em>).</li>
            <li>Поистине, Махамати, именно так бодхисаттвы-махасаттвы становятся свободными от воззрений о возникновении, пребывании и распаде.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Благословенный, по какой причине это тело называют созданным умом (<em>manomaya-kāya</em>)?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Его называют созданным умом, Махамати, потому что оно обладает беспрепятственным и стремительным движением, подобным мысли.</li>
            <li>Подобно тому, Махамати, как мысль беспрепятственно проносится сквозь горы, стены, реки и деревья, на сотни тысяч йоджан вспоминая объекты, виденные и познанные прежде, и движется как непрерывное тело, неотделимое от потока собственного ума (<em>svacitta-prabandha-avicchinna-śarīra</em>), не встречая преград, — точно так же, Махамати, [действует бодхисаттва].</li>
            <li>Одновременно с обретением тела, созданного умом, благодаря сосредоточению (<em>samādhi</em>), подобному иллюзии, украшенный «цветами» признаков (<em>lakṣaṇa</em>) <em>сил</em> (<em>bala</em>), <em>владычеств</em> (<em>vaśitā</em>) и <em>сверхзнаний</em> (<em>abhijñā</em>), он становится соприродным сонму Благородных и движется беспрепятственно, подобно мысли, памятуя о содержании своих прежних обетов ради созревания живых существ.</li>
            <li>Поистине, Махамати, именно так бодхисаттва-махасаттва становится свободным от воззрений о возникновении, пребывании и распаде.</li>
            <li>Как же, Махамати, бодхисаттва-махасаттва становится искусным в распознавании того, что внешнее лишено как бытия, так и небытия?</li>
            <li>[Это происходит], когда он ясно видит: все явления, Махамати, подобны миражу, сновидению и иллюзии «волосков» перед глазами (<em>keśoṇḍuka</em>).</li>
            <li>Он ясно видит, что природа всех явлений обусловлена привязанностью к отпечаткам различений, порождаемых многообразным кармическим вызреванием (<em>vipāka-vikalpa</em>) и пагубным понятийным разрастанием (<em>prapañca-dauṣṭhulya</em>), длящимся с безначальных времён. Прозревая это, он устремляется к сфере личного благородного постижения (<em>pratyātmāryajñānagativiṣaya</em>).</li>
            <li>Обладая этими четырьмя качествами, Махамати, бодхисаттвы-махасаттвы становятся великими практиками йоги. Посему, Махамати, тебе следует усердствовать в этой йоге.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.28 (28. Признак причинно-условной природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <p>— Пусть Благословенный разъяснит признак причин и условий (<em>hetupratyayalakṣaṇa</em>) всех дхарм! Дабы, постигнув этот признак, я и другие бодхисаттвы-махасаттвы, освободившись от различений и воззрений о существовании и несуществовании (<em>sadasaddṛṣṭivikalparahitāḥ</em>), более не воображали бы ни последовательного, ни одновременного возникновения всех явлений.<a href="#citation-281" id="ref-281" class="citation-mark"><sup>281</sup></a></p>

        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Существует два вида признака причинно-условного возникновения (<em>pratītyasamutpāda-hetu-lakṣaṇa</em>) всех дхарм, а именно: внешнее и внутреннее.</li>
            <li>Что же, Махамати, есть внешнее зависимое возникновение?</li>

            <li>Подобно тому, Махамати, как из кома глины с помощью палки, гончарного круга, нити, воды и усилий человека возникает кувшин; как из нитей — ткань, из тростника — циновка, из семени — росток, а из простокваши при сбивании и усилиях человека — масло, — именно так, Махамати, следует рассматривать внешнее зависимое возникновение: как последовательность предшествующего и последующего.<a href="#citation-282" id="ref-282" class="citation-mark"><sup>282</sup></a></li>

            <li>Что же касается внутреннего причинно-условного возникновения (<em>ādhyātmikaḥ pratītyasamutpāda</em>), Махамати, — то это такие дхармы, как неведение, жажда и карма. Именно они обозначаются как «зависимое возникновение». Рождённые из них, Махамати, дхармы, называемые <em>скандхами</em>, <em>дхату</em> и <em>аятанами</em>, также обозначаются как «зависимое возникновение». Хотя всё это неотличимо, невежды воображают их [как нечто отдельное].<a href="#citation-283" id="ref-283" class="citation-mark"><sup>283</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
            <li>Существует, Махамати, шесть видов причин:</li>
            <li>• Причина становления (<em>bhaviṣyad-dhetu</em>) исполняет роль порождения внутренних и внешних дхарм.</li>
            <li>• Причина связи (<em>saṃbandha-hetu</em>) исполняет роль опоры (<em>ālambana</em>) при возникновении внутренних и внешних <em>скандх</em>, семян и прочего.</li>
            <li>• Причина признака (<em>lakṣaṇa-hetu</em>) порождает связанность через непрерывность действия.</li>
            <li>• Действующая причина (<em>kāraṇa-hetu</em>) исполняет роль главенствующего воздействия, подобно царю-миродержцу.</li>
            <li>• Проявляющая причина (<em>vyañjana-hetu</em>) исполняет роль высвечивания признаков явления, возникшего в различении, подобно светильнику, [освещающему] формы.</li>
            <li>• Причина нейтральности (<em>upekṣā-hetu</em>) в момент прекращения [обусловленности] исполняет роль пресечения деятельности потока, [ведя] к возникновению состояния без различений (<em>avikalpa</em>).<a href="#citation-284" id="ref-284" class="citation-mark"><sup>284</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Ведь все они, Махамати, умозрительно измышлены собственным различением невежд и простаков; они не возникают ни последовательно, ни одновременно. Почему это так?</li>
            <li>Если бы они возникали одновременно, Махамати, то не было бы разделения на причину и следствие, поскольку отсутствовал бы признак причины.</li>
            <li>Если бы они возникали последовательно, то это также невозможно, поскольку ещё не возникшее не обладает собственным признаком. Подобно выражению «отец нерождённого сына», Махамати, связь последовательности здесь несостоятельна.</li>
            <li>Поскольку у логиков всё сводится к отношениям порождающего и порождаемого через причины, объект-опору, непрерывное и господствующее условия, Махамати, явления не возникают последовательно.</li>
            <li>Из-за привязанности к признакам воображаемой природы, Махамати, они не возникают одновременно.</li>
            <li>Поскольку тело, объекты наслаждения и обитель — лишь видимое собственным умом, а внешнее лишено собственных и общих признаков существования и несуществования, Махамати, они не возникают ни последовательно, ни одновременно.</li>
            <li>Помимо этого, различающее сознание разворачивается лишь потому, что оно умозрительно измышлено различением видимого собственным умом.</li>
            <li>Потому, Махамати, тебе следует оставить воззрения о последовательном и одновременном возникновении, основанные на признаках действия причин и условий.</li>
        </ul>
        </blockquote>
        <p>Об этом сказано гатхами:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>138. Здесь ничто не возникает из условий </li>
            <li>и ничто не прекращается.</li>
            <li>Возникают и прекращаются </li>
            <li>лишь сами измышленные условия.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>139. Омрачённость представлениями</li>
            <li>о возникновении и распаде</li>
            <li>не устраняется в самих условиях;</li>
            <li>однако там, где простаки строят различения через условия, —</li>
            <li>именно там она устраняется.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>140. Поскольку у дхарм, лишённых истинного существования,</li>
            <li>нет возникновения из условий,</li>
            <li>ум, введённый в заблуждение отпечатками,</li>
            <li>проявляется как Тройственный мир.</li>
            <li>Ничто не рождается, прежде не существовав,</li>
            <li>и ничто не пресекается условиями.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>141. Когда обусловленное видится</li>
            <li>подобным сыну бесплодной женщины</li>
            <li>или цветку в небе,</li>
            <li>тогда, распознав эту иллюзию,</li>
            <li>схватывание и схватываемое прекращаются.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>142. Нет ни того, что должно возникнуть,</li>
            <li>ни возникшего, и сами условия — ничто.</li>
            <li>Это нигде и никем не обнаруживается,</li>
            <li>а то, что изрекается —</li>
            <li>лишь условное обозначение.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.29 (29. Четыре вида признаков речи и построения понятий)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>

        <p>— Пусть Благословенный разъяснит изложение Дхармы (<em>dharmaparyāya</em>), именуемое «Сутью признаков речи и построений понятий» (<em>vāgvikalpa-lakṣaṇa-hṛdaya</em>)! Дабы благодаря этому ясно разграниченному и упорядоченному учению я и другие бодхисаттвы-махасаттвы постигли двойственный путь выражения и выражаемого смысла (<em>abhilāpa-abhilāpya-artha</em>) и, быстро достигнув непревзойдённого совершенного пробуждения, очистили бы всех живых существ от двойственного пути.</p>

        <p>Благословенный сказал:</p>

        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Существует, Махамати, четыре вида речи и различающих построений:</li>
            <li>• Речь признаков (<em>lakṣaṇa-vāk</em>);</li>
            <li>• Речь сновидений (<em>svapna-vāk</em>);</li>
            <li>• Речь привязанности к косным различениям (<em>dauṣṭhulya-vikalpa-abhiniveśa-vāk</em>);</li>
            <li>• Речь безначальных различений (<em>anādi-vikalpa-vāk</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Здесь, Махамати, речь признаков (<em>lakṣaṇa-vāk</em>) возникает из привязанности к формам и образам-знакам, созданным собственным построением понятий.</li>

            <li>Речь сновидений (<em>svapna-vāk</em>), Махамати, возникает из припоминания ранее пережитого, даже когда само это переживание отсутствует после пробуждения.</li>

            <li>Речь привязанности к косным различениям (<em>dauṣṭhulya</em>) возникает из воспоминаний о вражде и прошлых деяниях, и из привязанности к ним.</li>

            <li>Речь безначальных различений, Махамати, возникает из семян и привычных следов (<em>vāsanā</em>), порождённых привязанностью к косности многообразия понятий (<em>prapañca</em>), тянущегося из безначальных времён.</li>

            <li>Таковы, Махамати, четыре вида речи и различающих построений, о которых Я говорил; это и есть ответ на твой вопрос.<a href="#citation-285" id="ref-285" class="citation-mark"><sup>285</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.30 (30. Путь проявления речи и построения понятий)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному с той же просьбой:</p>
        <p>— Пусть Благословенный ещё раз разъяснит путь проявления речи и построения понятий! Где, из чего, как и почему, о Благословенный, у людей возникают эти построения понятий и как эти построения понятий выражаются в речи (<em>vāg-vijñapti-vikalpa</em>)?</p>
        <p>Благословенный ответил:</p>
        <p>— Махамати, речь приходит в движение благодаря сочетанию головы, груди, носа, горла, нёба, губ, языка и зубов.</p>
        <p>Махамати спросил:</p>
        <p>— Но является ли речь, о Благословенный, отличной от построения понятий (<em>vikalpa</em>) или же она не отлична от него?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, речь не отлична от построения понятий, но и не тождественна ему. Почему это так? Потому что, Махамати, речь возникает, опираясь на построение понятий как на свою причину. Если бы, Махамати, речь была отлична от построения понятий, она не имела бы его своей причиной.</li>
            <li>Если бы она была тождественна ему, она не могла бы выполнять роль проявления смысла (<em>arthābhivyaktitvāt</em>). Однако она её выполняет. Потому она не отлична от него и не тождественна ему.<a href="#citation-286" id="ref-286" class="citation-mark"><sup>286</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.31 (31. Обозначаемое словом и высший смысл)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Махамати вновь спросил:</p>
        <p>— Благословенный, является ли само слово высшим смыслом (<em>paramārtha</em>), или же высший смысл — это то, что обозначается словом?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Нет, Махамати, ни само слово не является высшим смыслом, ни то, что им обозначается. Почему это так? Поскольку слова лишь вводят в словесное указание на благородное блаженство (<em>āryasukha</em>) высшего смысла, сами они — не высший смысл. Высший смысл, Махамати, есть сфера личного постижения благородным знанием (<em>āryajñāna-pratyātmagati</em>); он недоступен рассудочному различению и речевому построению понятий. Потому построение понятий не может явить высший смысл.</li>

            <li>Слово же, Махамати, возникает и мгновенно исчезает; оно мимолётно (<em>capala</em>) и рождено из сочетания взаимных условий. То же, что рождено из условий, не может явить высший смысл. Из-за отсутствия признаков «себя» и «другого» оно не может явить признаки внешнего.</li>

            <li>Более того, Махамати, поскольку [весь мир] есть лишь видимое собственным умом, и поскольку внешнее бытие и небытие суть лишь разнообразные многоцветные признаки, — структура понятий, выраженная в речи, не способна охватить высший смысл. Поэтому, Махамати, тебе следует пребывать свободным от разнообразных построений понятий, порождаемых речью.</li>

            <li>Об этом сказано так:</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>143. Все явления лишены собственной природы;</li>
            <li>даже слова о «бытии» — ложны.</li>
            <li>Не узрев смысла шуньяты и не-шуньяты (<em>śūnyatā-aśūnyatā</em>),</li>
            <li>невежда устремляется вперёд.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>144. Собственная природа всех явлений и речь людей — </li>
            <li>лишь построение понятий;</li>
            <li>но и самого этого построения нет;</li>
            <li>нирвана подобна сну. Исследуй бытие так,</li>
            <li>чтобы не оставаться в сансаре и не угасать в нирване.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>145. Подобно тому как царь или богач</li>
            <li>манит своих детей пёстрыми глиняными зверушками,</li>
            <li>давая им наиграться,</li>
            <li>а затем дарит им истинных зверей, —</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>146. так и Я, используя разнообразные признаки</li>
            <li>и отображения дхарм, наставляю своих сыновей,</li>
            <li>дабы привести их к пределу истинности (<em>bhūtakoṭi</em>),</li>
            <li>постигаемому лишь в собственном опыте.<a href="#citation-287" id="ref-287" class="citation-mark"><sup>287</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.32 (32. Мир как отражение и представление: разрушение иллюзий)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Пусть Благословенный разъяснит [природу] всех дхарм — свободную от существования и несуществования, тождественности и нетождественности, обоих и ни того ни другого [вместе], вечности и непостоянства; недоступную всем подходам тиртхиков, но постигаемую на пути личного благородного знания (<em>ārya-pratyātmajñāna-gati-gamya</em>); свободную от измышленных собственных и общих признаков; являющуюся вхождением в истину высшего смысла (<em>paramārtha-tattvāvatāra</em>); характеризующуюся последовательной связью ступеней (<em>bhūmy-anusaṃdhi-krama</em>) и всё более глубоким очищением (<em>uttarottara-viśuddhi</em>); характеризующуюся вхождением на ступень Татхагаты (<em>tathāgatabhūmy-anupraveśa</em>); [действующую] без усилий (<em>anābhoga</em>), силой прежних обетов (<em>pūrva-praṇidhāna</em>) и подобно драгоценному камню, отражающему всевозможные формы; разворачивающую бесконечное многообразие признаков в различных сферах объектов (<em>viṣayānantalakṣaṇapracāra</em>); и характеризующуюся различением уровней сферы того, что воспринимается как видимое собственным умом (<em>svacittadṛśya-gocara-gati-vibhāga-lakṣaṇa</em>).</li>
            <li>Дабы я и другие бодхисаттвы-махасаттвы, устранив воззрения, основанные на <em>воображаемой природе</em>, собственных и общих признаках и подобном, быстро достигли непревзойдённого совершенного пробуждения и привели всех живых существ к полноте всех благих качеств!</li>
        </ul>
        </blockquote>

        <p>Благословенный сказал:</p>
        <p>— Превосходно, Махамати! Истинно превосходно, Махамати, что ты пожелал вопрошать об этом смысле. Ты действуешь ради блага многих, ради счастья многих, из сострадания к миру, ради пользы, блага и счастья богов и людей. Потому слушай внимательно и удерживай это в уме. Я разъясню тебе.</p>
        <p>— Да, Благословенный! — ответил Махамати.</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, из-за непонимания того, что всё есть лишь воспринимаемое собственным умом, невежды привязываются к внешним многообразным явлениям. Из-за привязанности к различениям, возникающим из отпечатков умозрительных построений о несуществовании и существовании, тождественности и нетождественности, обоих и ни того ни другого, вечности и непостоянстве, они продолжают измышлять структуры понятий.</li>

            <li>Подобно тому, Махамати, как олени в летний зной, мучимые жаждой, принимают мираж за воду и бегут к нему, не понимая, из-за заблуждения восприятия собственного ума, что никакой воды здесь нет, — так и невежды, чей разум с безначальных времён пропитан отпечатками безначального расширяющегося построения понятий, а умы опалены огнём страсти, гнева и заблуждения, жаждут разнообразных форм и объектов. Пребывая в плену воззрений о рождении, пребывании и распаде, они впадают в цепляние за тождественность и нетождественность, существование и несуществование.</li>

            <li>Подобно тому, Махамати, как у неискушённых людей возникает представление о городе при виде города гандхарвов — хотя там нет никакого города, — и этот облик города видится лишь из-за привязанности к безначальным отпечаткам-семенам города; и этот «город» — ни не-город, ни город, — точно так же, Махамати, те, кто с безначальных времён привязан к отпечаткам разрастающихся умозрительных учений тиртхиков, цепляются за утверждения о тождественности и нетождественности, существовании и несуществовании, поскольку их разум не удостоверился в том, что всё есть лишь воспринимаемое собственным умом.</li>

            <li>Подобно тому, Махамати, как человек во сне видит страну и внутренние покои дворца, украшенные мужчинами, женщинами, слонами, конями, колесницами, пешими воинами, городами, деревнями, коровами, буйволами, лесами, парками, разнообразными горами, реками, прудами и озёрами, а затем пробуждается, — и, пробудившись, продолжает вспоминать ту страну и дворец как существовавшие [на самом деле].<a href="#citation-288" id="ref-288" class="citation-mark"><sup>288</sup></a></li>
           <li>Как ты думаешь, Махамати, можно ли назвать мудрым человека, который удерживает в памяти и обдумывает иллюзорное многообразие своего сна?</li>
        </ul>
        </blockquote>
        <p>— О нет, Благословенный!</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Точно так же, Махамати, невежды, укушенные дурными воззрениями и увлечённые учениями тиртхиков, не распознают, что всё — лишь воспринимаемое собственным умом, подобное сну. Они цепляются за воззрения о тождественности и нетождественности, существовании и несуществовании.</li>

            <li>Подобно тому, Махамати, как на картине, написанной художником, нет ни впадин, ни выступов, но невежды воображают их там, — точно так же в будущем люди, вскормленные отпечатками воззрений и различающих построений тиртхиков, будут цепляться за утверждения о тождественности, нетождественности, обоих и ни того ни другого. Сами заблудшие, они станут называть нигилистами тех, кто учит о не-возникновении (<em>anutpāda-vādin</em>) и свободен от крайностей «существующего» и «несуществующего». Отрицая причины и плоды (<em>hetu-phala-apavādin</em>), они дурными воззрениями выкорчёвывают благие и светлые корни. Те, кто ищет высшего блага, должны держаться от них как можно дальше! Павшие в воззрения о своём, другом и обоих, чьи устремления погрузились в ложные различения существования и несуществования, приписывания (<em>samāropa</em>) и отрицания (<em>apavāda</em>), они устремляются в адские миры.</li>

            <li>Подобно тому, Махамати, как люди с помутнением зрения (<em>taimirika</em>), видя мнимый пучок волос, говорят друг другу: «Смотрите, как это дивно! Поглядите, о почтенные!» — но этот пучок волос не является ни явлением, ни отсутствием явления, поскольку его видят одни и не видят другие, — точно так же и тиртхики, глубоко укоренённые в различениях дурных воззрений, цепляются за утверждения о тождественности, нетождественности, обоих и ни того ни другого, за крайности «существующего» и «несуществующего»; клевеща на истинную Дхарму, они губят и себя, и других.</li>

            <li>Подобно тому, Махамати, как мнимое «огненное» колесо, возникающее от быстрого вращения горящей лучины, воображается невеждами колесом, но не мудрецами, — точно так же павшие в дурные воззрения тиртхиков будут измышлять тождественность, нетождественность, оба и ни то ни другое при возникновении всех явлений.</li>

            <li>Подобно тому, Махамати, как во время дождя водяные пузыри кажутся невеждам хрусталём, и они бегут к ним, — но эти пузыри не являются ни хрусталём, ни не-хрусталём, поскольку глаз их видит, но рука не может схватить, — точно так же, Махамати, тиртхики, чей разум пропитан отпечатками ложных различений, будут утверждать возникновение несуществующего благодаря условиям и разрушение существующего.<a href="#citation-289" id="ref-289" class="citation-mark"><sup>289</sup></a></li>

            <li>Кроме того, Махамати, в будущем некоторые будут утверждать, опираясь на выстраивание доводов и три средства познания (<em>pramāṇa</em>), будто существует сама по себе некая данность (<em>vastu</em>), постигаемая личным благородным знанием и свободная от двух видов собственной природы. </li>

            <li>Однако, Махамати, у йогинов, чей ум (<em>citta</em>), <em>манас</em> (<em>manas</em>) и различающее сознание (<em>vijñāna</em>) совершили поворот основы (<em>parāvṛtti</em>), кто оставил различения между схватываемым и схватывающим и кто вошёл в сферу личного благородного знания ступени Татхагаты, — у них не возникает представления (<em>saṃjñā</em>) явления и отсутствия явления. Если бы у таких йогинов, пребывающих в этой сфере, всё же возникло цепляние за явление и его отсутствие, это было бы у них цеплянием за «я» (<em>ātman</em>), цеплянием за «питающее» (<em>poṣa</em>), цеплянием за «человека» (<em>puruṣa</em>) и цеплянием за «личность» (<em>pudgala</em>).</li>

            <li>Помни, Махамати: учения о собственной природе явлений и их собственных и общих признаках — это поучения Явленного Будды (<em>nairmāṇikabuddha-deśanā</em>), а не поучения Будды-дхарматы (<em>dharmatābuddha-deśanā</em>). Эти поучения, Махамати, сообразуются с воззрениями, укоренёнными в умах невежд, но они не раскрывают блаженства <em>самадхи</em> и прямого личного постижения посредством благородного знания.</li>

            <li>Подобно тому, Махамати, как тень дерева видится в воде, но она не является ни тенью, ни не-тенью — поскольку она и соответствует форме дерева, и не соответствует ей, — точно так же, Махамати, тиртхики, чей разум пропитан отпечатками дурных воззрений, измышляют тождественность, нетождественность, оба вместе и ни то ни другое, существование и несуществование, не удостоверившись в том, что всё есть лишь воспринимаемое собственным умом.</li>

            <li>Подобно тому, Махамати, как в зеркале видны отражения всех форм в зависимости от условий и собственного построения понятий, — эти отражения не являются ни самими прообразами (<em>bimba</em>), ни не-прообразами, поскольку они и видимы как образы, и не являются самими образами, и всё же они видятся невеждам в форме реальных очертаний, — точно так же отражения собственного ума проявляются в виде воззрений о тождественности, нетождественности, обоих вместе и ни том ни другом.</li>

            <li>Подобно эху, Махамати, которое слышится вследствие сочетания человека, реки и ветра, — оно не является ни явлением, ни отсутствием явления, поскольку звук то слышится, то не слышится, — точно так же проявляются различения, возникающие из отпечатков собственного ума, принимая форму воззрений о существовании и несуществовании, тождественности и нетождественности.</li>

            <li>Подобно тому, Махамати, как на лишённой травы и кустарников земле под лучами солнца колеблется мираж, подобный волнам, — и он не является ни явлением, ни отсутствием явления, поскольку вызывает влечение, но им невозможно обладать, — точно так же, Махамати, различающее сознание невежд, пропитанное с безначальных времён отпечатками пагубной косности понятийного разрастания, волнуется, подобно миражу, даже в отношении сферы личного благородного знания, порождая различения возникновения, пребывания, распада, тождественности, нетождественности, обоих, ни того ни другого, существования и несуществования.</li>

            <li>Подобно тому, Махамати, как механическая кукла и оживлённый труп (<em>vetāla</em>), будучи лишены жизни, совершают движения и действия лишь силой чар пишачей, и невежды впадают в ложные различения из-за восприятия их движений и перемещений, — точно так же невежды, павшие в лоно дурных воззрений тиртхиков, впадают в утверждения о тождественности и нетождественности. Но всё это — лишь ложное приписывание несуществующего (<em>asadbhūta-samāropa</em>).</li>

            <li>Потому, Махамати, тебе следует пребывать свободным от различений возникновения, пребывания, распада, тождественности, нетождественности, обоих, ни того ни другого, существования и несуществования — свободным даже в отношении личного постижения благородной данности.</li>
        </ul>

        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>147. Пять <em>скандх</em>, во главе с сознанием,</li>
            <li>подобны отражению деревьев в воде,</li>
            <li>магии и сну; не измышляй</li>
            <li>различений посредством представления (<em>vijñapti</em>)!</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>148. Этот Тройственный мир</li>
            <li>подобен видению пучка волос или водному миражу;</li>
            <li>он зовётся сном и магией.</li>
            <li>Лишь тот, кто созерцает его так, обретает свободу.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>149. Как мираж в зной колеблется, обманывая разум,</li>
            <li>и олени бегут к нему за водой, хотя воды там нет, —</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>150. так и семя сознания (<em>vijñāna-bīja</em>)</li>
            <li>пульсирует в сфере видимого.</li>
            <li>Невежды хватаются за возникающее,</li>
            <li>подобно тому как страдающие болезнью глаз</li>
            <li>видят пучки волос.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>151. В безначальной сансаре,</li>
            <li>объятой цеплянием за явления (<em>bhāva</em>), </li>
            <li>невежду следует отвратить от заблуждений,</li>
            <li>подобно тому как один колышек выбивают другим.</li>
        </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>152. Созерцая этот мир как механическую куклу,</li>
            <li>как призрака (<em>vetāla</em>), как сон,</li>
            <li>вспышку молнии или облако, —</li>
            <li>через пресечение трёх непрерывностей (<em>trisaṃtati</em>)</li>
            <li>человек освобождается.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>153. В этом нет никакого представления об объектах,</li>
            <li>как нет воды в небесных миражах.</li>
            <li>Постигая так дхармы,</li>
            <li>мудрые не выдвигают никаких утверждений.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>154. Представление — лишь имя;</li>
            <li>по собственному признаку (<em>lakṣaṇa</em>)</li>
            <li>оно не существует.</li>
            <li><em>Скандхи</em> подобны пучкам волос в воздухе,</li>
            <li>в которых и строится различение.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>155. Подобно волоскам в глазу, иллюзии, сну,</li>
            <li>городу гандхарвов, огненному колесу и миражу</li>
            <li>ум кажется людям существующим, хотя не существует.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>156. Вечное и невечное,</li>
            <li>тождественность и нетождественность,</li>
            <li>и то, и другое, и ни то, ни другое —</li>
            <li>всё это невежды, опутанные безначальными пороками,</li>
            <li>воображают в своём ослеплении.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>157. В зеркале, в воде, в глазу,</li>
            <li>в полированном сосуде и в драгоценном камне —</li>
            <li>всюду видится отражение (<em>bimba</em>),</li>
            <li>но этого отражения нет ни в одном из них.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>158. Так и ум — лишь кажимость явлений,</li>
            <li>подобно миражу в небе;</li>
            <li>он является в многообразных формах,</li>
            <li>как сын бесплодной женщины, увиденный во сне.<a href="#citation-290" id="ref-290" class="citation-mark"><sup>290</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.33 (33. Учение Татхагат: свобода от крайностей и очищение от завес)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, поучение Татхагат в Дхарме свободно от четвероякого рассмотрения крайностей (<em>catuṣṭaya</em>). Оно оставляет стороны тождественности и нетождественности (<em>ekatva-anyatva</em>), обоих [вместе] и ни того ни другого; оно свободно от ложного приписывания (<em>samāropa</em>) и отрицания (<em>apavāda</em>) существования и несуществования.</</li>

            <li>Поучение Татхагат, Махамати, разворачивает освобождение через путь прекращения ложного зависимого возникновения (<em>asatya-pratītyasamutpāda-nirodha-mārga-vimokṣa-pravṛtti-pūrvakā</em>). Поучение Татхагат не связано с представлениями о Первоматерии (<em>prakṛti</em>), Владыке-Творце (<em>īśvara</em>), причине (<em>hetu</em>), случайности (<em>yadṛcchā</em>), атомах (<em>aṇu</em>), времени (<em>kāla</em>) или собственной природе (<em>svabhāva</em>).</</li>

            <li>Кроме того, Махамати, ради очищения от двоякой завесы — завесы омрачений (<em>kleśa-āvaraṇa</em>) и завесы познаваемого (<em>jñeya-āvaraṇa</em>) — Татхагаты, подобно проводникам караванов (<em>sārthavāha</em>), последовательно утверждают [йогинов] в ста восьми положениях, свободных от образов (<em>nirābhāsa-pada-śata</em>), а также в ясном различении колесниц, ступеней и составляющих пути.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4
    mb-4">Подглава 2.34 (34. Четыре вида дхьяны)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, существует четыре вида дхьяны. Каковы эти четыре?</li>
            <li>— <em>Дхьяна, свойственная невеждам</em> (<em>bālopacārikam</em>);</li>
            <li>— <em>Дхьяна исследования смысла</em> (<em>arthapravicayam</em>);</li>
            <li>— <em>Дхьяна, опирающаяся на Таковость</em> (<em>tathatālambanam</em>);</li>
            <li>— <em>Дхьяна Татхагаты</em> (<em>tāthāgatam</em>) — четвёртая.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Что же, Махамати, есть <em>дхьяна, свойственная невеждам</em>? Это созерцание, присущее йогинам-шравакам и пратьекабуддам, когда они, привязавшись к признакам отсутствия «я» в личности (<em>pudgala-nairātmya</em>), к образам собственных и общих признаков явлений, а также к признакам непостоянства, страдания и нечистоты, наблюдают всё это последовательно, вплоть до прекращения восприятия (<em>saṃjñā-nirodha</em>), полагая: «Этот признак именно таков и не иначе».</li>

            <li>Что есть <em>дхьяна исследования смысла</em>? Это созерцание, когда йогин, отвергнув воззрения внешних тиртхиков о «я», «другом» и «обоих», а также о собственных и общих признаках, последовательно исследует смысл отсутствия «я» в дхармах (<em>dharma-nairātmya</em>) и признаки ступеней (<em>bhūmi</em>).</li>

            <li>Что есть <em>дхьяна, опирающаяся на Таковость</em>? Это состояние, когда благодаря пребыванию в реальности как она есть (<em>yathābhūta</em>) прекращается развёртывание построений понятий (<em>vikalpa</em>) о воображаемом двойном отсутствии «я» (<em>nairātmya-dvaya</em>). Я называю это «дхьяной, опирающейся на Таковость».</li>

            <li>Что же есть <em>дхьяна Татхагаты</em>? Это вхождение в образ ступеней Татхагаты, пребывание в блаженстве трёх признаков личного благородного знания (<em>pratyātmāryajñāna</em>) и совершение непостижимых деяний ради живых существ. Это Я называю «дхьяной Татхагаты».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>159. <em>Дхьяна исследования смысла</em>,</li>
            <li><em>дхьяна, свойственная невеждам</em>,</li>
            <li><em>дхьяна, опирающаяся на Таковость</em>,</li>
            <li>и <em>дхьяна Татхагаты</em> — благая.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>160. Подобно образу луны и солнца,</li>
            <li>подобно багровому лотосу во тьме,</li>
            <li>подобно небу или вспышкам огня —</li>
            <li>такие разнообразные [образы]</li>
            <li>созерцает йогин в своей практике.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>161. [Но] эти многообразные образы-знаки (<em>nimitta</em>)
            <li>уводят [йогина] на пути тиртхиков,</li>
            <li>или же низвергают в состояние шраваков</li>
            <li>и в область пратьекабудд.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>162. Когда же, отбросив всё это,</li>
            <li>йогин пребывает в без-образности (<em>nirābhāsa</em>),</li>
            <li>тогда Будды из всех миров, сияющие как солнца,</li>
            <li>собираются вместе и возлагают руки на его голову —</li>
            <li>[это] образ-знак (<em>nimitta</em>), согласующийся с Таковостью.<a href="#citation-291" id="ref-291" class="citation-mark"><sup>291</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.35 (35. Нирвана)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
    <p>— «Нирвана, нирвана», о Благословенный, — так говорится. Обозначением чего именно является это слово «нирвана»?</p>
    <p>Благословенный ответил:</p>

    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Нирваной всеми Буддами и Мною именуется поворот основы (<em>parāvṛtti</em>) — преобразование отпечатков (<em>vāsanā</em>), [через которые] все виды сознания (<em>sarva-vijñāna</em>) воспринимают [свои объекты] как обладающие собственной природой (<em>svabhāva</em>), а также преобразование отпечатков воззрений (<em>dṛṣṭi-vāsanā</em>), укоренённых в <em>Алае</em>, <em>манасе</em> и <em>мановиджняне</em>; это — путь нирваны (<em>nirvāṇa-gati</em>), чья сфера опыта (<em>vastu-gocara</em>) раскрывается как <em>шуньята</em> собственной природы явлений.<a href="#citation-292" id="ref-292" class="citation-mark"><sup>292</sup></a></li>

        <li>Кроме того, Махамати, нирвана — это сфера личного благородного постижения, свободная от построений понятий о вечности и уничтожении, о явлении и отсутствии явления.</li>

        <li>Почему она не является вечностью? Потому что в ней оставлены построения понятий о собственных и общих признаках; потому она не является вечностью.</li>

        <li>Почему в ней нет уничтожения? Потому что все содержания  (<em>sarvārtha</em>) прошлого, будущего и настоящего обращаются к сфере личного постижения; потому это — не уничтожение.</li>

        <li>Более того, Махамати, Великая Нирвана — это не уничтожение и не смерть. Если бы Великая Нирвана была смертью, Махамати, то вновь возникала бы непрерывность рождения. Если бы она была уничтожением, она подпадала бы под признаки обусловленного. По этой причине, Махамати, Великая Нирвана — ни уничтожение, ни смерть. Йогины же достигают смерти, свободной от нового рождения.</li>

        <li>Кроме того, Махамати, Великая Нирвана именуется нирваной, поскольку она — ни оставление, ни достижение; вне уничтожения и вечности, вне единства и множественности.</li>

        <li>Более того, Махамати, нирвана шраваков и пратьекабудд [заключается в том], что благодаря постижению собственных и общих признаков они пребывают в обособленности (<em>asaṃsarga</em>). Благодаря видению объектов без искажений, их построение понятий (<em>vikalpa</em>) более не разворачивается. Именно поэтому у них возникает представление о том, что это и есть нирвана.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.36 (36. Две формы признака собственной природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
        <li>Кроме того, Махамати, признак собственной природы проявляется двояко. Каковы эти два вида?</li>
        <li>- Привязанность к собственной природе словесных обозначений (<em>abhilāpa-svabhāva-abhiniveśa</em>);</li>
        <li>- Привязанность к собственной природе объектов (<em>vastu-svabhāva-abhiniveśa</em>).</li>
        <li>Махамати, привязанность к собственной природе словесных обозначений разворачивается вследствие привязанности к отпечаткам (<em>vāsanā</em>) безначального размножествления понятий, выражаемого речью (<em>vāk-prapañca</em>).</li>
        <li>Привязанность же к собственной природе объектов, Махамати, разворачивается вследствие непостижения того, что всё есть лишь воспринимаемое собственным умом (<em>svacitta-dṛśya-mātra</em>).</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.37 (37. Поддержка Татхагат)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
       <li>Кроме того, Махамати, благодаря двоякой поддержке (<em>adhiṣṭhāna</em>) бодхисаттвы склоняются к стопам Татхагат, Архатов, Совершенно Пробуждённых и задают им вопросы. Какова эта двоякая поддержка?<br>
        — поддержка через вхождение в <em>самадхи</em> (<em>samādhi-samāpatti</em>);<br>
        — поддержка через посвящение телом, ликом и руками (<em>sarva-kāya-mukha-pāṇi-abhiṣeka</em>).</li>

        <li>Махамати, на первой ступени (<em>bhūmi</em>) бодхисаттвы-махасаттвы, удерживаемые поддержкой Будд, входят в <em>самадхи</em> бодхисаттв под названием «Сияние Махаяны» (<em>mahāyāna-prabhāsa</em>). Как только они входят в это <em>самадхи</em>, Татхагаты, пребывающие в мирах десяти сторон света, осуществляют поддержку через проявление [своих] тел, ликов и речи. Подобно тому как это происходит с бодхисаттвой Ваджрагарбхой и другими бодхисаттвами-махасаттвами, наделёнными подобными признаками и качествами, так и бодхисаттвы-махасаттвы на первой ступени обретают поддержку через вхождение в <em>самадхи</em>.</li>

        <li>Накопив корни благого в течение сотен тысяч кальп и постепенно постигая признаки благоприятствующих и препятствующих факторов на ступенях, бодхисаттва-махасаттва достигает десятой ступени бодхисаттв — «Облака Дхармы» (<em>dharmameghā</em>). Там, восседая на престоле в великом лотосовом чертоге, окружённый бодхисаттвами-махасаттвами, соответствующими ему по качествам, в короне, украшенной всеми драгоценностями, — руки Победителей (<em>jina-karāḥ</em>), [сияющие] подобно аурипигменту, золоту, цветам чампака, лунным лучам и лотосу, простёртые из миров десяти сторон света, изливают воду посвящения на голову этого бодхисаттвы-махасаттвы, восседающего на лотосовом престоле, подобно помазанию царя-чакравартина, владыки по собственной воле. И этот бодхисаттва, и те бодхисаттвы именуются удерживаемыми поддержкой через посвящение руками.</li>

        <li>Такова, Махамати, двоякая поддержка бодхисаттв-махасаттв. Благодаря этой двоякой поддержке бодхисаттвы-махасаттвы взирают на лики всех Будд. Вне этого Татхагаты, Архаты, Совершенно Пробуждённые недоступны для взора.</li>

        <li>Кроме того, Махамати, всё, что раскрывается бодхисаттвам-махасаттвам в форме <em>самадхи</em>, чудесных сил (<em>ṛddhi</em>) или наставления (<em>deśanā</em>), — всё это происходит благодаря двоякой поддержке всех Будд.</li>
        <li>Если бы, Махамати, подобное раскрытие возникало у бодхисаттв-махасаттв без поддержки, то и у обычных непросветлённых людей (<em>bāla-pṛthagjana</em>) возникало бы такое же раскрытие. Почему это не так? Потому что они не удерживаются этой поддержкой.</li>

        <li>Махамати, благодаря поддержке вхождения Татхагаты (<em>tathāgata-praveśa-adhiṣṭhāna</em>) даже травы, кусты, деревья и горы, а также различные музыкальные инструменты, города, дворцы, дома, небесные чертоги и троны приводятся к звучанию.</li>

        <li>Что же говорить о наделённых сознанием? Даже немые, слепые и глухие, Махамати, освобождаются от своих недостатков.</li>

        <li>Таково, Махамати, особое великое качество поддержки Татхагаты.</li>
    </ul>
    </blockquote>
    <p>Махамати вновь спросил:</p>

    <p>— Благословенный, почему Татхагаты, Архаты, Совершенно Пробуждённые оказывают поддержку (<em>adhiṣṭhāna</em>) бодхисаттвам-махасаттвам во время пребывания в достижении <em>самадхи</em> и на особых ступенях, включая посвящение (<em>abhiṣeka</em>)?</p>

    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
        <li>Ради освобождения их от Мары, кармы и омрачений (<em>kleśa</em>); чтобы они не пали на ступень созерцания шраваков; ради их личного постижения ступени Татхагаты; и ради углубления постижения уже достигнутой Дхармы.</li>

        <li>По этой причине, Махамати, Татхагаты, Архаты, Совершенно Пробуждённые поддерживают бодхисаттв-махасаттв своей поддержкой (<em>adhiṣṭhāna</em>).</li>

        <li>Без этой поддержки, Махамати, бодхисаттвы-махасаттвы, впав в скрытые устремления (<em>āśaya</em>) ложных тиртхиков, шраваков или Мары, не достигли бы непревзойдённого совершенного пробуждения.</li>

        <li>Именно поэтому бодхисаттвы-махасаттвы благостно поддерживаются (<em>anugṛhyante</em>) Татхагатами, Архатами, Совершенно Пробуждёнными.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>163. Поддержка Владык Людей (<em>narendra</em>)</li>
        <li>очищена их обетами (<em>praṇidhāna</em>);</li>
        <li>посвящение, <em>самадхи</em> </li>
        <li>и прочие [формы поддержки даруются]</li>
        <li>от первой до десятой [ступени].</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <hr class="my-8 border-t-4 border-gray-500">

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.38 (38. Спор о зависимом возникновении)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
    <p>Затем Бодхисаттва Махамати вновь сказал Благословенному:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
        <li>Благословенный, проповедуя зависимое возникновение, Ты даёшь лишь обозначение причин (<em>kāraṇavyapadeśa</em>), но не раскрываешь пребывание [явлений] в собственной природе согласно Твоему собственному методу (<em>svanaya-prakṛtyavasthāna-kathā</em>). Тиртхики тоже описывают возникновение из причин: из Первоматерии, Владыки-Творца, Духа, Времени и атомов как причинных начал. [По их мнению] возникновение явлений происходит от них. Ты же, Благословенный, описываешь возникновение явлений, используя иной термин для условий (<em>pratyayaparyāyāntareṇa</em>). И между этими доктринами нет особого различия.</li>

        <li>И те, и другие описывают возникновение явлений в терминах бытия и небытия, а затем — их разрушение после возникновения в силу условий. А то, что сказано Тобой, Благословенный: «Из неведения возникают формирующие факторы и так далее (<em>avidyāpratyayāḥ saṃskārā...</em>) до старости и смерти» — это есть не что иное, как изложение учения о беспричинности (<em>ahetuvādavyapadeśa</em>), а не учение о причине (<em>hetuvāda</em>). Твоё изречение: «При наличии этого возникает то» — справедливо лишь для одновременно существующих [причины и следствия], но не для того, что разворачивается последовательно.</li>

        <li>Более того, доводы тиртхиков кажутся убедительнее Твоих! Почему? У тиртхиков причина, не возникшая зависимо, порождает следствие. У Тебя же, Благословенный, причина зависит от следствия, а следствие зависит от причины. Так возникает смешение причины и условия, и взаимное необоснование (<em>anyonyānavasthā</em>). И утверждается беспричинность мира, Благословенный, когда Ты говоришь: «При наличии этого возникает то».</li>
    </ul>
    </blockquote>
    <p>Благословенный ответил:</p>
    <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>Нет, Махамати. Из Моего учения не следует беспричинность или смешение причин и условий, когда Я говорю: «При наличии этого возникает то». Поскольку отсутствуют воспринимаемое и воспринимающий (<em>grāhyagrāhakābhāvāt</em>) и имеется постижение того, что всё есть лишь воспринимаемое собственным умом (<em>svacittadṛśyamātrāvabodhāt</em>).</li>

        <li>Этот изъян, Махамати, возникает у тех, кто привязан к воспринимаемому и воспринимающему и не постигает, что [мир] есть лишь воспринимаемое собственным умом, усматривая внешние объекты как существующие или несуществующие. У них, Махамати, возникает этот изъян, но не у Меня, дающего обозначение зависимых причин (<em>pratītyakāraṇavyapadeśa</em>).<a href="#citation-293" id="ref-293" class="citation-mark"><sup>293</sup></a></li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.39 (39. Спор о словесных обозначениях и явлениях)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Махамати вновь спросил:</p>
        <p>— Но разве, Благословенный, существование словесных обозначений (<em>abhilāpa</em>) не подразумевает существование всех явлений? Ведь если бы явлений не было, то и словесные обозначения не употреблялись бы. Но они употребляются. Следовательно, Благословенный, употребление словесных обозначений доказывает существование всех явлений.</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Махамати, словесные обозначения употребляются даже в отношении несуществующих явлений. Разве в мире не говорят о «рогах зайца», «шерсти черепахи» или «сыне бесплодной женщины»? Они, Махамати, не относятся ни к явлениям, ни к не-явлениям (<em>na bhāvā nābhāvāḥ</em>) и всё же о них говорят. Поэтому твой довод о том, что все явления существуют благодаря употреблению словесных обозначений, несостоятелен.</li>

            <li>К тому же, Махамати, не во всех землях Будд (<em>buddhakṣetreṣu</em>) принято словесное обозначение. Словесное обозначение, Махамати, является придуманным (<em>kṛtaka</em>). В одних землях Будд Дхарма передается через пристальный взгляд (<em>animiṣaprekṣayā</em>), в других — через жесты, в иных — через движение бровей (<em>bhūvikṣepeṇa</em>), через движение глаз (<em>netrasaṃcāreṇa</em>), через мимику (<em>āsyena</em>), через зевание (<em>vijṛmbhitena</em>), через покашливание (<em>utkāsanaśabdena</em>), через памятование о [другой] земле (<em>kṣetrasmṛtyā</em>), или через лёгкое движение/трепет (<em>spanditena</em>).</li>

            <li>Подобно тому, Махамати, как в мире «Немигающего Благоухания» (<em>Animiṣā Gandhasugandhā</em>), в чистой земле Татхагаты, Архата, Всесовершенного Будды Самантабхадры, бодхисаттвы-махасаттвы, лишь созерцая друг друга немигающими глазами (<em>animiṣairnetraiḥ</em>), обретают стойкость в познании не-возникновения дхарм (<em>anutpattikadharmakṣānti</em>) и высшие <em>самадхи</em>. Именно по этой причине, Махамати, наличие словесных обозначений вовсе не означает, что все явления существуют.</li>

            <li>Это можно увидеть и здесь, Махамати: в этом мире такие существа, как черви и мухи, прекрасно совершают свои дела вообще без всяких слов (anabhilāpenaiva).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>164. О пространстве (<em>ākāśa</em>), о рогах зайца</li>
            <li>и о сыне бесплодной женщины говорят, хотя их нет;</li>
            <li>точно так же воображаются явления.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>165. Опираясь на совокупность причин </li>
            <li>и условий (<em>hetupratyayasāmagrī</em>),</li>
            <li>невежды воображают возникновение; не зная этого метода,</li>
            <li>они блуждают в обители Тройственного мира.<a href="#citation-294" id="ref-294" class="citation-mark"><sup>294</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.40 (40. Вечность иллюзии)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем Бодхисаттва-махасаттва Махамати вновь спросил Благословенного:</p>
        <p>— Относительно чего, Благословенный, Ты произносишь слово «вечный»?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Относительно иллюзии (<em>bhrānti</em>), Махамати. Ибо эта иллюзия является даже Благородным — в связи с переворачиванием [восприятия] (<em>viparyāsa</em>).</li>

            <li>Подобно тому, Махамати, как мираж, огненный круг, мушки перед глазами, город гандхарвов, магия, сон, отражение и механическая кукла принимаются невеждами за реальность, тогда как мудрецы не заблуждаются относительно них; при этом сами эти явления продолжают являться.</li>

            <li>Эта иллюзия, Махамати, способна являться в бесчисленных формах — однако это многообразие не делает её невечной. Почему? Потому что её нельзя ни утвердить как существующую, ни отвергнуть как несуществующую.</li>

            <li>Как же это понимать, Махамати? Она является сферой восприятия всех невежд во всём его многообразии — подобно волнам океана или водам Ганги: одни существа эту «воду» видят, преты же — не видят. Поэтому иллюзию нельзя признать действительно существующей; однако, поскольку она всё же является восприятию других существ, нельзя признать её и полностью несуществующей.</li>

            <li>Так и иллюзия для Благородных — за пределами как переворачивания, так и не-переворачивания [восприятия]. Поэтому, Махамати, иллюзия вечна — ибо образ-знак (nimitta) и признак (lakṣaṇa) в ней не разделяются. Она не распадается, даже когда воображается через множество разнообразных образов-знаков. Поэтому, Махамати, иллюзия — вечна.<a href="#citation-295" id="ref-295" class="citation-mark"><sup>295</sup></a></li>

            <li>Как же, Махамати, иллюзия (<em>bhrānti</em>) становится истинным (<em>tattva</em>)? Именно потому, Махамати, что у Благородных в отношении этой иллюзии не разворачивается ни представление об искажении (<em>viparyāsabuddhi</em>), ни представление о не-искажении. Благородные, Махамати, не имеют в отношении этой иллюзии никакого обозначения (<em>saṃjñā</em>) — ни «что бы то ни было», ни «предмет благородного знания» (<em>āryajñānavastu</em>). «Что бы то ни было», Махамати, — это детский лепет, а не речь Благородных.</li>

            <li>Это же самое заблуждение, различаемое через представления об искажённом и не-искажённом, порождает два рода (<em>gotra</em>): род Благородных и род обычных непросветлённых людей.</li>

            <li>Род Благородных, Махамати, принимает три формы: род шраваков, род пратьекабудд и род Будд.</li>

            <li>Как же заблуждение, различаемое невеждами, порождает род Пути шраваков? Через привязанность (abhiniveśa) к собственным и общим признакам (<em>svasāmānyalakṣaṇa</em>) оно приводит к роду шраваков. Так это заблуждение влечёт к роду шраваков.</li>

            <li>Как это же самое заблуждение порождает род Пути пратьекабудд? Через отстранение от привязанности к тем же собственным и общим признакам оно приводит к роду пратьекабудд.</li>

            <li>Как это же самое заблуждение, различаемое мудрыми, порождает род Пути Будды? Через постижение того, что всё является лишь воспринимаемым собственным умом (<em>svacittadṛśyamātra</em>), и через понимание самой природы различений о внешнем «есть» и «нет»  — оно приводит к роду Будды. Таков смысл слова «род» (<em>gotra</em>).</li>

            <li>Когда же невежды различают в этом заблуждении многообразие явлений, утверждая: «Это именно так и не иначе!» — оно влечёт их к роду вращающихся в сансаре. Поэтому невежды воображают иллюзию как множество разнообразных явлений — хотя сама она не может быть утверждена ни как то, что «есть», ни как то, чего «нет».</li>

            <li>Само же это заблуждение, когда оно более не различается у Благородных — благодаря повороту основы (<em>parāvṛtti</em>), [то есть] повороту той дхармы, что составляет природу пагубных отпечатков (<em>vāsanā</em>) ума (<em>citta</em>), <em>манаса</em> и <em>мановиджняны</em>, — именуется у Благородных Таковостью (<em>tathatā</em>). Поэтому и сказано, Махамати: «Таковость свободна от ума» (<em>tathatā cittavinirmuktā</em>). И именно для прояснения этого сказано: «лишена умопостроений (<em>kalpanā</em>), свободна от всех различений» — и так далее.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Благословенный, существует ли заблуждение (<em>bhrānti</em>) или нет?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Подобно магии (<em>māyā</em>), Махамати, заблуждение не имеет существования, основанного на привязанности к признакам (<em>lakṣaṇābhiniveśa</em>). Если бы заблуждение, Махамати, существовало в силу привязанности к признакам — привязанность к явлениям оказалась бы непрекращаемой. Это, Махамати, уподобилось бы [взгляду на] зависимое возникновение — и [взгляду на] производящую причину тиртхиков.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Но если заблуждение подобно магии — не станет ли оно причиной других заблуждений?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Нет, Махамати. Магия не является причиной заблуждения — ибо она не несёт в себе пагубного изъяна (<em>dauṣṭhulyadoṣa</em>). Магия, Махамати, когда она не является предметом различения, разворачивается опираясь на знание-заклинание другого человека (<em>parapuruṣavidyā</em>) — а не на пагубные отпечатки (<em>vāsanā</em>) собственных различений. Поэтому она не порождает изъяна. Это, Махамати, лишь помрачение ума и воззрения (<em>cittadṛṣṭimoha</em>) у невежд — возникающее из привязанности к «чему бы то ни было»; у Благородных такого нет.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>166. Благородный не видит ни заблуждения,</li>
            <li>ни истинного, ни чего-либо между ними.</li>
            <li>Само заблуждение и есть истинное,</li>
            <li>ибо истинное — между ними.<a href="#citation-296" id="ref-296" class="citation-mark"><sup>296</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>167. Если же, отбросив всякое заблуждение,</li>
            <li>[йогин] вновь порождает образ-знак (<em>nimitta</em>), —</li>
            <li>именно это и станет его заблуждением, </li>
            <li>подобно нечистому помутнению зрения (<em>timira</em>).<a href="#citation-297" id="ref-297" class="citation-mark"><sup>297</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.41 (41. Дхармы подобны магии)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Более того, Махамати, нельзя сказать, что магии (<em>māyā</em>) нет. Из видения сходства (<em>sādharmya</em>) возникает понимание, что все дхармы подобны магии.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
            <li>Через что именно, Благословенный, все дхармы подобны магии? Через признак привязанности к многообразной магии или через признак привязанности к обманчивому (<em>vitatha</em>)?</li>
            <li>Если, Благословенный, дхармы подобны магии через признак привязанности к многообразной магии, то явления не могут быть ей подобны. Почему? Потому что мы видим отсутствие единой причины, порождающей многообразие признаков формы (<em>rūpa</em>). Ибо нет, Благословенный, никакой причины, по которой форма проявлялась бы в виде многообразных признаков подобно магии. Поэтому явления не подобны магии через сходство с многообразием её признаков.<a href="#citation-298" id="ref-298" class="citation-mark"><sup>298</sup></a></li>
        </ul>
        </blockquote>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-12 pl-2 space-y-1 ml-2">
            <li>Нет, Махамати, все дхармы подобны магии не через сходство с многообразием её признаков. Они подобны магии через сходство с тем, что обманчивы, стремительны и подобны вспышке молнии.</li>
            <li>Подобно тому, Махамати, как вспышка молнии является невеждам — и тотчас исчезает из поля зрения, — точно так же и все явления, обладающие собственными и общими признаками, возникающими из различения (<em>vikalpa</em>), не раскрываются в своей природе из-за отсутствия исследования и вследствие привязанности к признакам формы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>168. Магия не есть несуществующее;</li>
            <li>из-за сходства с ней говорится,</li>
            <li>что явления существуют.</li>
            <li>Поскольку они обманчивы, </li>
            <li>стремительны и подобны вспышке молнии,</li>
            <li>поэтому они считаются подобными магии.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.42 (42. Не-возникновение и явленность)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Махамати вновь спросил:</p>
        <p>— Благословенный, когда Ты говоришь, что все явления (<em>bhāva</em>) не возникли (<em>anutpanna</em>) и подобны магии, не возникает ли тогда как следствие противоречия между предыдущим и последующим высказыванием — ведь Ты одновременно провозглашаешь не-возникновение явлений и уподобляешь их магии?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Нет, Махамати. Когда Я говорю, что все явления не возникли и подобны магии, никакого противоречия между предыдущим и последующим утверждением не возникает. Почему? Потому что благодаря постижению (<em>avabodha</em>) того, что и возникновение (<em>utpāda</em>) и не-возникновение (<em>anutpāda</em>) суть лишь воспринимаемое собственным умом (<em>svacittadṛśyamātra</em>), и благодаря видению (<em>darśana</em>) не-возникновения (<em>anutpatti</em>) внешнего (<em>bāhya</em>) «есть» и «нет» (<em>sadasat</em>) — явления и его отсутствия (<em>bhāvābhāva</em>), никакого внутреннего противоречия не возникает.</li>
            <li>Я говорю: «Все явления подобны магии и не возникли» — ради устранения (<em>vyudāsa</em>) воззрений тиртхиков о возникновении (<em>utpatti</em>) из внешней причины (<em>kāraṇa</em>). Ибо тиртхики, Махамати, охваченные заблуждением, стремятся утвердить возникновение явлений через внешние причины и не понимают, что всё возникает лишь из условий (<em>pratyaya</em>) привязанности к многообразию (<em>vicitra</em>) собственных различений  (<em>svavikalpa</em>).</li>
            <li>Для Меня же, Махамати, не возникает никакого страха [перед не-возникновением]. Поэтому и провозглашается учение о не-возникновении.</li>
            <li>Наставление о явлениях (<em>bhāva</em>), Махамати, даётся ради удержания сансары и ради предотвращения крайности, когда говорят «нет» и тем самым впадают в уничтожение (<em>uccheda</em>). Чтобы мои ученики охватывали [понимание] разнообразия кармических последствий, [способов] рождения и сфер существования — используется слово «явление».</li>
            <li>Поэтому Я учу, что все дхармы подобны магии и сну — ради отвращения невежд от их ложных воззрений: тех, чьи скрытые установки (<em>āśaya</em>) погружены в признаки (<em>lakṣaṇa</em>) ложных воззрений (<em>kudṛṣṭi</em>), кто не удостоверился в том, что всё есть лишь воспринимаемое собственным умом, и кто держится (<em>abhiniviṣṭha</em>) признаков возникновения (<em>utpatti</em>) через причины (<em>hetu</em>), условия (<em>pratyaya</em>) и действия.</li>
            <li>Эти невежды, удерживаемые скрытыми установками ложных воззрений, будут вводить в заблуждение и себя, и других — поскольку не видят подлинного способа пребывания всех дхарм.</li>
            <li>Видеть же дхармы в их подлинном способе пребывания, Махамати, — значит входить в постижение того, что всё есть лишь воспринимаемое собственным умом.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>169. В не-возникновении — отсутствие внешней причины;</li>
            <li>в [учении о] явлении — охват сансары.</li>
            <li>Следует видеть [то, что является,]</li>
            <li>подобным магии и прочему —</li>
            <li>и не выстраивать различений относительно [этого].</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.43 (43. Признаки обозначения имён, слов и знаков)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, Я разъясню признаки совокупностей имени, слова и знака (<em>nāma-pada-vyañjana-kāya</em>). Благодаря ясному распознаванию этих совокупностей бодхисаттвы-махасаттвы, следующие за смыслом, словом и знаком, быстро обретут непревзойдённое совершенное пробуждение и приведут к нему всех существ.</li>
            <li>Что же, Махамати, называется совокупностью имени (<em>nāmakāya</em>)? Это имя, возникающее на основе некоторого объекта (<em>vastu</em>); этот объект и является [его] опорой (<em>kāya</em>). «Опора» и «тело» (<em>śarīra</em>) здесь не различаются по смыслу. Такова, Махамати, совокупность имени. Что называется совокупностью слова (<em>padakāya</em>)? Это удостоверение (<em>niścaya</em>) присутствия смысла, выраженного через слово. «Завершённость» (<em>niṣṭhā</em>) и «обнаружение» (<em>upalabdhi</em>) здесь синонимичны. Таково, Махамати, наставление о совокупности слова — [само оно подобно] магии.</li>
           <li>Что называется совокупностью знака (<em>vyañjanakāya</em>)? Это то, посредством чего становятся явными имя и слово. «Знак» (<em>vyañjana</em>), «метка» (<em>liṅga</em>), «признак» (<em>lakṣaṇa</em>), «постижение» (<em>upalabdhi</em>) и «условное обозначение» (<em>prajñapti</em>) здесь синонимичны. Кроме того, Махамати, совокупность слова — это завершённость смыслового действия слова.</li>
            <li>Имя (<em>nāma</em>), Махамати, — это различение собственной природы имён букв (<em>akṣara</em>) — от (первой буквы алфавита) «a» (अ) до (последней) «ha» (ह).</li>
            <li>Знаки (<em>vyañjana</em>), Махамати, — это краткие, долгие и протяжные звуки.</li>
            <li>Совокупностями слов, Махамати, называются слова, входящие в словесные ряды: «слон», «конь», «человек», «олень», «скот», «корова», «буйвол», «коза», «баран» и тому подобное — они получают обозначение совокупности слова.</li>
            <li>Имя и знак, Махамати, — это также четыре бесформенные скандхи (<em>arūpiṇaḥ skandhāḥ</em>) [— ощущение (<em>vedanā</em>), распознавание (<em>saṃjñā</em>), формирующие факторы (<em>saṃskāra</em>) и сознание (<em>vijñāna</em>)]. Они называются «именем», поскольку обозначаются посредством имён; и называются «знаком», поскольку проявляются через собственный признак (<em>svalakṣaṇa</em>).</li>
            <li>Таковы, Махамати, признаки обозначения имён, слов и знаков. В этом тебе следует обрести ясность.</li>
    </ul>
    <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
        <li>170. В знаках, в совокупностях слов</li>
        <li>и особенно — в именах</li>
        <li>вязнут скудоумные невежды,</li>
        <li>подобно слонам в великой трясине.</li>
    </ul>
    </blockquote>
    <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.44 (44. Необъяснимые вопросы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, в будущем появятся лже-логики с превратно изощрённым умом, ущербные в верном рассуждении (<em>yukti</em>), логическом основании (<em>hetu</em>) и понимании (<em>buddhi</em>). Когда мудрецы спросят их о том, что свободно от признаков воззрений на единство, различие, оба и ни одно из двух — и свободно от установления двух крайностей, — они ответят так: «Это не вопрос; он поставлен не должным образом».</li>
            <li>Когда их спросят: «Отлично ли непостоянство от формы (<em>rūpa</em>) и прочего — или не отлично? Отлична ли нирвана от обусловленного (<em>saṃskāra</em>)? Носитель признака (<em>lakṣaṇin</em>) — от самого признака (<em>lakṣaṇa</em>)? Обладающий качествами — от качеств (<em>guṇa</em>)? Производное из элементов — от элементов? Видение — от видимого? Атомы — от пыли? Йогин — от знания?» — и зададут подобные вопросы, следующие один за другим в установленном порядке, — они скажут: «Благословенный объявил это необъяснимым (<em>avyākṛta</em>) и подлежащим оставлению без ответа (<em>sthāpanīya</em>)».</li>
            <li>Но эти заблуждающиеся люди не поймут, что Татхагаты, Архаты, Совершенно Пробуждённые не отвечают на такие вопросы ради слушателей, чьё понимание ещё незрело, — ради устранения почвы для страха (<em>utrāsapada</em>).</li>
            <li>Более того, Махамати, даже «необъяснимое» не преподаётся Татхагатами ради устранения воззрений тиртхиков. Ведь тиртхики, Махамати, говорят так: «"Жизненное начало" (<em>jīva</em>) и тело — одно», «"Жизненное начало" — одно, а тело — другое», — и тому подобное составляет их учение о «необъяснимом».</li>
            <li>У тиртхиков, Махамати, совершенно запутавшихся в [поиске внешних] причин, существует «необъяснимое»; в Моём же учении его нет. В Моём учении, Махамати, когда отсутствует связь между воспринимаемым (<em>grāhya</em>) и воспринимающим (<em>grāhaka</em>), различение (<em>vikalpa</em>) не разворачивается. Как же тогда может существовать то, что следует оставлять без ответа? Лишь для тех, Махамати, кто привязан к воспринимаемому и воспринимающему и чей ум не удостоверился в том, что всё есть лишь воспринимаемое собственным умом, — для них и устанавливается «оставление без ответа».</li>
            <li>Махамати, Татхагаты, Архаты, Совершенно Пробуждённые наставляют существ в Дхарме посредством четырёх видов ответа на вопросы (<em>caturvidhapadapraśnavyākaraṇa</em>). «Оставление без ответа» — это наставление, установленное Мною на иное время  (<em>kālāntaradeśanā</em>) для тех, чьи способности ещё не созрели. Для тех же, чьи способности созрели, нет ничего, что следовало бы оставлять без ответа.<a href="#citation-299" id="ref-299" class="citation-mark"><sup>299</sup></a></li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>

    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.45 (45. Природа дхарм)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, все дхармы не возникают, ибо лишены действия и деятеля. Поэтому говорится: все дхармы не являются возникшими.</li>
            <li>Почему же, Махамати, все явления лишены собственной природы? Потому что, когда они исследуются собственным разумом, их собственные и общие признаки не устанавливаются. Поэтому говорится: все дхармы лишены собственной природы.</li>
            <li>Почему же, Махамати, все дхармы свободны от собирания-накапливания-наложения (āyūha) и разложения-устранения-отбрасывания (niryūha)? Потому что, Махамати, при собирании-накапливании-наложении их собственных и общих признаков они не собираются, не накапливаются и не накладываются; при разложении-устранении-отбрасывании — не разлагаются, не устраняются и не отбрасываются. По этой причине, Махамати, все дхармы свободны от собирания-накапливания-наложения и разложения-устранения-отбрасывания.</li>
            <li>Почему все дхармы непрекращаемы? Потому что из-за отсутствия признаков собственной природы явлений все дхармы не обнаруживаются. Поэтому говорится: все дхармы непрекращаемы.</li>
            <li>Почему же, Махамати, все дхармы называются непостоянными? Потому что возникновение признаков имеет природу непостоянства. Поэтому говорится: все дхармы непостоянны.</li>
            <li>И почему же, Махамати, все дхармы называются постоянными? Потому что вследствие отсутствия признаков возникшего и невозникшего они постоянны через непостоянство. Поэтому говорится, Махамати: все дхармы постоянны.<a href="#citation-300" id="ref-300" class="citation-mark"><sup>300</sup></a></li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>171. Четыре вида разъяснения:</li>
            <li>прямой ответ, встречный вопрос,</li>
            <li>раздельный анализ и оставление без ответа —</li>
            <li>[все] служат устранению воззрений тиртхиков.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>172. Санкхьяики и вайшешики утверждают</li>
            <li>не-возникновение из существующего и несуществующего;</li>
            <li>именно ими и были провозглашены</li>
            <li>все эти «необъяснимые» положения.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>173. Когда они исследуются собственным разумом,</li>
            <li>собственная природа не устанавливается.</li>
            <li>Поэтому Я учу: они невыразимы</li>
            <li>и лишены собственной природы.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.46 (46. Вступившие в поток)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь воззвал к Благословенному:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Пусть Благословенный разъяснит мне признаки метода различения путей и продвижения <em>Вступивших в поток</em> (<em>srotāpanna</em>)! Благодаря этому я и другие бодхисаттвы-махасаттвы, став искусными в различении путей <em>Вступивших в поток</em> и зная признаки и методы последовательного достижения состояний <em>Однажды возвращающегося</em> (<em>sakṛdāgāmin</em>), <em>Невозвращающегося</em> (<em>anāgāmin</em>) и <em>Архата</em>, смогут должным образом преподавать Дхарму существам.</li>
            <li>Так, тщательно очистив двоякий признак отсутствия «я» (<em>nairātmyalakṣaṇadvaya</em>) и два [вида] завес (<em>āvaraṇa-dvaya</em>), пройдя путём преодоления признаков каждой ступени и обретя сферу непостижимого пути Татхагаты, [мы] уподобимся самоцвету, принимающему любой облик (<em>viśvarūpamaṇi</em>), и станем опорой для всех существ. И через тело, охватывающее сферу всех дхарм, станем для них и опорой, и способом соприкосновения с Дхармой.</li>
        </ul>
        </blockquote>
        <p>Благословенный сказал:</p>
        <p>— Тогда слушай, Махамати, и удерживай это в уме хорошо и внимательно. Я объясню.</p>
        <p>— Да, Благословенный, — ответил бодхисаттва-махасаттва Махамати.</p>
        <p>Благословенный сказал:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, существуют три вида плода <em>вступления в поток</em> (<em>srotāpanna</em>): низший, средний и высший.</li>
            <li>Низший — тот, для кого пределом являются семь рождений. Средний — тот, кто окончательно угасает после трёх или пяти существований. Высший — тот, кто угасает в этом самом рождении.</li>
            <li>У этих троих, Махамати, имеются три узы (<em>saṃyojana</em>) — слабые, средние и сильные. Каковы эти три? Воззрение на [<em>скандхи</em> как на] «я» (<em>satkāya-dṛṣṭi</em>), сомнение (<em>vicikitsā</em>) и цепляние за нравственные предписания и обеты (<em>śīlavrata-parāmarśa</em>). По мере последовательного превосхождения этих трёх уз достигается плод <em>Архата</em>.</li>
            <li>Воззрение на [<em>скандхи</em> как на] «я», Махамати, бывает двух видов: врождённое (<em>sahajā</em>) и понятийно-выстроенное (<em>parikalpitā</em>), подобно зависимой (<em>paratantra</em>) и воображаемой (понятийно-выстроенной) (<em>parikalpita</em>) природам.</li>
            <li>Подобно тому как на основе <em>зависимой природы</em> разворачивается привязанность к разнообразной <em>воображаемой (понятийно-выстроенной) природе</em> — которая не является ни тем, что «есть», ни тем, чего «нет», ни тем и другим одновременно, поскольку обладает признаком ложного построения понятий (<em>abhūtaparikalpa</em>), — так и невежды выстраивают различения, привязываясь к признакам многообразных природ, подобно тому как олени гонятся за миражом. </li>
            <li>Таково понятийно-выстроенное воззрение на [<em>скандхи</em> как на] «я» у <em>Вступившего в поток</em>: оно накоплено неведением и долговременной привязанностью. Оно устраняется благодаря постижению отсутствия «я» в «личности» (<em>pudgala-nairātmya</em>).</li>
            <li>Врождённое же воззрение на [<em>скандхи</em> как на] «я» у <em>Вступившего в поток</em> устраняется через видение равенства собственного и чужого тела; через понимание того, что форма относится к одной из <em>скандх</em>; что её возникновение обусловлено великими элементами и производным от них; что сами элементы взаимно обусловлены и потому форма не имеет [самостоятельного] возникновения. Через видение того, что это воззрение впадает в крайности «есть» и «нет», — оно устраняется. Именно поэтому у того, кто устранил воззрение на [<em>скандхи</em> как на] «я», страсть (<em>rāga</em>) более не разворачивается. Таков, Махамати, признак воззрения на [<em>скандхи</em> как на] «я».</li>
            <li>В чём, Махамати, проявляется признак [отсутствия] сомнения (<em>vicikitsā-lakṣaṇa</em>) у <em>Вступившего в поток</em>?</li>
            <li>Поскольку [<em>Вступивший в поток</em>] обладает ясным воззрением (<em>sudṛṣṭi</em>), основанным на прямом постижении достигнутой Дхармы, и поскольку прежде устранено различение двух видов воззрения на [<em>скандхи</em> как на] «я» — сомнение в дхармах у него не возникает. И у него нет иного воззрения на учителя (<em>śāstṛdṛṣṭi</em>) — через [различение] чистого и нечистого. Таков, Махамати, признак [отсутствия] сомнения у <em>Вступившего в поток</em>.</li>
            <li>Как же, Махамати, <em>Вступивший в поток</em> не цепляется за нравственные предписания и обеты (<em>śīlavrataparāmarśa</em>)? Потому что он ясно видит в них основание возникновения страдания.</li>
            <li>Цепляние (<em>parāmarśa</em>) же, Махамати, — это когда невежды, держась за нравственные предписания, обеты (<em>śīlavrata</em>), аскезы (<em>tapas</em>) и самоограничение (<em>niyama</em>), желая наслаждений и счастья, стремятся к новому рождению. Те же, кто не цепляется, — направляют [практику] к особому постижению, постигаемому лишь внутренним опытом (<em>pratyātmādhigamaviśeṣa</em>). Они связываются с составляющими нравственной дисциплины (<em>śīlāṅga</em>) как с аспектом дхарм, свободных от различений (<em>nirvikalpa</em>) и загрязнений (<em>anāsrava</em>).</li>
            <li>Таков, Махамати, признак цепляния за нравственные предписания и обеты (<em>śīlavrataparāmarśa</em>)  у <em>Вступившего в поток</em>. У <em>Вступившего в поток</em>, Махамати, устранившего три узы, страсть (<em>rāga</em>), отвращение (<em>dveṣa</em>) и помрачение (<em>moha</em>) более не разворачиваются.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Благословенный, Ты учил, что существует множество видов страсти (<em>rāga</em>). Какой же именно вид страсти исчезает у <em>Вступившего в поток</em>?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Страсть к чувственным объектам, чувственному желанию и [чувственным] наслаждениям; страсть, связанная с соединением [с женщиной], — приносящая счастье в настоящем и являющаяся причиной рождения страдания в будущем — [страсть,] [проявляющаяся] в щипках, шлепках, объятиях, поцелуях, прикосновениях, вдыхании запаха, кокетливых взглядах. Такая страсть у него более не разворачивается. Почему? Потому что он обрёл пребывание в счастье <em>самадхи</em> (<em>samādhisukha</em>).</li>
            <li>Устраняется именно эта страсть, тогда как устремлённость к постижению нирваны сохраняется (<em>nirvāṇādhigamarāga</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.47 (47. Однажды возвращающийся)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Каков же, Махамати, признак плода <em>Однажды возвращающегося</em> (<em>sakṛdāgāmin</em>)?</li>
            <li>Это тот, у кого лишь однажды ещё разворачивается различение (<em>vikalpa</em>) о форме, её признаках (<em>lakṣaṇa</em>) и проявлениях (<em>ābhāsa</em>). Поскольку он ясно видит отсутствие образа-знака (<em>nimitta</em>), воззрения (<em>dṛṣṭi</em>), объекта [созерцания] (<em>lakṣya</em>) и признака — и ясно видит признаки состояний <em>дхьяны</em> — он лишь единожды вернётся в этот мир, чтобы положить конец страданию и угаснуть окончательно.</li>
            <li>Посему он зовётся <em>Однажды возвращающимся</em>.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.48 (48. Невозвращающийся)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Как же, Махамати, [определяется] <em>Невозвращающийся</em> (<em>anāgāmin</em>)?</li>
            <li>Это тот, у кого не разворачивается [движение] в отношении существования и не-существования признаков формы в прошлом, будущем и настоящем; к кому не приходит различение скрытых влечений (<em>anuśaya</em>) и изъянов воззрений (<em>dṛṣṭidoṣa</em>) — [и именно это не-приходящее состояние] и есть его невозвращение; и у кого устранена форма [существования], связанная с состоянием невозвращения (<em>anāgāmirūpa</em>), а также узы (<em>saṃyojana</em>).</li>
            <li>Потому он зовётся <em>Невозвращающимся</em>.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.49 (49. Архат)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li><em>Архатом</em> же, Махамати, именуется тот, у кого отсутствует различение о <em>дхьянах</em>, объектах созерцания (<em>dhyeya</em>), <em>самадхи</em>, освобождениях (<em>vimokṣa</em>), <em>[духовных] силах</em> (<em>bala</em>), <em>сверхзнаниях</em> (<em>abhijñā</em>), <em>клешах</em> и страдании. Посему он зовётся <em>Архатом</em>.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Благословенный, Ты говорил о трёх видах <em>Архатов</em>. Кому же именно принадлежит это имя «Архат»? Тем ли, кто обрёл покой на Едином Пути (<em>ekāyanamārga</em>)? Или тем, кто, дав обет пробуждения и накопив корни благого, принял облик неведения? Или же нирманическим проявлениям?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Махамати, имя «Архат» принадлежит шраваку, обретшему покой на Едином Пути, — и не другим.</li>
            <li>Иные же, Махамати, — это бодхисаттвы, следующие по пути практики, и нирманические проявления Будды. В силу предшествующих искусных средств (<em>upāya</em>), корней благого (<em>kuśalamūla</em>) и обетов (<em>praṇidhāna</em>) они являют рождение в собраниях — ради украшения собраний учеников Будды.</li>
            <li>Все эти наставления — о плодах, ступенях, созерцании и созерцающем — суть разнообразные учения, соответствующие различным способам развёртывания различения (<em>vikalpa</em>). На самом же деле, поскольку достижение плода, дхьяна, созерцающий и созерцаемое не составляют единства, и поскольку всё есть лишь воспринимаемое собственным умом (<em>svacittadṛśya</em>), — Я учу о признаке «достижения плодов».</li>
            <li>Более того, Махамати: если бы у <em>Вступившего в поток</em> возникла мысль: «Вот эти узы, и я с ними не связан», — он бы впал в допущение двойственности (<em>dvitvaprasaṅga</em>) и уклонился бы во взгляд на «я» (<em>ātmadṛṣṭi</em>), а его узы остались бы неустранёнными.</li>
            <li>Кроме того, Махамати, чтобы выйти за пределы <em>дхьян</em>, безмерных состояний (<em>apramāṇa</em>) и сфер бесформенного (<em>ārūpyadhātu</em>), следует совершить поворот (<em>vyāvṛtti</em>) от признаков воспринимаемого собственным умом (<em>svacittadṛśya</em>).</li>
            <li>И даже вхождение в прекращение восприятия и чувствования, Махамати, не может быть превосхождением течения воспринимаемого собственным умом, поскольку [и это] есть лишь ум.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>174. [Четыре] <em>дхьяны</em>, безмерные состояния,</li>
            <li><em>бесформенные самадхи (<em>ārūpyāśca samādhayaḥ</em>)</em></li>
            <li>и полное прекращение восприятия —</li>
            <li>ничего из этого не обнаруживается как самостоятельное</li>
            <li>в [сфере] «только лишь ума».</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>175. Плод <em>Вступившего в поток</em>,</li>
            <li>[плод] <em>Однажды возвращающегося</em>,</li>
            <li>плод <em>Невозвращающегося</em> и состояние <em>Архата</em> —</li>
            <li>всё это — блуждание ума (<em>citta-vibhrama</em>).</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>176. Созерцающий, созерцание и объект созерцания,</li>
            <li>устранение [<em>клеш</em>] и видение истин —</li>
            <li>всё это — лишь выстраивание понятий (<em>kalpanā-mātra</em>).</li>
            <li>Тот, кто пробуждается к этому — освобождается.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.50 (Два вида разума)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, существует два вида различительной способности (<em>buddhi</em>):<br>исследующая [способность] (<em>pravicayabuddhi</em>) и<br>[способность], устанавливающая привязанность к схватыванию признаков различения (<em>vikalpalakṣaṇagrāhābhiniveśapratiṣṭhāpikā</em>).</li>
            <li>Что же такое исследующая [способность]? Это та [способность], посредством которой при исследовании признаки природы явлений (<em>bhāvasvabhāvalakṣaṇa</em>) не обнаруживаются ни в одной из четырёх крайностей (<em>catuṣkoṭi</em>).</li>
            <li>Под четырьмя крайностями (<em>catuṣkoṭi</em>), Махамати, Я подразумеваю [свободу] от<br>
            — единства, различия, обоих и ни одного из двух;<br>
            — от «есть», «нет», обоих и ни одного из двух;<br>
            — от вечного и непостоянного, обоих и ни одного из двух.</li>
            <li>Именно этой тетралеммой, Махамати, следует пользоваться при исследовании всех дхарм.</li>
            <li>Что же такое [способность], устанавливающая привязанность к схватыванию признаков различения? Это та [способность], посредством которой, Махамати, через различение ума (<em>cittavikalpa</em>), схватывание признаков и привязанность — а также через привязанность к тезису (<em>pratijñā</em>), логическому основанию (<em>hetu</em>), признаку (<em>lakṣaṇa</em>) и примеру (<em>dṛṣṭānta</em>) — совершается ложное наложение (<em>samāropa</em>) на великие элементы — тепло, влажность, движение и твёрдость, сами по себе имеющие признак ложного построения понятий (<em>abhūtaparikalpa</em>).</li>
            <li>Таковы, Махамати, признаки двух видов различительной способности (<em>buddhi</em>).</li>
            <li>Бодхисаттвы, обладающие признаками этих двух видов [различительной способности], достигшие пути признаков отсутствия «я» дхарм и личности (<em>dharmapudgalanairātmyalakṣaṇa</em>) и искусные на ступенях практики исследования [способности], свободной от образов (<em>nirābhāsa</em>), — достигают первой ступени (<em>bhūmi</em>).</li>
            <li>Они входят в сотни <em>самадхи</em> и — благодаря обретению особых <em>самадхи</em> — видят сотни Будд и Бодхисаттв; проникают в сотни кальп со стороны начала прошлого и предела будущего (<em>pūrvāntāparānta</em>); и озаряют сотни миров.</li>
            <li>Озарив сотни миров и зная признаки и способы высших ступеней, играя в силу особенности своих обетов, — они получают посвящение «Облака Дхармы» (<em>dharmameghābhiṣeka</em>), достигают собственной ступени Татхагаты, прочно утверждённые в дхармах десяти конечных положений (<em>daśaniṣṭhāpada</em>), и сияют многообразными лучами проявлений (<em>nirmāṇakiraṇa</em>) ради созревания существ — пребывая в сосредоточении блаженства пути внутреннего постижения (<em>pratyātmagati</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.51 (51. Первоэлементы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, бодхисаттве-махасаттве следует стать искусным в [понимании] великих элементов (<em>mahābhūta</em>) и производных от них форм (<em>bhautika</em>). Как же, Махамати, бодхисаттва становится в этом искусным? Там, Махамати, бодхисаттва-махасаттва обучается тому, что истина — там, где невозникновение великих элементов; и ясно видит, что эти элементы не возникли.</li>
            <li>Видя так, он постигает, что имя есть лишь различение (<em>nāmavikalpamātra</em>). Благодаря постижению того, что всё есть лишь воспринимаемое собственным умом (<em>svacittadṛśyamātra</em>), и благодаря [отсутствию] внешнего «есть» и «нет» — он ясно видит: это тройственное существование (<em>traidhātuka</em>) есть лишь различение воспринимаемого умом (<em>cittadṛśyavikalpamātra</em>), лишённое великих элементов и производных от них форм.</li>
            <li>Он видит [все дхармы] очищенными через верный способ (<em>naya</em>) тетралеммы (<em>catuṣkoṭika</em>), свободными от «я» и «моего», утверждёнными в пребывании собственного признака как они есть (<em>yathābhūtasvalakṣaṇa</em>) и установленными через собственный признак невозникновения (<em>anutpādasvalakṣaṇa</em>).</li>
            <li>Как же, Махамати, из великих элементов возникают производные формы?</li>
            <li>Великий элемент, различаемый как влажность (<em>snehavikalpa</em>), порождает элемент воды — внутри и снаружи.</li>
            <li>Великий элемент, различаемый как жар (<em>utsāhavikalpa</em>), порождает элемент огня — внутри и снаружи.</li>
            <li>Великий элемент, различаемый как движение (<em>samudīraṇavikalpa</em>), порождает элемент ветра — внутри и снаружи.</li>
            <li>Великий элемент, различаемый как очерченность формы (<em>rūpaparicchedavikalpa</em>), порождает элемент земли вместе с пространством — внутри и снаружи. </li>
            <li>Из привязанности к ложному и истинному (<em>mithyāsatya</em>) разворачивается совокупность пяти <em>скандх</em>, состоящая из великих элементов и производных от них форм.</li>
            <li>Сознание (<em>vijñāna</em>) разворачивается в соединении с иными состояниями существования (<em>anyagatisandhi</em>) — вследствие того, что оно является причиной привязанности и стремления к разнообразным словам и объектам. Для производных форм, [происходящих] из элемента земли, Махамати, великие элементы являются причиной производных форм — но не самих себя. По какой причине? Потому что, Махамати, возникновение связи с действием (<em>kriyāyoga</em>) возможно лишь для того, что обладает явлением (<em>bhāva</em>), меткой (<em>liṅga</em>), признаком (<em>lakṣaṇa</em>), схватыванием (<em>grahaṇa</em>), структурой (<em>saṃsthāna</em>) и связью с действием (<em>kriyāyoga</em>) — но не для лишённого метки (<em>aliṅga</em>). Поэтому, Махамати, этот признак великих элементов и производных от них форм выстраивается в различении тиртхиками, но не Мною.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.52 (52. Скандхи)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>Кроме того, Махамати, [Я] разъясню признак природы <em>скандх</em> (<em>skandhasvabhāvalakṣaṇa</em>).</li>
            <li>Существует пять <em>скандх</em>: форма (<em>rūpa</em>), ощущение (<em>vedanā</em>), восприятие (<em>saṃjñā</em>), формирующие факторы (<em>saṃskāra</em>) и сознание (<em>vijñāna</em>).</li>
            <li>Из них, Махамати, четыре <em>скандхи</em> лишены формы (<em>arūpiṇaḥ</em>) — это ощущение, восприятие, формирующие факторы и сознание.</li>
            <li>Форма же, Махамати, состоит из четырёх великих элементов (<em>mahābhūta</em>), признаки которых взаимно различны.</li>
            <li>Однако, Махамати, для бесформенных [<em>скандх</em>] не существует числового выражения «четвёрка» — как и для пространства.</li>
            <li>Подобно тому как пространство выходит за пределы числа и признака — и при этом различается [умом] как «вот это пространство», — так и <em>скандхи</em> выходят за пределы числа, признака и исчисления; они свободны от «есть» и «нет» и лишены четырёх крайностей (<em>catuṣkoṭi</em>).</li>
            <li>Их указывают посредством счёта и исчисления — так делают невежды, но не Благородные (<em>ārya</em>).</li>
            <li>Благородные же, Махамати, указывают на них как на подобные многообразным магическим формам и фигурам, свободным от тождества и отличия (<em>anyānanyavarjita</em>) — подобно сновидению, отражению или призрачной фигуре.</li>
            <li>Из-за заблуждения относительно пути благородного знания (<em>āryajñānagati</em>) и вследствие неотличности [<em>скандх</em>] от своей основы (<em>āśraya</em>), Махамати, проявляется различение <em>скандх</em> (<em>skandhavikalpa</em>).<a href="#citation-301" id="ref-301" class="citation-mark"><sup>301</sup></a> Таков, Махамати, признак природы <em>скандх</em>.</li>
            <li>Это различение тебе следует прекратить; прекратив его — осуществлять наставление о дхармах в их обособленности (<em>viviktadharmopadeśa</em>).</li>
            <li>Когда во всех собраниях Будд ради пресечения воззрений тиртхиков осуществляется такое наставление, Махамати, — очищается видение отсутствия «я» дхарм (<em>dharmanairātmyadarśana</em>) и совершается вхождение на ступень <em>Дурангама</em> (<em>Dūraṃgamābhūmi</em>).</li>
            <li>Войдя на эту великую ступень, [бодхисаттва] обретает власть над множеством <em>самадхи</em>. Благодаря обретению <em>тела, созданного умом</em> (<em>manomayakāya</em>), он достигает <em>самадхи, подобного магической иллюзии</em> (<em>māyopamasamādhi</em>).</li>
            <li>Достигнув [пути] власти над <em>силами</em> (<em>bala</em>) и <em>сверхзнаниями</em> (<em>abhijñā</em>), он становится тем, чем живут все существа, — подобно земле.</li>
            <li>Подобно тому, Махамати, как великая земля является тем, чем живут все существа, так и бодхисаттва-махасаттва становится тем, чем живут все существа.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.53 (53. Четыре вида нирваны)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
            <li>Кроме того, Махамати, существуют четыре вида нирваны. Каковы эти четыре?</li>
            <li>— Нирвана как отсутствие собственной природы явлений (<em>bhāvasvabhāvābhāvanirvāṇa</em>);</li>
            <li>— Нирвана как отсутствие многообразия признаков явлений (<em>lakṣaṇavicitrabhāvābhāvanirvāṇa</em>);</li>
            <li>— Нирвана как постижение отсутствия собственных признаков [явлений] (<em>svalakṣaṇabhāvābhāvāvabodhanirvāṇa</em>);</li>
            <li>— Нирвана как пресечение непрерывного потока собственных и общих признаков <em>скандх</em> (<em>skandhānāṃ svasāmānyalakṣaṇasaṃtatiprabandhavyucchedanirvāṇa</em>).</li>
            <li>Эти четыре вида нирваны, Махамати, принадлежат тиртхикам — но не Моему учению.</li>
            <li>В Моём же учении, Махамати, нирваной именуется прекращение (<em>vyāvṛtti</em>) различающей <em>мановиджняны</em> (<em>vikalpakasya manovijñānasya</em>).</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— Разве Благословенный не устанавливал [учение о] восьми сознаниях?</p>
        <p>Благословенный ответил:</p>
        <p>— Устанавливал, Махамати.</p>
        <p>Махамати спросил:</p>
        <p>— Если так, Благословенный, то почему прекращается деятельность лишь <em>мановиджняны</em>, а не остальных семи сознаний?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-12 pl-2 space-y-4 ml-2">
            <li>Ибо семь сознаний разворачиваются, имея её [<em>мановиджняну</em>] своей причиной и объектом-опорой (<em>ālambana</em>).</li>
            <li><em>Мановиджняна</em> же, Махамати, разворачиваясь через привязанность к разграничению объектов, посредством отпечатков (<em>vāsanā</em>) питает <em>Алая-виджняну</em>.</li>
            <li>Сопровождаемая <em>манасом</em>, она непрерывно разворачивается, принимая облик иного, как привязанность к схватыванию «я» и «моего».</li>
            <li>Эта группа сознаний (<em>cittakalāpa</em>), обладающая признаком нераздельного состава, разворачивается взаимно-причинным образом (<em>anyonyahetuka</em>), имея <em>Алая-виджняну</em> своей причиной и опорой, — вследствие привязанности к объектам воспринимаемого собственным умом (<em>svacittadṛśyaviṣaya</em>).</li>
            <li>Подобно волнам океана, Махамати, гонимым ветром объектов воспринимаемого собственным умом, — они разворачиваются и прекращаются.</li>
            <li>Поэтому, Махамати, когда прекращается <em>мановиджняна</em> — прекращаются и семь [остальных] сознаний.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>177. Я не вхожу в нирвану через явление (<em>bhāva</em>),</li>
            <li>действие (<em>kriyā</em>) или признак (<em>lakṣaṇa</em>).</li>
            <li>Когда прекращается сознание,</li>
            <li>являющееся причиной различения (<em>vikalpahetuvijñāna</em>), —</li>
            <li>тогда воистину Я угас.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>178. Имея это своей причиной</li>
            <li>и опираясь на течение <em>манаса</em>,</li>
            <li>[<em>мановиджняна</em>] становится причиной для <em>citta</em>,</li>
            <li>и само сознание опирается на неё.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>179. Подобно тому как при иссыхании великого океана</li>
            <li>становится невозможным возникновение волн, —</li>
            <li>так и многообразие сознаний,</li>
            <li>будучи прекращённым,</li>
            <li>более не разворачивается.</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.54 (54. Признаки разделения воображаемой природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>Кроме того, Махамати, Я разъясню признаки разделения <em>воображаемой природы</em> (<em>parikalpitasvabhāva</em>). Постигнув их, ты и другие бодхисаттвы освободитесь от различений и выстраивания понятий. Ваше понимание пути Благородных и путей тиртхиков станет ясным; вы отбросите двойственность схватываемого и схватывающего и более не будете налагать форму <em>воображаемой природы</em> на многообразные признаки <em>зависимой природы</em>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li><strong>Каковы же, Махамати, признаки разделения <em>воображаемой природы</em>? Это:</strong></li>
            <li>— различение речи (<em>abhilāpavikalpa</em>);</li>
            <li>— различение того, что подлежит обозначению (<em>abhidheyavikalpa</em>);</li>
            <li>— различение признаков (<em>lakṣaṇavikalpa</em>);</li>
            <li>— различение объекта (<em>arthavikalpa</em>);</li>
            <li>— различение собственной природы (<em>svabhāvavikalpa</em>);</li>
            <li>— различение причины (<em>hetuvikalpa</em>);</li>
            <li>— различение воззрений (<em>dṛṣṭivikalpa</em>);</li>
            <li>— различение логического рассуждения (<em>yuktivikalpa</em>);</li>
            <li>— различение возникновения (<em>utpādavikalpa</em>);</li>
            <li>— различение не-возникновения (<em>anutpādavikalpa</em>);</li>
            <li>— различение связи (<em>saṃbandhavikalpa</em>);</li>
            <li>— различение связанности и освобождения (<em>bandhābandhavikalpa</em>).</li>
            <li>Таковы, Махамати, признаки разделения <em>воображаемой природы</em>.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
            <li><strong>Различение речи:</strong> привязанность к сладостным звукам и пению.</li>
            <li><strong>Различение того, что подлежит обозначению:</strong> различение того, что существует некий обозначаемый объект, обладающий собственной природой и постигаемый путём благородного знания, на который опирается речь.</li>
            <li><strong>Различение признаков:</strong> привязанность к многообразию признаков в этом обозначаемом, подобном миражу, — когда все явления различаются через признаки жара, влажности, движения и твёрдости.</li>
            <li><strong>Различение объекта:</strong> различение золота, серебра и разнообразных драгоценностей как объектов.</li>
            <li><strong>Различение собственной природы:</strong> утверждение в духе тиртхиков: «это именно так и не иначе!»</li>
            <li><strong>Различение причины:</strong> различение «есть» и «нет» через причины, условия и признаки возникновения.</li>
            <li><strong>Различение воззрений:</strong> привязанность к дурным взглядам тиртхиков о «есть» и «нет», единстве, инаковости, обоих и ни одном из них.</li>
            <li><strong>Различение логического рассуждения:</strong> споры и наставления, основанные на признаках «я» и «моего».</li>
            <li><strong>Различение возникновения:</strong> привязанность к возникновению явлений «есть» и «нет» из условий.</li>
            <li><strong>Различение не-возникновения:</strong> утверждение, что все явления прежде не существовали, а затем возникают из условий без причины.</li>
            <li><strong>Различение связи:</strong> представление о связанности, подобной соединению золотой нити.</li>
            <li><strong>Различение связанности и освобождения:</strong> привязанность к самой идее связывания и освобождения — подобно человеку, который завязывает и развязывает узлы на верёвке.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-2 ml-2">
            <li>Это и есть признаки разделения <em>воображаемой природы</em>, в которую погружены все невежды и обычные люди.</li>
            <li>Они привязываются к многообразию <em>воображаемой природы</em> вследствие привязанности к зависимому — как к «есть», так и к «нет».</li>
            <li>Подобно тому как в магии воображают многообразие, хотя сама магия не отлична от этого многообразия и не неотлична от него.</li>
            <li>Если бы она была отлична — многообразие не имело бы магии своей причиной;</li>
            <li>если бы она была неотлична — невозможно было бы различить магию и её многообразие.</li>
            <li>И всё же различие наблюдается. Поэтому, Махамати, тебе и другим бодхисаттвам-махасаттвам не следует привязываться к магии через категории «есть» и «нет».</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.55 (55. Воображаемая, зависимая и совершенная природы)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>180. Ум связан с объектом (<em>viṣayasaṃbandha</em>);</li>
                <li>познание (<em>jñāna</em>) проявляется в логическом рассуждении (<em>tarka</em>);</li>
                <li>мудрость (<em>prajñā</em>) же обнаруживается</li>
                <li>в особом [созерцании] (<em>viśeṣa</em>),</li>
                <li>свободном от образов (<em>nirābhāsa</em>).<a href="#citation-302" id="ref-302" class="citation-mark"><sup>302</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>181. <em>Воображаемая природа</em> (<em>parikalpitasvabhāva</em>)</li>
                <li>не существует в <em>зависимой [природе]</em> (<em>paratantre na vidyate</em>).</li>
                <li>Воображаемое (<em>kalpita</em>) схватывается по заблуждению (<em>bhrāntyā</em>);</li>
                <li>зависимое (<em>paratantra</em>) не выстраивается как воображаемое.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>182. Как магия (<em>māyā</em>), возникая через проявление</li>
                <li>множества частей (<em>vividhāṅgābhinirvṛttyā</em>),</li>
                <li>не устанавливается [как реальная], так и образ-знак (<em>nimitta</em>),</li>
                <li>сколь бы пёстрым-многообразным (<em>citra</em>) он ни был,</li>
                <li>будучи воображаемым (<em>kalpyamāna</em>), не устанавливается.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>183. Образ-знак — это связывание,</li>
                <li>насыщенное пагубной косностью (<em>dauṣṭhulya</em>),<a href="#citation-303" id="ref-303" class="citation-mark"><sup>303</sup></a></li>
                <li>возникающей из ума (<em>cittasaṃbhavam</em>).</li>
                <li>У тех, кто не знает (<em>ajānāna</em>) воображаемого,</li>
                <li>различение выстраивается на основе </li>
                <li><em>зависимой [природы]</em> (<em>paratantraiḥ vikalpyate</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>184. То, что называют </li>
                <li>воображаемым явлением (<em>kalpitaṃ bhāvaṃ</em>), —</li>
                <li>именно то и есть (<em>tadeva</em>) зависимое (<em>paratantra</em>)</li>
                <li>[в своём проявлении];</li>
                <li>именно в зависимом воображаемое,</li>
                <li>являющееся в многообразии (<em>vicitrābha</em>),</li>
                <li>разворачивается через различение (<em>vikalpyate</em>).<a href="#citation-304" id="ref-304" class="citation-mark"><sup>304</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>185. Есть условная истина (<em>saṃvṛti</em>) и высшая истина (<em>paramārtha</em>);</li>
                <li>третьего — обусловленного (<em>hetuka</em>), не существует.</li>
                <li>Воображаемое названо условным (<em>saṃvṛti</em>);</li>
                <li>с его пресечением открывается</li>
                <li>сфера Благородных (<em>āryagocara</em>).<a href="#citation-305" id="ref-305" class="citation-mark"><sup>305</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>186. Как йогину является одно лишь реальное (<em>vastu ekaṃ</em>),</li>
                <li>предстающее многообразным (<em>citra</em>),</li>
                <li>хотя многообразия там нет (<em>na hyasti citratā</em>), —</li>
                <li>таковы признаки воображаемого (<em>kalpitalakṣaṇa</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>187. Как те, у кого повреждено зрение (<em>taimira</em>),</li>
                <li>воображают видимость формы (<em>rūpadarśana</em>),</li>
                <li>хотя эта болезнь — ни форма (<em>rūpa</em>),</li>
                <li>ни отсутствие формы (<em>arūpa</em>), —</li>
                <li>так невежды (<em>abudhaiḥ</em>) воспринимают зависимое (<em>paratantra</em>).<a href="#citation-306" id="ref-306" class="citation-mark"><sup>306</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>188. Как золото (<em>haima</em>) бывает чистым,</li>
                <li>как вода (<em>jala</em>) свободна от мути (<em>kaluṣa</em>),</li>
                <li>как небо (<em>gagana</em>) чисто при отсутствии облаков (<em>ghanābhāvāt</em>) —</li>
                <li>так и воображаемое (<em>vikalpita</em>) [кажется] чистым.<a href="#citation-307" id="ref-307" class="citation-mark"><sup>307</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>189. Воображаемого явления (<em>kalpito bhāvaḥ</em>) нет;</li>
                <li>зависимое же (<em>paratantra</em>) присутствует.</li>
                <li>Тот, кто мыслит через наложение (<em>samāropa</em>) и</li>
                <li>отрицание (<em>apavāda</em>), гибнет (<em>vinaśyati</em>) в различении.<a href="#citation-308" id="ref-308" class="citation-mark"><sup>308</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>190. Если бы воображаемое было полным отсутствием (<em>abhāva</em>)</li>
                <li>относительно природы зависимого (<em>paratantrasvabhāvataḥ</em>),</li>
                <li>то явление (<em>bhāva</em>) существовало бы без явления,</li>
                <li>и явление возникало бы</li>
                <li>из отсутствия явления (<em>abhāvasaṃbhava</em>).<a href="#citation-309" id="ref-309" class="citation-mark"><sup>309</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>191. Опираясь на воображаемое (<em>parikalpita</em>),</li>
                <li>воспринимается зависимое (<em>paratantra</em>).</li>
                <li>Из связи имени (<em>nāma</em>) и образа-знака (<em>nimitta</em>)</li>
                <li>рождается воображаемое.</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>192. Воображаемое неустановлено (<em>atyantaṃ aniṣpannam</em>) и</li>
                <li>не возникает из чего-либо иного.</li>
                <li>Когда это постигнуто,</li>
                <li>познаётся чистая высшая природа (<em>pāramārthika-svabhāva</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>193. Воображаемое — десяти видов,</li>
                <li>а зависимое — шести видов.</li>
                <li>Но в личном постижении Таковости (<em>pratyātmatathatā</em>)</li>
                <li>нет места определениям (<em>viśeṣaṇa</em>).<a href="#citation-310" id="ref-310" class="citation-mark"><sup>310</sup></a></li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>194. Пять <em>дхарм</em> и три <em>природы</em> —</li>
                <li>вот истинность (<em>tattva</em>).</li>
                <li>Йогин, ясно постигающий их,</li>
                <li>не отклоняется от Таковости (<em>tathatā</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>195. Образ-знак (<em>nimitta</em>) — это именно зависимое;</li>
                <li>то, что является именем (<em>nāma</em>) — воображаемое.</li>
                <li>Но образы-знаки воображаемого</li>
                <li>разворачиваются из самой зависимости (<em>pāratantryāt</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>196. Но то, что исследуется разумом (<em>buddhyā vivecyamānam</em>), —</li>
                <li>ни зависимое, ни воображаемое.</li>
                <li><em>Совершенная природа</em> (<em>niṣpanna</em>) не есть явление (<em>bhāva</em>);</li>
                <li>как же она может быть помыслена различающим разумом?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>197. <em>Совершенная природа</em> обнаруживается как явление,</li>
                <li>свободное от явления и отсутствия явления (<em>bhāvābhāvavivarjita</em>).</li>
                <li>Если она свободна от явления и отсутствия явления, </li>
                <li>то как же в ней могут быть те две природы —</li>
                <li>воображаемая и зависимая?</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>198. В <em>воображаемой природе</em> различаются две природы:</li>
                <li>воображаемое видится как многообразие (<em>citra</em>),</li>
                <li>а чистое — это сфера созерцания Благородных (<em>āryagocara</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>199. Воображаемое, являющееся в многообразии (<em>vicitrābha</em>),</li>
                <li>разворачивается через различение на основе зависимого.</li>
                <li>Мыслить иначе — значит опираться</li>
                <li>на учения тиртхиков (<em>tīrthyavāda</em>).</li>
            </ul>
            <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
                <li>200. Выстраивание понятий называется воображаемым</li>
                <li>в силу усмотрения причинного возникновения.</li>
                <li>То, что полностью свободно</li>
                <li>от двойственности различений (<em>vikalpadvayanirmukta</em>),</li>
                <li>и есть <em>совершенная природа</em> (<em>niṣpanna</em>).</li>
            </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
    </div>

    <h4 class="text-center text-blue-800 font-bold text-xl sm:text-xl md:text-xl mt-4 mb-4">Подглава 2.56 (56. Единая колесница)</h4>
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p>Затем бодхисаттва-махасаттва Махамати вновь обратился к Благословенному:</p>
        <p>— Пусть Благословенный разъяснит мне признаки продвижения по пути личного постижения Благородных (<em>pratyātmāryajñānagati</em>) и Единой Колесницы (<em>ekayāna</em>)! Дабы благодаря пониманию этих признаков я и другие бодхисаттвы-махасаттвы стали искусными в личном постижении Благородных и Единой Колеснице — и более не нуждались в чужом руководстве в Учении Будды.</p>
        <p>Благословенный ответил:</p>
        <p>— Слушай же внимательно, Махамати, и глубоко запечатлей это в уме! Я буду говорить с тобой.</p>
        <p>— Да, Благословенный, — ответил бодхисаттва-махасаттва Махамати.</p>
        <p>Благословенный сказал ему следующее:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-8 pl-2 space-y-4 ml-2">
            <li>В силу отсутствия [опоры на] средства достоверного познания (<em>pramāṇa</em>), авторитетные источники (<em>āpta</em>), наставления (<em>upadeśa</em>) и различение (<em>vikalpa</em>), Махамати, бодхисаттва-махасаттва, удалившись в уединение, исследует [всё] посредством своего личного непосредственного постижения (<em>svapratyātmabuddhi</em>). Он становится независимым от чужих указаний, оставляет воззрения, выстроенные через различение (<em>dṛṣṭivikalpa</em>), и направленно упражняется в последовательном вхождении в ступени Татхагаты.</li>
            <li>Таков признак продвижения по пути личного постижения Благородных.</li>
            <li>Каков же признак продвижения к пути Единой Колесницы?</li>
            <li>Я называю это Единой Колесницей в силу пробуждения к пути Единой Колесницы.</li>
            <li>Что же представляет собой пробуждение к пути Единой Колесницы?</li>
            <li>Это прекращение разворачивания различения схватываемого и схватывающего (<em>grāhyagrāhakavikalpa</em>) — через пребывание в том, каково [всё] в действительности (<em>yathābhūta</em>). Так осуществляется пробуждение к Единой Колеснице.<a href="#citation-311" id="ref-311" class="citation-mark"><sup>311</sup></a></li>
            <li>Это пробуждение, Махамати, прежде никогда не достигалось ни тиртхиками, ни шраваками, ни пратьекабуддами, ни Брахмой — никем, кроме Меня.</li>
            <li>По этой самой причине она зовётся Единой Колесницей.</li>
        </ul>
        </blockquote>
        <p>Махамати спросил:</p>
        <p>— По какой же причине Благословенный проповедует три колесницы (<em>yānatraya</em>), а не одну лишь Единую Колесницу (<em>ekayāna</em>)?</p>
        <p>Благословенный ответил:</p>
        <blockquote class="border-l-4 border-sky-500 pl-6 my-6 text-gray-800 text-xl">
        <ul class="list-none mb-12 pl-2 space-y-4 ml-2">
            <li>Махамати, из-за того, что все шраваки и пратьекабудды сами по себе не обладают природой [окончательного] ухода в Нирвану (<em>svayam-aparinirvāṇa-dharmatvāt</em>), — я не провозглашаю [для них] Единую Колесницу.</li>
            <li>Потому что, Махамати, все шраваки и пратьекабудды освобождаются [лишь] благодаря наставлениям в йоге, уединении и дисциплине Татхагаты (<em>tathāgata-vinaya-viveka-yoga-upadeśena</em>), а не сами по себе (<em>na svayam</em>).</li>
            <li>И ещё, Махамати: из-за неустранённости кармических отпечатков завесы познаваемого (<em>jñeyāvaraṇa-karma-vāsanā-aprahīṇatvāt</em>)<a href="#citation-312" id="ref-312" class="citation-mark"><sup>312</sup></a>  у всех шраваков и пратьекабудд, для них нет Единой Колесницы.</li>
            <li>По причине их непонимания отсутствия «я» дхарм (<em>dharmanairātmya</em>) и из-за того, что они ещё не достигли непостижимого изменения-перехода (<em>acintyapariṇāmacyuti</em>),<a href="#citation-313" id="ref-313" class="citation-mark"><sup>313</sup></a> Я излагаю Три Колесницы для шраваков.</li>
            <li>Когда же, Махамати, все отпечатки их изъянов будут устранены благодаря постижению отсутствия «я» дхарм (<em>dharma-nairātmya-avabodhāt</em>), тогда они, избавившись от опьянения <em>самадхи</em> (<em>samādhimada</em>),<a href="#citation-314" id="ref-314" class="citation-mark"><sup>314</sup></a> порождаемого отпечатками омрачений, пробудятся в незагрязнённой сфере (<em>anāsrava-dhātu</em>).</li>
            <li>И вновь, накопив [необходимые] благие накопления, относящиеся к сверхмирской незагрязненной сфере (<em>lokottara-anāsravadhātu-paryāpannān saṃbhārān</em>), — они обретут владычество над непостижимым Телом Дхармы — Дхармакаей (<em>acintya-dharmakāya-vaśavartitāṃ pratilapsyante</em>).<a href="#citation-315" id="ref-315" class="citation-mark"><sup>315</sup></a></li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>201. Я проповедую Колесницу богов (<em>devayāna</em>),</li>
            <li>Колесницу Брахмы (<em>brahmayāna</em>),</li>
            <li>Колесницу шраваков (<em>śrāvakīya</em>),</li>
            <li>а также [Колесницы] пратьекабудд и Татхагат.</li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>202. Но пока разворачивается ум (<em>citta</em>),</li>
            <li>у колесниц нет окончательного предела (<em>niṣṭhā</em>).</li>
            <li>Когда же в уме совершается поворот основы (<em>parāvṛtti</em>),</li>
            <li>нет ни колесницы, ни тех, кто по ней движется.</li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>203. Установления колесниц вовсе не существует —</li>
            <li>и всё же Я говорю о различии колесниц.</li>
            <li>Лишь ради привлечения невежд (<em>bāla</em>)</li>
            <li>Я устанавливаю различие колесниц.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>204. Также существуют три вида освобождения</li>
            <li>и отсутствие «я» дхарм (<em>dharmanairātmya</em>).</li>
            <li>Однако [шраваки] лишены того освобождения,</li>
            <li>которое именуется Мудрость Равностности (<em>samatājñāna</em>)</li>
            <li>и полной свободой от клеш.</li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>205. Подобно тому, как бревно в океане</li>
            <li>уносится волнами,</li>
            <li>так и глупый шравака</li>
            <li>увлекается признаками (<em>lakṣaṇa</em>).</li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>206. Связанные отпечатками и клешами (<em>vāsanākleśa</em>),</li>
            <li>но свободные от их активных проявлений,</li>
            <li>опьянённые <em>самадхи</em> (<em>samādhimada</em>),</li>
            <li>они пребывают в сфере, свободной от клеш (<em>anāsravadhātu</em>).</li>
        </ul>
        <ul class="list-none mb-6 pl-2 space-y-1 ml-2">
            <li>207. Они не достигают окончательного предела,</li>
            <li>но и не возвращаются вновь.</li>
            <li>Достигнув тела самадхи (<em>samādhikāya</em>),</li>
            <li>они не пробуждаются вплоть до [конца] кальпы.</li>
        </ul>
        <ul class="list-none mb-8 pl-2 space-y-1 ml-2">
            <li>208. Подобно тому, как опьянённый человек</li>
            <li>трезвеет, когда иссякает действие хмеля,</li>
            <li>так и они обретут Моё Тело,</li>
            <li>именуемое Буддадхармой (<em>buddhadharmākhyaṃ kāyam</em>).</li>
        </ul>
        </blockquote>
        <p class="text-center font-bold">***</p>
        <p class="text-center italic">Так завершается вторая глава «Ланкаватара-сутры»,
        именуемая «Собрание всех дхарм в тридцати шести тысячах [шлок]».</p>
        <div class="relative text-center" style="margin-top: 4rem; margin-bottom: 4rem;">
            <div class="absolute inset-0 flex items-center">
                <div class="w-full border-t border-sky-300"></div>
            </div>
            <span class="relative bg-sky-50 px-4 text-xl text-sky-700">❈ ❈ ❈</span>
        </div>
    </div>

    <h4 class="text-center text-gray-800 font-bold text-xl my-4">ПРИМЕЧАНИЯ</h4>
    <hr class="my-8 border-t-4 border-gray-500">
    <div class="prose text-justify max-w-4xl mx-auto leading-relaxed space-y-4">
        <p></p>
        <div>
        <p class="my-2" id="citation-1"><sup>1</sup> <strong>Ващита</strong> (<em>vaśitā</em>) —
            духовная власть, обретаемая бодхисаттвой на высоких ступенях пути (<em>бхуми</em>).
            Она означает непринуждённое господство над собственным умом, дхармами, кармой и
            процессом перерождений. В отличие от обычного «самообладания», ограниченного
            эмоциональным контролем, <em>ващита</em> — это способность свободно проявляться в
            сансаре без загрязнений, действовать без усилий (<em>анабхисамскара</em>) и
            спонтанно откликаться на нужды существ. Она проистекает из прямого постижения
            недвойственной природы реальности (<em>адвая-джняна</em>) и преобразования ума (<em>āśraya-parāvṛtti</em>).
            Традиционно выделяют десять видов <em>ващиты</em>: власть над жизнью
            (<em>āyur-vaśitā</em>),
            власть над умом (<em>citta-vaśitā</em>), власть над необходимыми средствами (<em>pariṣkāra-vaśitā</em>),
            власть над дхармами (<em>dharma-vaśitā</em>), власть над чудесными силами (<em>ṛddhi-vaśitā</em>),
            власть над рождением (<em>janma-vaśitā</em>), власть над устремлением (<em>adhimukti-vaśitā</em>),
            власть над обетами (<em>praṇidhāna-vaśitā</em>), власть над кармой
            (<em>karma-vaśitā</em>), власть над мудростью (<em>jñāna-vaśitā</em>). Бодхисаттва,
            обладающий совершенной <em>ващитой</em>, может по своей воле принимать рождение в
            любом мире, сохранять память о прошлых жизнях, проявлять любые формы и применять
            любые искусные средства (<em>упая</em>) ради освобождения существ. В контексте
            <strong><em>Ланкаватара-сутры</em></strong> <em>ващита</em> тесно связана с владением
            <em>самадхи</em>
            (<em>samādhi-vaśitā</em>), постижением того, что всё есть проявление ума (<em>svacitta-dṛśya-gocara-parijñāna</em>)
            и игровой деятельностью (<em>vikrīḍita</em>) — ибо именно <em>ващита</em> делает
            возможной «игру» просветлённого бодхисаттвы в мире форм.<a href="#ref-1"
                                                                       class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-2"><sup>2</sup> <strong>Бала</strong> (<em>bala</em>) —
            духовная сила или непоколебимость, обретаемая бодхисаттвой благодаря прямому
            постижению природы ума. В отличие от обычной «силы воли», <em>бала</em> — это
            устойчивость, проистекающая из реализации <em>шуньяты</em>. Она делает бодхисаттву
            неуязвимым для заблуждений, страхов и власти кармы. Эта сила не является результатом
            эгоистического усилия — она возникает спонтанно из недвойственного знания (<em>адвая-джняна</em>)
            как его естественное качество. <em>Бала</em> позволяет бодхисаттве непрерывно
            действовать ради блага существ, не отклоняясь от пути даже в самых трудных
            обстоятельствах, подобно горе, неподверженной бурям («Как скала единая, не
            колеблется ветром» — <strong><em>Дхаммапада</em></strong>, ст. 81). В махаянской традиции
            различают пять сил (<em>pañca balāni:</em> вера, усердие, памятование, самадхи,
            мудрость) и десять сил Будды (<em>daśa tathāgata-balāni</em>): знание возможного и
            невозможного, знание созревания кармы, знание различных склонностей существ, знание
            различных элементов (<em>дхату</em>), знание высших и низших способностей, знание
            путей, ведущих везде, знание происхождения загрязнений и их очищения, знание
            воспоминаний о прошлых жизнях, знание смерти и рождения существ, знание истощения
            <em>асрав</em> (омрачений). Бодхисаттвы на высоких ступенях пути, особенно начиная с
            восьмой бхуми (<em>Ачала</em>, «Неподвижная»), обретают зачатки этих сил. На этой
            ступени они достигают <em>анивартаны</em> (невозвратности), их деяния становятся
            <em>анабхога</em> (безусильными), а знание — <em>анабхисамскара-джняна</em>
            (недеятельным). Именно здесь <em>бала</em> расцветает как <em>акампья</em> —
            абсолютная несотрясаемость. В контексте <strong><em>Ланкаватара-сутры</em></strong>
            <em>бала</em> неотделима от <em>ващиты</em> (власти), <em>абхиджни</em>
            (сверхзнаний) и <em>викриды</em> (игровой деятельности) — ибо все они являются
            гранями единого просветлённого ума, свободно играющего в мире форм ради спасения
            существ.<a href="#ref-2" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-3"><sup>3</sup> <strong>Абхиджня</strong> (<em>abhijñā</em>)
            — высшие знания или сверхспособности, возникающие как естественные функции освобождённого
            сознания. Традиционно выделяют шесть <em>абхиджня:</em> <strong>Ṛddhi</strong> —
            чудесные силы (полёт, хождение по воде, множественные эманации и т.д.), <strong>Divya-śrotra</strong>
            — божественный слух (восприятие звуков всех миров),
            <strong>Para-citta-jñāna</strong> — знание мыслей других существ, <strong>Pūrva-nivāsānusmṛti</strong>
            — память о прошлых жизнях, <strong>Divya-cakṣus</strong> — божественное око (видение
            смерти и перерождения существ в соответствии с их кармой),
            <strong>Āsrava-kṣaya-jñāna</strong>
            — знание об истощении загрязнений (<em>āsrava</em>). В отличие от магических
            навыков, приобретаемых через <em>мантры</em> или ритуалы, <em>абхиджни</em> — это
            спонтанные проявления ума, освободившегося от двойственности субъекта и объекта. В
            ранних текстах первые пять <em>абхиджня</em> доступны даже не-буддистам через
            достижение глубоких <em>дхьян</em>, но шестая <em>абхиджня</em> — знак истинного
            освобождения, недоступный тем, кто не преодолел āsrava (омрачения-загрязнения) или
            kleśa (эгоистические эмоциональные реакции). В <strong><em>Ланкаватара-сутре</em></strong>
            <em>абхиджни</em> радикально переосмыслены в духе учения <em>Читтаматры</em>
            («Только-ум»). Здесь истинная <em>абхиджня</em> — это <em>париджняна</em> (полное
            постижение) того, что весь воспринимаемый мир есть лишь проявление собственного ума
            (<em>svacitta-dṛśya-gocara</em>). Остальные способности являются частными аспектами
            этого фундаментального знания: если бодхисаттва постиг иллюзорность границ между
            умами, он естественным образом видит мысли других; если он знает, что его ум творит
            все миры, он может проявлять чудесные силы без усилий. Таким образом,
            <em>абхиджни</em> не являются целью практики, а служат искусными средствами
            (<em>упая</em>)
            для освобождения существ. У <em>махасаттв</em> они неотделимы от <em>балы</em>
            (непоколебимой силы), <em>ващиты</em> (духовной власти) и <em>викриды</em> (игровых
            проявлений), поскольку все эти качества проистекают из единой основы —
            недвойственного знания (<em>адвая-джняна</em>). Привязанность к <em>абхиджням</em>
            или гордость ими считается серьёзным препятствием на пути. Истинный бодхисаттва
            использует их исключительно ради блага существ, оставаясь внутренне свободным от
            всех проявлений. В <strong><em>Вималакирти-нирдеша-сутре</em></strong> есть замечательный
            эпизод, где Вималакирти критикует монахов, гордящихся своими <em>абхиджнями</em>,
            показывая, что истинная способность — это постижение <em>шуньяты</em>, а не
            магические силы. В <strong><em>Алмазной сутре</em></strong> также сказано: «Те, кто видит
            Меня в форме, Те, кто следует за Моим голосом, Идут ложным путём — Они не узрят
            Татхагату». Это напоминание, что <em>абхиджни</em> относятся к миру форм
            (<em>рупа-дхату</em>)
            и не являются конечной реализацией.<a href="#ref-3"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-4"><sup>4</sup> <strong>Викрида</strong>
            (<em>vikrīḍita</em>, тиб. <em>rol pa</em>) — «свободная игра» или «игровая
            деятельность» просветлённого ума. Термин происходит от санскритского корня
            √<strong>krīḍ</strong>
            («играть») с усилительной приставкой <strong>vi-</strong>, означающей «разворачивать
            игру во всём её многообразии». Это спонтанная, непринуждённая активность бодхисаттвы
            или Будды, совершаемая: <strong>без усилия</strong> (<em>anabhisaṃskāra</em>) — без
            волевого напряжения и искусственности, <strong>без привязанности к
                результату</strong>, <strong>без разделения на субъект и объект
                действия</strong>, <strong>без накопления кармических следов</strong>. В отличие
            от обычной деятельности, порождённой желанием, страхом или долгом, <em>викрида</em>
            подобна игре ребёнка: она полна энергии и жизни, но свободна от цели и расчёта.
            Однако это не легкомыслие, а высшая форма активности — деятельность, полностью
            освобождённая от эго-центричности. В <strong><em>Ланкаватара-сутре</em></strong>
            <em>викрида</em> — естественное выражение постижения <em>читтаматры</em>
            («только-ум»): бодхисаттва знает, что весь мир есть проявление ума, и потому в его
            действиях нет ни напряжения, ни следа. Он «играет» в сансаре, как актёр на сцене,
            зная иллюзорность декораций, но при этом искренне служа освобождению существ. <em>Викрида</em>
            неотделима от: <em>балы</em> (непоколебимой силы), <em>ващиты</em> (духовной
            власти), <em>абхиджни</em> (сверхзнаний). Все они — грани единой свободы,
            проявляющейся в мире форм <strong>исключительно ради блага существ</strong>.
            Истинная <em>викрида</em> возможна только при полном постижении <em>шуньяты</em> и
            недвойственности (<em>адвая</em>). Без этой реализации попытка «играть» превращается
            в обычную кармическую деятельность или, хуже того, в духовную гордыню. Как говорится
            в <strong><em>Ваджраччхедика-сутре</em></strong>: «Воистину, Субхути, нельзя называть
            бодхисаттвой того, кто держится понятия <em>атман, саттва, джива</em> или
            <em>пудгала</em>».
            Только <strong>когда нет играющего</strong>, игра становится совершенной. В <strong>индуизме</strong>:
            <em>лила</em> (<em>līlā</em>) — божественная игра Брахмана в творении мира;
            предполагается реальный играющий (Атман). В <strong>буддизме</strong>:
            <em>викрида</em> — игра без играющего (<em>найратмья</em>). В <strong>дзэн</strong>:
            <em>мусин</em> (<em>mushin</em>) — «не-ум», спонтанное действие. В <strong>тибетском
                буддизме</strong>: <em>ролпа</em> (<em>rol pa</em>) — игровое проявление
            <em>ригпа</em>
            (изначального осознавания). В <strong>тантре</strong>: <em>викрида</em> проявляется
            как игровая деятельность божеств мандалы. Из <strong><em>Аватамсака-сутры</em></strong>:
            «Подобно луне, отражающейся в тысяче озёр, — Бодхисаттва проявляется в мириадах
            форм. Но сама луна остаётся в небе, не тронутая водой». Это и есть <em>викрида</em>:
            <strong>полная вовлечённость без привязанности, деятельность без деятеля</strong>.<a
                href="#ref-4" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-5"><sup>5</sup> <strong>Абхишека</strong>
            (<em>abhiṣeka</em>) — буквально «орошение» или «освящение» (от корня
            √<strong>sic</strong> — «лить» с приставкой <strong>abhi-</strong> — «направленное
            действие»). В индийской традиции абхишека изначально — ритуал коронации царя
            (раджасуя), при котором его омывали священной водой из четырёх сосудов,
            символизирующих четыре стороны света. Этот обряд, упоминаемый уже в Ригведе, означал
            передачу кшатра-шакти — власти правителя. В <strong><em>Ланкаватара-сутре</em></strong>
            абхишека радикально переосмыслена: это не внешний ритуал, а внутреннее признание
            зрелости бодхисаттвы, достигшего глубокого постижения того, что весь мир есть
            проявление ума (<em>cittamātra</em>). Выражение «посвящённые руками всех Будд» (<em>sarvabuddha-pāṇi-abhiṣekābhiṣikta</em>
            — букв. «те, кто посвящён посвящением от рук [благословения] всех Будд») означает,
            что вся совокупность просветлённой мудрости подтверждает реализацию бодхисаттвы.
            «Рука Будды» здесь — метафора сострадания (<em>karuṇā</em>) и благословляющей силы (<em>adhiṣṭhāna</em>),
            через которую происходит прямая передача ума к уму. <em>Абхишека</em>
            на десятой <em>бхуми</em> (<em>Дхармамегха</em> — «Облако Дхармы») предшествует <em>āśraya-parāvṛtti</em>
            (повороту основы сознания) — полной трансформации алайя-виджняны в
            <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), которая завершится при достижении
            буддовости. Как сказано в традиции, опирающейся на
            <strong><em>Дашабхумика-сутру</em></strong>: в этот миг Будды из десяти направлений касаются
            головы бодхисаттвы, подобно тому, как царя помазывают при коронации, и возникает
            великое сияние (<em>mahā-prabhāsa</em>), знаменующее его невозвратность
            (<em>anivartanā</em>)
            и готовность стать Буддой. «Подобно тому, как царевич, достигший совершеннолетия,
            помазывается водой четырёх океанов и становится чакравартином, так и бодхисаттва,
            достигший совершенства в мудрости и сострадании, касается головой лотосовых стоп
            всех Будд и получает великую абхишеку. С этого момента он уже не обычное существо
            (<em>pṛthagjana</em>), но и ещё не полностью Будда — он <em>вирья-ратна</em>
            (драгоценность усилия), готовая засиять». В сутрическом контексте (включая
            <strong><em>Ланкаватару</em></strong>)
            <em>абхишека</em> — следствие реализации; бодхисаттва «посвящён», потому что его ум
            уже неотличим от ума всех Будд. Это описательный термин, а не предписание. В
            тантрическом контексте <em>абхишека</em> — причина или катализатор реализации,
            формальный ритуал, необходимый для практики. Указывают четыре типа <em>абхишеки</em>
            в тантре: <em>калаша</em> (сосуд), <em>гухья</em> (тайная), <em>праджня-джняна</em>
            (мудрость-знание), <em>чатуртха</em> (четвёртая). Важно не смешивать эти два уровня:
            в <strong><em>Ланкаватаре</em></strong> абхишека остаётся прямым выражением внутренней
            свободы, а не предварительным условием практики. В контексте
            <strong><em>Ланкаватары</em></strong> <em>абхишека</em> знаменует глубокое очищение
            <em>алайя-виджняны</em>
            от <em>васан</em> (кармических отпечатков). Если ритуальная вода очищает тело, то
            лучи мудрости (<em>raśmi</em>) Будд ослабляют тончайшие препятствия к всеведению
            (<em>jñeyāvaraṇa</em>). Здесь абхишека — это граница: бодхисаттва достигает высшей
            ступени пути и становится <em>ювараджей</em> (наследным принцем Дхармы), чья
            деятельность во благо существ становится тождественной деятельности самих Будд.<a
                href="#ref-5" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-6"><sup>6</sup> <strong>Париджняна</strong>
            (<em>parijñāna</em>, тиб. <em>yongs su shes pa</em>) — исчерпывающее,
            непосредственное постижение, в котором объект раскрывается со всех сторон, полностью
            и без остатка. Термин образован от корня √<strong>jñā</strong> («знать») с
            приставкой <strong>pari-</strong>, означающей «вокруг» (всестороннее охватывание),
            «полностью» (завершённость) и «за пределы» (превосхождение обычного знания). <em>Париджняна</em>
            — не интеллектуальное знание (<em>jñāna</em>), не результат обучения
            (<em>śruta-jñāna</em>)
            или логического размышления (<em>cintā-jñāna</em>). Она является вершиной
            взращённого созерцательного опыта (<em>bhāvanā-jñāna</em>) и плодом прямого постижения. Это
            не мимолётное озарение, не экстатическое переживание единства и не трансовое
            состояние, в котором может отсутствовать мудрость. Это необратимое изменение способа
            познания. В контексте <strong><em>Ланкаватара-сутры</em></strong> центральным является
            <em>париджняна</em>
            <em>svacitta-dṛśya-gocara</em> — полное и прямое постижение того, что весь
            воспринимаемый мир есть сфера проявления ума (<em>читтаматра</em>), ум
            окончательно перестаёт принимать внешний мир как независимый объект,
            субъектно-объектная двойственность растворяется. В момент <em>париджняны</em>
            познание и освобождение неразделимы: постижение шуньяты освобождает от
            привязанностей, поскольку объект теряет свою «внешнюю» власть над воспринимающим.
            <em>Париджняна</em> предшествует окончательному <em>повороту основы</em> (<em>āśraya-parāvṛtti</em>),
            способствует устранению <em>познавательных препятствий к всеведению
                (jñeyāvaraṇa)</em> и является внутренним фундаментом для духовного посвящения
            (<em>абхишеки</em>). Без <em>париджняны</em> даже глубокие состояния сосредоточения
            остаются ограниченными двойственным восприятием. С <em>париджняной</em> само бытие
            постигается как Татхата (Таковость) в её недвойственной природе, а любая
            деятельность бодхисаттвы превращается в <em>викриду</em> (свободную игру) и
            <em>упаю</em> (искусное средство) для блага существ.<a href="#ref-6"
                                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-7"><sup>7</sup> <strong>Svacitta-dṛśya-gocara</strong>
            (санскр. <em>sva-citta-dṛśya-gocara</em>, тиб. <em>rang sems kyi snang yul</em>) —
            «сфера видимого собственным умом», или, образно, «пастбище восприятий собственного
            ума». Слово <em>gocara</em> буквально означает «место, где пасутся коровы»
            (<em>go</em> — корова, <em>cara</em> — движение). В классической индийской
            эпистемологии оно обозначает сферу действия чувств: зрение «пасётся» в мире форм,
            слух — в мире звуков. В <strong><em>Ланкаватара-сутре</em></strong> этот образ получает
            глубокое переосмысление: ум сам создаёт своё пастбище. Обыденное сознание «пасётся»
            в мире, который является проекцией его собственных кармических отпечатков
            (<em>васан</em>). Здесь <em>citta</em> — не индивидуальное «я» или «сердце», а
            фундаментальный поток сознания (<em>алайя-виджняна</em>), проецирующий всё
            воспринимаемое как <em>ābhāsa</em> — «кажимость» или «отражение» (подобно луне в
            воде). То, что принимается за «внешний мир», на деле является динамикой самого ума,
            разворачивающейся в его собственной сфере (<em>gocara</em>). Учение не утверждает
            реальность «я», творящего мир. Напротив, оно постулирует, что и воспринимающий
            субъект (<em>грахака</em>), и воспринимаемый объект (<em>грахья</em>) равно лишены
            самосущности (<em>шунья</em>). Это безличный процесс возникновения иллюзии
            разделения. Мир, воспринимаемый как нечто внешнее и отдельное, — это
            <em>парикальпита</em>
            (воображаемое). Сам поток <em>svacitta-dṛśya-gocara</em>, процесс взаимозависимого
            возникновения явлений в уме, — это <em>паратантра</em> (зависимое). Постижение этого
            потока, свободного от наслоений двойственности «я и другие», — это
            <em>паринишпанна</em> (совершенное), или <em>Татхата</em> (Таковость). Постижение
            «сферы собственного ума» достигается через вопрос: «Где находится объект — внутри
            или снаружи?» Невозможность определить местоположение объекта (он не может быть ни
            внутри, ни снаружи) приводит к прямому переживанию: разделения не существует. В этот
            момент исчезает мнимая пропасть между познающим и познаваемым. Реализация <em>svacitta-dṛśya-gocara</em>
            устраняет цепляние за личность (<em>атма-граха</em>) и за независимость вещей (<em>дхарма-граха</em>).
            Бодхисаттва, постигший это, обретает недвойственную свободу (<em>адвая-гати</em>).
            Он действует в мире как актёр на сцене: будучи полностью вовлечённым, он остаётся
            свободным, так как знает — и сцена, и действие, и зрители суть безличный процесс
            проявления ума, игра без играющего.<a href="#ref-7"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-8"><sup>8</sup> <strong>Рупа</strong> (<em>rūpa</em>, тиб.
            <em>gzugs</em>) — в данном контексте это не «материальная форма» (одна из пяти <em>скандх</em>),
            а гибкий способ проявления бодхисаттвы, соответствующий кармическому восприятию и
            характеру существ. Для обычного существа <em>рупа</em> — кармическая тюрьма: оно
            цепляется за тело как за «своё», страшится его утраты и страдает от иллюзии
            плотности. Но для бодхисаттвы, постигшего <em>svacitta-dṛśya-gocara</em>,
            <em>рупа</em> становится инструментом освобождения — <em>майя-рупа</em> («телом,
            подобным иллюзии»): <em>шуньевым</em> по природе, но действенным. Это не намеренное
            преображение. Ум бодхисаттвы, свободный от двойственности, естественно откликается
            на нужды существ, и форма возникает сама — как звук небесных барабанов (<em>divya-dundubhi</em>)
            или свет драгоценности, исполняющей желания (<em>cintāmaṇi</em>). Такое проявление —
            <em>анабхисамскара</em>: безусильное, непринуждённое, лишённое эгоцентрического
            намерения. Благодаря знанию чужих умов (<em>para-citta-jñāna</em>) и пониманию
            различных склонностей существ (<em>nānā-sattva-citta-carita</em>), бодхисаттва
            принимает форму не как маску, а как часть триады искусных средств (<em>upāya</em>):
            <em>рупа</em> — подходящее тело, <em>найя</em> — подходящий метод наставления, <em>винайя</em>
            — способ усмирения клеш. В системе трёх Тел Будды (<em>tri-kāya</em>) такие
            проявления предвосхищают Нирманакаю — Тело Проявлений. Ключевое различие в отношении
            к форме выражается через уровни реализации: Обычное существо заперто в форме;
            Бодхисаттва играет с формой (викрида); Будда являет все формы — но ни одна не
            является его сутью. Постигнув, что и «он», и «другое существо» — проявления ума,
            свободного от разделения, бодхисаттва свободно проявляется во всех мирах, оставаясь
            внутренне недвижимым. Он подобен луне, которая отражается в тысячах водоёмов, но,
            оставаясь в небе, не затронута движением воды.<a href="#ref-8"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-9"><sup>9</sup> <strong>Найя</strong> (<em>naya</em>, тиб.
            <em>tshul</em>), происходящая от санскритского корня √<strong>nī</strong> («вести»),
            — персонализированный метод наставления или искусный подход, подбираемый
            бодхисаттвой в строгом соответствии со склонностями, способностями и кармическим
            состоянием конкретного существа. В отличие от догматического подхода, <em>найя</em>
            является живым процессом ведения к истине, где форма учения диктуется состоянием
            слушателя. Для одного бодхисаттва может использовать прямое указание на
            <em>шуньяту</em> — резкое и беспощадное, как удар меча, отсекающий корень
            привязанности; для другого он выберет иносказание или притчу, мягко раскрывающую
            сердце через сострадание. В иных случаях высшей <em>найей</em> становится
            благородное молчание, подобное ответу Вималакирти на вопрос о недвойственности,
            когда само отсутствие слов указывает на реальность, лежащую за пределами понятий.
            Такая гибкость становится возможной только на фундаменте <em>париджняны
                svacitta-dṛśya-gocara</em>, благодаря которой бодхисаттва непосредственно видит
            структуру чужого ума. Через <em>para-citta-jñāna</em> (знание мыслей других) он
            понимает, как ум другого существа строит свой мир, какие именно <em>васаны</em> и
            <em>клеши</em> формируют его иллюзию, и, исходя из этого видения, подбирает тот
            особый путь, который способен разрушить это конкретное заблуждение. В этом ключе
            сама доктрина трёх колесниц, описанная в <strong><em>Лотосовой сутре</em></strong>, объявляется не
            конечной
            истиной, а <em>найей</em> — временным средством, приспособленным к разной глубине
            понимания существ, подобно тому как отец в притче о горящем доме обещает детям
            разные повозки, чтобы спасти их от огня и в итоге привести к единому высшему
            Пробуждению. В неразрывной триаде <em>рупа—найя—винайя</em> именно <em>найя</em>
            занимает центральное положение, выступая мостом между проявленной формой и целью — освобождением от <em>клеш</em>. Если <em>рупа</em> (подходящий облик) устанавливает
            канал доверия, то <em>найя</em> передаёт смысл Дхармы в доступных категориях, а <em>винайя</em>
            закрепляет этот процесс, устраняя аффекты и приводя ум к покою. Вместе эти аспекты
            воплощают <em>упая-каушалью</em> (искусность в средствах), лишённую эгоцентрических
            намерений и проистекающую из глубокого постижения недвойственной природы ума.
            Действуя как искусный врач, бодхисаттва не применяет одно лекарство ко всем
            болезням, но определяет состояние каждого существа и назначает именно ту
            <em>найю</em>, которая принесёт исцеление в данное время и при данных
            обстоятельствах.<a href="#ref-9" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-10"><sup>10</sup> <strong>Винайя</strong> (<em>vinaya</em>),
            происходящая от санскритского корня √<strong>nī</strong> («вести») с приставкой
            <strong>vi-</strong> («прочь», «врозь»), буквально означает «ведение прочь от
            заблуждений», «усмирение» или «направление в правильное русло». В контексте глубоких
            реализаций бодхисаттвы этот термин радикально отличается от формального монашеского
            устава (<em>Vinaya-piṭaka</em>); здесь он обозначает живое, обращённое к конкретному
            существу воспитательное действие, направленное на устранение его клеш. Если
            <em>рупа</em> устанавливает доверительную связь через подходящий облик, а
            <em>найя</em> раскрывает смысл учения в доступной форме, то <em>винайя</em>
            закрепляет результат, непосредственно воздействуя на омрачения, которые блокируют
            путь к освобождению. Такое воспитательное действие может принимать самые разные
            формы: от строгого слова, сокрушающего самодовольство, до мягкого упрёка или
            временного отстранения от практики, если она выполняется из эгоистических
            побуждений. <em>Винайя</em> не является актом наказания, исходящим из гнева или
            осуждения; это лекарство сострадания, которое порой может выглядеть как суровая
            мера, но в действительности служит единственной цели — пробуждению ясности ума.
            Бодхисаттва применяет <em>винайю</em> искусно, поскольку его действия опираются на
            постижение <em>svacitta-dṛśya-gocara</em>: он видит тончайшие кармические наслоения
            (<em>васаны</em>), питающие эго другого существа, и точно знает, какая именно мера
            не вызовет бесполезного сопротивления, но разрушит сам корень заблуждения. В триаде
            <em>рупа—найя—винайя</em> именно <em>винайя</em> выступает завершающим актом
            преобразования сознания, превращая понимание в устойчивое состояние покоя. Она
            воплощает принцип, согласно которому истинное милосердие иногда требует жёсткости, а
            истинное наставление — решительного пресечения ложных путей. Таким образом,
            <em>винайя</em>
            становится проявлением искусности в средствах, где бодхисаттва действует не по букве
            правила, а исходя из глубокого видения того, что именно в данный миг необходимо
            существу для исцеления его ума.<a href="#ref-10"
                                              class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-11"><sup>11</sup> <strong>Пять дхарм</strong> (<em>pañcadharma</em>) — одна из центральных классификационных схем <strong><em>Ланкаватары</em></strong>: Имя (<em>nāma</em>), Признак (<em>nimitta</em>), Различение (<em>vikalpa</em>), Правильное знание (<em>samyagjñāna</em>) и Таковость (<em>tathatā</em>).<br>Первые три относятся к сфере обусловленного различения. Признак — непосредственно воспринимаемый облик вещи. Имя — слово, накладываемое на признак. Различение — умственное построение, соединяющее имена и признаки в «явления» и «я». Эти три соответствуют воображаемой (<em>parikalpita</em>) и зависимой (<em>paratantra</em>) природам.<br>Правильное знание и Таковость указывают за пределы этой схемы. Правильное знание видит имена и признаки без наложения различений. Таковость — сама природа реальности, открывающаяся в этом видении. Они соответствуют совершенной природе (<em>pariniṣpanna</em>). Подробное разъяснение этих пяти дхарм даётся в подглаве 6.2.<a href="#ref-11" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-12"><sup>12</sup> <strong>Три свабхавы</strong> (<em>tri-svabhāva</em>)
            — три уровня, на которых ум воспринимает реальность. <em>Парикальпита</em> (<em>parikalpita</em>)
            — воображаемая природа. Ум принимает свои проекции за независимую реальность: «я» и
            «мир» кажутся отдельными, самосущими. Это — корень всех заблуждений.
            <em>Паратантра</em> (<em>paratantra</em>) — зависимая природа. Ум видит, что всё
            возникает взаимозависимо: мысли, образы, чувства — всё это поток причин и условий.
            Но пока ещё не свободен от привычки делить опыт на «внутреннее» и «внешнее». <em>Паринишпанна</em>
            (<em>pariniṣpanna</em>) — совершенная природа. Прямое постижение того, что <em>паратантра</em>
            изначально чиста: нет ни «я», ни «мира», только недвойственная таковость
            (<em>татхата</em>).
            Это — реализация <em>шуньяты</em> без отрицания явления. Эти три природы — не три
            разных вещи, а три способа видеть одно и то же. <em>Паринишпанна</em> — это та же
            <em>паратантра</em>, но очищенная от <em>парикальпиты</em>. Обычное существо видит
            <em>парикальпиту</em>, йогин — <em>паратантру</em>, просветлённый —
            <em>паринишпанну</em>. Бодхисаттва использует это различие, чтобы точно направлять
            других.<a href="#ref-12" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-13"><sup>13</sup> <strong>Восемь виджнян</strong> (<em>aṣṭau
                vijñānāni</em>) — восемь видов сознания, описываемых в учении <em>йогачары</em>
            и центральных для <strong><em>Ланкаватара-сутры</em></strong>. 1–5. Пять чувственных
            сознаний: зрительное, слуховое, обонятельное, вкусовое, осязательное. 6. Ментальное
            сознание (<em>мано-виджняна</em>) — различает объекты, строит мысли, работает с
            памятью и логикой. 7. <em>Манас</em> (<em>kliṣṭa-manas</em>) — омрачённое
            эго-сознание. Оно постоянно цепляется за алайю, принимая её за «я», и порождает
            четыре коренных клеши: самомнение (<em>ātma-māna</em>), ложное воззрение о «я» (<em>ātma-dṛṣṭi</em>),
            привязанность к себе (<em>ātma-sneha</em>) и неведение о себе (<em>ātma-avidyā</em>).
            8. <em>Алайя-виджняна</em> (<em>ālaya-vijñāna</em>) — сознание-хранилище. В нём
            хранятся все кармические отпечатки (<em>bīja</em>, «семена»), которые созревают как
            <em>васаны</em> (привычные склонности) и проявляются в виде опыта. Это — основа всех
            остальных сознаний: они возникают из <em>алайи</em> и питают её новыми отпечатками.
            Обычный человек не замечает ничего, кроме первых шести. Бодхисаттва, углубляясь в
            медитацию, распознаёт тонкую работу <em>манаса</em> (седьмого) и <em>алайи</em>
            (восьмого). При <em>āśraya-parāvṛtti</em> (повороте основы) <em>алайя-виджняна</em>
            преображается в <em>ādarśa-jñāna</em> (Зерцалоподобную Мудрость), а манас — в <em>samatā-jñāna</em>
            (Мудрость Равностности). Остальные шесть сознаний также преображаются в
            соответствующие Мудрости. Восемь виджнян преображаются в пять Мудростей
            (<em>pañca-jñāna</em>):
            Зерцалоподобную, Равностности, Различающую, Совершающую деяния и Дхармадхату — свободные
            от кармических наслоений. Именно постижение восьми виджнян позволяет бодхисаттве
            видеть механизм возникновения иллюзии «я» и конструирования мира умом. Это —
            практическая основа для <em>āśraya-parāvṛtti</em> и освобождения.<a href="#ref-13"
                                                                                class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-14"><sup>14</sup> <strong>Пудгала-найратмья</strong> (<em>pudgala-nairātmya</em>)
            — отсутствие «я» в личности. Обычное сознание принимает поток пяти <em>скандх</em> —
            <em>рупа</em> (форма), <em>ведана</em> (чувства), <em>санджня</em> (различение),
            <em>самскара</em> (ментальные формирующие факторы) и <em>виджняна</em> (сознание) —
            за постоянное «я», обладающее опытом. Учение о <em>пудгала-найратмье</em>
            показывает, что такого независимого, неизменного «я» нет. Личность — лишь временный
            набор условий, лишённый собственной сущности. Это первая ступень освобождения:
            устранение цепляния за «я». В <strong><em>Ланкаватара-сутре</em></strong> она неразрывна со
            второй — <em>дхарма-найратмьей</em>, ибо пока есть вера в «я», будет и вера в «вещи»
            как нечто реальное.<a href="#ref-14" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-15"><sup>15</sup> <strong>Дхарма-найратмья</strong> (<em>dharma-nairātmya</em>)
            — отсутствие самости в явлениях. Если <em>пудгала-найратмья</em> отрицает «я», то
            <em>дхарма-найратмья</em> отрицает независимую реальность самих составляющих опыта —
            форм, звуков, мыслей, чувств и даже элементов пути. Ни одно явление (<em>дхарма</em>)
            не обладает независимой, устойчивой природой. Все они возникают зависимо, длятся
            мгновение и исчезают. Это более тонкое постижение, чем отсутствие личности. Оно
            разрушает последнее убежище эго — веру в то, что хотя «я» и нет, зато «мир» реален.
            В <strong><em>Ланкаватара-сутре</em></strong> полная реализация возможна только тогда, когда
            ум видит: ни «я», ни «вещи» не имеют собственной сущности — оба шунья.<a
                href="#ref-15" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-16"><sup>16</sup> <strong>Адвая-гати</strong>
            (<em>advaya-gati</em>)
            — недвойственная стезя, путь, свободный от противопоставлений. Здесь нет разделения
            на «я» и «мир», «сансару» и «нирвану», «чистое» и «нечистое», «субъект» и «объект»,
            «бытие» и «небытие». Такой путь не ведёт от чего-то к чему-то — он есть прямое
            пребывание в природе ума, как она есть. <em>Адвая-гати</em> — не теория и не
            состояние, а способ бытия, в котором вся деятельность бодхисаттвы — будь то учение,
            молчание или чудо — происходит без следа двойственности. Это завершение пути,
            описанного <em>через пять дхарм, три свабхавы, восемь виджнян</em> и <em>два вида
                отсутствия «я»</em>.<a href="#ref-16"
                                       class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-17"><sup>17</sup> Дворец Царя Нагов символизирует
            Алайя-виджняну — глубину сознания, где Дхарма пребывает в недоступной тишине. Семь
            дней — символ завершённого постижения, пребывания в недвойственном самадхи. Выход из
            него — спонтанное проявление сострадания: Дхармакая, оставаясь неизменной, являет
            Нирманакаю ради блага живых существ.<a href="#ref-17"
                                                   class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-18"><sup>18</sup> Встреча Будды с Индрой, Брахмой и
            дочерьми царей нагов в <strong><em>Ланкаватаре</em></strong> — это не просто сцена внешнего
            почитания, а символическое указание на внутренние уровни сознания. Индра
            олицетворяет чувственный мир (<em>kāma-dhātu</em>), Брахма — мир форм
            (<em>rūpa-dhātu</em>),
            а дочери <em>нагов</em> — глубинные слои «океана ума» (<em>citta-samudra</em>), где
            пребывают кармические семена (<em>bīja</em>) и <em>васаны</em>. Ни одно из этих
            существ не является источником Дхармы. Их присутствие лишь указывает на то, что
            учение Будды охватывает все уровни сознания — от грубых до тончайших. Однако сама
            Дхарма не принадлежит ни чувственному, ни рассудочному, ни даже глубинному
            подсознательному уровню. Когда Будда покидает дворец Царя Нагов, истина переходит из
            невыразимой тишины недвойственности в сферу выражаемого. Боги и наги здесь лишь
            подтверждают, что путь к освобождению теперь доступен для восприятия на всех уровнях
            бытия. Суть этой встречи в том, что пробуждение превосходит любые состояния сознания
            — будь то чувственные наслаждения Индры или тончайшие блаженства Брахмы. Источник
            Дхармы лежит за пределами этой структуры, в «несотворённом» (<em>asaṃskṛta</em>),
            которое Будда выносит из глубины океана для блага всех существ.<a href="#ref-18"
                                                                              class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-19"><sup>19</sup> Улыбка Будды (<em>smita</em>) — знак
            узнавания и преемственности. Взглянув на гору Малайя, Будда видит, что это место,
            где Дхарма всегда провозглашалась. Его улыбка — подтверждение, что он вступает в ту
            же стезю, что и все Татхагаты прошлого.<a href="#ref-19"
                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-20"><sup>20</sup> «<strong>Благородная мудрость</strong>» (<em>svapratyātmārya-jñāna</em>)
            — знание, постигаемое непосредственно в личном опыте, без опоры на слова, логику или
            авторитет. Оно возникает только в результате глубокого преобразования ума и
            недоступно тому, кто полагается на представления/идеи. <em>svapratyātma</em>
            подразумевает «своё собственное» знание, не заимствованное, не выведенное, а
            раскрытое изнутри.<a href="#ref-20" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-21"><sup>21</sup> <strong>Тарка</strong> (<em>tarka</em>) —
            логическое рассуждение, основанное на двойственности «субъект–объект». В <strong>Ланкаватара-сутре</strong>
            оно считается препятствием, поскольку не может привести к недвойственному
            постижению.<a href="#ref-21" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-22"><sup>22</sup> «<strong>Проявили […] Дхарму</strong>»
            (<em>tadbhāvito dharmo</em>) — глагол <em>deśitaḥ</em> («излагалась») определяется
            причастием <em>tadbhāvitaḥ</em> — «сделанная таковой», «доведённая до подлинного
            бытия». Это означает: Дхарма не просто рассказывалась, а возникла из самой природы
            просветления Татхагат и была проявлена как живое событие. В
            <strong><em>Ланкаватара-сутре</em></strong>
            учение всегда есть выражение реализации, а не передача информации.<a href="#ref-22"
                                                                                 class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-23"><sup>23</sup> В <strong><em>Ланкаватаре</em></strong> фигуры
            Раваны и города Ланки имеют символический характер. Равана, царь ракшасов,
            представляет ум огромной силы и проницательности, способный как к глубокому
            заблуждению, так и к пониманию. Ланка на вершине горы Малайя — образ
            труднодоступного внутреннего пространства, «крепости сознания», где возможно
            преобразование. Происхождение Раваны в индийской традиции подчёркивает эту
            двойственность. Его отец, мудрец Вишрава, был сыном Пуластьи и внуком Брахмы, что
            помещает Равану в линию «рожденных из ума» божественных прародителей и объясняет его
            выдающийся интеллект и знание Вед. Его мать, Кайкеши, происходила из рода ракшасов и
            стремилась родить наследника, способного вернуть им былую силу и власть. Из этого
            союза возникает фигура, сочетающая мудрость брахмана с мощью ракшаса. История
            возвышения Раваны далее усиливает этот образ. Он не унаследовал власть:
            первоначально Ланкой правил его брат Кубера. Добившись силы благодаря суровым
            аскезам перед Брахмой и получив обещание неуязвимости от богов и асуров, Равана
            сверг Куберу и овладел Ланкой и всем его богатством. Его эпитет «Десятиглавый» (<em>Daśagriva</em>)
            символически указывает на знание четырёх Вед и шести шастр, а также на способность
            управлять всеми направлениями опыта. В шиваитской традиции он известен как великий
            бхакта Шивы и автор почитаемого гимна <strong><em>Шива-тандава-стотра</em></strong>.
            Использование Раваны как центрального собеседника в буддийской сутре — не
            случайность. Эта фигура воплощает вершину мирского могущества, магической силы и
            интеллектуальной эрудиции. То, что именно Равана приглашает Будду и склоняется перед
            ним, подчёркивает ключевой мотив <strong><em>Ланкаватара-сутры</em></strong>: даже высшая
            форма мирского знания и силы уступает прямому пониманию природы сознания. Дхарма
            превосходит и побеждает как грубые страсти, так и утончённое рассудочное знание.<a
                href="#ref-23" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-24"><sup>24</sup> <strong>Сила благословения
                Татхагат</strong> (<em>tathāgatādhiṣṭhāna</em>) — не ответ на молитву, а милость
            Будд, без которой невозможно даже услышать Дхарму. Без неё Равана, несмотря на своё
            могущество, остался бы глух к учению.<a href="#ref-24"
                                                    class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-25"><sup>25</sup> <strong>Алайя-виджняна</strong> (<em>ālayavijñāna</em>)
            — «сознание-сокровищница», восьмое сознание в учении йогачары. В нём, как в океане,
            под действием «ветра» чувственного восприятия и <em>клеш</em> возникают «волны» —
            мысли, эмоции и кажущийся внешний мир. В этом образе внешний океан и внутренний —
            одно: всё видимое есть проявление ума. <em>Алайя</em> — как океан; семь сознаний —
            как волны. Ветер неведения движет их. Когда ветер стихает и волны успокаиваются —
            сам океан преобразуется: <em>алайя-виджняна</em>, освобождаясь от <em>васан</em>,
            раскрывается как <em>ādarśa-jñāna</em> (Зерцалоподобная Мудрость).<a href="#ref-25"
                                                                                 class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-26"><sup>26</sup> <strong>Колесница Пушпака</strong> —
            «Цветочная вимана» — самодвижущаяся воздушная колесница, первоначально
            принадлежавшая Кубере, хранителю севера и сокровищ земли. Согласно «Рамаяне», её
            захватил Равана, изгнав Куберу из Ланки. В буддийских текстах Пушпака символизирует
            высокое положение, но не просветление.<a href="#ref-26"
                                                     class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-27"><sup>27</sup> <strong>Вина</strong> (<em>vīṇā</em>) —
            один из древнейших и наиболее почитаемых музыкальных инструментов Индии. Это
            струнный щипковый инструмент с длинной шейкой и двумя резонаторами (обычно
            тыквенными или деревянными), натянутыми между ними струнами — чаще всего семью, хотя
            число могло варьироваться. В ведической и буддийской традициях <em>вина</em> — не
            просто инструмент, а символ гармонии между мудростью и состраданием. Её звук
            считался способным успокоить ум, рассеять помехи и подготовить слушателя к
            восприятию Дхармы. В индуизме <em>вина</em> — атрибут <em>Сарасвати</em>, богини
            знания, речи и искусства. В буддийских текстах (особенно махаянских) она часто
            звучит при встрече с Буддой — как знак того, что пространство очищено, а собрание
            готово слушать. Когда Равана берёт вину, он не просто играет — он совершает
            подношение через звук, превращая музыку в путь, ведущий к внутреннему постижению.
            Именно на фоне её мелодии он начинает петь <em>гатхи</em> — слияние слова и звука
            как единое выражение Дхармы.<a href="#ref-27"
                                           class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-28"><sup>28</sup> <strong>Индранела</strong>
            (<em>indranīla</em>) — драгоценный камень цвета неба, обычно лазурит или синий
            сапфир. В индийской традиции считается камнем Индры, царя богов.<a href="#ref-28"
                                                                               class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-29"><sup>29</sup> <strong>Вайдурья</strong>
            (<em>vaiḍūrya</em>) — драгоценный камень, упоминаемый в индийских и буддийских
            текстах как один из главных самоцветов. Его точная природа варьируется в зависимости
            от эпохи и региона: В древнеиндийских источниках (включая ранние буддийские сутры)
            <em>vaiḍūrya</em> обычно означает лазурит — глубокий сине-голубой камень с
            золотистыми прожилками, добывавшийся в Афганистане и высоко ценившийся за его
            небесный цвет. В поздних текстах (особенно в тибетской и китайской традициях) под
            <em>vaiḍūrya</em> часто подразумевают изумруд или зелёный берилл. В некоторых
            контекстах — прозрачный горный хрусталь или даже опал, если речь идёт о сиянии, а не
            цвете. В <strong><em>Ланкаватаре</em></strong> и других махаянских сутрах <em>вайдурья</em>
            символизирует чистоту, прозрачность ума и способность отражать истину без искажений.
            Этимология неясна. Согласно одной версии, название происходит от города Видура
            (Южная Индия), где добывали этот камень. Возможна также связь с греческим
            <em>beryllos</em>
            (берилл), хотя направление заимствования остаётся предметом дискуссий.<a
                href="#ref-29" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-30"><sup>30</sup> <strong>Приянга</strong>
            (<em>Priyaṅgu</em>, предположительно <em>Aglaia elaeagnoidea</em> или <em>Callicarpa
                macrophylla</em>) — тропическое растение, распространённое в Индии и
            Юго-Восточной Азии. Известно своими мелкими, густыми соцветиями белых или
            бледно-жёлтых цветов, которые источают нежный, сладковатый аромат. В санскритской
            поэзии и буддийских текстах цветы <em>приянги</em> — символ нежности, чистоты и
            благоухания добродетели. Их белый цвет часто сравнивают с лунным светом, снегом на
            вершинах Гималаев или чистой шёлковой тканью. Упоминание «ткани цвета
            <em>приянги</em>» — не просто описание оттенка, а аллегория свежести, мягкости и
            духовной чистоты. Когда Равана обвивает вину такой тканью, он не только соблюдает
            ритуальную эстетику — он подготавливает пространство для восприятия Дхармы через
            образ безупречности.<a href="#ref-30" class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-31"><sup>31</sup> <strong>Музыкальное подношение
                Раваны</strong> — это не просто пение под аккомпанемент вины, это сложный
            ритуальный акт, свидетельствующий о владении <em>сангита-шастрой</em> — наукой о
            звуке. Перечисление терминов — <em>шадджа, ришабха, гандхара, мадхьяма, дхаивата,
                нишада</em> — указывает на семь основных звуков (<em>свар</em>), которые в
            индийской традиции соотносятся с <em>чакрами</em>, планетами и уровнями космоса.
            Особое внимание привлекает <em>кайшика</em> — термин, обозначающий тончайший
            микротоновый оттенок (<em>шрути</em>). В классических трактатах, таких как <strong><em>Натьяшастра</em></strong>,
            <em>кайшика</em> не является самостоятельной нотой, а указывает на утончённую
            градацию звука. Её упоминание вместо стандартной пятой ступени (<em>панчамы</em>)
            подчёркивает исключительность исполняемого лада — вероятно, редкой ритуальной
            системы, предназначенной для воздействия на тонкие уровни сознания. Эта музыка
            опирается на строгую теоретическую основу: <em>грамы</em> и <em>мурччханы</em>. <em>Грама</em>
            — базовая ладовая система; в древности их было три (<em>Ṣaḍja-grāma</em> — основная,
            <em>Madhyama-grāma</em> — вторичная, <em>Gāndhāra-grāma</em> — утрачена к
            средневековью), каждая из которых соотносилась с одним из трёх миров.
            <em>Мурччхана</em> — способ получения новых ладов путём смещения тоники, аналогичный
            античным модусам. Владение четырнадцатью <em>мурччханами</em> (по семь для каждой из
            двух сохранившихся <em>грам</em>) символически означало власть над четырнадцатью
            мирами вселенной. Сам инструмент описан как микрокосм: гриф из <em>индранелы</em>
            (синего сапфира), накладки из <em>вайдурьи</em> (берилла или лазурита), ткань цвета
            <em>приянги</em> — всё это не украшение, а символическая структура. Струны вины
            уподобляются энергетическим каналам (<em>нади</em>), её корпус — телу Вселенной.
            Таким образом, Равана предстаёт не как мифологический демонический тиран, а как
            великий аскет и мастер <strong><em>Гандхарва-веды</em></strong> — ведической науки о
            ритуальном звуке. Согласно канону, особенно <strong><em>Самаведе</em></strong>, безупречное
            исполнение такой музыки очищает пространство и «настраивает» ум слушателя. Равана
            выступает как ритуальный исполнитель, подготавливающий пространство для проповеди
            Будды через гармонию звука, формы и намерения.<a href="#ref-31"
                                                             class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-32"><sup>32</sup> <strong>Устойчивое ошибочное
                воззрение</strong> (<em>dṛṣṭi</em>) — рассудочное убеждение, принимаемое за
            окончательную истину. Оно является не просто мнением или временной точкой зрения, а
            глубоко укоренившейся ментальной зацикленностью, возникающей из пристрастия к
            построению систем понятий (<em>vikalpa</em>). Такие воззрения формируют ложные
            представления о существовании «я», о сущностях, о мире и о способе их существования
            — будь то вера в вечность, уничтожение, тождество или различие, бытие или небытие. В
            канонических текстах, особенно в <strong><em>Брахмаджала-сутте</em></strong> (<em>Brahmajāla
                Sutta, Дигха-никая 1</em>), перечисляется 62 вида подобных воззрений, образующих
            «сеть» (<em>jāla</em>), в которую попадает ум, пытаясь уловить реальность через
            двойственные категории. Все они опираются на основополагающее разделение субъекта и
            объекта, порождают цепляние за «я» (<em>ātma-graha</em>) и «моё» и тем самым
            порождают, поддерживают и усиливают страдание и круг перерождений. Истинная Дхарма,
            согласно как ранним, так и махаянским источникам, не является ни философской
            позицией, ни даже «правильным» мнением. Она не утверждает ни бытия, ни небытия, не
            принимает и не отвергает сущностных утверждений и не может быть полностью выражена
            словами, логикой или понятиями. Освобождение — это постижение природы реальности в
            непосредственном опыте (<em>pratyātma-vedya</em>), за пределами всех конструкций
            ума.<a href="#ref-32" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-33"><sup>33</sup> <strong>Путь, постигаемый непосредственно
                (лично)</strong> (<em>pratyātma-vedya-gati</em>) — это путь, который невозможно
            усвоить через слушание (<em>śruta</em>), чтение, логическое умозаключение
            (<em>anumāna</em>)
            или опору на авторитет (<em>āgama</em>). Он принадлежит исключительно сфере личного,
            недвойственного опыта, свободного от посредничества слов, символов, понятий и
            рассудочного анализа. В <strong><em>Ланкаватаре</em></strong> подчёркивается: Дхарма — не
            система учений, это реальность, подлежащая внутреннему видению. Поэтому Будда говорит:
            «Я не проповедую Дхарму» — ибо подлинная Дхарма не есть нечто, что можно передать.
            Она — то, что должно быть увидено каждым самостоятельно. Этот термин противопоставляется
            постижению через внешние источники — всему, что опирается на Учителя, тексты,
            рассуждение, традицию, символы, ритуалы или веру. Даже «правильные взгляды», если
            они остаются на уровне понятий, не ведут к освобождению, поскольку продолжают быть
            <em>dṛṣṭi</em> — устойчивыми ложными воззрениями, пусть и внешне корректными.
            Непосредственное постижение в <strong><em>Ланкаватаре</em></strong> — это не вспышка эмоции,
            не мистический экстаз и не интеллектуальная интуиция. Это — ясное видение природы
            ума, сопровождаемое прекращением всех воззрений (<em>dṛṣṭi-nirodha</em>) и
            отсечением умственных построений (<em>vikalpa-kṣaya</em>). Освобождение не происходит
            благодаря рождению новой идеи или нового переживания, оно случается через распад всей
            структуры схватывания, в которой ум конструирует субъект, объект и их отношения.
            Именно поэтому даже Равана — владыка ракшасов — способен услышать Дхарму Татхагаты.
            Его «демоническая природа» не является препятствием: ум, готовый отпустить ложные
            воззрения, способен к непосредственному постижению, независимо от кармического
            прошлого или статуса. В <strong><em>Ланкаватаре</em></strong> важна не нравственная оценка
            персонажей, имеет значение их готовность в данный момент перестать цепляться за фиксации ума.
            Таким образом, встреча Раваны с Буддой — указание на
            внутреннюю возможность: когда ум выходит за пределы <em>vikalpa</em> и
            <em>dṛṣṭi</em>, становится возможно прямое постижение Дхармы.<a href="#ref-33"
                                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-34"><sup>34</sup> <strong>Нирмана</strong>
            (<em>nirmāṇa</em>) — «созидание-проявление», «чудесное воплощение». В махаянской
            доктрине это не просто «проявление», а активный акт сострадательного творения,
            посредством которого Будда создаёт формы — тела, голоса, миры, учения, даже
            множества «двойников» — в соответствии с потребностями существ. Отсюда Нирманакая —
            Тело Проявления, возникающее из деятельности Будды, а не из кармы. Важно различать
            <em>nirmāṇa</em> и <em>nirmita</em>. Первое — процесс, способность, акт проявления; второе —
            результат: «созданное», «проявленная форма», «чудесное творение». В
            <strong><em>Ланкаватаре</em></strong>
            эта разница подчёркнута формулой <em>nirmāṇa-nirmitapradarśanakaṃ</em> —
            «показывающий <em>nirmāṇa</em> и <em>nirmita</em>», то есть и сам акт проявления, и его
            проявленные формы. Грамматически: <em>nirmāṇa</em> — отглагольное существительное от
            √<strong>mā</strong> («создавать»), обозначающее действие; <em>nirmita</em> —
            причастие прошедшего времени, означающее «сотворённое». Распространённая ошибка —
            смешивать их, переводя <em>nirmāṇa</em> как «проявленный объект». Но объект — это
            <em>nirmita</em>; <em>nirmāṇa</em> же — живая сила сострадания, выражающаяся в
            форме. Именно поэтому Будда может быть одновременно недвойственным (в Дхармакае) и
            множественным (в Нирманакае): Его сострадание не остаётся в покое, а творит формы,
            чтобы достичь каждого, кто готов услышать.<a href="#ref-34"
                                                         class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-35"><sup>35</sup> <strong>«Ты пребываешь в радости, когда
                Дхарму постигают лично»</strong> — Радость Будды возникает, когда ум слушателя
            выходит за пределы всех внешних опор: Учителя, канона, ритуала, даже «правильного
            воззрения». Подлинная Дхарма — это то, что постигается непосредственно (<em>pratyātma-vedya</em>),
            а не передаётся как учение. Будда — лишь указующий палец (в примере с Луной); он
            теряет смысл, как только взгляд обращён на Луну. Поэтому
            <strong><em>Ланкаватара</em></strong> говорит: «За сорок пять лет проповеди Будда не произнёс
            ни единого слова». Ибо истинная Дхарма раскрывается сама, когда ум
            отпускает все ложные воззрения (<em>dṛṣṭi</em>) и прекращает умственное
            конструирование (<em>vikalpa</em>).<a href="#ref-35"
                                                  class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-36"><sup>36</sup> <strong>Якши, владеющие множеством
                обликов</strong> — здесь символ подвижного,
            многоликого сознания, способного быстро менять свои состояния. В
            <strong><em>Ланкаватаре</em></strong> их «слушание» Дхармы означает, что истина доступна даже
            такому уму, который кажется нестабильным, противоречивым или слишком изменчивым для
            практики. Главное — готовность открыться. Это продолжает
            тему Раваны: даже демонический, многоглавый, страстный ум может стать сосудом для
            Дхармы.<a href="#ref-36" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-37"><sup>37</sup> <strong>То́така</strong> (<em>toṭaka</em>)
            — санскритский стихотворный размер, состоящий из четырёх строк по 12 слогов. Часто
            использовался в гимнах и философских стихах. Сам Ади Шанкара писал гимны в этом
            размере. В <strong><em>Ланкаватаре</em></strong> указание на <em>то́така</em> подчёркивает:
            речь Раваны — ритуально-поэтическое подношение, достойное Будды.<a
                href="#ref-37" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-38"><sup>38</sup> <strong>Попугаи и майны</strong> —
            символы двух типов восприятия. Попугай олицетворяет повторение без понимания: он
            может точно воспроизвести речь, но не постигает её смысла. Майна — птица, известная
            своей чуткостью к звуку, — символ внимательного, внутреннего слушания. Их совместное
            упоминание подчёркивает, что истинное постижение требует не повторения слов, а
            живого отклика ума.<a href="#ref-38" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-39"><sup>39</sup> <strong>Кумбхакарна</strong> в
            <strong><em>Рамаяне</em></strong> —
            брат Раваны, гигант, погружённый в многолетний сон, пробуждающийся лишь для еды или
            битвы. Он олицетворяет инертное, спящее сознание, скованное неведением. Однако даже
            он, пробуждаясь, способен к ясности и мудрости — он критикует Равану за беззаконие,
            хотя и остаётся верен долгу. Его упоминание здесь — знак того, что даже самое
            тяжёлое, дремлющее сознание способно пробудиться к Махаяне, если возникает контакт с
            Дхармой.<a href="#ref-39" class="text-blue-500 hover:underline">↩</a></p>
        <p class="my-2" id="citation-40"><sup>40</sup> <strong>Апсары</strong> — небесные девы,
            символы чувственного наслаждения; рощи <strong>ашоки</strong> — «деревья без
            страдания» (<em>a-śoka</em>), чьё имя обещает утешение. Равана приносит в подношение
            всё, что связано с утешением, удовольствием и эстетикой сансары. Его обращение —
            готовность отпустить все формы привязанности, включая самые изящные.<a
                href="#ref-40" class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-41"><sup>41</sup> <strong>Явил Дхарму</strong> (<em>vibhāvayāmāsa</em>)
            — не означает словесного изложения. Глагол <em>vibhāvayati</em> (каузатив от <em>bhāvayati</em>)
            в йогачаринской традиции обозначает акт внутреннего проявления или «вызывания к бытию».
            Здесь Будда, приняв подношения, не произносит ещё ни слова, но своим присутствием
            раскрывает поле Дхармы, делая её внутреннюю суть ощутимой для бодхисаттв и иных
            присутствующих. Это — преддверие проповеди: истина, которая постигается только лично
            (<em>pratyātma-gati</em>), сначала проявляется в безмолвном пространстве между Учителем
            и учениками, и лишь затем облекается в форму ответов на вопросы Раваны.<a href="#ref-41"
                                                                                      class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-42"><sup>42</sup> В <strong><em>Ланкаватаре</em></strong> Махамати —
            главный вопрошающий, носитель высшей йогачаринской мудрости. Его имя означает «Великий
            Ум» (<em>Mahā-mati</em>), и он символизирует ум, способный вместить недвойственное
            знание. Махамати задаёт вопросы, которые становятся основой для изложения глубокой
            Дхармы. В каждую эпоху у каждого Будды есть такой вопрошающий о <em>pratyātma-gati</em>
            — Дхарме, постигаемой лично, вне слов.<a href="#ref-42"
                                                     class="text-blue-500 hover:underline">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-43"><sup>43</sup> <strong>Сон</strong> (<em>svapna</em>) —
            опыт, обладающий реальностью лишь внутри сновидения, демонстрирует отсутствие различия
            между субъектом и объектом: и то, и другое порождены одним умом. <strong>Мираж</strong>
            (<em>mṛgatṛṣṇ</em>ā) — видимость воды в пустыне, лишённая плотности и сущности,
            символизирует влечение ума к объектам, которые не существуют вне желания. <strong>Город
                гандхарвов</strong> (<em>gandharva-nagara</em>) — небесный град, возникающий в
            воздухе, показывает, как привычные отпечатки сознания (<em>васаны</em>) создают иллюзию
            устойчивого и внешнего мира. <strong>Помутнение зрения</strong> (<em>timira</em>) —
            зрительная иллюзия (например, видение двух лун при катаракте), указывает на то, что даже
            «ясное» восприятие может быть искажено природой самого ума. <strong>Сын
                бесплодной</strong> (<em>vandhyā-putra</em>) — образ, подчёркивающий абсолютное
            отсутствие объекта; подобно тому как у бесплодной женщины нет ребёнка, так и у всех
            явлений отсутствует самосущая природа. <strong>Огненное колесо</strong>
            (<em>alāta-cakra</em>) — иллюзия непрерывного круга огня, возникающая от быстрого
            вращения горящей палочки, демонстрирует иллюзию непрерывности: мир состоит из мгновенных
            вспышек сознания, создающих видимость плотного, длящегося бытия.<a href="#ref-43"
                                                                               class="text-blue-500 hover:underline">↩</a>
        </p>
        <p class="my-2" id="citation-44"><sup>44</sup> Видение Раваны — прямое раскрытие природы
            ума. Горы, драгоценности, множественные образы Будды и Раваны представляют собой
            проекции потока сознания, лишённого субъектно-объектной двойственности. Эта демонстрация
            лишает воспринимаемый мир внешней опоры. Сомнения Раваны — «сон? мираж? город
            гандхарвов?» — перечисляют классические примеры обманчивого восприятия, принятые в
            индийской философии для иллюстрации природы иллюзии. Такое понимание вызывает у Раваны
            внезапное прозрение (<em>avabodha</em>). Царь ракшасов осознаёт мир как порождение
            собственного ума. Происходит его преображение: Равана перестаёт воспринимать себя только
            как правителя и становится готовым принять Дхарму. Истинная природа реальности
            открывается ему в недвойственном состоянии (<em>advaya</em>), когда <em>викальпа</em>
            (конструирующая активность ума) прекращается.<a href="#ref-44"
                                                            class="text-blue-500 hover:underline">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-45"><sup>45</sup> <strong>«Пробудился
                непосредственно»</strong> — термин указывает на
            момент прямого прозрения (<em>avabodha</em>), когда ум Раваны внезапно постигает природу
            реальности. В это мгновение он оставляет привычку воспринимать мир как внешнюю среду и
            обретает прямое видение: всё видимое представляет собой проявление сознания, лишённого
            субъектно-объектной двойственности.</p>
        <p>Данный акт является глубоким сдвигом в восприятии — <em>париджняной
                svacitta-dṛśya-gocara</em> (исчерпывающим постижением того, что мир есть сфера
            проявления ума). После такого сдвига видение реальности изменяется фундаментально, хотя
            полная стабилизация требует дальнейшей практики.</p>
        <p>Подобное пробуждение описывается как личное постижение (<em>pratyātma-vedya</em>) —
            уникальный опыт, который пребывает вне сферы передачи словами, но преображает природу
            познающего. Это переход от интеллектуального анализа к непосредственному пребыванию в
            реальности «как она есть» (<em>yathābhūta</em>).</p>
        <p>Именно это прозрение делает Равану готовым услышать глубокую Дхарму о пути, постигаемом
            лично (<em>pratyātma-gati</em>), которую Будда затем излагает.<a href="#ref-45"
                                                                             class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-46"><sup>46</sup> <strong>«Когда его основа
                преобразилась»</strong>
            (<em>parāvṛttāśraye</em>) — термин, указывающий на момент прямого прозрения, когда
            структура восприятия радикально изменяется.</p>
        <p><em>Āśraya</em> («опора») — базовое сознание (<em>ālayavijñāna</em>), в котором
            накапливаются кармические отпечатки (<em>васаны</em>) и из которого возникает иллюзия
            разделения на «я» и «мир».</p>
        <p><em>Parāvṛtti</em> («поворот») — в полном смысле это необратимая трансформация <em>алайя-виджняны</em>
            в <em>ādarśa-jñāna</em> (Зерцалоподобную мудрость), происходящая при достижении
            буддовости.</p>
        <p>Однако в данном контексте термин <em>parāvṛttāśraya</em> описывает начальное переживание
            этого поворота — момент, когда Равана впервые постиг (<em>adhigama</em>), что весь
            видимый мир есть лишь <em>svacitta-dṛśya-mātra</em> (проявление собственного ума). Это
            не окончательная <em>паравритти</em>, но решающий прорыв: ум временно освобождается от
            грубой двойственности и напрямую видит свою истинную природу.</p>
        <p>Будда хвалит Равану словами «<em>sādhu, sādhu</em>» («отлично, отлично») и говорит: «<em>evaṃ
                śikṣitavyaṃ yoginā</em>» («так должен учиться йогин»), что указывает: Равана испытал
            правильное постижение, открывающее путь к полной реализации, но ещё продолжает обучение.
        </p>
        <p>После этого прозрения Равана становится готовым вместилищем Дхармы, способным воспринять
            глубокое учение о <em>pratyātma-gati</em> (пути, постигаемом лично).<a href="#ref-46"
                                                                                   class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-47"><sup>47</sup> <strong>«Всё видимое — лишь проявление
                собственного сознания»</strong>
            (<em>svacitta-dṛśya-mātra</em>) — указание на то, что воспринимаемый объект не имеет
            внешней опоры: он возникает вместе с актом восприятия, как волна в океане ума.</p>
        <p><em>Svacitta</em> — «собственное сознание» — сознание как таковое, лишённое разделения на
            «я» и «не-я».</p>
        <p><em>Mātra</em> — «лишь» — отсекает веру в реальность внешних сущностей.</p>
        <p>Таким образом, <em>svacitta-dṛśya-mātra</em> — это отрицание двойственности. Постижение
            этого видения открывает путь к <em>āśraya-parāvṛtti</em> — полному повороту основы
            сознания, который завершится при достижении буддовости. После такого поворота <em>алайя-виджняна</em>
            раскроется как Зерцалоподобная мудрость (<em>ādarśa-jñāna</em>), полностью свободная от
            цепляния за «я» и «мир» как реальные сущности.<a href="#ref-47"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-48"><sup>48</sup> <strong>«Утвердился в сфере безмолвия, где
                прекратилось движение
                умопостроений»</strong> (<em>avikalpa-pracāra-sthita</em>) — указывает на состояние,
            в котором ум перестаёт порождать понятийные конструкции.</p>
        <p><em>Pracāra</em> — «движение», «циркуляция» — описывает обычное состояние сознания,
            непрерывно проецирующее субъект, объект и их отношения.</p>
        <p><em>Avikalpa</em> — «отсутствие различающей деятельности ума» — это не переживается как оцепенение или пустое безмыслие, это ясное осознавание, свободное от сетки определений: «я / не-я», «бытие / небытие», «истина / ложь».</p>
        <p>Утверждение в этом состоянии означает, что Равана более не анализирует, не сравнивает, не
            интерпретирует — он пребывает в том, что есть. Именно здесь, в тишине, где затухает сам
            механизм различения, становится возможным непосредственное восприятие учения Татхагаты —
            вне слов и понятий, как прямое узнавание собственной природы Будды
            (<em>tathāgatagarbha</em>). Это состояние — необходимое условие перехода от
            интеллектуального понимания к непосредственному постижению.<a href="#ref-48"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-49"><sup>49</sup> <strong>«Побуждаемый корнями благого,
                взращёнными в
                прошлом»</strong> (<em>pūrvakuśalamūlasaṃcodita</em>)
            — указывает на внутреннюю зрелость, необходимую для подлинного постижения.</p>
        <p>Корни благого (<em>kuśala-mūla</em>) — технический термин, обозначающий устойчивые
            качества ума: прежде всего отсутствие жадности (<em>alobha</em>), гнева (<em>adveṣa</em>)
            и заблуждения (<em>amoha</em>). В случае Раваны это его прошлые аскезы, преданность и
            изучение наук, которые подготовили почву для преображения.</p>
        <p>Побуждение (<em>saṃcodita</em>) — внутренний импульс, возникающий, когда внешнее условие
            (встреча с Буддой) встречается с внутренней готовностью.</p>
        <p>Эта фраза поясняет, почему Равана — владыка ракшасов — способен непосредственно войти в
            состояние <em>avikalpa</em>. Его пробуждение — естественный расцвет того, что было
            посеяно в прошлом.<a href="#ref-49" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-50"><sup>50</sup> <strong>«Сведущий во всех шастрах»</strong>
            (<em>sarva-śāstra-vidagdha</em>) — указывает на глубокое овладение каноническими
            науками: философией, логикой, грамматикой, метрикой, искусством и дхармой.</p>
        <p><em>Vidagdha</em> — «закалённый» — означает разум, прошедший через строгую дисциплину
            учения и очищенный от грубого невежества.</p>
        <p>В <em>йогачаре</em> именно такой ум способен постичь <em>читтаматру</em> и встать на путь
            к <em>āśraya-parāvṛtti</em>: лишь тот, кто в совершенстве познал пределы понятийного
            мышления, может его отпустить.</p>
        <p>Поэтому Равана, несмотря на свою природу ракшаса, непосредственно распознаёт в явлении
            Будды то, что превосходит все шастры, — и переходит от анализа к непосредственному
            постижению.<a href="#ref-50" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-51"><sup>51</sup> <strong>«Видящий вещи такими, каковы они
                есть»</strong> (<em>yathātathya-darśana</em>)
            — прямое видение реальности, свободное от искажений желания, страха и понятийного
            мышления.</p>
        <p><em>Yathātathya</em> — «согласно их истинной природе» — означает восприятие вещей такими,
            каковы они есть: лишёнными самосущности (<em>niḥsvabhāva</em>), пустыми (<em>śūnya</em>)
            по природе. Это синоним <em>татхаты</em> — «таковости».</p>
        <p><em>Darśana</em> — «видение» — не зрение глазами, а непосредственное прозрение умом, в
            котором объекты распознаются как проекции собственного сознания (<em>svacitta-dṛśya-mātra</em>).
        </p>
        <p>Такое видение становится возможным только после прекращения <em>викальп</em> — умственных
            конструкций. Оно знаменует момент, когда постижение Раваны переходит от понятийного к
            непосредственному, делая его готовым к дальнейшему продвижению на пути.<a href="#ref-51"
                                                                                      class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-52"><sup>52</sup> <strong>«Не нуждающийся в чужом
                руководстве»</strong>
            (<em>aparapraṇeya</em>) — термин, обозначающий способность самостоятельно постигать
            Дхарму через прямой опыт. Это состояние йогина, который опирается на непосредственное
            видение реальности (<em>pratyātma-vedya</em>), а не на слепое доверие к авторитетам или
            логические построения.</p>
        <p>После прозрения Равана различает истину и заблуждение исходя из внутреннего опыта. Это делает его способным воспринять глубокое учение Будды как подтверждение собственного постижения.<a href="#ref-52" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-53"><sup>53</sup> <strong>«Искусный в исследовании
                собственного разума»</strong> (<em>svabuddhi-vicālana-kuśala</em>)
            — указывает на способность йогина непосредственно наблюдать природу своего интеллекта.
        </p>
        <p><em>Svabuddhi</em> — «собственный разум» — здесь означает сам механизм познания.</p>
        <p><em>Vicālana</em> — «исследование» — активное всматривание в работу ума с целью
            распознать скрытые проекции <em>викальпы</em>.</p>
        <p><em>Kuśala</em> — «искусный» — подчёркивает, что Равана владеет самонаблюдением как
            мастерством.</p>
        <p>Именно это позволяет ему увидеть, как ум конструирует иллюзию субъекта и объекта, — и тем
            самым открывает путь к <em>āśraya-parāvṛtti</em>: повороту, при котором <em>алайя-виджняна</em> полностью освобождается от омрачений и раскрывается как <em>ādarśa-jñāna</em>
            (Зерцалоподобная мудрость).<a href="#ref-53" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-54"><sup>54</sup> <strong>«Свободный от рассудочных
                воззрений»</strong> (<em>tarka-dṛṣṭi-vyapeta</em>)
            — указывает на выход за пределы формальной логики как средства постижения истины.</p>
        <p><em>Tarka</em> — «рассуждение» — метод умозаключения, полезный на начальных этапах пути,
            но неспособный проникнуть в недвойственную природу реальности, ибо всегда опирается на
            разделение.</p>
        <p><em>Dṛṣṭi</em> — «воззрение» — здесь означает привязанность к рассудочным воззрениям
            (<em>tarka-dṛṣṭi</em>) как к окончательной истине.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — означает, что Равана более не пытается
            «вывести» Дхарму логически. Его видение (<em>darśana</em>) стало непосредственным: он
            созерцает реальность, не опираясь на рассудочные построения, что является признаком
            перехода от теоретического знания к йогическому опыту.<a href="#ref-54"
                                                                     class="citation-back">↩</a></p>
        <p class="my-2" id="citation-55"><sup>55</sup> <strong>«Принимающий вселенскую
                форму»</strong> (<em>mahā-viśvarūpa-dhārin</em>)
            — эпитет, указывающий на способность йогина проявлять бесчисленные формы без
            привязанности к какой-либо из них.</p>
        <p><em>Viśvarūpa</em> — «вселенская форма» — означает способность проявляться во всех
            формах, постигнув их как проявления собственного ума.</p>
        <p><em>Dhārin</em> — «удерживающий» — подчёркивает, что он владеет искусством проявления
            форм, ибо постиг их природу как <em>svacitta-dṛśya-mātra</em> — «лишь проявление
            собственного сознания».<a href="#ref-55" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-56"><sup>56</sup> <strong>«Умелый в искусных
                средствах»</strong> (<em>upāyakauśalya</em>)
            — указывает на способность йогина являть Дхарму в любой форме, где есть существо,
            готовое её воспринять.</p>
        <p><em>Upāya</em> — «искусное средство» — непосредственное выражение сострадания,
            возникающее без намерения, когда ум свободен от разделения на «учителя» и «ученика».</p>
        <p><em>Kauśalya</em> — «умение» — мастерство, рождённое из прямого видения реальности.</p>
        <p>Такое умение проистекает из постижения недвойственности: когда ум перестаёт цепляться за
            «я» и «мир», он способен откликаться на нужду любого существа — через слово, молчание,
            образ или даже отсутствие формы.<a href="#ref-56" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-57"><sup>57</sup> <strong>«Искусный в последовательном
                постижении отличительных признаков
                всех ступеней»</strong> (<em>sarva-bhūmy-uttarottara-sva-lakṣaṇādhigama-kuśala</em>)
            — указывает на глубокое знание внутренней структуры пути.</p>
        <p><em>Bhūmi</em> — «земли, степени, ступени» — десять ступеней бодхисаттвы, каждая из
            которых имеет свою природу и функцию.</p>
        <p><em>Uttarottara</em> — «последовательный, один выше другого» — означает понимание того,
            как каждое состояние естественно рождает следующее.</p>
        <p><em>Svalakṣaṇa</em> — «собственные признаки» — указывает на способность непосредственно
            распознавать каждую ступень по её внутреннему качеству, а не по внешним проявлениям.</p>
        <p>Такое мастерство (<em>kuśala</em>) свидетельствует о зрелости Раваны как йогина,
            подготовленного прошлыми аскезами и накоплением корней благого. Оно позволяет ему не
            останавливаться на промежуточных состояниях, а стремиться к сфере личного постижения
            Татхагаты (<em>pratyātma-gati</em>).<a href="#ref-57" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-58"><sup>58</sup> <strong>«Радующийся различению природы
                ума, разума и сознания»</strong>
            (<em>cittamanomanovijñāna-svabhāva-viveka-rata</em>) — указывает на глубокое понимание
            структуры ума, лежащей в основе учения <em>йогачары</em>.</p>
        <p><em>Citta</em> — базовый ум, вместилище всех отпечатков (<em>васан</em>), тождественный
            <em>алайя-виджняне</em>.</p>
        <p><em>Manas</em> (<em>kliṣṭa-manas</em>) — омрачённое эго-сознание, цепляющееся за <em>алайя-виджняну</em>
            как за «я», порождая двойственность.</p>
        <p><em>Manovijñāna</em> — ментальное сознание, интерпретирующее данные чувств и порождающее
            понятийные построения (<em>викальпы</em>).</p>
        <p><em>Viveka</em> — «различение» — это не аналитическое разделение, это ясное видение их
            природы: все три — взаимозависимые аспекты единого потока сознания, лишённые
            самосущности.</p>
        <p><em>Rata</em> — «радующийся» — означает, что для Раваны это различение стало безусильным
            естественным состоянием. В этом — подлинная радость йогина: увидеть механизмы ума и
            более не быть ими обманутым.<a href="#ref-58" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-59"><sup>59</sup> <strong>«Прекративший тройственную
                непрерывность видимого»</strong>
            (<em>trisaṃtati-vyavacchinna-darśana</em>) — разрыв с механизмами, порождающими иллюзию
            сансарического опыта.</p>
        <p><em>Trisaṃtati</em> — «три потока преемственности»: поток причин (кармические отпечатки,
            <em>васаны</em>), поток объектов (кажущаяся устойчивость внешнего мира), поток сознания
            (непрерывная цепь моментов различения). Эти три потока создают видимость времени, «я» и
            мира.</p>
        <p><em>Vyavacchinna</em> — «отсечённый» — означает, что Равана более не поддерживает эту
            преемственность своим цеплянием. Он не «останавливает» процессы, но перестаёт придавать
            им реальность.</p>
        <p>Его <em>darśana</em> — «видение» — теперь свободно от веры в непрерывность. Он видит
            явления такими, каковы они есть: мгновенными, лишёнными сущности, не связанными
            причинной цепью.</p>
        <p>Этот разрыв преображает его видение: сознание становится готовым к восприятию Дхармы,
            пребывающей вне всякой преемственности.<a href="#ref-59" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-60"><sup>60</sup> <strong>«Свободный от причинных воззрений
                тиртхиков»</strong> (<em>sarva-kāraṇa-tīrthya-vyapeta</em>)
            — указывает на отказ от поиска внешних причин мира.</p>
        <p>Тиртхики объясняют существование через первопричины, лежащие вне сознания: Бога-творца,
            первоматерию, атомы или время.</p>
        <p>С точки зрения <strong>Ланкаватары</strong>, такие воззрения — заблуждение, ибо мир не
            имеет внешней опоры: всё видимое есть лишь проявления ума (<em>citta-mātra</em>), не
            существующие независимо от сознания.</p>
        <p><em>Vyapeta</em> — «ушедший за пределы» — означает, что Равана более не цепляется за идеи
            первопричин. Он не отвергает их логически, но просто видит их ненужность. И в этом
            заключён переход от философствования к йогическому видению: вопросы о «начале» теряют
            смысл, когда ум покоится в том, что есть.<a href="#ref-60" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-61"><sup>61</sup> <strong>«Вошедший во внутреннюю сферу
                Татхагатагарбхи»</strong> (<em>tathāgatagarbha-adhyātma-samāpanna</em>)
            — указывает на прямое постижение природы ума, в которой уже присутствует полнота качеств
            Будды.</p>
        <p><em>Tathāgatagarbha</em> — «зародыш Татхагаты» — чистая природа сознания, не затронутая
            омрачениями, хотя и скрытая ими.</p>
        <p><em>Adhyātma</em> — «внутреннее» — означает, что Равана обнаружил источник Дхармы в
            глубинной основе собственного ума.</p>
        <p><em>Buddhabhūmi</em> — «ступени Будды» — уровни, на которых эта природа проявляется без
            помех. Постижение их внутренней природы знаменует, что Равана осознал: разделение между
            «обычным существом» и «Буддой» — иллюзия, порождённая омрачениями.</p>
        <p>Это завершает подготовку Раваны: его ум настроен на ту же глубину постижения, что и ум
            Татхагаты, что делает его способным воспринять учение о <em>pratyātma-gati</em> — пути,
            постигаемом лично.<a href="#ref-61" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-62"><sup>62</sup> <strong>«Утвердившийся в мудрости
                Будды»</strong> (<em>sthita-buddha-buddhi</em>)
            — состояние, в котором разум йогина устойчиво пребывает в постижении природы мудрости
            Будды.</p>
        <p><em>Buddhi</em> — здесь высшая познавательная способность, свободная от сомнений,
            колебаний и понятийных искажений.</p>
        <p><em>Sthita</em> — «утвердившийся» — означает, что прозрение Раваны перестало быть
            мимолётным и стало его естественным состоянием.</p>
        <p>Это постижение того, что его собственный ум — по природе уже мудрость Будды (<em>tathāgatagarbha</em>),
            лишь временно скрытая омрачениями (вспоминаем Уттаратантру Майтреи).</p>
        <p>Так завершается подготовку Раваны: его разум устойчиво направлен на постижение той же
            таковости (<em>tathatā</em>), что полностью реализована Учителем, — и потому он готов
            воспринять Дхарму в её полной глубине.<a href="#ref-62" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-63"><sup>63</sup> <strong>«Звук, постигаемый лишь
                внутренне»</strong> (<em>adhyātma-vedya-śabda</em>)
            — указывает, что наставление не было внешним явлением, воспринимаемым ушами, а возникло
            непосредственно в сознании Раваны.</p>
        <p><em>Gagana</em> — «небо» — в буддийской символике означает природу ума, лишённую помех,
            подобно чистому пространству. Звук, «раздающийся из неба», — выражение мудрости,
            возникающей из самой чистоты сознания.</p>
        <p><em>Adhyātma-vedya</em> — «постигаемое внутренне» — означает, что Равана воспринял это
            наставление как прямое узнавание истины.</p>
        <p>Этот момент знаменует переход к <em>pratyātma-vedya</em> — личному постижению,
            недоступному передаче. Голос из пространства — проявление Дхармы, ставшее возможным
            потому, что ум Раваны более не цепляется за внешние объекты и понятия. Это — звук
            тишины, слышимый только тогда, когда умолкает <em>викальпа</em>.<a href="#ref-63"
                                                                               class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-64"><sup>64</sup> <strong>«Воззрение полного
                прекращения»</strong>
            (<em>uccheda-dṛṣṭi</em>) — одна из двух фундаментальных крайностей, отвергаемых Буддой;
            другая — «воззрение вечности» (<em>śāśvata-dṛṣṭi</em>).</p>
        <p><em>Uccheda</em> — «полное прекращение» — это нигилистическое воззрение, согласно
            которому после разрушения формы ничто не остаётся: ни сознания, ни кармы, ни возможности
            пробуждения.</p>
        <p>Эта ошибка возникает, когда йогин, постигая <em>śūnyatā</em>, отрицает не только
            самосущность явлений, но и само условное проявление ума. Он принимает <em>śūnyatā</em>
            за ничто, а не за отсутствие воображаемого «я» и «внешнего».</p>
        <p>Такое воззрение становится новой опорой (<em>āśraya</em>) для цепляния — уже не за
            «бытие» (<em>bhāva</em>), а за «небытие» (<em>abhāva</em>). Оно не ведёт к освобождению,
            но удерживает ум в сансаре под видом отречения.</p>
        <p>Истинное видение — срединный путь (<em>madhyamā-pratipad</em>): дхармы по природе не
            имеют сущности (<em>niḥsvabhāva</em>), но не лишены условного проявления (<em>saṃvṛti-satya</em>).
            Именно это видит Равана — и потому избегает обеих крайностей.<a href="#ref-64"
                                                                            class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-65"><sup>65</sup> <strong>«Оставив ум (citta), разум (manas)
                и различающее сознание
                (manovijñāna)»</strong> — указание на необходимость выйти за пределы трёх уровней
            сансарического сознания.</p>
        <p><em>Citta</em> (ум) — здесь означает <em>алайя-виджняну</em>, хранилище кармических
            отпечатков (<em>васан</em>), из которого возникает иллюзия непрерывности.</p>
        <p><em>Manas</em> (<em>манас</em>) — седьмое сознание (<em>kliṣṭa-manas</em>), цепляющееся
            за <em>алайю</em> как за «я» и порождающее двойственность.</p>
        <p><em>Manovijñāna</em> (<em>мановиджняна</em>) — шестое сознание, функция которого —
            понятийное различение (<em>vikalpa</em>): оно проецирует разделение на «субъект» и
            «объект», «внутреннее» и «внешнее».</p>
        <p>«Оставить» их — значит перестать принимать их проявления за реальность.<a href="#ref-65"
                                                                                     class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-66"><sup>66</sup> <strong>«Созерцание, падшее в сферу
                шраваков, пратьекабудд и
                тиртхиков»</strong> — указание на состояния, в которых сохраняется тонкая
            привязанность к опорам.</p>
        <p><em>Patita</em> — «упавшее» — означает, что созерцание, несмотря на глубину,
            останавливается на промежуточном уровне и не достигает недвойственности.</p>
        <p>Шраваки и пратьекабудды стремятся к освобождению через отрицание «я», но продолжают
            принимать дхармы как реальные или стремятся к личному покою (<em>nirvāṇa</em>), а не к
            буддовости ради всех существ. Их путь — личное упокоение, а не сострадательное
            пробуждение.</p>
        <p>Тиртхики ищут истину во внешних началах — Боге, душе, материи — и потому их созерцание
            опирается на двойственность с самого начала.</p>
        <p><em>Gocara</em> — «сфера» или «область деятельности» — здесь означает умственный
            горизонт, в котором ум пасётся. Будда предостерегает, что даже глубокое самадхи
            становится «падшим», если оно не выходит за пределы всех опор.</p>
        <p>Путь махайогина — без пристанища: он не ищет покоя для себя, но остаётся в мире ради
            блага всех существ, не цепляясь ни за освобождение, ни за созерцание — это <em>apratiṣṭhita-nirvāṇa</em>
            (нирвана без опоры).<a href="#ref-66" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-67"><sup>67</sup> <strong>«Не следует быть поглощённым
                историями и преданиями»</strong> (<em>ākhyāyiketihāsa-rata</em>)
            — предостережение против привязанности к описательному эпическому знанию.</p>
        <p><em>Ākhyāyika</em> — повествования, легенды, дидактические рассказы; <em>itihāsa</em> —
            эпические сказания, представляемые как «так оно и было». Такие тексты, даже если они
            мудры, укореняют ум во времени, пространстве и личной истории — сфере <em>vikalpa</em>,
            где всё расчленено на «героя», «событие» и «смысл».</p>
        <p><em>Rata</em> — «поглощённый» — указывает на наслаждение самим процессом слушания,
            которое отвлекает от непосредственного видения.</p>
        <p>Для Раваны — существа, чья фигура уже вплетена в мифы, — это наставление особенно важно:
            истинное пробуждение требует отказа от отождествления с любой историей, включая
            собственную.</p>
        <p>Путь йогина — не в том, чтобы знать больше историй, а в том, чтобы пребывать там, где
            истории исчезают: в недвойственности (<em>advaya</em>), за пределами прошлого,
            настоящего и будущего.<a href="#ref-67" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-68"><sup>68</sup> <strong>«Не следует держаться воззрения о
                самобытной природе»</strong>
            (<em>svabhāva-dṛṣṭi</em>) — указание на корневое заблуждение, лежащее в основе всей
            сансары.</p>
        <p><em>Svabhāva</em> — «собственное бытие» — есть убеждённость в том, что явления существуют
            сами по себе, независимо от условий и сознания.</p>
        <p>С точки зрения <strong><em>Ланкаватары</em></strong>, такое воззрение — иллюзия, порождённая
            понятийным различением (<em>vikalpa</em>): ум принимает временные проявления за
            устойчивые сущности.</p>
        <p>Если дхармы обладали бы <em>svabhāva</em>, они не могли бы возникать, меняться или
            исчезать — и потому не могли бы быть проявлениями сознания.</p>
        <p>Отказ от <em>svabhāva-dṛṣṭi</em> — фундамент постижения, которое постепенно углубляется
            на пути бодхисаттвы: ум перестаёт цепляться за формы и видит их такими, каковы они есть
            — лишёнными самосущности (<em>niḥsvabhāva</em>), но проявляющимися условно (<em>saṃvṛti-satya</em>).<a
                href="#ref-68" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-69"><sup>69</sup> <strong>«Не следует подпадать под
                опьянение властью и
                господством»</strong> (<em>rājādhipatya-mada</em>) — предостережение против цепляния
            за социальный статус как за реальность.</p>
        <p><em>Mada</em> — «опьянение» — это высокомерие, возникающее, когда ум принимает внешние
            знаки власти за подтверждение собственной значимости.</p>
        <p>Для Раваны, владыки Ланки и повелителя ракшасов, это искушение особенно велико: его
            могущество — видимое, осязаемое, воспетое в преданиях.</p>
        <p>Но с точки зрения <strong><em>Ланкаватары</em></strong>, всякая власть — условна (<em>pratītya-samutpanna</em>),
            ибо основана на двойственности: «я — правитель», «они — подданные». Такое разделение
            укрепляет <em>manas</em>, цепляющийся за «я», и разрушает состояние <em>avikalpa</em> —
            недвойственного пребывания.</p>
        <p>Истинное господство — в независимости от всех форм признания, включая царский титул.
            Отказ от <em>mada</em> — условие того, чтобы власть не порабощала того, кто ею обладает.<a
                href="#ref-69" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-70"><sup>70</sup> <strong>«Не следует ограничиваться
                медитацией шести дхьян»</strong>
            (<em>ṣaḍdhyānādidhyāyin</em>) — указание на то, что даже глубокие состояния
            сосредоточения не являются освобождением, если в них сохраняется разделение на
            «созерцающего» и «созерцаемое».</p>
        <p>Шесть <em>дхьян</em> — ступени умственного успокоения, общие для многих традиций, включая
            учения тиртхиков. Они приносят покой, ясность и блаженство, но не устраняют корень
            двойственности.</p>
        <p>Практикующий может принять эти состояния за <em>nirvāṇa</em>, не замечая, что «я,
            пребывающий в <em>дхьяне</em>» — всё ещё иллюзия, поддерживаемая <em>manas</em>.</p>
        <p>Такое цепляние препятствует освобождению: пока сохраняется «субъект опыта», ум остаётся в
            тонкой двойственности.</p>
        <p>Путь махайогина в том, чтобы распознавать природу ума во всех состояниях — до, во время и
            после <em>дхьяны</em>.</p>
        <p>Истинная йога Махаяны — прекращение самого различения, которое создаёт и «<em>дхьяну</em>»,
            и «обычное состояние».<a href="#ref-70" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-71"><sup>71</sup> <strong>«Искусный в тончайшем повороте
                сознания»</strong> (<em>sūkṣma-abhivijñāna-parāvṛtti-kuśala</em>)
            — качество бодхисаттвы, способного распознавать и устранять тончайшие движения
            двойственности в самом акте познания.</p>
        <p><em>Sūkṣma</em> — «тонкий» — означает, что речь идёт о первичном импульсе двойственности,
            возникающем до всякой концепции, раньше грубых мыслей и эмоций.</p>
        <p><em>Abhivijñāna</em> — «различающее знание» — обозначает акт осознавания в его самом
            начале, до разделения на «познающего» и «познаваемое».</p>
        <p><em>Parāvṛtti</em> — «поворот» — это разворот ума от проекции внешнего мира к
            распознаванию своей собственной природы.</p>
        <p><em>Kuśala</em> — «искусный» — указывает на мастерство бодхисаттв в этой практике: они
            способны уловить момент возникновения двойственности и повернуть ум к его истинной
            природе до того, как <em>викальпа</em> (построение понятий) затвердеет в воззрение.</p>
        <p>Эта искусность отличается от полной <em>āśraya-parāvṛtti</em> (поворота основы), которая
            происходит при буддовости, когда восемь виджнян окончательно трансформируются в
            мудрости. Здесь речь о практике, ведущей к этой цели: бодхисаттва тренируется
            распознавать и устранять тончайшую двойственность, подготавливая ум к окончательному
            повороту.</p>
        <p>Тот, кто овладел этой искусностью, видит корень всех ошибочных воззрений (<em>dṛṣṭi</em>):
            они рождаются из нераспознанного <em>manas</em>, цепляющегося за «я». Великий йогин
            потому не вступает в споры — его видение само рассеивает заблуждения, подобно тому, как
            свет рассеивает тьму.<a href="#ref-71" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-72"><sup>72</sup> <strong>«Цепляются за «я» и признаки
                видимого»</strong> (<em>ātmagrāha-dṛśya-lakṣaṇa-abhiniviṣṭa</em>)
            — принимают «я» и видимые объекты как действительно существующие и самодостаточные.<a
                href="#ref-72" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-73"><sup>73</sup> <strong>«Следуют за элементами, их
                качествами и субстанциями»</strong>
            (<em>bhūta-guṇa-dravya-anucārin</em>) — верят в материальные субстанции и качества
            как в нечто объективно существующее.<a href="#ref-73" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-74"><sup>74</sup> <strong>«Укоренены в воззрениях,
                порождённых неведением»</strong> (<em>avidyā-pratyaya-dṛṣṭi-abhiniveśa</em>)
            — мировоззрение основано на неведении и поддерживает дальнейшие заблуждения.<a
                href="#ref-74" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-75"><sup>75</sup> <strong>«Рассеяны представлением, что
                пустота «возникает»»</strong>
            (<em>śūnyatā-utpāda-vikṣipta</em>) — запутались в понимании возникновения из пустоты:
            ошибочно полагают, что <em>śūnyatā</em> — это субстанция, которая возникает и исчезает,
            а не отсутствие самосущности всех явлений.<a href="#ref-75" class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-76"><sup>76</sup> <strong>«Погружены в различения»</strong>
            (<em>vikalpābhiniviṣṭa</em>)
            — их мышление создаёт искусственные понятия и они принимают свои умственные построения
            за реальность.<a href="#ref-76" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-77"><sup>77</sup> <strong>«Упали в двойственность
                обозначаемого и признака»</strong>
            (<em>lakṣya-lakṣaṇa-patita</em>) — они разделяют реальность на «объект» и «его признаки»
            и принимают оба за действительно существующие, не понимая их умственной природы.<a
                href="#ref-77" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-78"><sup>78</sup> <strong>«Ведёт к обретению вселенской
                формы»</strong> (<em>viśvarūpa-gati-prāpaka</em>)
            — способность постигать все формы как проявления ума, лишённые самосущности и
            независимого существования.<a href="#ref-78" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-79"><sup>79</sup> <strong>«Пробуждает непосредственное
                постижение собственного
                пути»</strong> (<em>svapratyātmagati-bodhaka</em>) — прямое знание пути, а не
            принятые на веру учения или логические построения.<a href="#ref-79"
                                                                 class="citation-back">↩</a></p>
        <p class="my-2" id="citation-80"><sup>80</sup> <strong>«Ведёт к обретению высших ступеней
                (bhūmi)»</strong> (<em>viśeṣa-bhava-upapatti</em>)
            — здесь освоение всё более глубоких уровней реализации, соответствующих стадиям
            бодхисаттв (bhūmi).<a href="#ref-80" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-81"><sup>81</sup> <strong>«Прекращает волны различных
                виджнян»</strong> (<em>vividhavijñāna-taraṅga-vyāvartaka</em>)
            — устраняет волны различных <em>виджнян</em>, приводя сознание к естественной
            неподвижности, в которой прекращаются колебания восприятия, памяти, различения и
            кармических отпечатков.<a href="#ref-81" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-82"><sup>82</sup> <strong>«Кто открывает внутреннюю область
                личного постижения»</strong> (<em>pratyātma-gati-gocara-udbhāvaka</em>) — Будда
            не передаёт учение как внешний
            объект. Он раскрывает то, что уже присутствует в самом йогине.</p>
        <p><em>Pratyātma</em> — «личное», «непосредственное» — это постижение недоступно через
            логику, авторитет или заимствование.</p>
        <p><em>Gati</em> — «путь» — здесь это не движение от точки к точке, подразумевается способ
            пребывания ума в недвойственном постижении.</p>
        <p><em>Gocara</em> — «область» — поле опыта, в котором нет разделения на познающего и
            познаваемое.</p>
        <p><em>Udbhāvaka</em> — «раскрывающий» — подчёркивает, что Будда не создаёт эту сферу, Он
            устраняет завесы, мешающие её видению.</p>
        <p>Таким образом, истинная Дхарма распознаётся, а не сообщается.<a href="#ref-82"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-83"><sup>83</sup> <strong>«Чьё знание свободно от
                сотворённого и чудесных
                проявлений»</strong> (<em>nairmita-nairmāṇika-vyapeta adhigama-buddhiḥ</em>) —
            указывает, что подлинное постижение не связано с созданием форм, состояний или эффектов.
        </p>
        <p><em>Nirmita</em> — «сотворённое» — всё, что искусственно сконструировано умом: понятия,
            явления, даже священные образы, принимаемые за предмет постижения.</p>
        <p><em>Nairmāṇika</em> — «чудесные проявления» — относится к магическим проявлениям, которые
            в индийской традиции часто считались признаком духовной силы.</p>
        <p><em>Vyapeta</em> — «свободный от» — подчёркивает, что знание Татхагаты не опирается ни на
            создание, ни на проявление.</p>
        <p>Это — <em>adhigama-buddhi</em>: непосредственное постижение, возникающее без опоры на
            произведённое или проявленное.</p>
        <p>Это знание достигает совершенства при <em>āśraya-parāvṛtti</em> (повороте основы сознания
            при буддовости): когда ум окончательно освобождается от привязанности к «сотворённому»,
            становится видимым то, что изначально присутствует, но не нуждается в оформлении.</p>
        <p>Пробуждение потому не принадлежит сфере чудес, даже священных и почитаемых. Это — прямое
            внутреннее знание, не требующее подтверждения через явление, действие или форму.<a
                href="#ref-83" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-84"><sup>84</sup> Термин <strong>«йогин»</strong> в
            <strong><em>Ланкаватаре</em></strong> применяется
            только к тому, кто достиг постижения (<em>adhigama</em>).</p>
        <p>Мудрость, о которой идёт речь, не передаётся заранее и не усваивается через обучение
            (<em>śruta-jñāna</em>) или размышление (<em>cintā-jñāna</em>).</p>
        <p>Она раскрывается единственно в момент непосредственного постижения, при вхождении во
            врата самадхи (<em>samādhi-mukha</em>), когда умолкает умственное различение (<em>vikalpa</em>)
            и становится доступной внутренняя область личного постижения
            (<em>pratyātma-gati</em>).<a href="#ref-84" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-85"><sup>85</sup> <strong>«Свободный от признаков
                действия»</strong> (<em>kriyā-lakṣaṇa-vinivṛtta</em>)
            означает, что Татхагата не обладает характеристиками деятеля (<em>kartṛ</em>): у него
            нет намерения, усилия, цели или идеи «я действую».</p>
        <p>Его проявление — не действие в обыденном смысле (<em>kriyā</em>), это спонтанное
            раскрытие мудрости (<em>anābhoga</em> — безусильность), не порождающее кармических
            отпечатков.<a href="#ref-85" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-86"><sup>86</sup> <strong>«Не колеблется в нерождённости
                дхарм»</strong> (<em>anutpattika-dharma-kṣānti</em>)
            — означает отсутствие внутреннего смятения, когда раскрывается: ни одна дхарма никогда
            не возникала как самостоятельная сущность.</p>
        <p><em>Kṣānti</em> здесь — не психологическая устойчивость и не усилие по удержанию
            состояния. Это — естественная невозмутимость, в которой нет страха, ожидания или
            сомнения относительно бытия дхарм.</p>
        <p>В этом распознавании нет различия между видящим и видимым и нерождённость
            (<em>anutpāda</em>) здесь — это само прекращение двойственности. Достижение <em>anutpattika-dharma-kṣānti</em>
            — признак 8-й бхуми (<em>Ачала</em>, «Недвижимая») или выше, где бодхисаттва становится
            <em>anivartanīya</em> (необратимым). Будда видит, что Равана достиг этого постижения,
            что делает его готовым к глубокой Дхарме.<a href="#ref-86" class="citation-back">↩</a>
        </p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-87"><sup>87</sup> <strong>«Взор мудрости»</strong>
            (<em>buddhi-cakṣus</em>) — видение
            без разделения на субъект и объект, в отличие от плотского ока/обычного зрения
            (<em>māṃsa-cakṣus</em>).<a href="#ref-87" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-88"><sup>88</sup> <strong>«Великий смех»</strong>
            (<em>mahāhāsa</em>) — спонтанное
            выражение недвойственной радости, в которой нет страх перед шуньятой.<a
                href="#ref-88" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-89"><sup>89</sup> <strong>«Лучи из пор тела»</strong> —
            символ всепроникающего
            присутствия мудрости, не ограниченной физической формой.<a href="#ref-89"
                                                                       class="citation-back">↩</a></p>
        <p class="my-2" id="citation-90"><sup>90</sup> <strong>«Собственное внутреннее
                благородное знание»</strong> (<em>sva-pratyātma-ārya-jñāna</em>)
            — знание, недоступное через слова, раскрывающееся только в непосредственном опыте (<em>pratyātma-vedya</em>).<a
                href="#ref-90" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-91"><sup>91</sup> <strong>«Размышлял»</strong>
            (<em>anuvicintayamāna</em>) — прямое восприятие йогического пути Раваны без посредничества
            понятий.<a href="#ref-91" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-92"><sup>92</sup> <strong>«Смятение ума»</strong>
            (<em>citta-vibhrama</em>) — состояние недоумения,
            переживание потрясения основ веры, когда внешнее проявление Будды
            (смех) противоречит представлению о Нём как о бесстрастном.<a href="#ref-92"
                                                                          class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-93"><sup>93</sup> <strong>«Цепляются за буквальный
                смысл»</strong>
            (<em>yathāruta-artha-abhiniviṣṭa</em>) —
            принимают звуки слов за истину, не видя, что слова — лишь
            указатели.<a href="#ref-93" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-94"><sup>94</sup> <em>Traikālya</em> — «трёх времён» (прошлое, настоящее, будущее); указывает, что ложные воззрения (<em>dṛṣṭi</em>) одинаковы во все эпохи, и ответ Будды актуален всегда. <em>Svaparobhayārtha</em> — «ради блага себя, других и обоих»: три мотива действия в буддийской этике — <em>svārtha</em> (ради себя), <em>parārtha</em> (ради других) и <em>ubhayārtha</em> (ради обоих). Последний — недвойственный мотив бoдхисаттвы, где разделение между «я» и «другой» преодолено, и благо себя и других нераздельно, как вода и волны единого океана.<a href="#ref-94" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-95"><sup>95</sup> <strong>«Два вопроса»</strong> —
            «Существуют ли дхармы?» и «Не существуют ли
            дхармы?» — корень всех философских заблуждений. Их отвержение —
            вход в недвойственность.<a href="#ref-95" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-96"><sup>96</sup> <strong>«Преобразивший опору различающего
                мышления»</strong>
            (<em>parāvṛtta-vikalpāśraya</em>) — состояние поворота основы
            (<em>āśraya-parāvṛtti</em>), в котором исчезает действие <em>vikalpa</em>.<a
                href="#ref-96" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-97"><sup>97</sup> <strong>«Проницательная мудрость
                различения»</strong>
            (<em>pravicaya-buddhi</em>) —
            мудрость, распознающая, что за двойственностью нет никакой сущности,
            есть только игра ума. Она ведёт к прямому видению таковости.<a href="#ref-97"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-98"><sup>98</sup> <strong>«Ступени Ачала, Садхумати,
                Дхармамегха»</strong> —
            8-я, 9-я и 10-я земли/степени/ступени/бхуми бодхисаттвы, где проявляются соответственно:
            непоколебимость в недвойственности,
            совершенное мастерство в проповеди,
            излияние мудрости, как дождя, на всех существ.<a href="#ref-98"
                                                             class="citation-back">↩</a></p>
        <p class="my-2" id="citation-99"><sup>99</sup> <strong>Маха-ратна-падма-вимана</strong>
            (<em>mahā-ratna-padma-vimāna</em>) —
            «великий драгоценный чертог на лотосе» (<em>вимана</em> — также «дворец»
            или «небесная колесница»). Это высшая форма проявления пробуждённого ума.
            Описание <strong>мандалы</strong>, структуры, характерной для тантрической визуализации,
            но здесь представленной в <strong>сутрическом контексте</strong>.<a href="#ref-99"
                                                                                class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-100"><sup>100</sup> <strong>«Множество [своих] тел, явленных
                силой твоего собственного ума»</strong> —
            эта фраза имеет множество параллелей с другими текстами Махаяны:
            <em>Праджняпарамитой</em> (<strong><em>Хридая-сутра</em></strong>),
            <strong><em>Аватамсака-сутрой</em></strong>, а также с более поздними текстами тантры
            (структура мандалы, визуализация идама и его окружения).
            Если парадокс «ни единства, ни множественности» в <strong><em>Хридае</em></strong> и
            «один содержит всё, всё содержит одно, один в одном, всё во всём» в
            <strong><em>Аватамсаке</em></strong> выражается
            текстуально, то в <strong><em>Ланкаватаре</em></strong> это выражено образно-визуально:
            Равана видит это напрямую
            — множество тел, но нет "одного я"; один ум, но нет "единой субстанции". Этот парадокс
            разрешается только в прямом постижении шуньяты. Лотосы символизируют изначальную чистоту
            ума, не затронутую «грязью» измышлений (<em>vikalpa</em>): как лотос растёт из ила, но
            не загрязнён им, так и ум проявляется в сансаре, но по природе (<em>prakṛti</em>) сияюще
            чист.<a href="#ref-100" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-101"><sup>101</sup> <strong>«Узришь лики, взирающие друг на
                друга»</strong>
            (<em>anyonyavakramukhanirīkṣaṇa</em>) — если описывать в стиле тантры, то можно сказать,
            что Равана видит себя как центральное божество мандалы, окружённое множественными
            проявлениями самого себя. Это зримый символ недвойственности, где "я" растворяется в
            бесконечном взаимном созерцании; единое сознание проявляется как бесчисленные формы,
            каждая из которых одновременно субъект и объект созерцания. Предположу, что
            <strong><em>Ланкаватара</em></strong>
            — мост между сутрической философией и тантрической практикой визуализации.<a
                href="#ref-101" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-102"><sup>102</sup> Эта сфера опыта непостижима уму, который
            связан понятиями: её раскрывает тот, кто пребывает на ступени, вызывающей изумление
            свободой от кармической цепи «причина-следствие» благодаря спонтанному выражению
            сострадания, которое не имеет намерения, усилия или следа, через разнообразие форм.<a
                href="#ref-102" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-103"><sup>103</sup> <strong>«Многообразие форм ступени
                Татхагаты»</strong> — ступень Татхагаты (<em>tathāgata-bhūmi</em>) представляет
            собой состояние полного пробуждения, в котором проявление и шуньята нераздельны. Его
            сострадание естественно выражается в бесчисленных проявлениях ради блага всех существ.
            «Ступень» скорее всего, употреблена по аналогии со ступенями бодхисаттв, хотя то и
            принципиально иное бытие.<a href="#ref-103" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-104"><sup>104</sup> Брахма, Индра и Упендра (Вишну)
            символизируют три столпа сансары: творение, власть и сохранение космического порядка.
            Просветление Татхагаты превосходит их все — оно лежит вне самой структуры сансары, даже
            в её божественной форме.<a href="#ref-104" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-105"><sup>105</sup> <strong>Подъём на высоту семи
                пальм</strong> (<em>sapta tāla</em>) — возможно, символ полного превосхождения мира
            желаний (<em>kāmadhātu</em>). Подношение Раваны не ограничено ни одной сферой сансары:
            оно исходит из состояния, свободного от привязанности ко всем уровням условного
            существования.<a href="#ref-105" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-106"><sup>106</sup> <strong>Сцена подношения Раваны</strong>
            выражает его утверждённость на высших бхуми. Подъём с первой вершины, взлёт на высоту
            семи пальм и восседание на второй лотосовой вершине описывают выход за пределы мира
            желаний (<em>kāmadhātu</em>) и вхождение в сферу чистой земли (<em>buddha-kṣetra</em>),
            возникающей из преображённого ума. Подношения проявляются как естественное выражение
            ума, в котором устранено различие между дарящим, даром и получающим. Сам вопрос Раваны
            рождается из прозрения, и потому получает отклик Татхагаты в форме улыбки и
            дозволения.<a href="#ref-106" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
