        <p class="my-2" id="citation-116"><sup>116</sup> Суть вопроса: если все явления — продукт
            различающего мышления (<em>vikalpa</em>), лишённого собственной природы, то «оставление»
            не может быть актом отбрасывания объектов. Оно возможно только как узнавание того, что
            сам механизм различения изначально пуст (<em>śūnya</em>). Это не является достижением
            нового состояния, это прекращение веры в то, что дхармы существуют как объекты,
            подлежащие оставлению.<a href="#ref-116" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-117"><sup>117</sup> <strong>«Сфера различений невежд»</strong>
            (<em>bāla-vikalpa-gocara</em>) — здесь различение между дхармой и адхармой условно
            функционирует; кувшины, пламя, ветви воспринимаются как реально различные.<a
                href="#ref-117" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-118"><sup>118</sup> <strong>«Постижение благородного
                знания»</strong> (<em>Ārya-jñāna-adhigama</em>) — здесь различия не видны (<em>na
                darśana</em>), распознаётся единая природа всех явлений.<a href="#ref-118"
                                                                           class="citation-back">↩</a>
        </p>
        <p class="my-2" id="citation-119"><sup>119</sup> Метафоры огня и семени показывают, что
            единая природа (огонь, семя) — это <strong><em>парамартха-сатья</em></strong>
            (абсолютная истина); а многообразие проявлений (пламя, ветви) — это <strong><em>самврити-сатья</em></strong>
            (условная истина), возникающее в зависимости от условий (<em>indhanavaśāt</em> — «в силу
            топлива»).<a href="#ref-119" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-120"><sup>120</sup> <em>pratyātma-gati-lakṣaṇa</em><a
                href="#ref-120" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-121"><sup>121</sup> <em>prativikalpa-pravṛtti</em><a
                href="#ref-121" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-122"><sup>122</sup> <strong>«Причины, качества и
                субстанции»</strong> (<em>kāraṇa-guṇa-dravya</em>) — категории философии <em>вайшешики</em>
            и <em>ньяи</em>, согласно которым явления реально существуют как субстанции
            (<em>dravya</em>), обладающие качествами (<em>guṇa</em>) и порождаемые причинами (<em>kāraṇa</em>).
            <strong><em>Ланкаватара</em></strong> отвергает это овеществление: дхармы — не
            субстанции, а проекции ума (<em>svacitta-dṛśya</em>), лишённые собственного тела (<em>alabdha-śarīra</em>).<a
                href="#ref-122" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-123"><sup>123</sup>
            <em>svacitta-dṛśya-dharmatā-abhiniveśāt</em><a href="#ref-123"
                                                           class="citation-back">↩</a></p>
        <p class="my-2" id="citation-124"><sup>124</sup> <strong>«Уже отброшены»</strong> —
            оставление не есть действие, а результат видения (<em>vidarśana</em>). Как только
            распознано, что кувшин — лишь проекция (<em>svacitta-dṛśya</em>), он теряет статус
            «реального объекта» и тем самым «отброшен». Итак, если всё — <em>vikalpa</em>, и <em>vikalpa</em>
            пуст, как оставить? Оставить нужно не сами <em>vikalpa</em> (различения), а веру (<em>abhiniveśa</em>)
            в то, что они — внешняя реальность (<em>dharmatā</em>) через видение (<em>vidarśana</em>),
            что они — <em>svacitta-dṛśya</em> (лишь видимое умом). Как только узнано — они уже
            отброшены (<em>prahīṇa bhavanti</em>).<a href="#ref-124" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-125"><sup>125</sup> <em>alabdha-ātmaka</em><a href="#ref-125" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-126"><sup>126</sup> <em>lakṣaṇa-vikalpa-apracāra</em><a href="#ref-126" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-127"><sup>127</sup> <em>ahetuka</em><a href="#ref-127" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-128"><sup>128</sup> <strong>«Не-возникновение»</strong> (<em>Apravṛtti</em>) — или «отсутствие проявления». Термин указывает на статус объектов, которые, подобно «рогам зайца», никогда не возникали и не имеют причин для проявления. Их не-возникновение видится парадоксально (<em>bhūta-abhūtataḥ</em>): как существующее (<em>bhūta</em>) — поскольку мы говорим о нём, мыслим его; как несуществующее (<em>abhūta</em>) — поскольку его нет реально. Этот парадокс указывает на абсурдность попыток схватить (<em>grahaṇa</em>) такие "объекты" сознанием (<em>vijñāna</em>) или мыслить их через признаки (<em>lakṣaṇa</em>). Подобно рогам зайца, все проявления различающего мышления (<em>vikalpa-bhāva</em>) лишены сущности и не могут быть схвачены.<a href="#ref-128" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-129"><sup>129</sup> <em>na lakṣaṇataḥ kalpyāḥ</em><a href="#ref-129" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-130"><sup>130</sup> <em>saṃvyavahārārtham</em><a href="#ref-130" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-131"><sup>131</sup> <em>agrahaṇataḥ vijñānena</em><a href="#ref-131" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-132"><sup>132</sup> <em>vikalpa-bhāva</em><a href="#ref-132" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-133"><sup>133</sup> <strong><em>Visarjita</em></strong> — буквально «отпущенный» или «разрешённый». В контексте: прежние Будды ответили на этот вопрос (как делает сейчас Будда Шакьямуни), но сам вопрос порождён различением (<em>vikalpa</em>), и потому ответ не может быть окончательным в рамках различающего мышления. Истинное "разрешение" — выйти за пределы самого вопроса.<a href="#ref-133" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-134"><sup>134</sup> <strong>«Мыслительное разрастание»</strong> (<em>prapañca</em>) — самовоспроизводящийся поток ума, который, опираясь на различение (<em>vikalpa</em>), делит неделимое на противоположности — «я» и «не-я», «внутри» и «вне», «благо» и «неблаго» — и поддерживает это разделение через речь, имена и признаки. Этот поток создаёт видимость связного постигаемого мира, но при внимательном рассмотрении обнаруживает внутренние противоречия: одному и тому же объекту приписываются взаимоисключающие свойства — существующий и преходящий, единый и составной, реальный и иллюзорный. Так <em>prapañca</em> сама себя разрушает, обнажая свою безосновательность.<a href="#ref-134" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-135"><sup>135</sup> <strong>«Не полагают и не полагаемы»</strong> (<em>na kalpante na kalpyante</em>) — <em>kalpana</em> (от корня √<strong>kḷp</strong>) означает умственное действие установления чего-либо как реально существующего: например, «я» как субъект, «мир» как объект, «дхармы» как сущности. Татхагаты не осуществляют такого действия — они не принимают проекции ума за реальность, и их самих нельзя принять за объект подобного полагания, поскольку они лишены природы, доступной для различающего мышления (<em>vikalpa</em>).<a href="#ref-135" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-136"><sup>136</sup> Смотри примечание 7 в <strong><em>Ваджрачхедике</em></strong>.<a href="#ref-136" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-137"><sup>137</sup> <strong>«Вышедший за пределы различения и его отсутствия»</strong> (<em>vikalpāvikalpāgatena</em>) — имеется в виду, что освобождение не есть ни пребывание в различающем мышлении (<em>vikalpa</em>), ни фиксация/"замораживание ума" на его отсутствии (<em>avikalpa</em>). Истинное положение — вне обеих крайностей, ибо даже «отсутствие различения» становятся оковами, если ум цепляется за него как за достижение.<a href="#ref-137" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        <p class="my-2" id="citation-138"><sup>138</sup> <strong>«Фигуры на стене»</strong> (<em>bhittikhacitavigraha</em>) — метафора полной неподвижности сансары: всё «движение» — лишь иллюзия, порождённая умом, который придаёт жизнь мёртвым изображениям.<a href="#ref-138" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-139"><sup>139</sup> <strong>«Магическое изваяние»</strong> (<em>nirmitapratima</em>) — указание на автоматизм сансары: мир действует, как одушевлённая кукла, но в нём нет ни деятеля, ни живой души (<em>атмана</em>).<a href="#ref-139" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-140"><sup>140</sup> <strong><em>sva-vikalpa-grahaṇa</em></strong>. Здесь <em>grahaṇa</em> — «схватывание, захватывание» от корня √<strong>grah</strong> — «хватать, брать, захватывать». Ум «хватает» различения, принимает их за реальные объекты, держится за них и пленяется ими.<a href="#ref-140" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-141"><sup>141</sup> <strong>«Питают различения»</strong> (<em>vikalpayanti puṣṇanti</em>) — ум не только создаёт различения, но и поддерживает их вниманием и верой, делая их «реальными». Оставление — прекращение этого питания.<a href="#ref-141" class="citation-back">↩</a></p>
        <p class="my-2" id="citation-142"><sup>142</sup> <strong>«Покой»</strong> — обозначение единонаправленности (<em>ekāgratā</em>) — не концентрация на объекте, а возвращение ума к источнику, где различения затихают, и раскрывается Татхагатагарбха.<a href="#ref-142" class="citation-back">↩</a></p>
        <hr class="my-8 border-t-4 border-gray-500">
        </div>

       <p class="my-2" id="citation-143"><sup>143</sup> <strong>«Цветок в небе»</strong> (<em>khapuṣpa</em>) — традиционный буддийский образ невозможного, иллюзорного, не имеющего основы в реальности. Используется для обозначения явлений, лишённых собственной природы.<a href="#ref-143" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-144"><sup>144</sup> <strong>«Майя»</strong> (<em>māyā</em>) — иллюзия, мираж; в буддийском контексте — метафора нереальности, обманчивости обычного восприятия явлений, которые кажутся существующими, но лишены устойчивой сущности.<a href="#ref-144" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-145"><sup>145</sup> <strong>«Не удерживаются в категориях ума и различающего сознания»</strong> (<em>citta-vijñāna-varjitāḥ</em>) — буквально: «свободны от ума и различающего сознания». Однако здесь отрицается не существование сознания как такового, а возможность установить дхармы как независимый субъект (<em>citta</em>) или как самостоятельное содержание различающего сознания (<em>vijñāna</em>). Дхармы не фиксируются внутри двойственной схемы «познающий — познаваемое».<a href="#ref-145" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-146"><sup>146</sup> <strong>Употребление слова «всегда»</strong> (<em>sadā</em>) подчёркивает, что подобие мира сновидению не является временным состоянием или субъективной ошибкой отдельного существа. Призрачность и зависимый характер явлений рассматриваются как фундаментальная характеристика опыта.<a href="#ref-146" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-147"><sup>147</sup> Дхармакая по природе своей подобна майе и сновидению — она лишена любых устойчивых признаков. Именно поэтому её невозможно описать через утвердительные суждения: любое приписывание ей характеристик превращает безграничное в объект различения. Подлинная хвала (<em>stava</em>) Татхагате — прямое вхождение в недвойственное постижение шуньяты.<a href="#ref-147" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-147.1"><sup>147.1</sup> Строка «не-возникновение (<em>anutpāda</em>) и есть их возникновение (<em>saṃbhava</em>)» — прямое тождество без иерархии «истинного» над «ложным». Парадокс держится без оговорок: а) дхармы лишены собственной сущности (<em>niḥsvabhāva</em>) — их проявление всецело зависит от движения ума; б) с точки зрения высшей истины (<em>paramārtha</em>), принятие проявляемого за реальное рождение — признак омрачения (<em>kleśa</em>); в) «присутствие» дхармы раскрывается через постижение её изначального не-рождения. Так реальность видится тому, чей ум свободен от цепляния.<a href="#ref-147.1" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-148"><sup>148</sup> <em>Pratyātmagatigocaram</em> —область пути личного постижения. Будда обещает указать на то, что должно быть постигнуто непосредственно: сфера, недоступная через слова и логику.<a href="#ref-148" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-149"><sup>149</sup> <strong>«Умозрительное рассуждение» / «Различающее рассуждение»</strong> (<em>tarka</em>) и <strong>«заблуждение»</strong> (<em>bhrānti</em>): Махамати начинает с вопроса о механике ошибочного познания. <em>Тарка</em> понимается как линейное логическое мышление, зуд классифицирующего ума, умствование, умозрительная логика, строящая суждения о реальности через разделение субъекта и объекта; она сама является формой заблуждения (<em>bhrānti</em>), поскольку опирается на двойственность.<a href="#ref-149" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-150"><sup>150</sup> <strong>«Отсутствие [ментальных] образов» (<em>nirābhāsa</em>)</strong> — высшая стадия медитации, при которой ум перестаёт проецировать формы, образы и понятия. Вопрос Махамати касается способа (<em>kena</em>) и последовательности (<em>krama</em>) достижения этого состояния.<a href="#ref-150" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-151"><sup>151</sup> <strong>«Тройственное бытие»</strong> (<em>tribhava</em>): Мир желаний (<em>кама</em>), мир форм (<em>рупа</em>) и мир без форм (<em>арупа</em>). Махамати интересуется тем, кто способен «разрушить» эту структуру сансары.<a href="#ref-151" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-152"><sup>152</sup> <strong>«[Как ум] поворачивает от видимого»</strong>(<em>dṛśyān nivartate</em>) — буквально: «поворачивает от видимого, прекращает течь к видимому» (<em>ni-√vṛt</em> с падежом). Это прекращение устремлённости сознания к объектам — необходимое условие, предшествующее полному повороту основы (<em>āśraya-parāvṛtti</em>), но не тождественное ему. Вопрос Махамати — о том, каким образом это обращение ума происходит.<a href="#ref-152" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-153"><sup>153</sup> <strong>«Роды и без рода»</strong> (<em>gotra-agotra</em>): Этот вопрос Махамати рассматривается как запрос о духовной предрасположенности. <em>Готра</em> — это «семья» или «духовная предрасположенность» пробуждения. Махамати спрашивает, почему одни существа обладают потенциалом Будды, а другие (<em>аготра</em>) кажутся лишёнными его.<a href="#ref-153" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-154"><sup>154</sup> <strong>«Мгновенность распада»</strong> (<em>kṣaṇa-bhaṅga</em>) — «мгновенный распад»; доктрина, которую <strong><em>Ланкаватара-сутра</em></strong> критикует как недостаточно глубокую. В то время как ранние школы (школы никаи) используют идею моментального разрушения дхарм для отрицания постоянства «я», <strong><em>Ланкаватара</em></strong> видит в этом скрытый реализм: чтобы нечто «разрушилось», оно должно сначала «возникнуть». С позиции недвойственности Будда указывает, что дхармы не «мгновенны», они изначально не рождены (<em>anutpāda</em>). Если объект — лишь проекция ума (<em>svacitta-dṛśya</em>), то у него нет даже мгновения реального бытия, чтобы претерпеть распад. Таким образом, идея мгновенности отвергается ради более радикального постижения: мир не «быстро меняется», он никогда не возникал вне различающего ума.<a href="#ref-154" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-155"><sup>155</sup> <strong>Нирихика</strong> (<em>nirīhika</em>) — «безусильность» или «отсутствие воления». Термин указывает на то, что мир функционирует без внешнего творца-управителя (<em>īśvara</em>) и без внутреннего субъекта-деятеля (<em>kartṛ</em>). Космос в <strong><em>Ланкаватаре</em></strong> описывается как процесс, лишенный волевого импульса; он разворачивается спонтанно (<em>sahaja</em>), подобно магической иллюзии или отражению. Постижение мира как <em>nirīhika</em> означает осознание того, что за потоком явлений не стоит никакая основополагающая воля. Для бодхисаттвы это становится основой безусильного действия (<em>anabhisaṅkhāra</em>): когда устраняется иллюзия «деятеля», поступки перестают порождать кармическую связь, превращаясь в свободную игру мудрости.<a href="#ref-155" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-156"><sup>156</sup> <strong>«Изложение без букв»</strong> (<em>nirakṣara</em>): Прямая отсылка к знаменитому утверждению <strong><em>Ланкаватары</em></strong> о том, что истинная Дхарма не может быть передана буквами (<em>акшара</em>). Махамати просит разрешить парадокс: как Будда учит, если истина безмолвна?<a href="#ref-156" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-157"><sup>157</sup> <strong>«Два вида отсутствия "я"»</strong> (<em>nairātmyaṃ dvidhā</em>): Махамати имеет в виду отсутствие «я» в личности (<em>pudgala-nairātmya</em>) и отсутствие «я» дхарм (<em>dharma-nairātmya</em>).<a href="#ref-157" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-158"><sup>158</sup> <strong>«Очищение познаваемого»</strong> (<em>jñeya-viśuddhi</em>) — этот вопрос касается устранение <em>джнея-авараны</em> (<em>jñeya-āvaraṇa</em>), или «завесы познаваемого». В отличие от «завесы клеш» (<em>клеша-аварана</em>), порождающей личное страдание, завеса познаваемого — это тончайшее интеллектуальное препятствие, мешающее всеведению Будды. Она заключается в самой привычке ума разделять реальность на «познающего» и «познаваемое», наделяя объекты ложной плотностью и внешней независимостью. Фраза <em>jñeyaṃ viśudhyati</em> означает, что когда ум перестает проецировать двойственность, «объект» познания очищается от наслоений понятийной ложности. В этот момент мир перестает восприниматься как совокупность внешних явлений и раскрывается в своей истинной природе как <em>татхата</em> (таковость), что делает возможным достижение недвойственного всеведения.<a href="#ref-158" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-159"><sup>159</sup> <strong>«Лишь именование»</strong> (<em>prajñapti-mātra</em>) — технический термин, указывающий на условный статус всех явлений. Согласно <strong><em>Ланкаватаре</em></strong>, проявленный мир возникает тогда, когда ум, движимый привычкой различения, наделяет именами (<em>nāma</em>) фрагменты потока опыта. Эти имена создают видимость устойчивых и независимых объектов, хотя за ними нет неизменной основы. Постичь, что всё есть «лишь именование», — значит увидеть, что сознание взаимодействует не с самостоятельными явлениями, а с проекциями собственного ума, закреплёнными в языке. Такое постижение ослабляет цепляние к формам, поскольку йогин распознаёт, что за именами скрывается таковость (<em>tathatā</em>) — недвойственная, не имеющая границ, признаков или определений. Иными словами: мир — это игра имён, лишённая автора.<a href="#ref-159" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-160"><sup>160</sup> <strong>«Иччхантика»</strong> (<em>icchantika</em>) — термин, обозначающий существ, кажущихся лишёнными стремления к пробуждению. Это рассматривается двояко.  Иччхантики по омрачению — это те, чьи корни благого (<em>kuśala-mūla</em>) истощены вследствие тяжких проступков против Дхармы. Их ум настолько омрачён, что они не проявляют стремления к освобождению. Иччхантики по состраданию — великие бодхисаттвы, давшие обет не входить в окончательную нирвану, пока не освободится последнее существо. Поскольку круговорот существования бесконечен, они добровольно остаются в мире рождения-и-смерти не из-за кармы, а из безмерного сострадания. Однако на абсолютном уровне никто не лишён природы Будды. Учение об «иччхантике» выступает как искусное средство (<em>upāya</em>), побуждающее страшиться омрачений и отвернуться от разрушительных состояний ума. В свете учения о Татхагатагарбхе состояние иччхантики не является вечным: оно продолжается лишь до тех пор, пока действует различающее мышление (<em>vikalpa</em>), скрывающее изначальную чистоту сознания. Даже в этом состоянии природа Будды остаётся незатронутой, подобно золоту, покрытому грязью.<a href="#ref-160" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-161"><sup>161</sup> <strong>«Знаки и признаки в уходах и рождениях»</strong> — это вопрос о механизме кармической преемственности. Под «знаком» (<em>liṅga</em>) понимается скрытая потенция — семя в <em>Алайя-виджняне</em>, определяющее направление следующего перерождения. Под «признаком» (<em>lakṣaṇa</em>) — внешние проявления: форма тела, речь, поведение, в которых отражаются прошлые склонности и закладываются условия будущего. В свете йогачары, однако, нет никакого «существа», переходящего из жизни в жизнь. Есть лишь поток отпечатков (<em>vāsanā-prabandha</em>), который, подобно магниту, притягивается к соответствующим условиям. Постичь эти «знаки» — значит увидеть, как ум связывает мгновения опыта в иллюзию непрерывного «я», хотя на самом деле между смертью и рождением нет ни субъекта, ни преемника — только движение различения (<em>vikalpa</em>), лишённое опоры.<a href="#ref-161" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-162"><sup>162</sup> <strong>Риши Диргхатапас</strong> (<em>Dīrghatapas</em>, букв. «совершающий длительные аскезы») — имя или эпитет, встречающийся в различных индийских религиозных традициях. В буддийских источниках известен аскет Дигха Тапасси (<em>Dīgha Tapassī</em>), связанный с джайнской средой и упоминаемый в палийских суттах как участник споров о природе кармы и действия. В индуистской литературе имя Диргхатапас носили различные риши и подвижники, тогда как схожее имя <em>Dīrghatamas</em> («долгий мрак») принадлежит знаменитому ведическому мудрецу — автору гимнов <strong><em>Ригведы</em></strong>, прославившемуся своими загадочными и мистическими стихами.</p>
        <p class="my-2">В позднейшей индийской традиции фигуры Диргхатапаса и Диргхатамаса нередко сближаются или смешиваются. С Диргхатамасом связывают мотив внутреннего зрения: согласно ряду преданий, он был слепым, но обладал духовным прозрением. Ему приписывают знаменитое ригведийское изречение: <em>«Истина едина, мудрецы называют её различными именами»</em> (<em>ekaṃ sad viprā bahudhā vadanti</em>). Однако в контексте <strong><em>Ланкаватары</em></strong> это упоминание важно не как историческая ссылка на конкретного мудреца, а как постановка вопроса о происхождении знания, откровения и духовного авторитета.</p>
        <p class="my-2">Махамати спрашивает: откуда возникают учения, искусства, науки, прозрения риши и сами формы духовной традиции? Будда подводит к ответу, согласно которому даже возвышенные мистические переживания, видения и откровения остаются проявлениями собственного ума (<em>svacitta-dṛśya</em>), пока не произошёл «поворот основы» (<em>āśraya-parāvṛtti</em>) — радикальное преображение самого способа восприятия. Даже величайшее прозрение, если за него цепляются как за окончательную истину, остаётся внутри движения различения (<em>vikalpa</em>) и принадлежит сфере воображаемой природы (<em>parikalpita-svabhāva</em>).</p>
        <p class="my-2">Таким образом, Диргхатапас здесь символизирует предел добуддийской мудрости: аскетическое или мистическое знание способно приблизить к истине, но ещё не устраняет само основание двойственного восприятия. Пока существует различение между «видящим» и «видимым», сознание продолжает создавать мир как сеть именований, образов и идей. Подлинное освобождение начинается лишь там, где прекращается цепляние даже за духовное видение.<a href="#ref-162" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-163"><sup>163</sup> <strong>Формы миров</strong> — лотос, лев, Шриватса — указывают на бесконечное разнообразие земель Будд (<em>buddhakṣetra</em>), возникающих как проявление чистого ума. Форма мира не предопределена внешней необходимостью. Она зависит от благословенной силы (<em>adhiṣṭhāna</em>) Татхагаты, пребывающего в том мире, и кармы существ, его населяющих. Лотос символизирует мир, рождённый из чистоты и потенциала пробуждения. Лев — мир, где проявляется неодолимая мощь Дхармы. Шриватса — бесконечный узел, выражающий неразрывную взаимозависимость всех дхарм.<a href="#ref-163" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-164"><sup>164</sup> <strong>Будды Мудрости Таковости</strong> (<em>tathatā-jñāna-buddha</em>) соответствуют Дхармакае. Это — сама таковость реальности, лишённая признаков и различений. Здесь нет ни личности, ни познающего — только недвойственное постижение, доступное лишь в сфере личного прозрения (<em>pratyātmagati</em>), когда исчезает разделение на «я» и «мир».<br><strong>Будды созревания заслуг</strong> (<em>vipākaja-buddha</em>) соответствуют Самбхогакае — Телу Блаженства. Это — величественное проявление Татхагаты в чистых мирах, возникшее как плод (<em>vipāka</em>) бесконечного накопления мудрости и заслуг. Эта форма доступна восприятию бодхисаттв, пребывающих в глубоком самадхи.<br><strong>Будды воплощения</strong> (<em>nirmāṇika-buddha</em>) соответствуют Нирманакае — Телу Проявлений. Это — исторические Будды (как Шакьямуни) или нирманы, которые Татхагата являет в мирах желаний. Они принимают облик, речь и действия, соответствующие уму существ, чтобы вести их к пробуждению.<a href="#ref-164" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-165"><sup>165</sup> <strong>Сиддханта</strong> (<em>siddhānta</em>) в <strong><em>Ланкаватаре</em></strong> имеет два аспекта: личное постижение (<em>pratyātma-siddhānta</em>) — недвойственное, невыразимое, свободное от признаков и рассудочного мышления; изложение Учения (<em>deśanā-siddhānta</em>) — словесное указание, приспособленное к слушателям.<a href="#ref-165" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-166"><sup>166</sup> <strong>«Лес из мужчин и женщин»</strong> — здесь, возможно, символ двойственности восприятия. В адах такой лес — ловушка для страстных: иллюзорные образы желанных тел на деревьях из листьев-лезвий ведут к мучениям. В чистых землях — знак чудесного рождения, лишённого биологической кармы. Махамати указывает в вопросе, что одна и та же форма становится адом или раем в зависимости от состояния сознания. Ни привлекательность, ни ужас не принадлежат объекту — они суть проявление собственного ума (<em>svacitta-dṛśya</em>).<a href="#ref-166" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-167"><sup>167</sup> В этом эпизоде Будда применяет особый педагогический приём — священную иронию. Махамати, выступая от лица интеллектуала, стремится охватить Дхарму рассудочным знанием: его вопросы охватывают всё — от природы Нирваны до количества атомов в горчичном зерне. Это — попытка ума построить полную систему различений, где каждому явлению дано имя, мера и место.<br>Ответ Будды двоякий:<br><em>Доведение до абсурда (шлоки 71—80):</em> Он зеркально отражает эту страсть к детализации, предлагая вопросы ещё более мелочные и бессмысленные — сколько атомов в брови? Сколько пал весит гора Меру? Тем самым Он показывает: накопление информации не есть постижение. Ум может бесконечно дробить явления, но так и не коснётся их недвойственной природы.<br><em>Смешение уровней (шлоки 81—90):</em> Будда намеренно ставит в один ряд вопросы о Таковости и о «вкусности еды», о Пустоте и о половом влечении. Это — намеренное потрясение рассудка: разрушается иерархия «духовного» и «мирского», ибо для омрачённого ума любое различение — преграда, даже то, что касается Будды.<a href="#ref-167" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-168"><sup>168</sup> <strong>Bhramarā</strong> (букв. «пчелы») — в контексте <strong><em>Ланкаватара-сутры</em></strong> данный термин используется метафорически. Он указывает на «блуждающие умы» или живых существ, чье сознание из-за беспокойства и привязанностей постоянно «перелетает» от одного чувственного объекта к другому, подобно пчелам на лугу. Корень слова <strong>bhram</strong> («блуждать», «вращаться», «ошибаться») подчёркивает сансарическую природу такого сознания, вовлечённого в круговорот перерождений и ложных различений.<a href="#ref-168" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-169"><sup>169</sup> <strong><em>svapratyātmāryajñāna</em></strong> — «самопостигаемая мудрость благородных» — это знание, которое полностью свободно от слов, понятий, логических категорий (найяиков) и знаков. Его невозможно передать через логику, его можно только пережить на собственном опыте.<a href="#ref-169" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-170"><sup>170</sup> Этот список не утверждает и не отрицает понятия. Будда показывает, что каждое из них, взятое как объект цепляния, становится преградой. Только когда ум не зацепляется ни за X, ни за не-X, раскрывается недвойственная реальность.<a href="#ref-170" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-171"><sup>171</sup> <strong>«Прекращение потока»</strong> (<em>prabandha-nirodha</em>) — прекращение непрерывной цепи сцепленных состояний, в которой один акт различения мгновенно порождает следующий под влиянием кармических отпечатков. Этот поток — инерция сансарического мышления, при которой ум работает как автоматический «проектор», воспроизводящий прошлые галлюцинации. При <em>prabandha-nirodha</em> прекращается признак деятельности (<em>karma-lakṣaṇa</em>); признак рождения (<em>jāti-lakṣaṇa</em>) при этом не затрагивается.<a href="#ref-171" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-172"><sup>172</sup> <strong>«Прекращение признаков»</strong> (<em>lakṣaṇa-nirodha</em>) — прекращение привязанности к признакам (<em>lakṣaṇa</em>), через которые ум строит видимость внешнего мира. Обычное сознание воспринимает готовые объекты, «построенные» умом, а не поток различений. Эти признаки — умозрительные метки, придающие зыбким проекциям ума иллюзию плотности и самостоятельности. Освобождаясь от цепляния за признаки, ум перестаёт наделять опыт характеристиками формы, цвета или ценности. <em>Prabandha-nirodha</em> останавливает инерцию временного потока; <em>lakṣaṇa-nirodha</em> растворяет воображаемую плотность мира. Это состояние напрямую ведёт к без-образности (<em>nirābhāsa</em>) — высшей мудрости, в которой сознание отражает Таковость (<em>tathatā</em>) без наслоения различений (<em>vikalpa</em>).<a href="#ref-172" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-173"><sup>173</sup> <strong>«Возникновение потока»</strong> (<em>prabandha-utpāda</em>) — непрерывное воспроизводство двойственных состояний сознания, порождающее иллюзию временной непрерывности. Это динамический процесс, в котором различающий ум (<em>mano-vijñāna</em>) беспрестанно проецирует кармические отпечатки (<em>vāsanā</em>), под воздействием «ветров» внешних объектов, превращая семена <em>Алайи-виджняны</em> в волны восприятия. Так возникает самоподдерживающаяся инерция, создающая ложное чувство длительности «я» и «мира». Для бодхисаттвы этот поток — непрерывное развёртывание различений, подлежащее распознаванию и прекращению.<a href="#ref-173" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-174"><sup>174</sup> <strong>«Возникновение признака»</strong> (<em>lakṣaṇa-utpāda</em>) — акт умозрительного выделения, посредством которого ум наделяет недвойственный поток опыта конкретными свойствами — формой, цветом, плотностью — и закрепляет их через имена. Это — первичный источник иллюзии, превращающий Таковость (<em>tathatā</em>) в мир разделённых и «плотных» объектов, доступных для схватывания (<em>grahaṇa</em>) как «внешних». В <strong><em>Ланкаватаре</em></strong> это считается основой омрачения (<em>āvaraṇa</em>): <em>prabandha-utpāda</em> создаёт иллюзию времени; <em>lakṣaṇa-utpāda</em> создаёт иллюзию пространственной плотности. Этот процесс подлежит прямому постижению.<a href="#ref-174" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-175"><sup>175</sup> <strong>«Пребывание потока»</strong> (<em>prabandha-sthiti</em>) — динамическая устойчивость различающего сознания (<em>mano-vijñāna</em>), обеспечивающая непрерывность иллюзорного опыта. Это — инерция сансары, благодаря которой поток кармических проекций самоподдерживающе длится, создавая для омрачённого ума иллюзию временной непрерывности «я» и мира.<a href="#ref-175" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-176"><sup>176</sup> <strong>«Пребывание признака»</strong> (<em>lakṣaṇa-sthiti</em>) — фаза умозрительного закрепления, в которой ум наделяет мгновенные проекции статусом длительного и плотного существования. Это — умственный клей, превращающий поток «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>) в устойчивый мир объектов, доступных для схватывания (<em>grahaṇa</em>) и порождает страдание.<a href="#ref-176" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-177"><sup>177</sup> <strong>«Признак деятельности»</strong>, <strong>«признак развёртывания»</strong> (<em>pravṛtti-lakṣaṇa</em>) — характеристика активного развёртывания сознания в режиме различения. <em>Karma-lakṣaṇa</em>описывает накопление кармических отпечатков (<em>vāsanā</em>); <em>pravṛtti-lakṣaṇa</em> описывает сам процесс проявления различений (<em>vikalpa</em>) из скрытых семян. Это — деятельный аспект ума, который может быть прекращён (<em>nirodha</em>) без уничтожения <em>jāti-lakṣaṇa</em> — признака возникновения.<a href="#ref-177" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-178"><sup>178</sup> <strong>«Признак действия»</strong> (<em>karma-lakṣaṇa</em>) — аспект сознания, посредством которого деятельность различения превращается в новые кармические отпечатки. Это способ накопления, создающий условия для будущих циклов развёртывания. Именно этот признак прекращается при <em>prabandha-nirodha</em> (прекращение потока), а не <em>jāti-lakṣaṇa</em> (признак рождения).<a href="#ref-178" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-179"><sup>179</sup> <strong>«Признак рождения»</strong> или <strong>«возникновения»</strong> (<em>jāti-lakṣaṇa</em>) — аспект сознания, отвечающий за проявление нового цикла опыта — как тела, так и мира, воспринимаемого умом. Этот признак завершает процесс сансарического воспроизводства, описывая, как кармические отпечатки проявляются в виде «видимого собственным умом» (<em>svacitta-dṛśya</em>). Постижение его иллюзорности и изначальной нерождённости (<em>anutpāda</em>) всех явлений устраняет этот признак при повороте основы (<em>āśraya-parāvṛtti</em>).<a href="#ref-179" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-180"><sup>180</sup> <strong>«Сознание проявления»</strong> (<em>khyāti-vijñāna</em>) — аспект сознания, мгновенно и одновременно проецирующий весь феноменальный мир. Подобно зеркалу, оно являет образы тела, объектов и вместилища из скрытых отпечатков <em>Алайи-виджняны</em>. Это — первая кажимость (<em>ābhāsa</em>), предшествующая всякому рассуждению, и создающая сцену сансарического опыта.<a href="#ref-180" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-181"><sup>181</sup> <strong>«Сознание различения объектов»</strong> (<em>vastu-prativikalpa-vijñāna</em>) — рассудочный аспект ума, который анализирует, классифицирует и наделяет именами образы, проявленные сознанием проявления (<em>khyāti-vijñāna</em>). Оно работает последовательно, превращая единый поток «видимого собственным умом» (<em>svacitta-dṛśya</em>) в мир разделённых и плотных объектов. Это сознание является главным инструментом умозрительного различения (<em>vikalpa</em>), поддерживающего иллюзию внешней плотности.<a href="#ref-181" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-182"><sup>182</sup> <strong>«Непостижимое преобразование отпечатков»</strong> (<em>acintya-vāsanā-pariṇāma</em>) — процесс, посредством которого скрытые склонности (<em>vāsanā</em>), накопленные в <em>Алайя-виджняне</em>, созревают (<em>pariṇāma</em>) и проявляются как мир, тело и обстоятельства. Он называется «непостижимым» (<em>acintya</em>), потому что не поддаётся рассудочному мышлению (<em>tarka</em>), протекает вне осознанного контроля, и не может быть воспринят как объект. В <strong><em>Ланкаватаре</em></strong> этот термин указывает, что весь проявленный мир не является внешней реальностью — это динамика самого ума, движимая безначальными привычками различения. Бодхисаттва, пребывая в йоге видимого собственным умом (<em>svacitta-dṛśya-yoga</em>), не видит «проекции», а распознаёт единый поток, в котором нет разделения на внутреннее и внешнее.<a href="#ref-182" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-183"><sup>183</sup> <strong>«Различение объектов»</strong> (<em>viṣaya-vikalpa</em>) — умозрительное разделение, посредством которого ум наделяет свои проекции статусом внешних и независимых предметов; умственное искажение, создающее иллюзию объективного мира, противопоставленного субъекту, и служащее опорой для возникновения привязанностей и омрачений. Прекращение <em>viṣaya-vikalpa</em> является необходимым условием для возвращения ума в состояние недвойственного покоя.<a href="#ref-183" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-184"><sup>184</sup> <strong>«Отпечатки безначального разрастания понятийного многообразия»</strong> (<em>anādi-prapañca-vāsanā</em>) — накопленная в сознании вязкая инерция, заставляющая ум проецировать «воспринимаемое собственным умом» в виде сложной сети имён, образов, идей-понятий и различений. Это раздутость понятий (<em>prapañca</em>) создаёт ложную множественность там, где существует лишь единая Таковость (<em>tathatā</em>). Освобождение от этих отпечатков означает переход от рассудочного знания к прямому постижению «только-ума» (<em>cittamātra</em>).<a href="#ref-184" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-185"><sup>185</sup> <strong>«Ложное умопостроение</strong> (<em>abhūta-parikalpa</em>) — фундаментальный механизм ума, создающий иллюзию разделения на субъект и объект. Это процесс воображения того, чего нет, который превращает недвойственную Таковость (<em>tathatā</em>) в мир множественных форм. Постижение этого процесса как лишённого собственной природы позволяет йогину остановить словесную раздутость / понятийное разрастание (<em>prapañca</em>) и вернуться к прямому постижению «видимого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-185" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-186"><sup>186</sup> <em>lakṣaṇa-nirodha</em> — угасание различительных признаков: прекращение разнообразных отпечатков ложного умопостроения в <em>Алайя-виджняне</em>, вследствие чего исчезает разделение на воспринимающего и воспринимаемое, а отдельные чувственные сознания перестают проецировать мир воспринимаемого.<a href="#ref-186" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-187"><sup>187</sup> <em>prabandha-nirodha</em> — прекращение потока: прекращение непрерывного развёртывания различающего сознания и самих условий возникновения сознаний — их опоры (<em>āśraya</em>) и объектов восприятия (<em>ālambana</em>). Иначе говоря, это угасание потока сцепленных различений, поддерживающих переживание сансарического мира.<a href="#ref-187" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-188"><sup>188</sup> <strong>«Отпечатки пагубной косности безначального понятийного разрастания»</strong> (<em>anādi-prapañca-dauṣṭhulya-vāsanā</em>) — пагубная косность/порочность/тяжесть/вязкость/предрасположенность сознания, обусловленная безначальной привычкой к раздроблению «воспринимаемого собственным умом» через язык и умозрительные различения. Эта дурная предрасположенность заставляет ум воспринимать мир как вязкую сеть внешних и плотных объектов, блокируя доступ к лёгкости и ясности недвойственной мудрости.<a href="#ref-188" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-189"><sup>189</sup> <strong>«Воспринимаемое собственным умом»</strong> (<em>svacitta-dṛśya</em>) — положение, согласно которому весь проявленный мир является не чем-то «внешним», а проявлением самого ума. Постижение всего опыта как <em>svacitta-dṛśya</em> устраняет иллюзию разделённости между наблюдаемым и наблюдателем, позволяя йогину увидеть в каждом объекте лишь прозрачную игру ума, свободную от ложной плотности и независимого бытия.<a href="#ref-189" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-190"><sup>190</sup> <strong>«Сознание проявлений»</strong>, <strong>«активные сознания»</strong> (<em>pravṛtti-vijñāna</em>) — совокупность семи активных уровней сознания: пяти чувственных, ментального и сознания-<em>манас</em>, которые развёртываются из <em>Алайи-виджняны</em> под воздействием объектов, воспринимаемых как внешние. Это динамический аспект ума, ответственный за понятийное различение и создание иллюзии двойственности.<a href="#ref-190" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-191"><sup>191</sup> <em>jāti-lakṣaṇa</em> — признак рождения: характеристика, описывающая сам факт проявления сознаний из <em>Алайя-виджняны</em>. В отличие от признака действия (<em>karma-lakṣaṇa</em>), который прекращается при освобождении, признак рождения <em>Алайя-виджняны</em> сохраняется на уровне относительной истины до окончательного <em>поворота основы</em> (<em>āśraya-parāvṛtti</em>).<a href="#ref-191" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-192"><sup>192</sup> <strong>«Признак собственного рождения»</strong> (<em>svajāti-lakṣaṇa</em>) — характеристика, согласно которой каждое явление кажется возникающим в силу собственной природы. Если <em>jāti-lakṣaṇa</em> (признак рождения) описывает сам факт проявления мира из ума, то <em>svajāti-lakṣaṇa</em> указывает, как ум наделяет каждую проекцию иллюзией уникальности и независимости. Когда этот термин применяется к <em>Алайе-виджняне</em>, её <em>svajāti-lakṣaṇa</em> не прекращается на уровне относительной истины, пока не произойдёт <em>поворот основы</em> (<em>āśraya-parāvṛtti</em>). До этого <em>поворота</em> <em>Алайя</em> функционирует как относительно устойчивый поток на уровне условной истины (<em>saṃvṛti-satya</em>), обеспечивающий непрерывность кармических отпечатков и проявление активных сознаний. Однако её кажущаяся устойчивость — это не абсолютная реальность (<em>paramārtha</em>), а лишь тончайший уровень различений «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), который подлежит преображению при <em>parāvṛtti</em> (повороте основы).<a href="#ref-192" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-193"><sup>193</sup> <em>karma-lakṣaṇa</em> — признак действия: функциональная характеристика сознаний, описывающая их деятельность — проецирование объектов, порождение различений, накопление отпечатков. Именно этот признак прекращается при освобождении, тогда как признак рождения (<em>jāti-lakṣaṇa</em>) <em>Алайя-виджняны</em> сохраняется.<a href="#ref-193" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-194"><sup>194</sup> <strong>«Первоматерия, Дух, Ишвара, Время, Атомы»</strong> — перечисление основных метафизических понятий небуддийских школ: <em>pradhāna</em> — санкхья, <em>puruṣa</em> — санкхья, <em>Īśvara</em> — шиваизм/веданта, <em>kāla</em> — адживика, <em>aṇu</em> — вайшешика.<a href="#ref-194" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-195"><sup>195</sup> В <strong><em>Ланкаватаре</em></strong> термин <em>svabhāva</em> используется двояко: первые шесть видов описывают ложные природы, приписываемые явлениям различающим умом; седьмая (<em>niṣpatti-svabhāva</em>) — истинную природу, Таковость (<em>tathatā</em>), раскрывающуюся при отсечении всех ложных проекций.<a href="#ref-195" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-196"><sup>196</sup> <em>samudaya-svabhāva</em> — «природа совокупного возникновения»; заблуждение, будто явления реально возникают как сумма своих частей или условий.<a href="#ref-196" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-197"><sup>197</sup> <em>bhāva-svabhāva</em> — «природа существования»; ложная вера в то, что объекты обладают независимым существованием.<a href="#ref-197" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-198"><sup>198</sup> <em>lakṣaṇa-svabhāva</em> — «природа признаков»; убеждённость в том, что характеристики объектов (цвет, форма) принадлежат самим объектам, а не являются проекциями различающего ума.<a href="#ref-198" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-199"><sup>199</sup> <em>mahābhūta-svabhāva</em> — «природа первоэлементов»; вера в реальность четырёх <em>махабхути</em> (земли, воды, огня, ветра) как материального фундамента мира.<a href="#ref-199" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-200"><sup>200</sup> <em>hetu-svabhāva / pratyaya-svabhāva</em> — «природа причин и условий»; представление о том, что причинно-следственные связи — это реальные внешние законы, а не ментальные привычки упорядочивания опыта.<a href="#ref-200" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-201"><sup>201</sup> <em>niṣpatti-svabhāva</em> — «природа завершённости», «истинная природа»; Таковость изначально присутствует; прекращение ложных проекций открывает её как то, что никогда не исчезало.<a href="#ref-201" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-202"><sup>202</sup> <strong>Гочары</strong> (<em>gocara</em>) — сферы опыта. Эти термины описывают сферы, в которых обитает сознание, в зависимости от уровня его чистоты.<a href="#ref-202" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-203"><sup>203</sup> <em>citta-gocara</em> — «сфера ума»; обыденный уровень восприятия, где <em>Алайя-виджняна</em> проецирует мир и принимает его за независимую реальность.<a href="#ref-203" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-204"><sup>204</sup> <em>jñāna-gocara</em> — «сфера знания»; состояние, где знание сливается с объектом, и исчезает разделение на познающего и познаваемое.<a href="#ref-204" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-205"><sup>205</sup> <em>prajñā-gocara</em> — «сфера мудрости»; уровень бодхисаттвы, который использует праджню для исследования <em>шуньяты</em> и распознавания природы признаков.<a href="#ref-205" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-206"><sup>206</sup> <em>dṛṣṭi-dvaya-gocara</em> — «сфера двойственных взглядов»; ограниченное пространство ума, удерживаемого между крайностями «есть» и «нет».<a href="#ref-206" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-207"><sup>207</sup> <em>dṛṣṭi-dvayātikrānta-gocara</em> — «сфера, превзошедшая двойственность»; сфера свободы, где любые умозрительные оппозиции теряют смысл и опору.<a href="#ref-207" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-208"><sup>208</sup> <em>suta-bhūmi-anukramaṇa-gocara</em> — «сфера последовательного прохождения ступеней»; путь постепенного очищения сознания через слушание Учения и прохождение по ступеням (<em>бхуми</em>) бодхисаттвы.<a href="#ref-208" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-209"><sup>209</sup> <em>tathāgatasya pratyātmagati-gocara</em> — «сфера личного постижения Татхагаты»; высшая истина, невыразимая словами и недоступная рассудку; прямой внутренний опыт (<em>pratyātma</em>), возникающий в результате поворота основы (<em>āśraya-parāvṛtti</em>), когда <em>Алайя-виджняна</em> преображается в Великую Зерцалоподобную Мудрость (<em>mahā-ādarśa-jñāna</em>).<a href="#ref-209" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-210"><sup>210</sup> <strong>«Учение об уничтожении»</strong> (<em>ucchedavāda</em>) — в данном контексте Будда относит к нигилизму взгляды тех, кто верит в реальный распад <em>скандх</em> и <em>дхату</em>. Согласно <strong><em>Ланкаватаре</em></strong>, признание реального (а не условного) исчезновения явлений ведет к нигилизму, поскольку разрывает преемственность кармы и делает невозможными Путь, плод и освобождение. Истинный Путь основывается на постижении того, что явления никогда не рождались (<em>anutpāda</em>) как независимые сущности, а лишь казались существующими в проекциях собственного ума (<em>svacitta-dṛśya</em>). Только понимание мира как <em>майи</em> позволяет сохранить логику преемственности (<em>saṃtati</em>), не впадая при этом в веру в вечные сущности (<em>śāśvata-vāda</em>).<a href="#ref-210" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-211"><sup>211</sup> <strong>«Отсутствие видения начала»</strong> (<em>Ādyadarśanābhāvāt</em>) — неспособность увидеть, что явления безначальны (<em>anādi</em>). Те, кто ищут «первопричину» — будь то Бог, время или атомы, — совершают умственное заблуждение. Они пытаются найти начало там, где имеется лишь безначальный поток проекций, лишённый как начала, так и конца.<a href="#ref-211" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-212"><sup>212</sup> <strong>«Непрерывный поток»</strong> (<em>nairantarya-pravṛtti</em>) — иллюзия связного и длящегося потока опыта. В <strong><em>Ланкаватаре</em></strong> подчёркивается, что у явлений мира нет собственной внутренней преемственности. Их кажущаяся непрерывность — результат непрерывного возобновления различающим умом (<em>mano-vijñāna</em>) сходных кармических отпечатков (<em>vāsanā</em>). Постижение отсутствия этой непрерывности позволяет йогину прервать поток сансарического опыта и обнаружить нерождённую природу (<em>anutpāda-svabhāva</em>) «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>).<a href="#ref-212" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-213"><sup>213</sup> <strong>«Тройное сочетание»</strong> (<em>trisaṃgati</em>) — техническое обозначение <em>sparśa</em>, встречи объекта, органа чувств и сознания. Оппоненты полагают, что до этой встречи сознание «нет», а после неё — «возникает». Будда показывает несостоятельность этой логики: то, чего нет в причинах, не может появиться в результате. Ошибка состоит в принятии сочетания факторов за реальную причину опыта. Если элементы лишены собственной природы (<em>svabhāva</em>), их сумма не способна породить реально существующее сознание. Для бодхисаттвы «встреча факторов» — это не простое складывание мира из составляющих, это недвойственный процесс внутри «воспринимаемого собственным умом» (<em>svacitta-dṛśya</em>), подобный майе — кажущийся, но лишённый какой-либо сущностной основы.<a href="#ref-213" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-214"><sup>214</sup> <em>Prajñāpāramitā-vihāra</em> — «пребывание в Парамите Мудрости» указывает на устойчивое пребывание в состоянии, которое она описывает: прямое постижение <em>шуньяты</em> без опоры на двойственные категории.<a href="#ref-214" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-215"><sup>215</sup> <em>Anābhoga-caryā</em> — «деятельность без усилия». Состояние, при котором действия бодхисаттвы ради блага существ совершаются спонтанно, без намерения, усилия и кармического следа — как естественное проявление постигнутой недвойственности.<a href="#ref-215" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-216"><sup>216</sup> <em>Svacitta-dṛśya-gocara</em> — «сфера воспринимаемого собственным умом». Освобождение от уз этой сферы означает не отрицание опыта, а прекращение ложного принятия воспринимаемого за независимо существующий внешний мир. <a href="#ref-216" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-217"><sup>217</sup> <em>Udadhi-taraṃga-ālayavijñāna-gocara</em> — «сфера <em>Алайя-виджняны</em> волн [в] океане». Образ океана и волн — один из центральных в <strong><em>Ланкаватаре</em></strong>: <em>Алайя</em> — океан, активные сознания (<em>pravṛtti-vijñāna</em>) — волны, поднимаемые ветром объектов.<a href="#ref-217" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-218"><sup>218</sup> <em>Svacitta-dṛśya-grahaṇā-anavabodhataḥ</em> — «из непостижения схватывания воспринимаемого собственным умом». Сознание не осознаёт, что сам акт схватывания объектов разворачивается внутри области <em>svacitta-dṛśya</em>, а не во «внешнем мире».<a href="#ref-218" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-219"><sup>219</sup> <strong>«Пагубная косность безначального понятийного разрастания»</strong> (<em>anādi-prapañca-dauṣṭhulya</em>) — накопленная косность ума, заставляющая его порождать понятийные построения и принимать их за реальность. Эта косность (<em>dauṣṭhulya</em>) делает сознание тяжёлым и невосприимчивым к истине, удерживая его в привычном разделении субъекта и объекта.<a href="#ref-219" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-220"><sup>220</sup> <em>Vijñāna-prakṛti-svabhāva</em> — «природная сущность сознания». Указывает на то, что сама природа сознания — его склонность к объективации — является одной из причин его развёртывания вовне.<a href="#ref-220" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-221"><sup>221</sup> <em>vicitra-rūpa-lakṣaṇa-kautūhala</em> — «влечение к многообразию форм и признаков». <em>Kautūhala</em> = жадное любопытство, неотступная тяга. Сознание непрестанно ищет объект, за который можно ухватиться, не способное пребывать в покое без опоры на воспринимаемое.<a href="#ref-221" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-222"><sup>222</sup> <em>Pravṛtti-vijñāna-taraṃga</em> — «волны развёртывающегося сознания». Образ прямо связан с предыдущим: если <em>Алайя</em> — океан, то семь активных сознаний — волны, поднимаемые «ветром» (<em>pavana</em>) объектов.<a href="#ref-222" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-223"><sup>223</sup> <strong>«Тело, объекты и мир-вместилище»</strong> (<em>deha-bhoga-pratiṣṭhāna</em>) — триединая структура проявления <em>Алайя-виджняны</em>. Согласно <strong><em>Ланкаватаре</em></strong>, наше физическое присутствие, предметы восприятия и окружающая среда не являются внешними, все три — целостная проекция ума. Осознание того, что эта триада лишена независимого бытия, позволяет бодхисаттве выйти из-под власти кармической обусловленности и увидеть мир как игру собственного ума.<a href="#ref-223" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-224"><sup>224</sup> <strong>«Признак отсутствия образов»</strong> (<em>nirābhāsa-lakṣaṇa</em>) — состояние сознания, полностью очищенное от проекций идей, образов и представлений. Это переход от «восприятия признаков» (<em>lakṣaṇa-grāha</em>) к прямому постижению (<em>pratyātmāryajñāna</em>), где ум перестаёт строить мир как совокупность внешних объектов. Достижение этого «признака» означает, что завеса интеллектуальных наслоений спала, и сознание пребывает в недвойственной чистоте.<a href="#ref-224" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-225"><sup>225</sup> <strong>«Признак благого воздействия собственных обетов всех Будд»</strong> (<em>sarvabuddha-svapraṇidhāna-adhiṣṭhāna-lakṣaṇa</em>) — признак духовной поддержки, возникающей благодаря силе собственных обетов всех Будд. <em>Adhiṣṭhāna</em> здесь означает благое воздействие, поддерживающее продвижение бодхисаттвы по пути благородной мудрости.<a href="#ref-225" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-226"><sup>226</sup> <strong>«Признак личного благородного постижения»</strong> (<em>pratyātmāryajñāna-gati-lakṣaṇa</em>) — высшая характеристика реализации, при которой Истина постигается напрямую, вне всяких представлений и рассудочных построений. Граница между познающим и познаваемым растворяется и тогда Таковость (<em>tathatā</em>) неотделима от самого постижения.<a href="#ref-226" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-227"><sup>227</sup> <strong>«Хромой осёл»</strong> (<em>khañjagardabha</em>) — образ ограниченного средства, которое оказывается оставленным после достижения более высокого состояния. Здесь Будда указывает, что даже различения ума, мудрости и знания должны быть оставлены после достижения высших ступеней бодхисаттвы.<a href="#ref-227" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-228"><sup>228</sup> <strong>«Тело в самадхи, подобном майе»</strong> (<em>māyopama-samādhi-kāya</em>) — проявление бодхисаттвы, чьё присутствие в мире форм уже не обусловлено кармой, но является прямым продолжением его медитативного опыта. Это — тело, которое функционирует среди явлений как магический мираж. Оно действенно и сострадательно, но абсолютно лишено собственной природы. Обретение такого «тела» знаменует победу над иллюзией плотности мира и переход к безусильной деятельности во благо всех существ.<a href="#ref-228" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-229"><sup>229</sup> <strong>«Исследование основы благородного знания»</strong> (<em>āryajñāna-vastu-pravicaya</em>) направлено на прямое различение содержания опыта, свободного от рассудочного выстраивания понятий. Разбор ста восьми положений служит практическим методом для перехода от условных обозначений к непосредственному постижению.<a href="#ref-229" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-230"><sup>230</sup> <em>parikalpita-svabhāva</em> — воображаемая природа возникает, когда ум наделяет воспринимаемые признаки самостоятельным статусом. Путь её преодоления состоит в распознавании условного характера всех обозначений, что устраняет ложную опору для присвоения.<a href="#ref-230" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-231"><sup>231</sup> <em>pudgala-dharma-nairātmya</em> — двоякое отсутствие «я»: в личности (<em>pudgala</em>) и в явлениях (<em>dharma</em>). Постижение отсутствия «я» в личности устраняет завесу омрачений (<em>kleśa-āvaraṇa</em>), постижение отсутствия «я» в дхармах — завесу познаваемого (<em>jñeya-āvaraṇa</em>), открывая путь к всеведению (<em>sarvajñatā</em>).<a href="#ref-231" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-232"><sup>232</sup> <strong>«Небытие»</strong>, <strong>«отсутствие» или «отрицание существования»</strong> (<em>nāstitva</em>) — В <strong><em>Ланкаватаре</em></strong> это понятие рассматривается как умственная ловушка — вторая из «двух крайностей» (<em>anta-dvaya</em>). Вера в «небытие» — это обратная сторона веры в «бытие». Чтобы нечто «отсутствовало», оно должно было сначала «быть». Но поскольку все явления изначально не рождены (<em>anutpāda</em>) и являются лишь «воспринимаемым собственным умом» (<em>svacitta-dṛśya</em>), то и говорить об их «небытии» так же некорректно, как и об их «бытии». Взгляд «небытия» (<em>nāsti-dṛṣṭi</em>) особенно опасен, так как он может привести к отрицанию закона кармы, плода и самого Пути.<a href="#ref-232" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-233"><sup>233</sup> <strong>«Истощение причины различающего рассудка»</strong>, <strong>«исчерпание оснований для рассудочного вывода»</strong> (<em>vikalpa-buddhi-hetu-kṣaya</em>) — различающий рассудок (<em>vikalpa-buddhi</em>), не обнаруживая устойчивой причины (<em>hetu</em>) явлений, заключает: «раз причины нет — явление не существует». Это <em>kṣaya</em> — полное «исчерпание» реальности в умозрительном отрицании. Будда указывает, что само это отрицание — плод того же различающего ума: нигилист видит лишь отсутствие вещей, не постигая Таковость (<em>tathatā</em>). Его рассудок занят уничтожением объектов вместо того, чтобы остановиться самому.<a href="#ref-233" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-234"><sup>234</sup> <strong>Логическая ошибка нигилистов.</strong> Они говорят: «Рогов у зайца нет (это факт), значит и мир такой же несуществующий». Будда критикует их за то, что они строят свое отрицание мира на сравнении с несуществующим объектом. Но если объект (рога зайца) абсолютно невозможен, он не может служить даже примером для отрицания. Чтобы сказать «чего-то нет», нужно сначала иметь идею о том, что это «есть». Но сами "рога зайца" — это идея, заимствованная у "рогов коровы". Таким образом, отрицание паразитирует на утверждении «есть», и обе крайности остаются в ловушке различающего ума (<em>vikalpa</em>).<a href="#ref-234" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-235"><sup>235</sup> <strong>Логическая ошибка реалистов.</strong> Они говорят: «Ладно, рогов зайца нет, но рога коровы-то мы видим! Значит, мир реален». Они разделяют реальность на «абсолютно отсутствующее» и «реально присутствующее». Будда же утверждает, что и то, и другое — лишь <em>vikalpa</em> (различение). Рога коровы так же «пусты» от собственной природы, как и рога зайца. Разница лишь в устойчивости проекции.<a href="#ref-235" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-236"><sup>236</sup> <strong>«Обусловленность через взаимную зависимость»</strong> или <strong>«относительность причинности»</strong> (<em>anyonyāpekṣa-hetutva</em>) — одна идея «взирает» (<em>apekṣā</em>) на другую, чтобы обрести смысл; ключевой логический принцип, вскрывающий ловушку, в которой представления существуют лишь парами, взаимно определяя друг друга. Будда указывает, что «небытие» (<em>nāstitva</em>) всегда тайно опирается на «бытие» (<em>astitva</em>). Когда мы говорим «у зайца нет рогов», мы неявно подтверждаем, что концепция «рога» имеет смысл (заимствованный у коровы). Отрицая одну сторону, ум всё равно остаётся в плену у другой. Если при анализе «бытие» объекта (рога коровы) оказывается лишь проекцией ума, то и «небытие» (отсутствие рогов у зайца) теряет всякую почву. Нельзя построить истинное знание, опираясь на отрицание иллюзии, ибо само это отрицание — такая же умозрительная конструкция, как и утверждение. Истинная мудрость (<em>jñāna</em>) не выбирает между «есть» и «нет». Она распознаёт, что обе эти категории — лишь словесная раздутость (<em>prapañca</em>), и оставляет саму эту двойственность. Этот термин объясняет, почему Будда отвергает как реализм, так и нигилизм.<a href="#ref-236" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-237"><sup>237</sup> <strong>«Исследование вплоть до мельчайших атомов»</strong> (<em>āparamāṇu-pravicayāt</em>) — аналитический метод разрушения кажущейся плотности объектов. Он заключается в мысленном дроблении объекта на составляющие части до тех пор, пока сама идея его независимого существования не исчезнет. Обнаруживая, что при предельном разборе никакой собственной природы (<em>svabhāva</em>) не находится, бодхисаттва убеждается, что мир не имеет внешней опоры и является лишь динамической проекцией ума. Это праджня-анализ (<em>prajñā-pravicaya</em>): вера в плотность объекта доводится до самоопровержения через обнаружение отсутствия предельной частицы. Так различающий ум (<em>vikalpa</em>) лишается опоры и прекращается сам.<a href="#ref-237" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-238"><sup>238</sup> В этом вопросе Махамати проверяет Будду, пытаясь обосновать «небытие» (<em>nāstitva</em>) через факт «прекращения» (<em>apravṛtti</em>) работы ума. Это — утончённая ловушка: попытка утвердить небытие (<em>nāstitva</em>) как логический вывод из факта прекращения деятельности различения. Махамати ищет логическое обоснование для отсутствия объектов через наблюдение за прекращением самого процесса различения, не осознавая, что Таковость (<em>tathatā</em>) не нуждается в подобных соотнесениях и лежит выше любой логики «наличия» или «отсутствия».<a href="#ref-238" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-239"><sup>239</sup> <strong>«Порочность причины»</strong> (<em>viṣama-hetu</em>) — умственное заблуждение, при котором для доказательства истины используются ложные или относительные основания. Будда указывает, что нельзя утвердить «небытие» объектов, опираясь на «бытие» других, так как при тщательном анализе любая опора лишена собственной природы. Эта порочность основания делает рассудочное доказательство невозможным: истина открывается лишь тогда, когда ум оставляет саму привычку утверждать одно через соотнесение с другим.<a href="#ref-239" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-240"><sup>240</sup> В этом фрагменте Будда последовательно устраняет опоры умозрительного различения:<br> • Ни тождество, ни различие (<em>anyānanya-vivarjita</em>): субъект и объект различения не утверждаются ни как одно, ни как два. Тем самым снимается возможность как утверждения бытия, так и отрицания через противопоставление.<br> • Порочность причины (<em>viṣama-hetu</em>): отрицание одного через другое логически недопустимо, поскольку сам объект сравнения при анализе лишён устойчивой основы (<em>vastu</em>).<br> • Снятие различия формы и пространства (<em>ākāśameva rūpam</em>): форма не существует отдельно от пространства и не «располагается» в нём; оба — условные обозначения, возникающие в различении.<br> • Исчерпание признака при анализе (<em>aṇutva-lakṣaṇe nāvatiṣṭhante</em>): при аналитическом разложении объект не обнаруживает предельной частицы и утрачивает сам признак формы, переставая быть опорой мышления.<a href="#ref-240" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-241"><sup>241</sup> <em>svacitta-dṛśya-vikalpa-anugama-manasā</em> — «манас, следующий различениям видимого собственного ума». Речь идёт о <em>манасе</em> как о сознании, которое непрерывно движется вслед за различениями (<em>vikalpa</em>), принимая воспринимаемое за внешний мир. Он удерживает привычное разделение на воспринимающего и воспринимаемое, вновь и вновь вовлекая поток сознания в круговорот цепляния и понятийного развёртывания. <a href="#ref-241" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-242"><sup>242</sup> <em>svacitta-dṛśya-yoga</em> — «йога видимого как собственного ума». Это прямое созерцательное постижение того, что всё воспринимаемое не обладает самостоятельной внешней природой, но является проявлением самого ума. Такая йога прекращает опору на двойственность субъекта и объекта и ведёт к личному благородному постижению (<em>pratyātmāryajñāna</em>).<a href="#ref-242" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-243"><sup>243</sup> <strong>Нишьянда-будда</strong> (<em>niṣyanda-buddha</em>) — «Будда излияния»: аспект Пробуждённого, проявляющийся как спонтанное, естественное излучение (<em>niṣyanda</em>) Таковости (<em>tathatā</em>) в форму. В <strong><em>Ланкаватаре</em></strong> этот термин описывает Будду, который является «истечением» Таковости (<em>tathatā</em>) в сферу форм. Это тот образ Будды, который наставляет бодхисаттв на высоких ступенях пути, служа живым мостом между невыразимой Таковостью и миром умозрительных различений (<em>vikalpa</em>).<a href="#ref-243" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-244"><sup>244</sup> <strong>«Признак привязанности к различению собственной природы явлений»</strong> (<em>bhāva-vikalpa-svabhāva-abhiniveśa-lakṣaṇa</em>) — описывает трёхступенчатую ловушку познания: различающий ум (<em>vikalpa</em>) разделяет целостный опыт на отдельные явления (<em>bhāva</em>), наделяет их независимой собственной природой (<em>svabhāva</em>) и затем цепляется (<em>abhiniveśa</em>) за эти ментальные проекции как за внешнюю реальность. <a href="#ref-244" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-245"><sup>245</sup> <em>Нилапитаушнадравачалакатхина</em> (<em>nīla-pīta-uṣṇa-drava-cala-kaṭhina</em>) — перечисление чувственных признаков, которые <em>шраваки</em> ошибочно принимают за объективные свойства великих элементов (<em>mahābhūta</em>): <em>nīla</em> и <em>pīta</em> — цветовые аспекты формы (<em>rūpa</em>), <em>uṣṇa</em> — жар (огонь), <em>drava</em> — текучесть (вода), <em>cala</em> — движение (ветер), <em>kaṭhina</em> — твёрдость (земля). Хотя эти признаки введены в учении лишь как условные обозначения (<em>prajñapti</em>) для анализа опыта, <em>шраваки</em>, удерживаясь в рамках созерцания отсутствия «я» в «личности» (<em>pudgala-nairātmya</em>), не проникают в отсутствие «я» в дхармах (<em>dharma-nairātmya</em>) и потому овеществляют элементы. Это показывает привязанность к воображаемой природе (<em>parikalpita-svabhāva-abhiniveśa</em>) — принятие собственных категорий анализа за реальные сущности.<a href="#ref-245" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-246"><sup>246</sup> <em>anitya-bhāva-vilakṣaṇa-hetutvāt</em> — «по причине [желания найти] иное по отношению к непостоянному бытию». Тиртхики строят свою «<strong>Вечность</strong>» на отталкивании от изменчивости мира. Но если ваша вечность зависит от непостоянства (как его противоположность), она не является независимой познавательной реальностью. Сутра подчеркивает, что такой взгляд остается обусловлен тем самым непостоянством, которое он пытается отрицать.<a href="#ref-246" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-247"><sup>247</sup> <em>na svakṛta-hetu-lakṣaṇa-prabhāvitā</em> — буквально: «[состояние], не явленное/не порождённое через признаки своих собственных причин». Будда указывает, что эта идея проявляется лишь через признаки причин, придуманные ими самими. Она создаётся их собственным рассудочным мышлением, и потому не обнаруживается в непосредственном созерцательном опыте и лишена подлинной познавательной силы.<a href="#ref-247" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-248"><sup>248</sup> <em>vāg-vikalpa-mātra</em> — «словесная раздутость», когда ум плодит определения, не имея под ними живого опыта. Это состояние, при котором учение сводится лишь к словесному различению, а логические категории принимаются за реальные явления. Это подчеркивает полную содержательную пустоту подобных умозрительных систем.<a href="#ref-248" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-249"><sup>249</sup> <em>pratyātmāryādhigama-lakṣaṇa</em> — «признак личного благородного постижения». В отличие от тиртхиков, строящих свои теории на логических выводах, Будда указывает на этот признак как на единственный критерий истины. Вечность Татхагат открывается непосредственно в созерцательном опыте. Это измерение изначальной мудрости, которое полностью свободно от понятийных категорий рассудка.<a href="#ref-249" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-250"><sup>250</sup> <em>kṛtaka-bhāva-abhāva-varjita.</em> Тиртхики видят мир как «сотворённый» и потому разрушимый, а свою вечность — как нечто «несотворённое». Будда же «свободен» (<em>varjita</em>) от самой этой пары. Его состояние не является ни «сотворённым», ни «несотворённым», так как оно лежит за пределами двойственности возникновения и уничтожения. Это «ни то, ни другое», которое оставляет логиков в тупике.<a href="#ref-250" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-251"><sup>251</sup> <strong>«Рассудочное умозаключение на основе внешнего»</strong> (<em>bāhya-bhāva-anitya-anumāna</em>). Тиртхики смотрят на внешний мир (<em>bāhya-bhāva</em>), видят, что он распадается (<em>anitya</em>), и логически делают вывод: «значит, должно быть что-то вечное». Будда называет это «гаданием по признакам». Ошибка здесь в том, что они принимают «внешний мир» за реальную точку отсчёта. Для <strong><em>Ланкаватары</em></strong> внешний мир — это проявление ума, поэтому строить на его «непостоянстве» выводы о Вечности — всё равно что изучать законы оптики по отражению в кривом зеркале.<a href="#ref-251" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-252"><sup>252</sup> <em>svacitta-dṛśya-gocara</em> — «сфера того, что является лишь видимым/воспринимаемым собственным умом». Любой объект опыта не существует независимо, он представляет собой проекцию ментальных отпечатков (васан), разворачивающихся в уме.<a href="#ref-252" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-253"><sup>253</sup> <em>bāhya-citta-dṛśya-gocara</em> — буквально «сфера видимого вне ума». Заблуждение, свойственное как тиртхикам, так и последователям Трёх Колесниц (шравакам), которые принимают внешние объекты за независимую познавательную реальность (<em>bāhya</em>), не понимая, что эти объекты — лишь проявления самого ума (<em>citta-dṛśya</em>).<a href="#ref-253" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p id="citation-254"><sup>254</sup> <em>gotra</em> — род, духовный тип или предрасположенность. В контексте сутры это понятие выражает изначальную созерцательную направленность потока сознания существа, далекую от социальных или кастовых делений. Определение готры помогает соотнести проповедь с познавательными возможностями слушателя. Классификация на пять родов предрасположенности к постижению (<em>abhisamaya</em>) служит упорядочиванию различных подходов к освобождению в рамках махаянского обучения.<a href="#ref-254" class="citation-back">↩</a></p>

        <p id="citation-255"><sup>255</sup> <em>śravakayāna-gotra</em> — род постижения колесницы шраваков (слушателей). Этот тип практикующих ориентирован на личное успокоение через аналитическое различение элементов опыта. Их созерцание сосредоточено на анализе отдельных составных признаков (<em>скандх</em>, <em>дхату</em>, <em>аятан</em>), образующих иллюзию плотного существования. Главным достижением здесь считается прекращение грубых эмоциональных омрачений за счет устранения ложной веры в постоянное «я» личности.<a href="#ref-255" class="citation-back">↩</a></p>

        <p id="citation-256"><sup>256</sup> <em>pratyekabuddhayāna-gotra</em> — род постижения колесницы пратьекабудд. Практикующие этого типа склонны к полному созерцательному уединению и независимости от духовных общин. Их внимание привлекает учение об обусловленности без соприкосновения (<em>asaṃsarga-pratyaya</em>), где причинно-следственные связи рассматриваются изолированно. Хотя они глубоко продвигаются в успокоении ума, их познавательной ошибкой остается привязанность к существованию воспринимаемых образов.<a href="#ref-256" class="citation-back">↩</a></p>

        <p id="citation-257"><sup>257</sup> <em>tathāgatayāna-gotra</em> — род постижения колесницы Татхагат. Высший тип духовной предрасположенности, направленный на полное и всеобъемлющее пробуждение ради блага всех существ. Бодхисаттвы этого рода способны воспринимать мир без разделения на субъект и объект. Их ум подготовлен к пониманию того, что любые внешние проявления представляют собой лишь проекции созревающего ума.<a href="#ref-257" class="citation-back">↩</a></p>

        <p id="citation-258"><sup>258</sup> <em>aniyata-gotra</em> — неопределенный или подвижный род. Этот тип обозначает практикующих, чьи созерцательные семена еще не приняли жестко определённого направления. В зависимости от внешних условий, наставников и внутренних импульсов они могут воспринять методы любой из трех колесниц. Сутра предписывает направлять их поэтапно, исходя из их текущих склонностей.<a href="#ref-258" class="citation-back">↩</a></p>

        <p id="citation-259"><sup>259</sup> <em>agotra</em> — лишённые рода. Категория существ, у которых временно отсутствуют благие отпечатки, необходимые для устремления к освобождению. В сутре они описываются как те, кто отбросил корни добродетели из-за ложных воззрений или ложного сострадания. Махаянская традиция рассматривает это состояние как преодолимое в долгосрочной перспективе созревания семян ума.<a href="#ref-259" class="citation-back">↩</a></p>

        <p id="citation-260"><sup>260</sup> <em>ṣaṭpañcamyāṃ bhūmau</em> — на рубеже пятой и шестой ступени. Упоминание этого созерцательного стыка указывает на предел, где шравак достигает наивысшего успокоения ума. В йогачаринских схемах этот уровень сопоставим с глубоким сосредоточением бодхисаттвы, однако шравак останавливается здесь из-за отсутствия постижения нерасчлененной природы дхарм. Он устраняет лишь грубые клеши, принимая этот промежуточный покой за окончательный исход.<a href="#ref-260" class="citation-back">↩</a></p>

        <p id="citation-261"><sup>261</sup> Перечисление небуддийских терминов для обозначения субъекта («атман», «пуруша», «пудгала») подчеркивает, что шраваки подсознательно придерживаются некой тонкой индивидуальной сущности. Очищая сознание от грубых эгоцентрических движений ума, они продолжают наделять содержанием саму нирвану как пространство, куда уходит освобожденный субъект. Полное раскрытие природы явлений требует преодоления этих остаточных ментальных опор.<a href="#ref-261" class="citation-back">↩</a></p>

        <p id="citation-262"><sup>262</sup> <em>aniryāṇa-niryāṇa-buddhi</em> — убеждение в наличии освобождения там, где его нет. Познавательный тупик, возникающий при остановке на этапе личного успокоения. Сутра рассматривает практику шраваков как подготовительную, критикуя придание абсолютного положения промежуточному плоду. Этот плод является лишь заблуждением ума (<em>citta-vibhrama</em>). Без постижения безопорности всех элементов опыта их освобождение остается незавершенным.<a href="#ref-262" class="citation-back">↩</a></p>

        <p id="citation-263"><sup>263</sup> <em>svabhāva-niḥsvabhāva-dharma-abhisamaya-gotra</em> — род постижения собственной природы и отсутствия собственной природы явлений. Этот тип реализации удерживает срединный взгляд йогачары. Дхармы лишены независимой сущности на уровне ментальных измышлений, но проявляются как относительный поток восприятия. Бодхисаттва этого рода видит изменчивую ткань причин и условий, что позволяет его уму не цепляться за существование объектов, а распознавать их как проекции ума.<a href="#ref-263" class="citation-back">↩</a></p>

        <p id="citation-264"><sup>264</sup> <em>adhigama-sva-pratyātmārya-abhisamaya-gotra</em> — род постижения личного благородного достижения. Понятие указывает на то, что освобождающее знание невозможно перенять из чужих слов или священных текстов. Оно открывается исключительно как глубоко личный, недвойственный созерцательный опыт. Принадлежность к этому роду означает, что мудрость практикующего полностью достоверна для него самого, поскольку истинная суть явлений проживается им как прямое, свободное от двойственности осознавание.<a href="#ref-264" class="citation-back">↩</a></p>

        <p id="citation-265"><sup>265</sup> <em>bāhya-buddhakṣetra-udārya-abhisamaya-gotra</em> — род постижения внешних земель Будд и их величия. Хотя учение подчеркивает, что весь видимый мир является проявлением ума, чистые земли Будд рассматриваются здесь как измерения сострадания. Осуществляя их величие, бодхисаттва преодолевает стремление к эгоистическому покою. Он обретает способность проявляться в любых мирах ради блага существ, воспринимая внешние условия как пластичное пространство для применения искусных методов.<a href="#ref-265" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-266"><sup>266</sup> <strong>«Благословение Татхагат»</strong>, <strong>«сила поддержания»</strong> (<em>tathāgatādhiṣṭhāna</em>) — проявление недвойственности ума бодхисаттвы и Татхагат на уровне Таковости (<em>tathatā</em>). Татхагаты не рассматривают существ как отдельных, обособленных, их сострадательная поддержка действует непрерывно, создавая условия для прекращения ментального различения даже у тех, кто временно отвратился от учения.<a href="#ref-266" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-267"><sup>267</sup> Бодхисаттва реализует «непребывающую нирвану» (<em>apratiṣṭhita-nirvāṇa</em>), которая не является ни сансарой, ни бездейственным покоем.<a href="#ref-267" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-268"><sup>268</sup> <strong>«Три признака собственных природ»</strong> (<em>svabhāva-lakṣaṇa-traya</em>) — воображаемая природа (<em>parikalpita</em>) (мир двойственности и имен), зависимая природа (<em>paratantra</em>) (поток причин и условий) и совершенная природа (<em>pariniṣpanna</em>) (Таковость). При этом важно понимать, что <em>parikalpita</em> — единственная полностью иллюзорная природа; <em>paratantra</em> — условно реальна (поток причин существует, но лишён собственной природы); <em>pariniṣpanna</em> — совершенна, ибо есть сама Таковость, свободная от наложений.<a href="#ref-268" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-269"><sup>269</sup> <strong>Образ-знак</strong> (<em>nimitta</em>) — метка качества-характеристики, которую наш ум накладывает на поток опыта. В системе пяти дхарм <em>нимитта</em> — первая: за ней следуют <em>имя</em> (<em>nāma</em>), <em>различение</em> (<em>vikalpa</em>), <em>правильное знание</em> (<em>samyag-jñāna</em>) и Таковость (<em>tathatā</em>). Первые три принадлежат сфере ложного воображения; последние два — сфере освобождения. Если «имя» (<em>nāma</em>) — это ярлык в языке, то «признак» — это то, что мы «видим» как плотную характеристику явления: его цвет, форму, твердость или протяженность. Ум выхватывает из безбрежного океана <em>Алайи</em> отдельные качества и «замораживает» их, создавая иллюзию устойчивого объекта. Без образа-знака ум не мог бы «схватить» поток восприятия. Мы привязываемся не к явлениям, а к их образам-знакам (приятное, постоянное, «мое»). Именно <em>нимитта</em> делает возможной двойственность «субъекта» и «объекта», создавая поле для работы различающего сознания (<em>викальпы</em>). Практика бодхисаттвы направлена на <em>анимитту</em> — «без-образность - без-знаковость».<a href="#ref-269" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-270"><sup>270</sup> <strong>«Основа, образ-знак, признак и внешняя форма»</strong> (<em>vastu-nimitta-lakṣaṇa-ākāra</em>) — В <strong><em>Ланкаватаре</em></strong> эта цепочка раскрывает процесс ложного воображения-представления (<em>abhūta-parikalpa</em>). Будда показывает, как ум строит иллюзию, последовательно наделяя её деталями: <em>Васту</em> (<em>vastu</em>) — «Основа» или «точка фиксации», первичное выделение в океане <em>Алайи</em>. Ум «выхватывает» некое ментальное пятно, принимая его за независимую «вещь». <em>Нимитта</em> (<em>nimitta</em>) — «образ-знак». На выбранную основу ум накладывает общую метку (например, «зримое» или «твёрдое»). Это — первый импульс выделения объекта из фона. <em>Лакшана</em> (<em>lakṣaṇa</em>) — признак или «специфическая характеристика». Здесь объект обретает детальные качества: цвет, размер, плотность. Это этап «раскрашивания» ментального образа, придающий ему уникальность. <em>Акара</em> (<em>ākāra</em>) — «Внешняя форма» или «вид». Финальная стадия, на которой объект предстаёт перед сознанием как завершённая, оформленная и «внешняя» фигура. Именно здесь формируется окончательная вера в то, что мир существует «снаружи».<a href="#ref-270" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-271"><sup>271</sup> <strong>«Признак привязанности к именам»</strong> (<em>nāma-abhiniveśa-lakṣaṇa</em>) — он описывает лингвистический плен сознания. Слово «имя» (<em>nāma</em>) здесь означает не только названия предметов, но и все понятия, которыми мы пользуемся. Ум обладает безначальной привычкой (<em>vāsanā</em>) наделять слова статусом значимости. Как только мы даем явлению имя, мы мгновенно приписываем этому слову плотную, неизменную суть. Термин <em>абхинивеша</em> (упорствование, вязкая привязанность) указывает на то, что сознание «прикипает» к именам и начинаем взаимодействовать с миром «ярлыков». Но имена — это лишь условные соглашения (<em>saṃketa</em>), не имеющие под собой никакой основы (<em>vastu</em>).<a href="#ref-271" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-272"><sup>272</sup> <strong>«Признак привязанности к имени, основе и образу-знаку»</strong> (<em>nāma-vastu-nimitta-abhiniveśa-lakṣaṇa</em>) — финальный этап цепи ложного воображения: ум склеивает имя (<em>nāma</em>, например, «кувшин») с чувственными признаками (<em>nimitta</em> — форма, цвет, твёрдость) и рождает иллюзию самостоятельного объекта (<em>vastu</em>). Эта «склейка» создаёт веру в существование внешнего мира, обладающего собственной сутью, тогда как на деле за именами и формами — лишь поток опыта, лишённый основы. Распознав этот механизм, бодхисаттва видит мир как прозрачную игру ума — «словесную химеру, в которой нет ни явлений, ни «схватывающего» их.<a href="#ref-272" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-273"><sup>273</sup> <strong>«Внешние и внутренние дхармы»</strong> (<em>bāhyādhyātma-dharma</em>) — привязанность к объектам не ограничивается внешним миром. Ум «овеществляет» даже психические состояния — мысли, ощущения, самоощущение — наделяя их ложной плотностью и превращая в объекты обладания.<a href="#ref-273" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-274"><sup>274</sup> <strong>«Распознавание собственных и общих признаков во внешних и внутренних дхармах»</strong> (<em>sva-sāmānya-lakṣaṇa-parijñāna-avabodha</em>) — Будда указывает на два типа признаков, за которые цепляется ум:<br>— собственные признаки (<em>sva-lakṣaṇa</em>) — качества, кажущиеся «уникальными»: твёрдость земли, текучесть воды, черты лица. Они принимаются как внутренние свойства явлений, наделяя их кажущейся собственной природой (<em>svabhāva</em>);<br>— общие признаки (<em>sāmānya-lakṣaṇa</em>) — универсальные категории: «все кувшины», «все люди», «всё непостоянное». Это уровень абстрактного, обобщающего мышления, где ум группирует опыт по схемам, категориям, группам.<br>Здесь <em>parijñāna</em> и <em>avabodha</em> используются иронически — это не истинное постижение, а самоуверенное «знание» различающего ума, принимающего свои классификации за подлинное положение дел.<a href="#ref-274" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-275"><sup>275</sup> Процесс построения «плотной реальности» разворачивается в строгой последовательности. Всё начинается с внутреннего «зуда» неведения (<em>ajñāna</em>) — основополагающей слепоты, неспособности распознать в текущем опыте его истинную, пустотную природу (<em>шуньяту</em>). Это неведение направляется кармой —  устойчивостью прошлых привычек — и подпитывается жаждой (<em>tṛṣṇā</em>). Жажда заставляет сознание «выбрасываться» вовне в поисках опоры, превращая покой океана <em>Алайи</em> в движение активных сознаний. Когда органы чувств встречаются с потоком данных, происходит мгновенное «слипание» (<em>abhiniveśa</em>). Ум не просто отражает форму, он «хватается» за неё (<em>grahaṇa</em>), наделяя статусом независимого объекта. В этот момент возникает разделение на «воспринимающего» и «воспринимаемое». Именно процесс захвата признака «овеществляет» пустотный опыт, придавая ему видимую плотность и внешнее положение. В ответ на акт захвата сознание-хранилище (<em>Алайя-виджняна</em>) мгновенно развёртывает  иллюзию — целостное обитель-вместилище (<em>bhājanadehālaya</em>), объединяющую в себе внешний материальный мир-сосуд (<em>bhājana</em>) и тело (<em>deha</em>). Важнейшее утверждение <strong><em>Ланкаватары</em></strong> состоит в том, что тело не находится в мире, и мир не находится вне тела. Оба — равноправные проекции одного ума (<em>svacitta-dṛśya</em>). Это единое явление, которое ошибочно разделяется на «внутреннее» и «внешнее». Итогом становится «воображение различениями собственного ума». Использование двойного корня «викальп» в оригинале указывает на взаимообращающийся характер иллюзии. Ум не просто выдумывает мир; он структурирует его через бесконечные разделения (субъект/объект, приятное/болезненное, я/другой). Эти различения (<em>vikalpa</em>) наслаиваются друг на друга, создавая вязкую сеть понятий, в которой ум запутывается, как в паутине, принимая плоды собственного воображения за независимую и твердую реальность.<a href="#ref-275" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-276"><sup>276</sup> Постижение отсутствия «я» в личности (<em>pudgala-nairātmya</em>) раскрывается через ряд точных метафор, обнажающих кажущуюся устойчивость существования. Иллюзия «дления» личности во времени объясняется через образы реки, ростка, светильника, ветра и облака. Подобно реке, которая кажется неизменной, хотя в каждый миг в ней течет новая вода, или ростку, который видится единым процессом, являясь лишь непрерывной сменой состояний, — так и совокупность <em>скандх</em> есть лишь мгновенная преемственность (<em>kṣaṇa-paramparā</em>). Как пламя светильника создаёт видимость одного огня через череду сгорающих частиц масла, или как ветер и облако постоянно меняют форму, не имея какого-либо центра, так и личность распадается и пересобирается в каждое мгновение. Ум, подобно обезьяне, не может остановиться ни на секунду, вечно прыгая по веткам объектов, а суетливость сознания, инстинктивно ищущего, к чему бы «прилипнуть» в поисках удовольствия, уподоблена мухе. Сами же стремления ненасытны, словно бушующий огонь: чем больше «дров» в виде впечатлений в него бросаем, тем сильнее разгорается жажда, поддерживая горение этой иллюзии. Цикличность и автоматизм нашего существования уподоблены колодезному колесу (<em>araghaṭṭa</em>) с прикрепленными к нему кувшинами. Как колесо принудительно вращается, то опуская кувшины в мутную глубину, то поднимая их к поверхности, так и личность вращается в круговороте сансары. Это движение не управляется волей «я», оно движимо лишь тяжестью накопленных отпечатков безначального многообразия (<em>anādi-prapañca-vāsanā</em>). В конечном итоге Будда лишает личность самой «живости», уподобляя её механической кукле (янтра) или магической иллюзии. Внутри этого аппарата нет «души»; «кукла» движется лишь потому, что натянуты нити кармы и дуют ветры прошлых привычек. Это «оживлённый труп». Знание, прозревающее эти признаки, именуется знанием об отсутствии «я» в личности. Оно превращает «хозяина жизни» в прозрачный, закономерный и никем не управляемый поток элементов, окончательно лишая его ложной плотности и власти эго.<a href="#ref-276" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-277"><sup>277</sup> Будда здесь совершает двойное отрицание, ведущее к полному растворению иллюзии плотности <em>скандх</em>. Первый уровень — <em>pudgala-nairātmya</em>: <em>скандхи</em> лишены «я» — нет хозяина потока, есть лишь совокупность факторов, движимых причиной, кармой и жаждой. Второй уровень — <em>dharma-nairātmya:</em> сами <em>скандхи</em> лишены собственных (<em>sva-lakṣaṇa</em>) и общих признаков (<em>sāmānya-lakṣaṇa</em>). Их «твёрдость», «форма», «непостоянство» — проекции различающего ума. Термин — <em>abhūta-parikalpa</em> («ложное воображение несуществующего») указывает, что <em>скандхи</em> хотя и пусты, но воображаются как плотные.<a href="#ref-277" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-278"><sup>278</sup> Отрицание возникновения в данном фрагменте направлено против идеи обособленного появления дхарм. Явления даны восприятию исключительно в меняющемся сочетании условий (<em>samādhyavasthā</em>). По причине такой зависимости от совокупности взаимосвязанных факторов они именуются «невозникшими» и «лишёнными собственной природы». Довод об отсутствии непрерывности (<em>prabandha-abhāva</em>) указывает на учение о мгновенности (<em>kṣaṇika-vāda</em>), согласно которому поток опыта состоит из отдельных сменяющихся вспышек различения. Именно наблюдаемая изменчивость (<em>anyathā-bhāva</em>) служит созерцательным свидетельством отсутствия установленной собственной природы у всех явлений.<a href="#ref-278" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-279"><sup>279</sup> Принцип недвойственности (<em>advaya</em>) раскрывается здесь через взаимную соотнесённость понятийных пар, элементы которых обнаруживаются исключительно в сопоставлении друг с другом. Будда переносит этот принцип на пару «сансара и нирвана», указывая на отсутствие у них обособленной собственной природы. На уровне различающего восприятия эти состояния исключают друг друга, поскольку обусловлены взаимоотличными основаниями различения (<em>vilakṣaṇa-hetu</em>). Разделение на мир омрачений и освобождение обнаруживается лишь на уровне условных обозначений (<em>prajñapti</em>) ума. Практика йоги направлена на преодоление цепляния за эти крайности, что позволяет удерживать срединную направленность познания вне умозрительных утверждений о тождестве или различии дхарм.<a href="#ref-279" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-280"><sup>280</sup> Данный фрагмент предостерегает от крайностей полного уничтожения (<em>uccheda</em>) и вечного существования дхарм (<em>śāśvata</em>). Утверждение об иллюзорности сансары согласуется с законом кармы, поскольку отпечатки прошлых действий (<em>vāsanā</em>) продолжают обусловливать новые вспышки различения ума. Пространство, нирвана и прекращение признаются «непроизведёнными» исключительно в значении их непорожденности причинно-следственными условиями. Благородные воспринимают эти состояния очищенными от крайностей существования и несуществования. Обозначение нирваны как «непроизведённой» (<em>akṛtaka</em>) служит искусным средством, предотвращающим увязание ума в ложных представлениях о бытии.<a href="#ref-280" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-281"><sup>281</sup> Вопрос Махамати касается ловушки причинно-условного мышления. В индийской философии велись споры о том, возникают ли явления последовательно (<em>anukrama</em>) или одновременно (<em>yugapad</em>). Однако с позиции учения «только-ума» оба представления остаются зависимыми от различения существования и несуществования, поскольку предполагают реальное возникновение явлений. Махамати просит разъяснить признак причин и условий (<em>hetu-pratyaya</em>) для того, чтобы освободиться от этих воззрений. Постижение причинно-условности ведёт к пониманию того, что ни одно явление не обладает собственной природой (<em>niḥsvabhāva</em>), а потому ничто не возникает ни последовательно, ни одновременно.<a href="#ref-281" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-282"><sup>282</sup> Внешнее зависимое возникновение (<em>bāhya-pratītyasamutpāda</em>) раскрывается здесь через совокупность условий (<em>pratyaya</em>): материального основания (глины) и сопутствующих факторов (гончарного круга, усилий человека и т.д.). Перечисляя эти примеры, Будда показывает, что ни одно явление не обнаруживается как существующее само по себе или независимо от условий. Формула «предшествующего и последующего» (<em>pūrvottarottara</em>) указывает на условно различаемую последовательность возникновения, посредством которой ум связывает отдельные моменты опыта в представление о непрерывном процессе. Тем самым зависимое возникновение раскрывается как взаимозависимое развертывание лишённых собственной природы явлений.<a href="#ref-282" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-283"><sup>283</sup> Внутреннее зависимое возникновение (<em>ādhyātmika-pratītyasamutpāda</em>) описывает обусловленное развертывание опыта через неведение (<em>avidyā</em>), жажду (<em>tṛṣṇā</em>) и карму. Возникающие из них <em>скандхи</em>, <em>дхату</em> и <em>аятаны</em> также именуются «зависимым возникновением», поскольку сами не обладают самостоятельной природой. Утверждение об их «неразличимости» (<em>aviśiṣṭa</em>) указывает на отсутствие окончательной границы между обусловливающими факторами и обусловленными проявлениями. Однако невежды (<em>bāla</em>) мысленно разделяют этот единый поток зависимого возникновения на отдельные и самостоятельно существующие элементы опыта.<a href="#ref-283" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-284"><sup>284</sup> Шесть причин (<em>hetu</em>) описывают различные способы развертывания зависимого возникновения в потоке различения. Первые пять причин раскрывают процессы возникновения, связывания, поддержания и проявления воспринимаемых дхарм — от скрытого потенциала до их различимого обнаружения в опыте. Проявляющая причина (<em>vyañjana-hetu</em>) особенно подчёркивает, что явления становятся различимыми лишь в зависимости от акта различения (<em>vikalpa</em>). Шестая причина — причина нейтральности (<em>upekṣā-hetu</em>) — описывает прекращение вовлечённости ума в поддержание потока различений. С прекращением этой деятельности прерывается непрерывность потока (<em>prabandha</em>), что ведёт к возникновению состояния без различений (<em>avikalpa</em>).<a href="#ref-284" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-285"><sup>285</sup> Учение о четырёх видах речи в сутре показывает, каким образом язык подменяет непосредственное переживание сетью умозрительных различений.<br>
            • Речь признаков овеществляет воспринимаемое, закрепляя измышленные умом образы-знаки (<em>nimitta</em>) как будто бы самостоятельные сущности.<br>
            • Речь сновидений показывает способность языка обращаться со следами отсутствующих объектов, выстраивая замкнутые иллюзорные миры.<br>
            • Речь косных различений (<em>dauṣṭhulya</em>) раскрывает эмоциональную природу языка, воспроизводящую умственную привязанность к прошлой вражде и деяниям врагов.<br>
            • Речь безначальных различений укоренена в глубинных слоях скрытых отпечатков (<em>vāsanā</em>), где многообразие понятий (<em>prapañca</em>) поддерживает разделение на воспринимающее и воспринимаемое.<br>
            Бодхисаттва должен осознать, что между «выражением» (<em>abhilāpa</em>) и «выражаемым» (<em>abhilāpya</em>) нет нерушимой связи; это разделение — лишь работа различающего ума, создающая иллюзию объективной реальности.<a href="#ref-285" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-286"><sup>286</sup> Здесь разбирается, как речь возникает из сочетания телесных условий артикуляции (<em>samavāya</em>) и построения понятий (<em>vikalpa</em>). Ответ на вопрос о соотношении речи и построения понятий опирается на принцип зависимого возникновения: речь не существует самостоятельно, поскольку обусловлена деятельностью ума, но и не совпадает с построением понятий полностью, так как обладает особой способностью выражать смысл (<em>arthābhivyaktitvāt</em>). Заблуждение возникает тогда, когда ум принимает выражение (<em>abhilāpa</em>) за само выражаемое (<em>abhilāpya</em>), превращая словесные обозначения в якобы самостоятельно существующие сущности. Постижение того, что речь не является ни полностью отличной от ума, ни тождественной ему, позволяет освободиться от привязанности к именам и словесным формам учения.<a href="#ref-286" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-287"><sup>287</sup> Здесь проводится различие между словом и высшим смыслом (<em>paramārtha</em>). Речь способна лишь направлять сознание к личному благородному постижению. Она не способна выразить саму таковость. Поскольку всякое словесное выражение возникает из сочетания причин и условий, оно не может явить то, что свободно от возникновения и исчезновения. Образ глиняных игрушек показывает значение искусных средств (<em>upāya</em>): слова, признаки и учения служат лишь временными указателями. Они подводят ум к пределу истинности (<em>bhūtakoṭi</em>), который раскрывается только в личном благородном постижении.<a href="#ref-287" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-288"><sup>288</sup> В этом фрагменте Будда последовательно разрушает представление о самостоятельной реальности воспринимаемого. Метафора миража показывает, как страсть, гнев и заблуждение заставляют живых существ устремляться к тому, убегать от того, игнорировать то, чего в действительности нет. Метафора города гандхарвов раскрывает, что видимость мира возникает из привязанности к безначальным отпечаткам представлений. Метафора сна показывает, что даже после исчезновения воспринимаемого ум продолжает удерживать его как действительно существующее. Главный смысл этого раздела заключён в <em>svacittadṛśyamātrānavabodha</em> — непонимании того, что всё воспринимаемое есть лишь видимое собственным умом. Именно это неведение порождает цепляние за крайности существования и несуществования, тождественности и нетождественности.<a href="#ref-288" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-289"><sup>289</sup> Этот ряд примеров — картина, мнимые волоски, огненное колесо и водяные пузыри — показывает способ явления дхарм в учении Йогачары. Они не являются ни подлинно существующими (<em>sat</em>), ни полностью несуществующими (<em>asat</em>). Как водяные пузыри кажутся хрусталём лишь вследствие ошибки восприятия, так и мир воспринимается как состоящий из внешних объектов из-за отпечатков (<em>vāsanā</em>) и ложных различений. Цепляние за крайности «существующего» и «несуществующего» уводит от срединного пути. Подлинное видение состоит в понимании того, что всё воспринимаемое есть лишь видимое собственным умом (<em>svacittadṛśya</em>) и не обладает неизменной сущностью, подобно мнимому колесу, возникающему от вращения горящей лучины.<a href="#ref-289" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-290"><sup>290</sup> Цепочка метафор — мираж, пучки волос, огненное колесо, отражение, механическая кукла, призрак, сын бесплодной женщины — указывает на призрачный характер воспринимаемых явлений и одновременно раскрывает способ освобождения. Ключевым здесь является принцип «клин клином вышибают»: хотя условные представления и различения сами по себе не являются истиной, они служат средствами для устранения более грубых заблуждений. Когда цепляние за существование и несуществование прекращается, сами эти средства более не удерживаются. Поэтому мудрец «не выдвигает никаких утверждений» (<em>na kiṃcit pratijānate</em>), не становясь ни на сторону существования, ни на сторону несуществования.<a href="#ref-290" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-291"><sup>291</sup> <strong>Четыре вида <em>дхьяны:</em></strong><br>
        <strong>I. <em>Дхьяна, свойственная невеждам</em></strong> (<em>bālopacārika-dhyāna</em>)<br>

        Термин <em>bāla</em> («дитя», «незрелый», часто переводимый как «невежда»)  в контексте <strong><em>Ланкаватары</em></strong> обозначает существо, ещё не постигшее недвойственную природу ума и продолжающее воспринимать реальность через цепляние за признаки (<em>lakṣaṇa</em>). <em>Upacāra</em> означает «практика, соответствующая определённому уровню»; поэтому выражение <em>bālopacārika-dhyāna</em> указывает на созерцание, свойственное тем, кто ещё не вышел за пределы двойственного восприятия.<br>

        Несмотря на название, эту <em>дхьяну</em> практикуют шраваки и пратьекабудды, достигшие значительных плодов. Их «невежество/незрелость» заключается в ограниченности воззрения: они реализуют отсутствие «я» в личности (<em>pudgala-nairātmya</em>), но их <em>дхьяна</em> не достигает постижения отсутствия «я» в дхармах (<em>dharmanairātmya</em>). Поэтому их созерцание всё ещё удерживается в сфере признаков (<em>lakṣaṇa</em>) и образов.<br>

        Санскритский составной термин перечисляет объекты такой практики: (а) отсутствие «я» в личности (<em>pudgala-nairātmya</em>); (б) собственные и общие признаки явлений (<em>sva-sāmānya-lakṣaṇa</em>); (в) нечистота тела и созерцание телесного распада (<em>aśubha-bhāvanā</em>); (г) непостоянство, страдание и нечистота (<em>anitya, duḥkha, aśubha</em>). Практика разворачивается последовательно (<em>pūrvottarottara</em>) вплоть до прекращения восприятия (<em>saṃjñā-nirodha</em>; <em>nirodha-samāpatti</em>). Однако ключевая проблема такой <em>дхьяны</em> — привязанность (<em>abhiniveśa</em>) к самим признакам: практикующий продолжает удерживать мысль «это именно так и не иначе», а потому даже созерцание непостоянства или нечистоты остаётся формой тонкого цепляния.<br>

        Цзунми в «Предисловии к своду всех источников о дхьяне» помещает эту <em>дхьяну</em> на третью ступень своей пятичленной классификации — «дхьяна Малой колесницы». Она признаётся полезной и очищающей, но всё ещё не достигающей полного постижения того, что всё воспринимаемое есть лишь проявление ума (<em>cittamātra</em>).<br><br>

        <strong>II. <em>Дхьяна исследования смысла</em></strong> (<em>arthapravicaya-dhyāna</em>)<br>

        <em>Artha</em> означает «смысл», «предмет постижения», «цель», а <em>pravicaya</em> — «тщательное исследование», «аналитическое рассмотрение». Эта <em>дхьяна</em> знаменует переход от созерцательной дисциплины шраваков к собственно махаянскому исследованию природы дхарм.<br>

        Процесс исследования разворачивается в два этапа: (1) сначала практикующий утверждается в отсутствии «я» в личности (<em>pudgala-nairātmya</em>), исследуя собственные и общие признаки индивидуальности (<em>sva-sāmānyalakṣaṇa</em>), чтобы окончательно устранить представление о внутреннем субъекте или «владельце» <em>скандх</em>; (2) затем он превосходит крайности внешних учений тиртхиков (<em>bāhyatīrthakarasvaparobhayābhāvaṃ kṛtvā</em>), отвергая воззрения о «я», «другом» и «обоих». После этого двойного превосхождения — хинаянского воззрения и крайностей тиртхиков — практик переходит к последовательному исследованию отсутствия «я» в дхармах (<em>dharmanairātmya</em>) и признаков ступеней бодхисаттвы (<em>bhūmi-lakṣaṇa</em>, <em>daśabhūmi</em>). Китайские переводы, особенно версия Гунабхадры, также подчёркивают эту двуступенчатую структуру: сначала преодоление представления о личности, затем — устранение представления о «я» в дхармах.<br><br>

        <strong>III. <em>Дхьяна опоры на Таковость</em></strong> (<em>tathatālambana-dhyāna</em>)<br>

        Ключевой фрагмент — <em>parikalpita-nairātmya-dvaya-vikalpa-yathābhūtāvasthānād apravṛtter vikalpasya</em> — буквально означает: «вследствие пребывания в реальности как она есть (<em>yathābhūta-avasthāna</em>) прекращается развёртывание построений понятий (<em>vikalpa</em>), воображающих двойное отсутствие "я"». Речь идёт не о насильственном подавлении мышления. Имеется в виду состояние, при котором различение больше не возникает само собой — подобно тому как волны не поднимаются на совершенно спокойной поверхности воды.<br>

        Особенно важно, что здесь преодолевается даже привязанность к самому понятию отсутствия «я». Пока «не-я» удерживается как объект мышления, сохраняется тонкое двойственное построение. Эта установка характерна для йогачаринского понимания созерцания: даже пустотность (<em>śūnyatā</em>) не должна превращаться в новый предмет цепляния.<br>

        Термин <em>ālambana</em> («опора», «объект сосредоточения») здесь употребляется парадоксальным образом: Таковость (<em>tathatā</em>) не является объектом в обычном смысле. Она становится «опорой» лишь потому, что после прекращения всех построений понятий не остаётся ничего, кроме самой реальности как она есть.<br><br>

        <strong>IV. <em>Дхьяна Татхагаты</em></strong> (<em>tāthāgata-dhyāna</em>)<br>

        Высшая форма созерцания описывается сложным составным выражением: <em>tāthāgatabhūmyākārapraveśaṃ pratyātmāryajñānalakṣaṇatrayasukhavihārācintyasattvakṛtyakaraṇatayā</em>. Комментаторская традиция обычно выделяет здесь три аспекта:<br>
        (а) вхождение в образ ступеней Татхагаты (<em>tāthāgata-bhūmi-ākāra-praveśa</em>);<br>
        (б) пребывание в блаженстве, связанном с тремя признаками личного благородного знания (<em>pratyātmāryajñāna-lakṣaṇa-traya</em>) — поздняя традиция соотносила их либо с тремя вратами освобождения (<em>śūnyatā, animitta, apraṇihita</em>), либо с тремя телами Будды (<em>trikāya</em>);<br>
        (в) совершение непостижимых деяний ради живых существ (<em>acintya-sattva-kṛtya</em>) — спонтанная активность Будды, не обусловленная намеренным усилием (<em>anābhoga</em>).<br>

        Цзунми отождествляет эту <em>дхьяну</em> с «дхьяной высшей колесницы» и связывает её с чаньской передачей Бодхидхармы как непосредственным постижением природы ума. Шэньхуэй, комментируя это состояние через <strong><em>Вималакирти-сутру</em></strong>, подчёркивает принцип непребывания (<em>anupalambha</em>; кит. 無住 <em>wu-zhu</em>): Татхагата не приходит, не уходит и нигде не пребывает.<br><br>

        В гатхе 160 выражение <em>padma-pātāla-sādṛśam</em> представляет трудность для точного толкования. Слово <em>pātāla</em> означает «подземная глубина», «нижний мир», «бездна». В контексте перечисления медитативных образов-знаков (<em>nimitta</em>) — солнца, луны, огня и неба — это выражение, вероятно, указывает на глубокое багровое свечение, подобное лотосу, возникающему во тьме. Речь идёт не о космологическом описании, а о внутренних визуальных знаках, возникающих в созерцании.<br>

        В гатхе 161 слово <em>nimitta</em> означает «образ-знак», «медитативное видение», «опорный признак сосредоточения». Согласно <strong><em>Ланкаватаре</em></strong>, привязанность даже к тончайшим медитативным знакам остаётся препятствием. Поэтому говорится, что эти <em>nimitta</em> способны «уводить на пути тиртхиков» или «низвергать» практикующего в область шраваков и пратьекабудд. Даже глубокое <em>самадхи</em>, если оно основано на цеплянии за видения и формы, остаётся ограниченным состоянием сознания.<br>

        В гатхе 162 выражение <em>nimittaṃ tathatānugam</em> допускает несколько прочтений. Его можно понимать как «образ-знак, следующий за Таковостью» — то есть возникающий после реализации Таковости, — или как «образ-знак, согласующийся с Таковостью». Китайский перевод Гунабхадры подчёркивает второе значение: прикосновение Будд к голове йогина понимается как своего рода «печать» (<em>mudrā</em>), удостоверяющая подлинность реализации.<br><br>

       <em>Текстовые источники</em>: Vaidya, P. L. (ed.). <em>Saddharmalaṅkāvatārasūtram</em>. Buddhist Sanskrit Texts, no. 3. Darbhanga: Mithila Institute, 1963. — Guṇabhadra (Гунабхадра), trans. <em>Laṅkāvatāra-sūtra</em> (四卷本), ок. 443 г. <em>Taishō Tripiṭaka</em>, vol. 16, no. 670. — Bodhiruci (Бодхиручи), trans. (十卷本). <em>Taishō Tripiṭaka</em>, vol. 16, no. 671. — Śikṣānanda (Шикшананда), trans. (七卷本). <em>Taishō Tripiṭaka</em>, vol. 16, no. 672.<br>

