        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-292"><sup>292</sup> <em>sarva-vijñāna-svabhāva-vāsanā-ālaya-manas-manovijñāna-dṛṣṭi-vāsanā-parāvṛtti</em> — этот единый составной термин описывает «поворот основы» (<em>parāvṛtti</em>) как одновременное коренное преобразование двух уровней сансарического сознания. Первый уровень — <em>sarva-vijñāna-svabhāva-vāsanā</em> — включает привычные следы (<em>vāsanā</em>), из-за которых все виды сознания (<em>sarva-vijñāna</em>) воспринимают свои объекты как обладающие собственной природой (<em>svabhāva</em>). Настоящее положение указывает исключительно на глубинную привычку восприятия, автоматически схватывающую явления как независимо существующие. Это относится прежде всего к работе пяти чувственных сознаний, которые сами по себе кармически нейтральны, но поддерживают сансарическое переживание через привычное закрепление объектов в качестве реально существующих. Второй уровень — <em>ālaya-manas-manovijñāna-dṛṣṭi-vāsanā</em> — охватывает отпечатки воззрений (<em>dṛṣṭi-vāsanā</em>), связанные с тремя внутренними уровнями сознания — сознанием-хранилищем (<em>ālaya</em>), <em>манасом</em> (<em>manas</em>) и различающим сознанием (<em>manovijñāna</em>). Именно здесь возникают присвоение опыта как «я», построение субъектно-объектной двойственности, философские воззрения, различения (<em>vikalpa</em>) и кармически обусловленное развёртывание сансары. Таким образом, Будда определяет нирвану через качественное преобразование самого процесса сансарического восприятия: угасание как привычки видеть внешне «существующие» объекты, так и процессов выработки воззрений двойственности. Это полностью соответствует йогачаринской доктрине <em>āśraya-parāvṛtti</em> — «переворота основы», при котором радикально меняется сам способ работы сознания. Фактически здесь сжата вся методология Пути, описывающая динамику и способ достижения освобождения через прекращение развертывания обоих уровней отпечатков. Выражение <em>nirvāṇa-gati-svabhāva-śūnyatā-vastu-gocaram</em> раскрывает уже содержательное поле этого переживания. Слово <em>gati</em> здесь означает одновременно «ход», «путь», «способ раскрытия» и «достижение». После поворота основы сфера восприятия (<em>vastu-gocara</em>) переживается как пустая от собственной природы (<em>svabhāva-śūnyatā</em>). Это указывает исключительно на прекращение наложения самостоятельной природы на воспринимаемое, полностью исключая как уничтожение явлений, так и признание некой новой надмирской сущности. По этой причине Нирвана в <strong><em>Ланкаватаре</em></strong> утверждается в качестве радикального преображения способа восприятия и переживания реальности.<a href="#ref-292" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-293"><sup>293</sup> Этот отрывок — один из наиболее философски насыщенных фрагментов <em>Ланкаватары</em>. Махамати выдвигает серию возражений против буддийского учения о зависимом возникновении (<em>pratītyasamutpāda</em>), воспроизводя реальную критику буддизма со стороны брахманистских школ, зафиксированную в полемических текстах (особенно в <em>Ньяя-сутрах</em> Гаутамы с комментарием Ватсьяяны; <em>Юкти-дипике</em> на <em>Санкхья-карике</em>, где критикуется буддийская доктрина мгновенности и причинности). Центральный пункт критики: буддизм, отрицая фундаментальную реальность (<em>dravya</em>), не может объяснить устойчивость причинно-следственных связей. Санкхья постулирует <em>Пракрити</em> как вечную, несотворённую первопричину (<em>pradhāna, mūla-prakṛti</em>), которая сама не возникла, но порождает все видоизменения (<em>vikāra</em>). Ньяя-вайшешика постулирует <em>Ишвару</em> как независимую действующую причину (<em>nimitta-kāraṇa</em>) и атомы (<em>paramāṇu</em>) как вечную материальную причину (<em>upādāna-kāraṇa</em>). Обе школы обвиняют буддизм в том, что отказ от абсолютной первопричины ведёт к <em>anavasthā-doṣa</em> (изъяну бесконечного регресса).<br>
        Ответ, сформулированный в <em>Ланкаватаре</em>, позднее станет одним из центральных мотивов виджнянавадинской и йогачаринской традиции (Дигнага, Дхармакирти, Шантаракшита): причинность не является непреложным свойством мира, а представляет собой способ связывания опыта в потоке сознания. Вопрос «что является абсолютной причиной мира» некорректен, поскольку «мир» как независимая от сознания реальность не существует. Существует лишь поток сознания (<em>vijñāna-santāna</em>), в котором одно содержание закономерно следует за другим — и эту закономерность мы, в силу привычных отпечатков (<em>vāsanā</em>), ошибочно проецируем «вовне» как «объективную причинность».<br>
        <strong>I. Структура возражения Махамати</strong><br>
        <strong>Первое обвинение: терминологическая подмена.</strong><br>
        Махамати утверждает, что Будда лишь переименовывает «причины» (<em>kāraṇa</em>) в «условия» (<em>pratyaya</em>), но по сути описывает то же самое, что и тиртхики: возникновение одного из другого. Разница — лишь в словах (<em>pratyaya-paryāya-antara</em> — «иной способ обозначения условий»), но не в самом учении.<br>
        Важно, что в индийской философии <em>kāraṇa</em> обозначает не просто «причину» в современном смысле, а причинное основание, рассматриваемое как реально производящее следствие. <em>Hetu</em> — причинный фактор или основание, а буддийское <em>pratyaya</em> («условие») сознательно избегает представления о причине как о самостоятельно существующем производящем основании: условие включено в процесс взаимозависимого возникновения и не существует само по себе. Именно поэтому Махамати обвиняет Будду в том, что тот лишь заменяет термин <em>kāraṇa</em> на <em>pratyaya</em>, не меняя сути причинной схемы.<br>
        Выражение <em>svanaya-prakṛtyavasthāna</em> здесь особенно сложно. Махамати упрекает Будду в том, что учение о зависимом возникновении ограничивается описанием причин и условий, но не раскрывает самого способа проявления явлений согласно буддийскому методу.<br>

        <strong>Второе обвинение: скрытая беспричинность (<em>ahetuvāda</em>).</strong><br>
        Формула «из неведения — формирующие факторы, из формирующих факторов — сознание…» (двенадцатичленная цепь зависимого возникновения) на самом деле является учением о беспричинности. Логика такова: если причина <strong>А</strong> сама обусловлена условием <strong>Б</strong>, условие <strong>Б</strong> — условием <strong>В</strong> и так до бесконечности, то абсолютной первопричины нет. Бесконечный регресс (<em>anavasthā</em>) равнозначен отсутствию причины вообще. Это классическое возражение школ, утверждающих реальное существование независимых сущностей: без независимой, несотворённой первопричины (как <em>Пракрити</em> в санкхье или <em>Ишвара</em> в ньяе) любое учение о причинности вырождается в беспричинность.<br>
        <strong>Третье обвинение: проблема одновременности и последовательности.</strong><br>
        Махамати указывает на классическую проблему: формула «при наличии этого возникает то» (<em>asmin sati idam bhavati</em>) логична только если причина и следствие существуют одновременно (<em>yugapat</em>). Но тогда нет порождения — они уже сосуществуют. Если же они последовательны (<em>krama-vṛtti</em>), то когда причина ещё есть, следствия ещё нет; а когда следствие возникло, причина уже прекратилась. Как же несуществующая причина может породить существующее следствие? Эта дилемма была центральной в индийской дискуссии о причинности (ср. спор <em>satkāryavāda</em> против <em>asatkāryavāda</em> в санкхье и ньяе)<br>
        <strong>Четвёртое обвинение: взаимная зависимость определений.</strong><br>
        У Будды «причина зависит от следствия, а следствие — от причины» (<em>kāraṇam api kāryāpekṣaṃ kāryam api kāraṇāpekṣam</em>). То есть то, что мы называем причиной, определяется через то, что оно производит (следствие); а следствие — через то, что его произвело (причину). Это взаимная опора понятий (<em>anyonya-āśraya</em>), а не подлинная причинность. Возникает «путаница причин и условий» (<em>hetupratyaya-saṃkara</em>) и «взаимный бесконечный регресс» (<em>anyonya-anavasthā</em>). У тиртхиков этой проблемы нет: причина (<em>Пракрити</em>, <em>Ишвара</em>) абсолютна, независима и сама не возникла (<em>a-pratītya-samutpanna</em>), но порождает всё остальное.<br>
        <strong>II. Ответ Будды: виджнянавадинское переосмысление</strong><br>
        Будда не отрицает возражений Махамати по существу. Вместо этого он указывает, что все эти проблемы возникают только при реалистическом понимании причинности — то есть если верить в подлинное существование внешних объектов, выступающих причинами и следствиями.<br>
        <strong>Ключ ответа: отсутствие противопоставляющей двойственности схватывающего и схватываемого.</strong><br>
        «Из Моего учения не следует беспричинность или смешение причин и условий, когда Я говорю: «При наличии этого возникает то». Поскольку отсутствуют воспринимаемое и воспринимающий (<em>grāhyagrāhakābhāvāt</em>) и имеется постижение того, что всё есть лишь воспринимаемое собственным умом (<em>svacittadṛśyamātrāvabodhāt</em>)». Здесь — суть виджнянавадинского переосмысления причинности. Зависимое возникновение в <strong><em>Ланкаватаре</em></strong> не является описанием объективного процесса во внешнем мире; это описание того, как в потоке ума одно содержание (<em>vijñapti</em>) обусловливает появление другого. Нет подлинных «причин» и «следствий» как внешних явлений — есть только последовательность содержаний ума, каждое из которых возникает в зависимости от предыдущего.<br>
        <strong>Разрешение проблемы одновременности и последовательности.</strong><br>
        Если причина и следствие суть содержания одного потока ума, тогда проблема их одновременности или последовательности во «внешнем времени» снимается сама собой. Один момент ума (<em>kṣaṇa</em>) переходит в другой через непрерывность потока (<em>santāna</em>), и потому формула «при наличии этого возникает то» описывает последовательное развёртывание опыта.<br>
        <strong>Разрешение проблемы бесконечного регресса.</strong><br>
        Обвинение в <em>ahetuvāda</em> (беспричинности) справедливо, если искать абсолютную первопричину во внешнем мире. Но виджнянавада не утверждает подлинности внешнего мира: «этот изъян касается лишь тех, кто привязан к двойственности субъекта и объекта и не понимает, что [так называемый] внешний [мир] лишён бытия и небытия (<em>bāhya-sva-viṣaya-bhāva-abhāva</em>)».<br>
        <em>bhāva-abhāva</em> — пара «бытие и небытие/явление и отсутствие явления». Виджнянавада отвергает не только вечность («внешний мир существует сам по себе»), но и уничтожение («внешнего мира совершенно нет»). Внешний мир — не реален и не нереален; он — лишь проявление ума (<em>vijñapti-mātra</em>). Поэтому вопрос о его «первопричине» оказывается некорректным.<br>
        <strong>Источники</strong><br>
        Современные исследования: Kalupahana David J. Causality: The Central Philosophy of Buddhism. Honolulu: University of Hawaii Press, 1975 (глава 9: «Criticisms and Replies»). — Westerhoff Jan. Nāgārjuna's Madhyamaka: A Philosophical Introduction. Oxford: OUP, 2009, ch. 3 (анализ буддийской критики субстанциалистской причинности). — Siderits Mark. Buddhism as Philosophy. Indianapolis: Hackett, 2007, ch. 5 (виджнянавадинская теория причинности).<a href="#ref-293" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-294"><sup>294</sup> Этот отрывок продолжает критику наивного реализма, начатую в подглаве 2.38. Там опровергалась объективная причинность (явления не порождают друг друга вне сознания); здесь — что слова не указывают на независимо существующие объекты. Обе критики направлены против веры в независимо существующие внешние объекты.<br><br>
        <strong>I</strong>. Возражение Махамати воспроизводит позицию языкового реализма, характерную для брахманистской традиции: существование слова доказывает существование обозначаемого объекта. Логика аргумента такова: если бы объектов не было, не было бы и слов для их обозначения; но слова есть — следовательно, объекты реальны. Эта позиция опиралась на представление о сакральности ведийского языка и основополагающей связи между именем и именуемым (<em>nāma-nāmin-sambandha</em>). То есть полагали, что слово не просто условный знак, но выражение сущности явления.<br>
        Буддийская позиция (как в <strong><em>Ланкаватаре</em></strong>, так и в других текстах традиции) утверждает условность языка: слова — это договорные обозначения (<em>saṃketa</em>), установленные по соглашению и привычке употребления, они не являются отражением реальной структуры мира. Нет необходимой связи между словом и объектом — связь устанавливается привычкой и договорённостью. Следовательно, из наличия слова нельзя вывести существование объекта.<br><br>
        <strong>II</strong>. Рога зайца, шерсть черепахи, сын бесплодной женщины (<em>śaśa-viṣāṇa</em>, <em>kūrma-roma</em>, <em>vandhyā-putra</em>) — классические буддийские примеры того, чего в природе нет и быть не может. О них можно говорить, но самих таких явлений нет. Это прямо опровергает утверждение: «раз есть слово — значит, есть и то, что оно обозначает».<br>
        Формула «ни явление, ни не-явление» (<em>na bhāvā nābhāvāḥ</em>) показывает, как следует понимать подобные утверждения: рога зайца не существуют в реальности, но и не являются абсолютным несуществованием, поскольку возникают в уме как воображаемые образы.<br><br>
        <strong>III</strong>. Слова — лишь один из многих способов передачи Дхармы. Будда перечисляет иные: взгляд, жесты, движение бровей, мигание глаз, мимика, зевота, кашель, воспоминание, трепет. Никакой неразрывной связи между словом и реальностью нет. Дхарма может передаваться различными способами — в том числе вне словесного выражения.<br>
        В земле Будды Самантабхадры, который называют «Немигающий Благоухающий», бодхисаттвы обретают высшую реализацию — стойкость в постижении не-возникновения дхарм — просто взирая друг на друга немигающими глазами. Здесь сама земля называется «Немигающий Благоухающий», и постижение в ней осуществляется через немигающее созерцание. Это указание на возможность непосредственного постижения вне словесного обозначения.<br>
        Такое постижение невыразимо словами — слова способны лишь указывать направление. Для продвинутых практиков слова не нужны. Именно этот отрывок <strong><em>Ланкаватары</em></strong> лёг в основу позднейшей дзэнской формулы: «передача вне слов и письмен».<br>
        И даже в нашем мире всё это видно наглядно: черви и мухи совершают свои дела, не имея языка в нашем понимании. Это напоминание о том, что слова — надстройка над более глубокими процессами — в буддизме их называют кармическими отпечатками (<em>vāsanā</em>). Даже сложное, целенаправленное поведение возможно без речи.<br><br>
        <strong>IV</strong>. Если предшествующий отрывок указывал, что явления не порождают друг друга в реальности — то, что мы принимаем за «внешнюю причинность», есть лишь закономерная смена образов в потоке сознания, то данная часть текста добавляет: слова тоже не связаны с независимо существующими объектами — они соотносятся лишь с тем, что возникает в уме.<br>
        Оба отрывка разоблачают одну и ту же иллюзию — веру в то, что наши понятия и слова отражают независимую реальность. Причинность и язык — способы, посредством которых ум упорядочивает и различает поток опыта.<a href="#ref-294" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-295"><sup>295</sup> Парадокс «вечности иллюзии» (<em>bhrānti</em>) раскрывается через то, что её нельзя ни утвердить как действительно существующую, ни свести к полному отсутствию. Иллюзия продолжает являться, принимая множество форм, однако это многообразие не разрушает саму возможность её явления. Пример с водами Ганги показывает, что один и тот же образ воспринимается различными существами по-разному в зависимости от их состояния: люди видят воду, преты — гной, боги — нектар. Даже Благородные продолжают воспринимать иллюзорные формы (мираж, отражение и т.п.), однако больше не принимают их за нечто действительно существующее. Иллюзия сохраняет способность являться, но утрачивает для них силу заблуждения.<a href="#ref-295" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-296"><sup>296</sup> Здесь формулируется недвойственность заблуждения (<em>bhrānti</em>) и истинного (<em>tattva</em>). Благородный не утверждает ни заблуждение, ни истинность как самостоятельные противоположности и не ищет «третьего» между ними. Поэтому само заблуждение, когда оно более не становится предметом различения, раскрывается как то, что следует признать истинным.<a href="#ref-296" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-297"><sup>297</sup> Если йогин, «устранив заблуждение», продолжает удерживать образ-знак (<em>nimitta</em>) чистоты, освобождения или самого устранения, возникает новое, более тонкое заблуждение. Метафора <em>timira</em> (помутнение зрения) указывает, что даже очищенное зрение вновь искажается, если появляется новая фиксация. Поэтому в махаянской практике требуется оставить привязанность и к заблуждению, и к самой идее его устранения.<a href="#ref-297" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-298"><sup>298</sup>  Сравнение дхарм с магией раскрывает условность и мгновенность их явления в восприятии. Махамати замечает, что многообразие форм не имеет единой порождающей причины, тогда как источник магического представления видится ясным и внешним. Благословенный переносит внимание на другое сходство: и магия, и дхармы обманчивы, стремительны и подобны вспышке молнии. Из-за отсутствия внимательного исследования ум цепляется за внешние признаки формы и принимает возникающее в восприятии за нечто устойчивое и независимо существующее. Распознавание этой мгновенной и условной структуры опыта возвращает внимание к непосредственному потоку восприятия, свободного от наложения привычных устойчивых представлений.<a href="#ref-298" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-299"><sup>299</sup> <strong>I. Четырнадцать необъяснимых вопросов (<em>avyākṛta</em>)</strong><br>
        В палийском каноне Будда оставляет без ответа четырнадцать вопросов (<em>catuddasavyākatavatthūni</em>), которые распределяются по трём темам с применением тетралеммы (<em>catuṣkoṭi</em> — утверждение, отрицание, оба сразу, ни то ни другое):<br>
        О мире: вечен ли он? не вечен? и вечен, и не вечен? ни вечен, ни не вечен?<br>
        О пространственных границах мира: конечен ли? бесконечен? и то, и другое? ни то, ни другое?<br>
        О Татхагате после смерти: существует ли? не существует? и то, и другое? ни то, ни другое?<br>
        О душе и теле: душа (<em>jīva</em>) и тело (<em>śarīra</em>) — одно или разное? (один вопрос, дающий в итоге четырнадцать позиций).<br>
        Будда последовательно отказывается отвечать на них, поясняя, что такие вопросы «не ведут к благу, не ведут к нирване» (см. <strong>Cūḷamāluṅkya-sutta</strong>, MN 63; <strong>Aggivacchagotta-sutta</strong>, MN 72). Классическая метафора — человек, раненный отравленной стрелой, который вместо извлечения стрелы требует узнать, кто её выпустил и из какого дерева она сделана.</p>

        <p class="my-2"><strong>II. Как объясняется молчание Будды</strong><br>
        <em>Палийская традиция</em> объясняет молчание прагматически: эти вопросы отвлекают от практики и не опираются на подтверждаемый опыт.<br>
        <strong><em>Ланкаватара</em></strong> добавляет йогачарское объяснение:<br>
        <strong>а)</strong> Педагогическая защита. Слабые умом (<em>buddhi-vaikalya</em>) испугались бы (<em>utrāsa</em>) учения об отсутствии «я», если бы Будда прямо сказал: «Атмана нет»; поэтому ответ намеренно оставлен открытым — это метод устранения поводов для страха (<em>utrāsa-pada-vivarjana</em>).<br>
        <strong>б)</strong> Опровержение ложной предпосылки. Вопросы тиртхиков строятся на допущении существования атмана или внешнего мира; ответить — значит принять эту предпосылку. Молчание отказывает самому вопросу в состоятельности.<br>
        <strong>в)</strong> Устранение через постижение. Для тех, кто постиг «только-ум» (<em>svacittadṛśyamātra</em>), вопрос «вечен ли мир?» утрачивает смысл: то, что принимается за «мир», неотделимо от деятельности ума, а значит, нет и независимогообъекта вопроса. Это означает, что вопрос был изначально поставлен неверно.</p>

        <p class="my-2"><strong>III. Четыре способа ответа (<em>catur-vidha-vyākaraṇa</em>):</strong><br>
        • Прямой ответ (<em>ekāṃśa-vyākaraṇa</em>): «Все обусловленные дхармы непостоянны» — универсальное утверждение.<br>
        • Аналитический ответ (<em>vibhajja-vyākaraṇa</em>): «Убийство плохо? — Да, если намеренное; нет, если случайное» — требует различения контекста.<br>
        • Встречный вопрос (<em>paṭipucchā-vyākaraṇa</em>): «Много ли песчинок в Ганге?» — «А что ты понимаешь под "много"?» — выявляет неясность в самом вопросе.<br>
        • Оставление без ответа (<em>sthāpanīya-vyākaraṇa</em>): Вопрос отклоняется, поскольку основан на ложной предпосылке или не способствует освобождению. <em>sthāpanīya</em> — временная педагогическая мера (<em>kālāntara-deśana</em>, «учение для другого времени») для незрелых (<em>aparipakvendriya</em>). Для зрелых (<em>paripakvendriya</em>) нет ничего «необъяснимого» — они видят природу вопросов.<a href="#ref-299" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-300"><sup>300</sup> Настоящий отрывок представляет собой единую цепь рассуждения, где каждое последующее утверждение вытекает из предыдущего как необходимое следствие. Аргументация последовательно разрушает овеществление дхарм — привычку ума приписывать возникающему независимое существование.<br>
        <strong>1. Отсутствие деятеля → не-возникновение (<em>akārakatvāt → anutpannāḥ</em>)</strong><br>
        Первое звено отвергает классическую модель причинности, основанную на тройке «деятель — действие — результат». Если отсутствует самостоятельный деятель (<em>kāraka</em>), невозможно установить и действие (<em>kriyā</em>) как реально производящую силу. Поэтому дхармы не могут считаться действительно возникающими. Они не возникают ни из существующего, ни из несуществующего, поскольку обе модели предполагают устойчивую причинную основу.<br>
        <strong>2. Не-возникновение → отсутствие собственной природы (<em>anutpannāḥ → niḥsvabhāvāḥ</em>)</strong><br>
        То, что не возникает, не может обладать собственной природой (<em>svabhāva</em>). Собственная природа предполагает устойчивое само-тождество, сохраняющееся через возникновение, пребывание и прекращение. Однако при исследовании дхарм собственным разумом (<em>svabuddhi</em>) их собственные и общие признаки (<em>sva-sāmānya-lakṣaṇa</em>) не устанавливаются. Поэтому дхармы определяются как лишённые собственной природы.<br>
        <strong>3. Отсутствие собственной природы → свобода от собирания-накапливания-наложения и разложения-устранения-отбрасывания (<em>niḥsvabhāvāḥ → anāyūhāniryūhāḥ</em>)</strong><br>
        Здесь текст переходит от отрицания собственной природы к анализу самой работы ума. <em>Āyūha</em> обозначает собирание, накопление и наложение признаков: ум стягивает разрозненные восприятия в устойчивые сочетания и приписывает им самостоятельное существование. <em>Niryūha</em>, напротив, означает разложение, устранение и отбрасывание этих выстроенных сочетаний через аналитическое различение. Однако <strong><em>Ланкаватара</em></strong> утверждает, что дхармы свободны от обоих процессов. При собирании-накапливании-наложении признаки не собираются, не накапливаются и не накладываются; при разложении-устранении-отбрасывании — не разлагаются, не устраняются и не отбрасываются. Тем самым разрушается сама основа двойственности между наложением и устранением признаков.<br>
        <strong>4. Свобода от собирания-накапливания-наложения и разложения-устранения-отбрасывания → непрекращаемость (<em>anāyūhāniryūhāḥ → aniruddhāḥ</em>)</strong><br>
        Если дхармы невозможно действительно составить через признаки, их невозможно и уничтожить через устранение признаков. То, что никогда не было подлинно выстроено, не может быть и разрушено. Поэтому дхармы называются непрекращаемыми (<em>aniruddha</em>) в том смысле, что прекращение применимо только к тому, что прежде действительно возникло.<br>
        <strong>5. Непостоянство и постоянство как снятие крайностей (<em>anitya / nitya</em>)</strong><br>
        Финальный этап снимает противоположность между постоянством и непостоянством. На уровне признаков (<em>lakṣaṇa</em>) дхармы непостоянны, поскольку признаки непрерывно возникают и исчезают. Однако на уровне, свободном от овеществления признаков, отсутствует действительное возникновение и прекращение; поэтому дхармы называются постоянными. «Постоянство через непостоянство» означает освобождение от утверждения любой крайности.<br>
        <strong>Общий смысл</strong><br>
        Вся последовательность направлена на разрушение двойственности «существующее — несуществующее» (<em>bhāvābhāva</em>). <strong><em>Ланкаватара</em></strong> показывает, что сансарический ум непрерывно движется между двумя полюсами: сначала собирает и накапливает признаки, выстраивая устойчивый мир, а затем пытается устранить и отбросить эти же построения. Освобождение достигается выходом за пределы обеих процессов. Когда прекращается наложение признаков, мир перестаёт восприниматься как совокупность независимых объектов; остаётся лишь воспринимаемое собственным умом (<em>svacittadṛśyamātra</em>).<a href="#ref-300" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-301"><sup>301</sup> Фраза допускает два основных толкования.<br>1. В классической йогачаре <em>āśraya</em> («основа», «опора») указывает на <em>Алая-виджняну</em> — сознание-сокровищница. Заблуждение здесь состоит в том, что <em>manas</em> не распознаёт <em>скандхи</em> как проявления самой <em>Алая-виджняны</em>: они — лишь волны на её поверхности, поднятые ветром различений, — образ, который <strong><em>Ланкаватара</em></strong> разворачивает в сравнении океана и ветра (II.46). <em>Скандхи</em> овеществляются, принимаются за самостоятельно существующее — тогда как они подобны отражениям в зеркале, явленным самим зеркалом.<br>2. Второе толкование связывает <em>āśraya</em> с Таковостью (<em>tathatā</em>). Благородное знание видит <em>скандхи</em> недвойственными своей глубинной основе. Обычный же ум, не понимая природы этого знания, сначала отождествляет <em>скандхи</em> с «я», а затем — стремясь преодолеть это — продолжает удерживать их как нечто отдельное, подлежащее устранению. <em>Āśrayānanyatva</em> в этом случае указывает на то, что <em>скандхи</em> неотличны от самой Таковости — без отсылки к какой-либо промежуточной основе.<br>При всём различии оба прочтения указывают на одно: различение <em>скандх</em> прекращается тогда, когда ум перестаёт выстраивать разрыв между основой и тем, что из неё разворачивается.<a href="#ref-301" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">

        <p class="my-2" id="citation-302"><sup>302</sup> Шлока выстраивает восходящую трёхчастную схему: <em>citta</em> (ум как таковой) — <em>jñāna</em> (рассудочное знание) — <em>prajñā</em> (мудрость). Это различение перекликается с классификацией из <strong><em>Махаянасамграхи</em></strong> Асанги, где разграничиваются сознание, порождающее видимость внешних объектов, знание, движущееся в понятиях и умозаключениях, и знание вне образов (<em>nirvikalpajñāna</em>). Термин <em>nirābhāsa</em> — «лишённый образа, свободный от образов (<em>ābhāsa</em>)» — технически указывает именно на последнее: тот этап познания, в которой снято разделение на познающего и познаваемое. В <strong><em>Дхармадхармататавибхаге</em></strong> («Различение явлений и их природы»), приписываемой Майтрее/Асанге, то же состояние описывается как преодоление двойственности схватываемого и схватывающего (<em>grāhya-grāhaka-dvaya</em>). Слово <em>viśeṣa</em> («особое состояние») подчёркивает, что речь идёт о качественно иной ступени опыта, достигаемой в созерцании, — переживаемой как полнота целостного, нераздвоенного восприятия.<a href="#ref-302" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-303"><sup>303</sup> Термин <em>dauṣṭhulya</em> — один из специфических понятий йогачары, трудно передаваемых на русский язык. В <strong><em>Йогачарабхуми</em></strong> и <strong><em>Махаянасамграхе</em></strong> он обозначает особую отягощённость, неподатливую инертность/негибкость/оцепенелость ума и тела, препятствующую как созерцательной практике (<em>bhāvanā</em>), так и прямому восприятию природы дхарм (<em>dharmatā</em>). Это не просто загрязнённость в общем смысле (<em>kleśa</em> или <em>āvaraṇa</em>), это именно практическая помеха: <em>dauṣṭhulya</em> делает ум неспособным к усилию освобождения. Противоположность ему — <em>karmanyatā</em>, «рабочая пригодность» ума и тела, взращиваемая через <em>samādhi</em>. В данном контексте образ-знак (<em>nimitta</em>) назван «несущим <em>dauṣṭhulya</em>», поскольку именно через цепляние за образы-знаки ум приобретает эту инертную привязанность к выстроенным им же образам.<a href="#ref-303" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-304"><sup>304</sup> Гатхи 181-184 посвящены учению о трёх природах (<em>trisvabhāva</em>): воображаемой (<em>parikalpita</em>), зависимой (<em>paratantra</em>) и совершенной (<em>pariniṣpanna</em>). Утверждение, что <em>воображаемая природа</em> не имеет самостоятельного существования внутри зависимой, но обнаруживается через неё в акте заблуждения (<em>bhrānti</em>) сходным образом формулирует Васубандху в <strong><em>Тридцати строфах</em></strong> (<em>Triṃśikā</em>): <em>зависимая природа</em> служит основанием (<em>āśraya</em>), на которое <em>воображаемая природа</em> накладывается через наложение (<em>samāropa</em>), тогда как <em>совершенная природа</em> — это та же зависимая, взятая без наложений, в её подлинном виде.<br>Что касается парадоксального выражения: «воображаемое есть зависимое» — вне <em>зависимой природы</em> воображаемое не имеет никакой точки опоры. Его «материалом» всегда служит зависимое, ошибочно принятое за нечто независимо существующее. Иными словами, воображаемое не существует отдельно от зависимого — оно есть зависимое, воспринятое через заблуждение.<a href="#ref-304" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-305"><sup>305</sup> Отождествление воображаемого (<em>parikalpita</em>) с условной истиной (<em>saṃvṛti</em>) — особенность учения <strong><em>Ланкаватары</em></strong>. В мадхьямике — у Нагарджуны и Чандракирти — <em>saṃvṛti</em> охватывает весь мир явлений, включая зависимое возникновение (<em>pratītyasamutpāda</em>), которое не считается заблуждением.<br>В йогачаре же, и особенно в <strong><em>Ланкаватаре</em></strong>, воображаемое выделяется как то, что не имеет опоры в явлениях: это лишь наложение (<em>samāropa</em>), лишённое собственной основы. Именно его здесь называют <em>saṃvṛti</em>.<br>Поэтому «пресечение» (<em>cheda</em>) — не устранение мира явлений, это прекращение именно <em>parikalpita</em>, ошибочного наложения на <em>зависимую природу</em>.<br>Сфера Благородных (<em>āryagocara</em>) открывается, когда зависимое видится свободным от образов (<em>nirābhāsa</em>) — то есть в своей <em>совершенной природе</em> (<em>pariniṣpanna</em>).<br>Сходное понимание сферы Благородных встречается в <strong><em>Сандхинирмоканасутре</em></strong>, где <em>āryagocara</em> связывается с <em>самадхи</em>, свободным от образов.<a href="#ref-305" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-306"><sup>306</sup> Оба примера — йогин, видящий один объект по-разному, и больной <em>тимирой</em> — показывают, что многообразие (<em>citra</em>) не принадлежит объекту, оно возникает в уме. <em>Зависимая природа</em>, воспринимаемая невеждами, подобна видению при глазной болезни и не является нереальной, она воспринимается через наложение воображаемого.<a href="#ref-306" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-307"><sup>307</sup> Три уподобления — золото, вода, небо — образуют нарастающий ряд от частного к безграничному. В буддийской литературе небо (<em>gagana, ākāśa</em>) устойчиво служит образом <em>dharmadhātu</em> или <em>tathātā</em>: оно изначально чисто, а облака — лишь временные наслоения. Тот же образ развёрнут в <strong><em>Ратнаготравибхаге</em></strong> применительно к природе будды (<em>tathāgatagarbha</em>): она подобна небу, омрачения — облакам. В данном контексте чистота не указывает на самостоятельную реальность воображаемого; даже воображаемое не существует отдельно от основы зависимого. Когда зависимое перестаёт восприниматься через наложения воображаемого (<em>parikalpita</em>), оно раскрывается как <em>совершенная природа</em> (<em>pariniṣpanna</em>).<a href="#ref-307" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-308"><sup>308</sup> <em>Samāropa</em> — приписывать зависимому то, чего у него нет (например, независимую неизменную сущность). <em>Apavāda</em> — отрицать то, что есть (например, само зависимое). Гатха отвергает обе крайности: воображаемого нет, но зависимое существует. Это — срединный путь, выраженный в терминах трёх природ.<a href="#ref-308" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-309"><sup>309</sup> Здесь используется довод от нелепого следствия (<em>prasaṅga</em>). Логика такова: если воображаемое и зависимое абсолютно разделены и первое есть полное отсутствие по отношению ко второму, возникают два невозможных следствия — явление могло бы существовать без основания для своего проявления, а возникновение из полного отсутствия стало бы возможным. Тем самым отвергается представление о полной раздельности природ: воображаемое не есть абсолютное ничто, оно надстраивается над зависимым как его искажённое восприятие. Сходную логику Васубандху использует в <strong><em>Двадцати строфах</em></strong> (<strong><em>Viṃśatikā</em></strong>), отвергая вывод, будто отрицание внешней реальности объектов равнозначно признанию абсолютного ничто.<br>Если выразить это проще: <em>paratantra</em> — это сам поток опыта, зависимо возникающий и непрерывно разворачивающийся; <em>parikalpita</em> — способ, которым ум истолковывает этот поток, разделяя его на «я» и «мир». Это подобно мути в воде или глазной болезни. <em>Pariniṣpanna</em> же — то же самое зависимое, увиденное без наложений воображаемого.<br>Ошибка (<em>samāropa</em>) состоит в приписывании зависимому того, чего в нём нет; ошибка (<em>apavāda</em>) — в отрицании самого зависимого потока. Мудрость (<em>prajñā</em>) же означает видеть зависимое таким, каково оно есть, — в состоянии <em>nirābhāsa</em>, свободном от образов.</p>

        <p class="my-2" id="citation-310"><sup>310</sup> Число видов <em>воображаемой природы</em> варьируется в традиции. В подглаве 2.54 дана классификация из 12 типов <em>vikalpa</em>. Здесь речь идёт о сжатой схеме из 10 видов, используемой в контексте <em>трёх природ</em> (<em>tri-svabhāva</em>). Шесть видов зависимого традиционно связывают с шестью сознаниями (<em>vijñāna</em>): зрительным, слуховым, обонятельным, вкусовым, осязательным и умственным.<a href="#ref-310" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">Ы

        <p class="my-2" id="citation-311"><sup>311</sup> В <strong><em>Ланкаватаре</em></strong> <em>ekayāna</em> («Единая Колесница») понимается иначе, чем в <strong><em>Саддхармапундарике</em></strong>. Здесь она означает не объединение различных путей в один, а прекращение самого различения между схватываемым и схватывающим (<em>grāhya-grāhaka-vikalpa</em>). Поэтому Единая Колесница тождественна личному непосредственному постижению Благородных (<em>pratyātmāryajñāna</em>) и не достигается ни шраваками, ни тиртхиками, поскольку они всё ещё остаются в пределах различения.<a href="#ref-311" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-312"><sup>312</sup> Завеса познаваемого (<em>jñeyāvaraṇa</em>) — одно из двух главных препятствий в йогачаре. Шраваки устраняют завесу омрачений (<em>kleśāvaraṇa</em>) и достигают личной нирваны, но <em>jñeyāvaraṇa</em> — более тонкое препятствие, мешающее всеведению (<em>sarvajñatā</em>). Поэтому их освобождение не является окончательным с точки зрения Махаяны.<a href="#ref-312" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-313"><sup>313</sup> «Изменение-переход» (<em>pariṇāmacyuti</em>) — технический термин йогачары, обозначающий процесс, при котором шравака, вошедший в нирвану без остатка, призывается к продолжению пути.<a href="#ref-313" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-314"><sup>314</sup> «Опьянение <em>самадхи</em>» (<em>samādhimada</em>) — привязанность к блаженству медитативного поглощения как самоцели. Это тонкое препятствие, удерживающее шраваков от вступления на путь бодхисаттвы даже после устранения грубых омрачений.<a href="#ref-314" class="citation-back">↩</a></p>

        <p class="my-2" id="citation-315"><sup>315</sup> <em>Vaśavartitā</em> — «владычество», «свободное распоряжение», «нахождение в полной власти над». Речь идёт об обретении состояния, в котором бывшие шраваки становятся проводниками деятельности Дхармакаи в мире.<a href="#ref-315" class="citation-back">↩</a></p>

        <hr class="my-8 border-t-4 border-gray-500">
    </div>
